export default JSON.parse("{\"source\":{\"book\":11728,\"sha\":\"56e52b86c23a0d363a6e51d8fee677eec4f582ceb580e14d2beb8c851400d9f9\"},\"kinds\":{\"52\":\"النَّوْعُ الثَّانِي وَالْخَمْسُونَ: فِي حَقِيقَتِهِ وَمَجَازِهِ\",\"53\":\"النَّوْعُ الثَّالِثُ وَالْخَمْسُونَ: فِي تَشْبِيهِهِ وَاسْتِعَارَاتِهِ\",\"54\":\"النَّوْعُ الرَّابِعُ وَالْخَمْسُونَ: فِي كِنَايَاتِهِ وَتَعْرِيضِهِ\",\"55\":\"النَّوْعُ الْخَامِسُ وَالْخَمْسُونَ: فِي الْحَصْرِ وَالِاخْتِصَاصِ\",\"56\":\"النَّوْعُ السَّادِسُ وَالْخَمْسُونَ: فِي الْإِيجَازِ وَالْإِطْنَابِ\",\"57\":\"النَّوْعُ السَّابِعُ وَالْخَمْسُونَ: فِي الْخَبَرِ وَالْإِنْشَاءِ\",\"58\":\"النَّوْعُ الثَّامِنُ وَالْخَمْسُونَ: فِي بَدَائِعِ الْقُرْآنِ\"},\"entries\":[[52,\"\",3,120,121,884,\"الْأَوَّلُ: الْمَجَازُ فِي التَّرْكِيبِ وَيُسَمَّى مَجَازُ الْإِسْنَادِ وَالْمَجَازُ الْعَقْلِيُّ وَعَلَاقَتُهُ الْمُلَابَسَةُ وَذَلِكَ أَنْ يُسْنَدَ الْفِعْلُ أَوْ شَبَهُهُ إِلَى غَيْرِ مَا هُوَ لَهُ أَصَالَةً لِمُلَابَسَتِهِ لَهُ كَقَوْلِهِ تَعَالَى: ﴿وَإِذَا تُلِيَتْ عَلَيْهِمْ آيَاتُهُ زَادَتْهُمْ إِيمَانًا﴾ نُسِبَتِ الزِّيَادَةُ - وَهِيَ فِعْلُ اللَّهِ - إِلَى الْآيَاتِ لِكَوْنِهَا سَبَبًا لَهَا ﴿يُذَبِّحُ أَبْنَاءَهُمْ﴾ ﴿يَا هَامَانُ ابْنِ لِي﴾ نُسِبَ الذَّبْحُ وَهُوَ فِعْلُ الْأَعْوَانِ إِلَى فِرْعَوْنَ وَالْبِنَاءُ وَهُوَ فِعْلُ الْعَمَلَةِ إِلَى هَامَانَ لِكَوْنِهِمَا آمِرِينَ بِهِ\",[[8,2,8,13,1],[28,4,11,12,1],[40,36,2,4,1]]],[52,\"\",3,121,121,885,\"وَكَذَا قَوْلُهُ: ﴿وَأَحَلُّوا قَوْمَهُمْ دَارَ الْبَوَارِ﴾ نُسِبَ الْإِحْلَالُ إِلَيْهِمْ لِتَسَبُّبِهِمْ فِي كُفْرِهِمْ بِأَمْرِهِمْ إِيَّاهُمْ بِهِ\",[[14,28,8,11,1]]],[52,\"\",3,121,121,885,\"وَمِنْهُ قوله تعالى: ﴿وْمًا يَجْعَلُ الْوِلْدَانَ شِيبًا﴾ نُسِبَ الْفِعْلُ إِلَى الظَّرْفِ لِوُقُوعِهِ فِيهِ.\",[[73,17,4,7,1]]],[52,\"\",3,121,121,885,\"﴿عِيشَةٍ راضية﴾ أَيْ مَرْضِيَّةٍ\",[[69,21,2,3,2],[101,7,2,3,2]]],[52,\"\",3,121,121,885,\"﴿فَإِذَا عَزَمَ الأَمْرُ﴾ أَيْ عُزِمَ عَلَيْهِ بِدَلِيلِ ﴿فَإِذَا عَزَمْتَ﴾\",[[47,21,3,5,1],[3,159,21,22,1]]],[52,\"\",3,121,121,885,\"أَحَدُهَا: مَا طَرَفَاهُ حَقِيقِيَّانِ كَالْآيَةِ الْمُصَدَّرِ بِهَا وَكَقَوْلِهِ: ﴿وَأَخْرَجَتِ الأَرْضُ أَثْقَالَهَا﴾\",[[99,2,0,2,1]]],[52,\"\",3,121,121,885,\"ثَانِيهَا: مَجَازِيَّانِ نَحْوُ: ﴿فَمَا رَبِحَتْ تِجَارَتُهُمْ﴾ أَيْ مَا رَبِحُوا فِيهَا وَإِطْلَاقُ الرِّبْحِ وَالتِّجَارَةِ هُنَا مَجَازٌ\",[[2,16,5,7,1]]],[52,\"\",3,121,122,885,\"أَمَّا الْأَوَّلُ وَالثَّانِي: فَكَقَوْلِهِ: ﴿أَمْ أَنْزَلْنَا عَلَيْهِمْ سُلْطَانًا﴾ أَيْ بُرْهَانًا ﴿كَلاَّ إِنَّهَا لَظَى نَزَّاعَةً لِلشَّوَى تَدْعُو﴾ فَإِنَّ الدُّعَاءَ مِنَ النَّارِ مَجَازٌ وَقَوْلُهُ: ﴿حَتَّى تَضَعَ الْحَرْبُ أَوْزَارَهَا﴾ ﴿تُؤْتِي أُكُلَهَا كُلَّ حِينٍ﴾ ﴿فَأُمُّهُ هَاوِيَةٌ﴾ وَاسْمُ الْأُمِّ الْهَاوِيَةُ مَجَازٌ أَيْ كَمَا أَنَّ الْأُمَّ كَافِلَةٌ لِوَلَدِهَا وَمَلْجَأٌ لَهُ كَذَلِكَ النَّارُ لِلْكَافِرِينَ كَافِلَةٌ وَمَأْوًى وَمَرْجِعٌ\",[[30,35,0,3,1],[70,15,0,2,1],[70,16,0,1,1],[70,17,0,0,1],[47,4,16,19,1],[14,25,0,3,1],[101,9,0,1,1]]],[52,\"\",3,122,122,886,\"الثَّالِثُ: إِطْلَاقُ اسْمِ الْكُلِّ عَلَى الْجُزْءِ نَحْوُ: ﴿يَجْعَلُونَ أَصَابِعَهُمْ فِي آذَانِهِمْ﴾ أَيْ أَنَامِلُهُمْ وَنُكْتَةُ التَّعْبِيرِ عَنْهَا بِالْأَصَابِعِ الْإِشَارَةُ إِلَى إِدْخَالِهَا عَلَى غَيْرِ الْمُعْتَادِ مُبَالَغَةً مِنَ الْفِرَارِ فَكَأَنَّهُمْ جَعَلُوا الْأَصَابِعَ ﴿وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ﴾ أَيْ وُجُوهُهُمْ لِأَنَّهُ لَمْ يَرَ جُمْلَتَهُمْ، ﴿فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ﴾ أطلق الشهر وهو إسم لثلاثين ليلة وأراد جزء مِنْهُ كَذَا أَجَابَ بِهِ الْإِمَامُ فَخْرُ الدِّينِ عَنِ اسْتِشْكَالِ أَنَّ الْجَزَاءَ إِنَّمَا يَكُونُ بَعْدَ تَمَامِ الشَّرْطِ وَالشَّرْطُ أَنْ يَشْهَدَ الشَّهْرَ وَهُوَ اسْمٌ لِكُلِّهِ حَقِيقَةً فَكَأَنَّهُ أَمَرَ بِالصَّوْمِ بَعْدَ مُضِيِّ الشَّهْرِ وَلَيْسَ كَذَلِكَ وَقَدْ فَسَّرَهُ عَلَيٌّ وَابْنُ عَبَّاسٍ وَابْنُ عُمَرَ عَلَى أَنَّ الْمَعْنَى مَنْ شَهِدَ أَوَّلَ الشَّهْرِ فَلْيَصُمْ جَمِيعَهُ وَإِنْ سَافَرَ فِي أَثْنَائِهِ.\",[[2,19,8,11,1],[63,4,0,3,1],[2,185,12,16,1]]],[52,\"\",3,122,123,886,\"أَخْرَجَهُ ابْنُ جَرِيرٍ وَابْنُ أَبِي حَاتِمٍ وَغَيْرُهُمَا وَهُوَ أَيْضًا مِنْ هَذَا النَّوْعِ وَيَصْلُحُ أَنْ يَكُونَ مِنْ نَوْعِ الْحَذْفِ الرَّابِعُ: عَكْسُهُ نَحْوُ: ﴿وَيَبْقَى وَجْهُ رَبِّكَ﴾ أَيْ ذَاتُهُ ﴿فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ﴾ أَيْ ذَوَاتُكُمْ إِذِ الِاسْتِقْبَالُ يَجِبُ بِالصَّدْرِ ﴿وُجُوهٌ يَوْمَئِذٍ نَاعِمَةٌ﴾ ﴿وُجُوهٌ يَوْمَئِذٍ خَاشِعَةٌ عَامِلَةٌ نَاصِبَةٌ﴾ عَبَّرَ بِالْوُجُوهِ عَنْ جَمِيعِ الْأَجْسَادِ لِأَنَّ التَّنَعُّمَ والنصب حاصل لكلها ﴿ذَلِكَ بِمَا قَدَّمَتْ يَدَاكَ﴾ ﴿فَبِمَا كَسَبَتْ أَيْدِيكُمْ﴾ أَيْ قَدَّمْتَ وَكَسَبْتُمْ وَنُسِبَ ذَلِكَ إِلَى الْأَيْدِي لِأَنَّ أَكْثَرَ الْأَعْمَالِ تُزَاوَلُ بِهَا ﴿قُمِ اللَّيْلَ﴾ ﴿وَقُرْآنَ الْفَجْرِ﴾ ﴿وَارْكَعُوا مَعَ الرَّاكِعِينَ﴾ ﴿وَمِنَ اللَّيْلِ فَاسْجُدْ لَهُ﴾ أَطْلَقَ كُلًّا مِنَ الْقِيَامِ وَالْقِرَاءَةِ وَالرُّكُوعِ وَالسُّجُودِ عَلَى الصَّلَاةِ وَهُوَ بَعْضُهَا ﴿هَدْيًا بَالِغَ الْكَعْبَةِ﴾ أَيِ الْحَرَمِ كُلِّهِ بِدَلِيلِ أَنَّهُ لَا يُذْبَحُ فِيهَا.\",[[55,27,0,2,1],[2,144,17,19,2],[2,150,11,13,2],[88,8,0,2,1],[88,2,0,2,1],[88,3,0,1,1],[22,10,0,3,1],[42,30,4,6,1],[71,5,4,5,2],[73,2,0,1,2],[17,78,7,8,2],[17,78,10,11,2],[2,43,4,6,2],[3,43,4,6,2],[76,26,0,3,1],[5,95,23,25,1]]],[52,\"\",3,123,123,887,\"أَحَدُهُمَا: وَصْفُ الْبَعْضِ بِصِفَةِ الْكُلِّ كَقَوْلِهِ: ﴿نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ﴾ فَالْخَطَأُ صِفَةُ الْكُلِّ وُصِفَ بِهِ الناصية عكسه كقوله: ﴿إِنَّا مِنْكُمْ وَجِلُونَ﴾ وَالْوَجَلُ صِفَةُ الْقَلْبِ ﴿وَلَمُلِئْتَ مِنْهُمْ رُعْبًا﴾ وَالرُّعْبُ إِنَّمَا يَكُونُ فِي الْقَلْبِ\",[[96,16,0,2,1],[15,52,6,8,1],[18,18,19,21,1]]],[52,\"\",3,123,124,887,\"وَالثَّانِي: إِطْلَاقُ لَفْظِ بَعْضٍ مُرَادًا بِهِ الْكُلُّ ذَكَرَهُ أَبُو عُبَيْدَةَ وَخَرَّجَ عَلَيْهِ قَوْلَهُ: ﴿وَلأُبَيِّنَ لَكُمْ بَعْضَ الَّذِي تَخْتَلِفُونَ فِيهِ﴾ أَيْ كُلَّهُ ﴿وَإِنْ يَكُ صَادِقًا يُصِبْكُمْ بَعْضُ الَّذِي يَعِدُكُمْ﴾ وَتُعُقِّبُ بِأَنَّهُ لَا يَجِبُ عَلَى النَّبِيِّ بَيَانُ كُلِّ مَا اخْتُلِفَ فِيهِ بِدَلِيلِ السَّاعَةِ وَالرُّوحِ وَنَحْوِهِمَا وَبِأَنَّ مُوسَى كَانَ وَعَدَهُمْ بِعَذَابٍ فِي الدُّنْيَا وَفِي الْآخِرَةِ فَقَالَ: \\\"يُصِبْكُمْ هَذَا الْعَذَابُ فِي الدُّنْيَا وَهُوَ بَعْضُ الْوَعِيدِ مِنْ غَيْرِ نَفْيِ عَذَابِ الْآخِرَةِ ذَكَرَهُ ثَعْلَبٌ.\",[[43,63,8,13,1],[40,28,24,30,1]]],[52,\"\",3,124,124,888,\"الْخَامِسُ: إِطْلَاقُ اسْمِ الْخَاصِّ عَلَى الْعَامِّ نَحْوُ: ﴿إِنَّا رَسُولُ رَبِّ الْعَالَمِينَ﴾ أَيْ رُسُلُهُ\",[[26,16,3,6,2],[43,46,8,11,2]]],[52,\"\",3,124,124,888,\"السَّادِسُ: عَكْسُهُ نَحْوُ: ﴿وَيَسْتَغْفِرُونَ لِمَنْ فِي الأَرْضِ﴾ أَيِ الِمُؤْمِنِينَ بِدَلِيلِ قَوْلِهِ: ﴿وَيَسْتَغْفِرُونَ لِلَّذِينَ آمَنُوا﴾\",[[42,5,9,12,1],[40,7,10,12,1]]],[52,\"\",3,124,124,888,\"الثَّامِنُ: عَكْسُهُ نَحْوُ: ﴿هَلْ يَسْتَطِيعُ رَبُّكَ أَنْ يُنَزِّلَ عَلَيْنَا مَائِدَةً مِنَ السَّمَاءِ﴾ أَيْ هَلْ يَفْعَلُ أَطْلَقَ الِاسْتِطَاعَةَ عَلَى الْفِعْلِ لِأَنَّهَا لَازِمَةٌ لَهُ\",[[5,112,6,14,1]]],[52,\"\",3,124,125,888,\"التَّاسِعُ: إِطْلَاقُ الْمُسَبَّبِ عَلَى السَّبَبِ نَحْوُ: ﴿وَيُنَزِّلُ لَكُمْ مِنَ السَّمَاءِ رِزْقًا﴾ ﴿قَدْ أَنْزَلْنَا عَلَيْكُمْ لِبَاسًا﴾ أَيْ مَطَرًا يَتَسَبَّبُ عَنْهُ الرِّزْقُ وَاللِّبَاسُ، ﴿لَا يَجِدُونَ نِكَاحًا﴾ أَيْ مُؤْنَةً مِنْ مَهْرٍ وَنَفَقَةٍ وَمَا لَا بُدَّ لِلْمُتَزَوِّجِ مِنْهُ. الْعَاشِرُ: عَكْسُهُ نَحْوُ: ﴿مَا كَانُوا يَسْتَطِيعُونَ السَّمْعَ﴾ أَيِ الْقَبُولَ وَالْعَمَلَ بِهِ لِأَنَّهُ مُسَبَّبٌ عَنِ السَّمْعِ.\",[[40,13,4,8,1],[7,26,2,5,1],[24,33,2,4,1],[11,20,17,20,1]]],[52,\"\",3,125,125,889,\"مِنْ ذَلِكَ نِسْبَةُ الْفِعْلِ إِلَى سَبَبِ السَّبَبِ كَقَوْلِهِ: ﴿فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ﴾ ﴿كَمَا أَخْرَجَ أَبَوَيْكُمْ مِنَ الْجَنَّةِ﴾ فَإِنَّ الْمُخْرِجَ فِي الْحَقِيقَةِ هُوَ اللَّهُ تَعَالَى وَسَبَبُ ذَلِكَ أَكْلُ الشَّجَرَةِ وَسَبَبُ الْأَكْلِ وَسُوسَةُ الشَّيْطَانِ.\",[[2,36,3,6,1],[7,27,5,9,1]]],[52,\"\",3,125,125,889,\"الْحَادِي عَشَرَ: تَسْمِيَةُ الشَّيْءِ بِاسْمِ مَا كَانَ عَلَيْهِ نَحْوُ: ﴿وَآتُوا الْيَتَامَى أَمْوَالَهُمْ﴾ أَيِ الَّذِينَ كَانُوا يَتَامَى إِذْ لَا يُتْمَ بَعْدَ الْبُلُوغِ ﴿فَلا تَعْضُلُوهُنَّ أَنْ يَنْكِحْنَ أَزْوَاجَهُنَّ﴾ أَيْ الَّذِينَ كَانُوا أَزْوَاجَهُنَّ ﴿مَنْ يَأْتِ رَبَّهُ مُجْرِمًا﴾ سَمَّاهُ مُجْرِمًا بِاعْتِبَارِ مَا كَانَ فِي الدُّنْيَا مِنَ الْإِجْرَامِ.\",[[4,2,0,2,1],[2,232,5,9,1],[20,74,1,4,1]]],[52,\"\",3,125,125,889,\"الثَّانِي عَشَرَ: تَسْمِيَتُهُ بِاسْمِ مَا يَؤُولُ إِلَيْهِ نَحْوُ: ﴿إِنِّي أَرَانِي أَعْصِرُ خَمْرًا﴾ أَيْ عِنَبًا يَؤُولُ إِلَى الْخَمْرِيَّةِ، ﴿وَلا يَلِدُوا إِلاَّ فَاجِرًا كَفَّارًا﴾ أَيْ صَائِرًا إِلَى الْكُفْرِ وَالْفُجُورِ، ﴿تَنْكِحَ زَوْجًا غَيْرَهُ﴾ سَمَّاهُ زَوْجًا لِأَنَّ الْعَقْدَ يَؤُولُ إِلَى زَوْجِيَّةٍ لِأَنَّهَا لَا تُنْكَحُ إِلَّا فِي حَالِ كَوْنِهِ زَوْجًا ﴿فَبَشَّرْنَاهُ بِغُلامٍ حَلِيمٍ﴾ ﴿نُبَشِّرُكَ بِغُلامٍ عَلِيمٍ﴾ وَصَفَهُ فِي حَالِ الْبِشَارَةِ بِمَا يَؤُولُ إِلَيْهِ مِنَ الْعِلْمِ وَالْحِلْمِ\",[[12,36,6,9,1],[71,27,5,9,1],[2,230,8,10,1],[37,101,0,2,1],[15,53,4,6,1]]],[52,\"\",3,125,126,889,\"الثَّالِثَ عَشَرَ: إِطْلَاقُ اسْمِ الْحَالِ عَلَى الْمَحَلِّ نَحْوُ: ﴿فَفِي رَحْمَةِ اللَّهِ هُمْ فِيهَا خَالِدُونَ﴾ أَيْ فِي الْجَنَّةِ لِأَنَّهَا مَحَلُّ الرَّحْمَةِ، ﴿بَلْ مَكْرُ اللَّيْلِ﴾ أَيْ فِي اللَّيْلِ، ﴿إِذْ يُرِيكَهُمُ اللَّهُ فِي مَنَامِكَ﴾ أي في عينك عَلَى قَوْلِ الْحَسَنِ.\",[[3,107,4,9,1],[34,33,5,7,1],[8,43,0,4,1]]],[52,\"\",3,126,126,890,\"الرَّابِعَ عَشَرَ: عَكْسُهُ نَحْوُ: ﴿فَلْيَدْعُ نَادِيَهُ﴾ أَيْ أَهْلَ نَادِيهِ أَيْ مَجْلِسَهُ\",[[96,17,0,1,1]]],[52,\"\",3,126,126,890,\"وَمِنْهُ التَّعْبِيرُ بِالْيَدِ عَنِ الْقُدْرَةِ نحو: ﴿بِيَدِهِ الْمُلْكُ﴾ وَبِالْقَلْبِ عَنِ الْعَقْلِ نَحْوُ: ﴿لَهُمْ قُلُوبٌ لَا يَفْقَهُونَ بِهَا﴾ أَيْ عُقُولٌ وَبِالْأَفْوَاهِ عَنِ الْأَلْسُنِ نَحْوُ: ﴿يَقُولُونَ بِأَفْوَاهِهِمْ﴾ وَبِالْقَرْيَةِ عَنْ سَاكِنِيهَا نَحْوُ: ﴿وَاسْأَلِ الْقَرْيَةَ﴾ قد اجْتَمَعَ هَذَا النَّوْعُ وَمَا قَبْلَهُ فِي قَوْلِهِ تَعَالَى: ﴿خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ﴾ فَإِنَّ أَخْذَ الزِّينَةِ غَيْرُ مُمْكِنٍ لِأَنَّهَا مَصْدَرٌ فَالْمُرَادُ مَحَلُّهَا فَأَطْلَقَ عَلَيْهِ اسْمَ الْحَالِّ وَأَخُذُهَا لِلْمَسْجِدِ نفسه لا يجب فالمراد الصَّلَاةُ فَأَطْلَقَ اسْمَ الْمَحَلِّ عَلَى الْحَالِّ.\",[[67,1,2,3,1],[7,179,7,11,1],[3,167,23,24,1],[12,82,0,1,1],[7,31,2,6,1]]],[52,\"\",3,126,127,890,\"الْخَامِسَ عَشَرَ: تَسْمِيَةُ الشَّيْءِ بِاسْمِ آلَتِهِ نَحْوُ: ﴿وَاجْعَلْ لِي لِسَانَ صِدْقٍ فِي الآخِرِينَ﴾ أَيْ ثَنَاءً حَسَنًا لِأَنَّ اللِّسَانَ آلَتُهُ، ﴿وَمَا أَرْسَلْنَا مِنْ رَسُولٍ إِلاَّ بِلِسَانِ قَوْمِهِ﴾ أَيْ بِلُغَةِ قَوْمِهِ. السَّادِسَ عَشَرَ: تَسْمِيَةُ الشَّيْءِ بِاسْمٍ ضِدِّهِ نَحْوُ: ﴿فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ﴾ وَالْبِشَارَةُ حَقِيقَةٌ فِي الْخَبَرِ السَّارِّ وَمِنْهُ تَسْمِيَةُ الدَّاعِي إِلَى الشَّيْءِ بِاسْمِ الصَّارِفُ عَنْهُ ذَكَرَهُ السَّكَّاكِيُّ وَخَرَّجَ عَلَيْهِ قَوْلَهُ تَعَالَى: ﴿مَا مَنَعَكَ أَلاَّ تَسْجُدَ﴾ يَعْنِي مَا دَعَاكَ إِلَى أَلَّا تَسْجُدَ وَسَلِمَ بِذَلِكَ مِنْ دَعْوَى زِيَادَةِ \\\"لَا\\\"\",[[26,84,0,5,1],[14,4,0,6,1],[3,21,15,17,3],[9,34,25,27,3],[84,24,0,2,3],[7,12,1,4,1]]],[52,\"\",3,127,127,891,\"السَّابِعَ عَشَرَ: إِضَافَةُ الْفِعْلِ إِلَى مَا لَا يَصِحُّ مِنْهُ تَشْبِيهًا نَحْوُ: ﴿جِدَارًا يُرِيدُ أَنْ يَنْقَضَّ فَأَقَامَهُ﴾ وَصَفَهُ بِالْإِرَادَةِ وَهِيَ مِنْ صِفَاتِ الْحَيِّ تَشْبِيهًا لِمَيْلِهِ لِلْوُقُوعِ بِإَرَادَتُهُ.\",[[18,77,13,17,1]]],[52,\"\",3,127,128,891,\"الثَّامِنَ عَشَرَ: إِطْلَاقُ الْفِعْلِ وَالْمُرَادُ مُشَارَفَتُهُ وَمُقَارَبَتُهُ وَإِرَادَتُهُ نَحْوُ: ﴿فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ﴾ أَيْ قَارَبْنَ بُلُوغَ الْأَجَلِ أَيِ انِقِضَاءَ الْعِدَّةِ لِأَنَّ الْإِمْسَاكَ لَا يَكُونُ بَعْدَهُ وَهُوَ فِي قَوْلِهِ: ﴿فَبَلَغْنَ أَجَلَهُنَّ فَلا تَعْضُلُوهُنَّ﴾ حَقِيقَةً ﴿فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلا يَسْتَقْدِمُونَ﴾، أَيْ فَإِذَا قَرُبَ مَجِيئُهُ وَبِهِ يَنْدَفِعُ السُّؤَالُ الْمَشْهُورُ فِيهَا أَنَّ عِنْدَ مَجِيءِ الْأَجَلِ لَا يُتَصَوَّرُ تَقْدِيمٌ وَلَا تَأْخِيرٌ، ﴿وَلْيَخْشَ الَّذِينَ لَوْ تَرَكُوا مِنْ خَلْفِهِمْ﴾ الْآيَةَ أَيْ لَوْ قَارَبُوا أَنْ يَتْرُكُوا خَافُوا لَأَنَّ الْخِطَابَ لِلْأَوْصِيَاءِ وَإِنَّمَا يتوجه إليهم قَبْلَ التَّرْكِ لِأَنَّهُمْ بَعْدَهُ أَمْوَاتٌ، ﴿إِذَا قُمْتُمْ إِلَى الصَّلاةِ فَاغْسِلُوا﴾ أَيْ أَرَدْتُمُ الْقِيَامَ ﴿فَإِذَا قَرَأْتَ الْقُرْآنَ فَاسْتَعِذْ﴾ أَيْ أَرَدْتَ الْقِرَاءَةَ، لِتَكُونَ الِاسْتِعَاذَةُ قَبْلَهَا، ﴿وَكَمْ مِنْ قَرْيَةٍ أَهْلَكْنَاهَا فَجَاءَهَا بَأْسُنَا﴾ أَيْ أَرَدْنَا إِهْلَاكَهَا وَإِلَّا لَمْ يَصِحَّ الْعَطْفُ بِالْفَاءِ وَجَعَلَ مِنْهُ بَعْضُهُمْ قَوْلَهُ: ﴿مَنْ يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ﴾ أَيْ مَنْ يُرِدِ اللَّهُ هِدَايَتَهُ وَهُوَ حَسَنٌ جِدًّا لِئَلَّا يَتَّحِدَ الشَّرْطُ وَالْجَزَاءُ.\",[[65,2,0,3,1],[2,232,3,6,1],[7,34,3,10,1],[4,9,0,5,1],[5,6,3,7,1],[16,98,0,3,1],[7,4,0,5,1],[7,178,0,4,1]]],[52,\"\",3,128,128,892,\"التَّاسِعَ عَشَرَ: الْقَلْبُ إِمَّا قَلْبُ إِسْنَادٍ نَحْوُ: ﴿مَا إِنَّ مَفَاتِحَهُ لَتَنُوءُ بِالْعُصْبَةِ﴾ أَيْ لَتَنُوءُ الْعُصْبَةُ بِهَا ﴿لِكُلِّ أَجَلٍ كِتَابٌ﴾ أَيْ لِكُلِّ كِتَابٍ أَجَلٌ، ﴿وَحَرَّمْنَا عَلَيْهِ الْمَرَاضِعَ﴾ أَيْ حَرَّمْنَاهُ عَلَى الْمَرَاضِعِ ﴿وَيَوْمَ يُعْرَضُ الَّذِينَ كَفَرُوا عَلَى النَّارِ﴾ أَيْ تُعْرَضُ النَّارُ عَلَيْهِمْ لِأَنَّ الْمَعْرُوضَ عَلَيْهِ هُوَ الَّذِي لَهُ الِاخْتِيَارُ ﴿وَإِنَّهُ لِحُبِّ الْخَيْرِ لَشَدِيدٌ﴾ أَيْ وَإِنَّ حُبَّهُ لِلْخَيْرِ ﴿وَإِنْ يُرِدْكَ بِخَيْرٍ﴾ أَيْ يُرِدْ بِكَ الْخَيِّرَ ﴿فَتَلَقَّى آدَمُ مِنْ رَبِّهِ كَلِمَاتٍ﴾ لِأَنَّ الْمُتَلَقِّيَ حَقِيقَةً هُوَ آدَمُ كَمَا قُرِئَ بِذَلِكَ أَيْضًا\",[[28,76,11,15,1],[13,38,18,20,1],[28,12,0,2,1],[46,20,0,5,2],[46,34,0,5,2],[100,8,0,3,1],[10,107,9,11,1],[2,37,0,4,1]]],[52,\"\",3,128,128,892,\"أَوْ قَلْبُ عَطْفٍ نَحْوُ: ﴿ثُمَّ تَوَلَّ عَنْهُمْ فَانْظُرْ﴾، أَيْ فَانْظُرْ ثُمَّ تَوَلَّ ﴿ثُمَّ دَنَا فَتَدَلَّى﴾ أَيْ تَدَلَّى فَدَنَا لِأَنَّهُ بِالتَّدَلِّي مَالَ إِلَى الدُّنُوِّ\",[[27,28,5,8,1],[53,8,0,2,1]]],[52,\"\",3,128,129,892,\"مِنْهَا إِطْلَاقُ الْمَصْدَرِ عَلَى الْفَاعِلِ نَحْوُ: ﴿فَإِنَّهُمْ عَدُوٌّ لِي﴾ وَلِهَذَا أَفْرَدَهُ وَعَلَى الْمَفْعُولِ نَحْوُ: ﴿وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ﴾ أَيْ مِنْ مَعْلُومِهِ، ﴿صُنْعَ اللَّهِ﴾ أَيْ مَصْنُوعَهُ، ﴿وَجَاءُوا عَلَى قَمِيصِهِ بِدَمٍ كَذِبٍ﴾ أَيْ مَكْذُوبٍ فِيهِ لِأَنَّ الْكَذِبَ مِنْ صِفَاتِ الْأَقْوَالِ لَا الْأَجْسَامِ وَمِنْهَا إِطْلَاقُ الْبُشْرَى عَلَى الْمُبَشَّرِ بِهِ وَالْهَوَى عَلَى الْمَهْوِيِّ وَالْقَوْلِ عَلَى الْمَقُولِ.\",[[26,77,0,2,1],[2,255,32,36,1],[27,88,8,9,1],[12,18,0,4,1]]],[52,\"\",3,129,129,893,\"وَمِنْهَا إِطْلَاقُ الْفَاعِلِ وَالْمَفْعُولِ عَلَى الْمَصْدَرِ نَحْوُ: ﴿لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ﴾ أي تكذيب ﴿بِأَيِّكُمُ الْمَفْتُونُ﴾ أَيِ الِفِتْنَةُ عَلَى أَنَّ الْبَاءَ غَيْرُ زَائِدَةٍ\",[[56,2,0,2,1],[68,6,0,1,1]]],[52,\"\",3,129,129,893,\"وَمِنْهَا إِطْلَاقُ فَاعِلٍ عَلَى مَفْعُولٍ نَحْوُ: ﴿مَاءٍ دَافِقٍ﴾ أَيْ مَدْفُوقٍ ﴿لَا عَاصِمَ الْيَوْمَ مِنْ أَمْرِ اللَّهِ إِلاَّ مَنْ رَحِمَ﴾ أَيْ لَا مَعْصُومَ ﴿جَعَلْنَا حَرَمًا آمِنًا﴾ أَيْ مَأْمُونًا فِيهِ\",[[86,6,2,3,1],[11,43,8,16,1],[29,67,3,5,1]]],[52,\"\",3,129,129,893,\"وَعَكْسُهُ نَحْوُ: ﴿إِنَّهُ كَانَ وَعْدُهُ مَأْتِيًّا﴾ أي آتيا ﴿حِجَابًا مَسْتُورًا﴾ أي ساترا وقيل: على بابه أي مستورا على الْعُيُونِ لَا يُحِسُّ بِهِ أَحَدٌ\",[[19,61,7,10,1],[17,45,10,11,1]]],[52,\"\",3,129,129,893,\"وَمِنْهَا إِطْلَاقُ \\\"فَعِيلٍ\\\" بِمَعْنَى \\\"مَفْعُولٍ\\\" نَحْوُ: ﴿وَكَانَ الْكَافِرُ عَلَى رَبِّهِ ظَهِيرًا﴾ وَمِنْهَا إِطْلَاقُ وَاحِدٍ مِنَ الْمُفْرَدِ وَالْمُثَنَّى وَالْجَمْعِ عَلَى آخَرَ مِنْهَا\",[[25,55,9,13,1]]],[52,\"\",3,129,129,893,\"مِثَالُ إِطْلَاقِ الْمُفْرَدِ عَلَى الْمُثَنَّى: ﴿وَاللَّهُ وَرَسُولُهُ أَحَقُّ أَنْ يُرْضُوهُ﴾ أَيْ يُرْضُوهُمَا فَأُفْرِدَ لِتَلَازُمِ الرِّضَاءَيْنِ\",[[9,62,4,8,1]]],[52,\"\",3,129,130,893,\"وَعَلَى الْجَمْعِ نَحْوُ: ﴿إِنَّ الأِنْسَانَ لَفِي خُسْرٍ﴾ أَيِ الِأَنَاسِيَّ بِدَلِيلِ الِاسْتِثْنَاءِ مِنْهُ ﴿إِنَّ الْإِنْسَانَ خُلِقَ هَلُوعًا﴾ بدليل ﴿إِلاَّ الْمُصَلِّينَ﴾ وَمِثَالُ إِطْلَاقِ الْمُثَنَّى عَلَى الْمُفْرَدِ: ﴿أَلْقِيَا فِي جَهَنَّمَ﴾ أَيْ أَلْقِ وَمِنْهُ كُلُّ فِعْلٍ نُسِبَ إِلَى شَيْئَيْنِ وَهُوَ لِأَحَدِهِمَا فَقَطْ نَحْوُ: ﴿يَخْرُجُ مِنْهُمَا اللُّؤْلُؤُ وَالْمَرْجَانُ﴾ وَإِنَّمَا يَخْرُجُ مِنْ أَحَدِهِمَا وَهُوَ الْمِلْحُ دُونَ الْعَذْبِ وَنَظِيرُهُ ﴿وَمِنْ كُلٍّ تَأْكُلُونَ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُونَ حِلْيَةً تَلْبَسُونَهَا﴾ وَإِنَّمَا تَخْرُجُ الْحِلْيَةُ مِنَ الْمِلْحِ، ﴿وَجَعَلَ الْقَمَرَ فِيهِنَّ نُورًا﴾ أَيْ فِي إِحْدَاهُنَّ ﴿نَسِيَا حُوتَهُمَا﴾ وَالنَّاسِي يُوشَعُ بِدَلِيلِ قَوْلِهِ لِمُوسَى: ﴿فَإِنِّي نَسِيتُ الْحُوتَ﴾ وَإِنَّمَا أُضِيفَ النِّسْيَانُ إِلَيْهِمَا مَعًا لِسُكُوتِ مُوسَى عَنْهُ ﴿فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ﴾ وَالتَّعْجِيلُ فِي الْيَوْمِ الثَّانِي، ﴿عَلَى رَجُلٍ مِنَ الْقَرْيَتَيْنِ عَظِيمٍ﴾ قَالَ الْفَارِسِيُّ أَيْ مِنْ إِحْدَى الْقَرْيَتَيْنِ وَلَيْسَ مِنْهُ ﴿وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ﴾ وَأَنَّ الْمَعْنَى جَنَّةٌ وَاحِدَةٌ خِلَافًا لِلْفَرَّاءِ وَفِي كِتَابِ\\\"ذَا الْقَدِّ\\\" لِابْنِ جِنِّي أَنَّ مِنْهُ ﴿أَأَنْتَ قُلْتَ لِلنَّاسِ اتَّخِذُونِي وَأُمِّيَ إِلَهَيْنِ﴾ وَإِنَّمَا الْمُتَّخَذُ إِلَهًا عِيسَى دُونَ مَرْيَمَ\",[[103,2,0,3,1],[70,19,0,3,1],[70,22,0,1,1],[50,24,0,2,1],[55,22,0,3,1],[35,12,11,18,1],[71,16,0,3,1],[18,61,4,5,1],[18,63,6,8,1],[2,203,5,8,1],[43,31,5,9,1],[55,46,0,4,1],[5,116,6,11,1]]],[52,\"\",3,130,130,894,\"وَمِثَالُ إِطْلَاقِهِ عَلَى الْجَمْعِ ﴿ثُمَّ ارْجِعِ الْبَصَرَ كَرَّتَيْنِ﴾ أَيْ كَرَّاتٍ لِأَنَّ الْبَصَرَ لَا يُحْسَرُ إِلَّا بِهَا وَجَعَلَ مِنْهُ بَعْضُهُمْ قَوْلَهَ: ﴿الطَّلاقُ مَرَّتَانِ﴾\",[[67,4,0,3,1],[2,229,0,1,1]]],[52,\"\",3,130,131,894,\"وَمِثَالُ إِطْلَاقِ الْجَمْعِ عَلَى الْمُفْرَدِ: ﴿قَالَ رَبِّ ارْجِعُونِ﴾،أَيْ أَرْجِعْنِي وَجَعَلَ مِنْهُ ابْنُ فَارِسٍ: ﴿فَنَاظِرَةٌ بِمَ يَرْجِعُ الْمُرْسَلُونَ﴾ وَالرَّسُولُ وَاحِدٌ بِدَلِيلِ ﴿ارْجِعْ إِلَيْهِمْ﴾ وَفِيهِ نَظَرٌ لِأَنَّهُ يُحْتَمَلُ أَنَّهُ خَاطَبَ رَئِيسَهُمْ لا سيما وعادة الملوك جارية ألا يُرْسِلُوا وَاحِدًا وَجَعَلَ مِنْهُ ﴿فَنَادَتْهُ الْمَلائِكَةُ﴾ ﴿يُنَزِّلُ الْمَلائِكَةَ بِالرُّوحِ﴾ أَيْ جِبْرِيلَ ﴿وَإِذْ قَتَلْتُمْ نَفْسًا فَادَّارَأْتُمْ فِيهَا﴾ وَالْقَاتِلُ وَاحِدٌ\",[[23,99,5,7,1],[27,35,4,7,1],[27,37,0,1,1],[3,39,0,1,1],[16,2,0,2,1],[2,72,0,4,1]]],[52,\"\",3,131,131,895,\"وَمِثَالُ إِطْلَاقِهِ عَلَى الْمُثَنَّى: ﴿قَالَتَا أَتَيْنَا طَائِعِينَ﴾ ﴿قَالُوا لا تَخَفْ خَصْمَانِ﴾، ﴿فَإِنْ كَانَ لَهُ إِخْوَةٌ فَلِأُمِّهِ السُّدُسُ﴾ أَيْ أَخَوَانِ ﴿فَقَدْ صَغَتْ قُلُوبُكُمَا﴾ أَيْ قَلْبَاكُمَا ﴿وَدَاوُدَ وَسُلَيْمَانَ إِذْ يَحْكُمَانِ فِي الْحَرْثِ﴾ إِلَى قَوْلِهِ ﴿وَكُنَّا لِحُكْمِهِمْ شَاهِدِينَ﴾\",[[41,11,13,15,1],[38,22,6,9,1],[4,11,42,47,1],[66,4,4,6,1],[21,78,0,5,1],[21,78,11,13,1]]],[52,\"\",3,131,131,895,\"وَمِنْهَا إِطْلَاقُ الْمَاضِي عَلَى الْمُسْتَقْبَلِ لِتَحَقُّقِ وُقُوعِهِ نَحْوُ: ﴿أَتَى أَمْرُ اللَّهِ﴾ أَيِ السَّاعَةُ بِدَلِيلِ ﴿فَلا تَسْتَعْجِلُوهُ﴾ ﴿وَنُفِخَ فِي الصُّورِ فَصَعِقَ مَنْ فِي السَّمَاوَاتِ﴾ ﴿وَإِذْ قَالَ اللَّهُ يَا عِيسَى ابْنَ مَرْيَمَ أَأَنْتَ قُلْتَ لِلنَّاسِ﴾ الآية ﴿وَبَرَزُوا لِلَّهِ جَمِيعًا﴾ ﴿وَنَادَى أَصْحَابُ الأَعْرَافِ﴾\",[[16,1,0,4,1],[39,68,0,6,1],[5,116,0,8,1],[14,21,0,2,1],[7,48,0,2,1]]],[52,\"\",3,131,132,895,\"وَعَكْسُهُ لِإِفَادَةِ الدَّوَامِ وَالِاسْتِمْرَارِ فَكَأَنَّهُ وَقَعَ وَاسْتَمَرَّ نَحْوُ: ﴿أَتَأْمُرُونَ النَّاسَ بِالْبِرِّ وَتَنْسَوْنَ﴾ ﴿وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ﴾ أي تلت ﴿وَلَقَدْ نَعْلَمُ﴾ أَيْ عَلِمْنَا ﴿قَدْ يَعْلَمُ مَا أَنْتُمْ عَلَيْهِ﴾ أَيْ عَلِمَ، ﴿فَلِمَ تَقْتُلُونَ أَنْبِيَاءَ اللَّهِ﴾ أي قتلتم، ﴿فَفَرِيقًا كَذَّبْتُمْ وَفَرِيقًا تَقْتُلُونَ﴾ ﴿وَيَقُولُ الَّذِينَ كَفَرُوا لَسْتَ مُرْسَلًا﴾ أَيْ قَالُوا\",[[2,44,0,3,1],[2,102,0,6,1],[6,33,0,1,3],[15,97,0,1,3],[16,103,0,1,3],[24,64,7,11,1],[2,91,21,24,1],[2,87,24,27,1],[13,43,0,4,1]]],[52,\"\",3,132,132,896,\"وَمِنْ لَوَاحِقَ ذَلِكَ التَّعْبِيرُ عَنِ الْمُسْتَقْبَلِ بِاسْمِ الْفَاعِلِ أَوِ الْمَفْعُولِ، لِأَنَّهُ حَقِيقَةٌ فِي الْحَالِ لَا فِي الِاسْتِقْبَالِ نَحْوُ: ﴿وَإِنَّ الدِّينَ لَوَاقِعٌ﴾ ﴿ذَلِكَ يَوْمٌ مَجْمُوعٌ لَهُ النَّاسُ﴾\",[[51,6,0,2,1],[11,103,8,12,1]]],[52,\"\",3,132,133,896,\"وَمِنْهَا إِطْلَاقُ الْخَبَرِ عَلَى الطَّلَبِ أَمْرًا أَوْ نَهْيًا أَوْ دُعَاءً مُبَالِغَةً فِي الْحَثِّ عَلَيْهِ حَتَّى كَأَنَّهُ وَقَعَ وَأَخْبَرَ عَنْهُ قَالَ الزَّمَخْشَرِيُّ وُرُودُ الْخَبَرِ وَالْمُرَادُ الْأَمْرُ أَوِ النَّهْيُ أَبْلَغُ مِنْ صَرِيحِ الْأَمْرِ أَوِ النَّهْيِ كَأَنَّهُ سُورِعَ فِيهِ إِلَى الِامْتِثَالِ وَأُخْبِرَ عَنْهُ نَحْوُ: ﴿وَالْوَالِدَاتُ يُرْضِعْنَ﴾ ﴿وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ﴾ \\\"فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الحج\\\" على قراءة، الرافع ﴿وَمَا تُنْفِقُونَ إِلاَّ ابْتِغَاءَ وَجْهِ اللَّهِ﴾ أَيْ لَا تُنْفِقُوا إِلَّا ابْتِغَاءَ وَجْهِ اللَّهِ ﴿لَا يَمَسُّهُ إِلاَّ الْمُطَهَّرُونَ﴾ أي لا يمسسه ﴿وَإِذْ أَخَذْنَا مِيثَاقَ بَنِي إِسْرائيلَ لَا تَعْبُدُونَ إِلاَّ اللَّهَ﴾، أَيْ لَا تَعْبُدُوا بِدَلِيلِ ﴿وَقُولُوا لِلنَّاسِ حُسْنًا﴾ ﴿لَا تَثْرِيبَ عَلَيْكُمُ الْيَوْمَ يَغْفِرُ اللَّهُ لَكُمْ﴾، أَيِ اللَّهُمَّ اغْفِرْ لَهُمْ وَعَكْسُهُ، نَحْوُ: ﴿فَلْيَمْدُدْ لَهُ الرَّحْمَنُ مَدًّا﴾ أَيْ يَمُدُّ، ﴿اتَّبِعُوا سَبِيلَنَا وَلْنَحْمِلْ خَطَايَاكُمْ﴾ أي ونحن حاملون بدليل ﴿وَإِنَّهُمْ لَكَاذِبُونَ﴾ وَالْكَذِبُ إِنَّمَا يَرِدُ عَلَى الْخَبَرِ، ﴿فَلْيَضْحَكُوا قَلِيلًا وَلْيَبْكُوا كَثِيرًا﴾ قَالَ الْكَوَاشِيُّ: فِي الْآيَةِ الْأَوْلَى الْأَمْرُ بِمَعْنَى الْخَبَرِ أَبْلَغُ مِنَ الْخَبَرِ لِتَضَمُّنِهِ اللُّزُومَ نَحْوُ: \\\"إِنْ زُرْتَنَا فَلْنُكْرِمْكَ\\\" يُرِيدُونَ تَأْكِيدَ إِيجَابِ الْإِكْرَامِ عَلَيْهِمْ وَقَالَ ابْنُ عَبْدِ السَّلَامِ: لِأَنَّ الْأَمْرَ لِلْإِيجَابِ فَشُبِّهَ الخبر به في إيجابه.\",[[2,233,0,1,1],[2,228,0,1,1],[2,272,13,18,1],[56,79,0,3,1],[2,83,0,8,1],[2,83,15,17,1],[12,92,1,7,1],[19,75,5,8,1],[29,12,5,8,1],[29,12,16,17,1],[9,82,0,3,1]]],[52,\"\",3,133,133,897,\"منها: وَضَعُ النِّدَاءِ مَوْضِعَ التَّعَجُّبِ نَحْوُ: ﴿يَا حَسْرَةً عَلَى الْعِبَادِ﴾ قال الفراء: معناه فيالها حَسْرَةً وَقَالَ ابْنُ خَالَوَيْهِ: هَذِهِ مِنْ أَصْعَبِ مَسْأَلَةٍ فِي الْقُرْآنِ لِأَنَّ الْحَسْرَةَ لَا تُنَادَى وَإِنَّمَا يُنَادَى الْأَشْخَاصُ لِأَنَّ فَائِدَتَهُ التَّنْبِيهُ وَلَكِنَّ الْمَعْنَى عَلَى التَّعَجُّبِ.\",[[36,30,0,2,1]]],[52,\"\",3,133,133,897,\"وَمِنْهَا وَضْعُ جَمْعِ الْقِلَّةَ مَوْضِعَ الْكَثْرَةِ، نَحْوُ: ﴿وَهُمْ فِي الْغُرُفَاتِ آمِنُونَ﴾ وَغُرَفُ الْجَنَّةِ لَا تُحْصَى، ﴿لَهُمْ دَرَجَاتٌ عِنْدَ رَبِّهِمْ﴾ وَرُتَبُ النَّاسِ فِي عِلْمِ اللَّهِ أَكْثَرُ مِنَ الْعَشَرَةِ لَا مَحَالَةَ، ﴿اللَّهُ يَتَوَفَّى الأَنْفُسَ﴾ ﴿أَيَّامًا مَعْدُودَاتٍ﴾ وَنُكْتَةُ التَّقْلِيلِ، فِي هَذِهِ الْآيَةِ التَّسْهِيلُ عَلَى الْمُكَلَّفِينَ\",[[34,37,19,22,1],[8,4,4,7,1],[39,42,0,2,1],[2,184,0,1,3],[2,203,3,4,3],[3,24,7,8,3]]],[52,\"\",3,133,133,897,\"وَعَكْسُهُ نَحْوُ: ﴿يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ ثَلاثَةَ قُرُوءٍ﴾\",[[2,228,1,4,1]]],[52,\"\",3,133,134,897,\"وَمِنْهَا تَذْكِيرُ الْمُؤَنَّثِ عَلَى تَأْوِيلِهِ بِمُذَكَّرٍ، نَحْوُ: ﴿فَمَنْ جَاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ﴾ أَيْ وُعِظَ ﴿وَأَحْيَيْنَا بِهِ بَلْدَةً مَيْتًا﴾ عَلَى تَأْوِيلِ الْبَلْدَةِ بِالْمَكَانِ ﴿فَلَمَّا رَأى الشَّمْسَ بَازِغَةً قَالَ هَذَا رَبِّي﴾ أَيِ الشَّمْسُ أَوِ الطَّالِعُ ﴿إِنَّ رَحْمَتَ اللَّهِ قَرِيبٌ مِنَ الْمُحْسِنِينَ﴾ قَالَ الْجَوْهَرِيُّ: ذُكِرَتْ عَلَى مَعْنَى الْإِحْسَانِ وَقَالَ الشَّرِيفُ الْمُرْتَضَى فِي قَوْلِهِ: ﴿وَلا يَزَالُونَ مُخْتَلِفِينَ إِلاَّ مَنْ رَحِمَ رَبُّكَ وَلِذَلِكَ خَلَقَهُمْ﴾: إِنَّ الْإِشَارَةَ لِلرَّحْمَةِ وَإِنَّمَا لَمْ يَقُلْ \\\"وَلِتِلْكَ\\\" لِأَنَّ تَأْنِيثَهَا غَيْرُ حَقِيقِيٍّ وَلِأَنَّهُ يَجُوزُ أَنْ يَكُونَ فِي تَأْوِيلِ \\\"أَنْ يَرْحَمَ\\\"\",[[2,275,25,29,1],[50,11,2,5,1],[6,78,0,6,1],[7,56,9,14,1],[11,118,7,9,1],[11,119,0,5,1]]],[52,\"\",3,134,134,898,\"وَمِنْهَا تَأْنِيثُ الْمُذَكَّرِ نَحْوُ: ﴿الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا﴾ أَنَّثَ الْفِرْدَوْسَ وَهُوَ مُذَكَّرٌ حَمْلًا عَلَى مَعْنَى الْجَنَّةِ ﴿مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا﴾ أنت \\\"عَشْرًا\\\" حَيْثُ حَذَفَ الْهَاءَ مَعَ إِضَافَتِهَا إِلَى \\\"الْأَمْثَالِ\\\" وَوَاحِدُهَا مُذَكِّرٌ فَقِيلَ لِإِضَافَةِ الْأَمْثَالِ إِلَى مُؤَنَّثٍ وَهُوَ ضَمِيرُ الْحَسَنَاتِ فَاكْتَسَبَ مِنْهُ التَّأْنِيثَ وَقِيلَ هُوَ مِنْ بَابِ مُرَاعَاةِ الْمَعْنَى لِأَنَّ \\\"الْأَمْثَالَ\\\" فِي الْمَعْنَى مُؤَنَّثَةٌ لِأَنَّ مِثْلَ الْحَسَنَةِ حَسَنَةٌ وَالتَّقْدِيرُ فَلَهُ عَشْرُ حَسَنَاتٍ أَمْثَالُهُا وَقَدْ قَدَّمْنَا فِي الْقَوَاعِدِ الْمُهِمَّةِ قَاعِدَةً فِي التَّذْكِيرِ وَالتَّأْنِيثِ\",[[23,11,0,4,1],[6,160,0,5,1]]],[52,\"\",3,134,135,898,\"وَمِنْهَا التَّغْلِيبُ وَهُوَ إِعْطَاءُ الشَّيْءِ حُكْمَ غَيْرِهِ: وَقِيلَ تَرْجِيحُ أَحَدِ المعلومين عَلَى الْآخَرِ وَإِطْلَاقُ لَفْظِهِ عَلَيْهِمَا إِجْرَاءً لِلْمُخْتَلِفِينَ مَجْرَى الْمُتَّفِقِينَ، نَحْوُ: ﴿وَكَانَتْ مِنَ الْقَانِتِينَ﴾ ﴿إِلاَّ امْرَأَتَهُ كَانَتْ مِنَ الْغَابِرِينَ﴾ وَالْأَصْلُ \\\"مِنَ الْقَانِتَاتِ\\\" وَ\\\"الْغَابِرَاتِ\\\" فَعُدَّتِ الْأُنْثَى مِنَ الْمُذَكِّرِ بِحُكْمِ التَّغْلِيبِ، ﴿بَلْ أَنْتُمْ قَوْمٌ تَجْهَلُونَ﴾ أَتَى بِتَاءِ الْخِطَابِ تَغْلِيبًا لِجَانِبِ \\\"أَنْتُمْ\\\" عَلَى جَانِبِ \\\"قَوْمٌ\\\" وَالْقِيَاسُ أَنْ يُؤْتَى بِيَاءِ الْغَيْبَةِ لِأَنَّهُ صفة \\\"لقوم\\\" وَحَسَّنَ الْعُدُولَ عَنْهُ وُقُوعُ الْمَوْصُوفِ خَبَرًا عَنْ ضَمِيرِ الْمُخَاطَبِينَ ﴿قَالَ اذْهَبْ فَمَنْ تَبِعَكَ مِنْهُمْ فَإِنَّ جَهَنَّمَ جَزَاؤُكُمْ﴾ غَلَبَ فِي الضَّمِيرِ الْمُخَاطَبِ وَإِنْ كَانَ \\\"مَنْ تَبِعَكَ\\\" يَقْتَضِي الْغَيْبَةَ وَحَسَّنَهُ أَنَّهُ لَمَّا كَانَ الْغَائِبُ تَبَعًا لِلْمُخَاطِبِ فِي الْمَعْصِيَةِ وَالْعُقُوبَةِ جُعِلَ تَبَعًا لَهُ فِي اللَّفْظِ أَيْضًا وَهَوَ مِنْ مَحَاسِنِ ارْتِبَاطِ اللَّفْظِ بِالْمَعْنَى ﴿وَلِلَّهِ يَسْجُدُ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ﴾ غَلَّبَ غَيْرَ الْعَاقِلِ حَيْثُ أَتَى بِ \\\"مَا\\\" لِكَثْرَتِهِ وَفِي آيَةٍ أُخْرَى بِ \\\"مِنْ\\\" فَغَلَّبَ الْعَاقِلَ لشرفه ﴿لَنُخْرِجَنَّكَ يَا شُعَيْبُ وَالَّذِينَ آمَنُوا مَعَكَ مِنْ قَرْيَتِنَا أَوْ لَتَعُودُنَّ فِي مِلَّتِنَا﴾ أَدْخَلَ شُعَيْبٌ فِي \\\"لَتَعُودُنَّ \\\"بِحُكْمِ التَّغْلِيبِ، إِذْ لَمْ يَكُنْ فِي مِلَّتِهِمْ أَصْلًا حَتَّى يَعُودَ فِيهَا وَكَذَا قَوْلُهُ ﴿إِنْ عُدْنَا فِي مِلَّتِكُمْ﴾ ﴿فَسَجَدَ الْمَلائِكَةُ كُلُّهُمْ أَجْمَعُونَ إِلاَّ إِبْلِيسَ﴾ عُدَّ مِنْهُمْ بِالِاسْتِثْنَاءِ تَغْلِيبًا لِكَوْنِهِ كَانَ بَيْنَهُمْ ﴿يَا لَيْتَ بَيْنِي وَبَيْنَكَ بُعْدَ الْمَشْرِقَيْنِ﴾ أَيِ الِمَشْرِقِ وَالْمَغْرِبِ قَالَ ابْنُ الشَّجَرِيِّ: وَغَلَّبَ الْمَشْرِقَ لِأَنَّهُ أَشْهَرُ الجهتين ﴿مَرَجَ الْبَحْرَيْنِ﴾ أَيِ الِمِلْحِ وَالْعَذْبِ وَالْبَحْرُ خَاصٌّ بِالْمِلْحِ فَغُلِّبَ لِكَوْنِهِ أَعْظَمَ ﴿وَلِكُلٍّ دَرَجَاتٌ﴾ أَيْ مِنَ الْمُؤْمِنِينَ وَالْكُفَّارِ وَالدَّرَجَاتُ لِلْعُلُوِّ وَالدَّرَكَاتُ لِلسُّفْلِ فَاسْتَعْمَلَ الدَّرَجَاتِ فِي الْقِسْمَيْنِ تَغْلِيبًا لِلْأَشْرَفِ\",[[66,12,14,16,1],[7,83,2,6,1],[27,55,7,10,1],[17,63,0,7,1],[16,49,0,7,1],[7,89,5,8,1],[15,30,0,3,2],[15,31,0,1,2],[38,73,0,3,2],[38,74,0,1,2],[43,38,4,8,1],[25,53,2,3,2],[55,19,0,1,2],[6,132,0,1,2],[46,19,0,1,2]]],[52,\"\",3,136,136,900,\"وَاخْتَلَفُوا أَيُّهُمَا أَوْلَى فَقَالَ أَهْلُ اللُّغَةِ وَقَوْمٌ مِنَ النُّحَاةِ التَّوَسُّعُ فِي الْحَرْفِ وَقَالَ الْمُحَقِّقُونَ التَّوَسُّعُ فِي الْفِعْلِ لِأَنَّهُ فِي الْأَفْعَالِ أَكْثَرُ مِثَالُهُ ﴿عَيْنًا يَشْرَبُ بِهَا عِبَادُ اللَّهِ﴾ فَيَشْرَبُ إِنَّمَا يَتَعَدَّى بِمِنْ فَتَعْدِيَتُهُ بِالْبَاءِ إِمَّا عَلَى تَضْمِينِهِ مَعْنَى \\\"يروي\\\" و\\\"يَلْتَذُّ\\\" أَوْ تَضْمِينِ الْبَاءِ مَعْنَى \\\"من\\\" نحو ﴿أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ إِلَى نِسَائِكُمْ﴾ فَالرَّفَثُ لَا يَتَعَدَّى بِإِلَى إِلَّا عَلَى تَضَمُّنِ معنى الإفضاء ﴿فَقُلْ هَلْ لَكَ إِلَى أَنْ تَزَكَّى﴾\",[[76,6,0,4,1],[2,187,0,6,1],[79,18,0,5,1]]],[52,\"\",3,136,136,900,\"والأصل \\\"في أن\\\" فضمن مَعْنَى \\\"أَدْعُوكَ\\\"، ﴿وَهُوَ الَّذِي يَقْبَلُ التَّوبَةَ عَنْ عِبَادِهِ﴾ عُدِّيَتْ بِعَنْ لِتَضَمُّنِهَا مَعْنَى الْعَفْوِ وَالصَّفْحِ\",[[42,25,0,5,1]]],[52,\"\",3,136,137,900,\"وَأَمَّا فِي الْأَسْمَاءِ فَأَنْ يُضَمَّنَ اسْمٌ مَعْنَى اسْمٍ لِإِفَادَةِ مَعْنَى الِاسْمَيْنِ مَعًا نَحْوُ ﴿حَقِيقٌ عَلَى أَنْ لَا أَقُولَ عَلَى اللَّهِ إِلاَّ الْحَقَّ﴾ ضُمِّنَ \\\"حَقِيقٌ\\\" مَعْنَى \\\"حَرِيصٌ\\\" لِيُفِيدَ أَنَّهُ مَحْقُوقٌ بِقَوْلِ الْحَقِّ وَحَرِيصٌ عَلَيْهِ وَإِنَّمَا كَانَ التَّضْمِينُ مَجَازًا لِأَنَّ اللَّفْظَ لَمْ يُوضَعْ لِلْحَقِيقَةِ وَالْمَجَازِ مَعًا فَالْجَمْعُ بَيْنَهُمَا جائز.\",[[7,105,0,8,1]]],[52,\"\",3,137,137,901,\"قِسْمٌ يَتَوَقَّفُ عَلَيْهِ صِحَّةُ اللَّفْظِ وَمَعْنَاهُ مِنْ حَيْثُ الْإِسْنَادِ نَحْوُ: ﴿وَاسْأَلِ الْقَرْيَةَ﴾ أَيْ أَهْلَهَا إِذْ لَا يَصِحُّ إِسْنَادُ السُّؤَالِ إِلَيْهَا\",[[12,82,0,1,1]]],[52,\"\",3,137,137,901,\"وَقِسْمٌ يَتَوَقَّفُ عَلَيْهِ عَادَةً لَا شَرْعًا نَحْوُ: ﴿أَنِ اضْرِبْ بِعَصَاكَ الْبَحْرَ فَانْفَلَقَ﴾ أَيْ فَضَرَبَهُ\",[[26,63,3,7,1]]],[52,\"\",3,137,138,901,\"وَقِسْمٌ يَدُلُّ عَلَيْهِ دَلِيلٌ غَيْرُ شَرْعِيٍّ وَلَا هُوَ عَادَةً نَحْوُ: ﴿فَقَبَضْتُ قَبْضَةً مِنْ أَثَرِ الرَّسُولِ﴾ دَلَّ الدَّلِيلُ عَلَى أَنَّهُ إِنَّمَا قَبَضَ مِنْ أَثَرِ حَافِرِ فَرَسِ الرَّسُولِ وَلَيْسَ فِي هَذِهِ الْأَقْسَامِ مَجَازٌ إِلَّا الْأَوَّلَ. وَقَالَ الزَّنْجَانِيُّ فِي الْمِعْيَارِ: إِنَّمَا يَكُونُ مَجَازًا إِذَا تَغَيَّرَ حُكْمٌ فَأَمَّا إِذَا لَمْ يَتَغَيَّرْ كَحَذْفِ خبرالمبتدأ الْمَعْطُوفِ عَلَى جُمْلَةٍ فَلَيْسَ مَجَازًا إِذْ لَمْ يَتَغَيَّرْ حُكْمُ مَا بَقِيَ مِنَ الْكَلَامِ\",[[20,96,6,10,1]]],[52,\"\",3,138,138,902,\"وَقَالَ الْقَزْوِينِيُّ فِي الْإِيضَاحِ: مَتَى تَغَيَّرَ إِعْرَابُ الْكَلِمَةِ بِحَذْفٍ أَوْ زِيَادَةٍ فَهِيَ مَجَازٌ نَحْوُ: ﴿وَاسْأَلِ الْقَرْيَةَ﴾ ﴿لَيْسَ كَمِثْلِهِ شَيْءٌ﴾ فَإِنْ كَانَ الْحَذْفُ أَوِ الزِّيَادَةُ لَا يُوجِبُ تَغَيُّرَ الْإِعْرَابِ نَحْوُ: ﴿أَوْ كَصَيِّبٍ﴾ ﴿فَبِمَا رَحْمَةٍ﴾ فَلَا تُوصَفُ الْكَلِمَةُ بِالْمَجَازِ\",[[12,82,0,1,1],[42,11,13,15,1],[12,33,12,12,1],[3,159,0,1,1]]],[52,\"الْأَعْلَامُ\",3,140,140,904,\"ثَالِثُهَا: اللَّفْظُ الْمُسْتَعْمَلُ فِي الْمُشَاكَلَةِ نَحْوُ: ﴿وَمَكَرُوا وَمَكَرَ اللَّهُ﴾ ﴿وَجَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا﴾ ذَكَرَ بَعْضُهُمْ أَنَّهُ وَاسِطَةٌ بَيْنَ الْحَقِيقَةِ وَالْمَجَازِ قَالَ لِأَنَّهُ لَمْ يُوضَعْ لِمَا اسْتُعْمِلَ فِيهِ فَلَيْسَ حَقِيقَةً وَلَا عَلَاقَةً مُعْتَبَرَةً فَلَيْسَ مَجَازًا كَذَا فِي شَرْحِ بَدِيعِيَّةِ ابْنِ جَابِرٍ لِرَفِيقِهِ\",[[3,54,0,2,1],[42,40,0,3,1]]],[52,\"الْأَعْلَامُ\",3,141,141,905,\"لَهُمْ مَجَازُ الْمَجَازِ وَهُوَ أَنْ يَجْعَلَ الْمَجَازَ الْمَأْخُوذَ عَنِ الْحَقِيقَةِ بِمَثَابَةِ الْحَقِيقَةِ بِالنِّسْبَةِ إِلَى مَجَازٍ آخَرَ فَيَتَجَوَّزُ بِالْمَجَازِ الْأَوَّلِ عَنِ الثَّانِي لِعَلَاقَةٍ بَيْنَهُمَا كَقَوْلِهِ تَعَالَى: ﴿وَلَكِنْ لَا تُوَاعِدُوهُنَّ سِرًّا﴾ فَإِنَّهُ مَجَازٌ عَنْ مَجَازٍ فَإِنَّ الْوَطْءَ تُجَوِّزُ عَنْهُ بِالسِّرِّ لِكَوْنِهِ لَا يَقَعُ غَالِبًا إِلَّا فِي السِّرِّ وَتُجَوِّزُ بِهِ عَنِ الْعَقْدِ لِأَنَّهُ مُسَبَّبٌ عَنْهُ فَالْمُصَحِّحُ لِلْمَجَازِ الْأَوَّلِ الْمُلَازِمَةُ وَالثَّانِي السَّبَبِيَّةُ وَالْمَعْنَى \\\"لَا تُوَاعِدُوهُنَّ عَقْدَ نِكَاحٍ\\\"\",[[2,235,17,20,1]]],[52,\"الْأَعْلَامُ\",3,141,141,905,\"وَكَذَا قوله: ﴿وَمَنْ يَكْفُرْ بِالأِيمَانِ فَقَدْ حَبِطَ عَمَلُهُ﴾ فَإِنَّ قَوْلَهُ: ﴿لَا إِلَهَ إِلاَّ اللَّهُ﴾ مَجَازٌ عَنْ تَصْدِيقِ الْقَلْبِ بِمَدْلُولِ هَذَا اللَّفْظِ وَالْعَلَاقَةُ السَّبَبِيَّةُ لِأَنَّ تَوْحِيدَ اللِّسَانِ مُسَبَّبٌ عَنْ تَوْحِيدِ الْجَنَانِ وَالتَّعْبِيرُ بِ \\\"لَا إِلَهَ إِلَّا اللَّهُ\\\" عَنِ الْوَحْدَانِيَّةِ مِنْ مَجَازِ التَّعْبِيرِ بِالْقَوْلِ عَنِ الْمَقُولِ فِيهِ\",[[5,5,32,37,1],[37,35,5,8,2],[47,19,2,5,2]]],[52,\"الْأَعْلَامُ\",3,141,141,905,\"وَجَعَلَ مِنْهُ ابْنُ السَّيِّدِ قوله: ﴿أَنْزَلْنَا عَلَيْكُمْ لِبَاسًا﴾ فَإِنَّ الْمُنَزَّلَ عَلَيْهِمْ لَيْسَ هُوَ نَفْسُ اللِّبَاسِ بَلِ الْمَاءُ الْمُنْبِتُ لِلزَّرْعِ الْمُتَّخَذِ مِنْهُ الْغَزَلُ الْمَنْسُوجُ مِنْهُ اللِّبَاسُ.\",[[7,26,3,5,1]]],[53,\"\",3,142,143,906,\"وَأَدَوَاتُهُ حُرُوفٌ وَأَسْمَاءُ وَأَفْعَالٌ فَالْحُرُوفُ الْكَافُ نحو: ﴿كَرَمَادٍ﴾ وكأن نحو: ﴿كَأَنَّهُ رُؤُوسُ الشَّيَاطِينِ﴾ وَالْأَسْمَاءُ مِثْلٌ وَشِبْهٌ وَنَحْوُهُمَا مِمَّا يُشْتَقُّ مِنَ الْمُمَاثَلَةِ وَالْمُشَابَهَةِ قَالَ الطِّيبِيُّ: وَلَا تُسْتَعْمَلُ \\\"مَثَلُ\\\" إِلَّا فِي حَالٍ أَوْ صِفَةٍ لَهَا شَأْنٌ وَفِيهَا غَرَابَةٌ نَحْوُ: ﴿مَثَلُ مَا يُنْفِقُونَ فِي هَذِهِ الْحَيَاةِ الدُّنْيَا كَمَثَلِ رِيحٍ فِيهَا صِرٌّ﴾ وَالْأَفْعَالُ نَحْوُ: ﴿يَحْسَبُهُ الظَّمْآنُ مَاءً﴾ ﴿يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى﴾ قال في التخليص اتِّبَاعًا لِلسَّكَاكِيِّ: وَرُبَّمَا يُذْكَرُ فِعْلٌ يُنْبِئُ عَنِ التَّشْبِيهِ فَيُؤْتَى فِي التَّشْبِيهِ الْقَرِيبِ بِنَحْوِ: \\\"عَلِمْتُ زَيْدًا أَسَدًا\\\" الدَّالِّ عَلَى التَّحْقِيقِ\",[[14,18,5,5,1],[37,65,1,3,1],[3,117,0,10,1],[24,39,5,7,1],[20,66,6,11,1]]],[53,\"\",3,143,143,907,\"مِثَالُ الْأَوَّلِ: ﴿وَالْقَمَرَ قَدَّرْنَاهُ مَنَازِلَ حَتَّى عَادَ كَالْعُرْجُونِ الْقَدِيمِ﴾ ﴿كَأَنَّهُمْ أَعْجَازُ نَخْلٍ مُنْقَعِرٍ﴾\",[[36,39,0,6,1],[54,20,2,5,1]]],[53,\"\",3,143,144,907,\"وَمِثَالُ الثَّانِي: ﴿ثُمَّ قَسَتْ قُلُوبُكُمْ مِنْ بَعْدِ ذَلِكَ فَهِيَ كَالْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةً﴾ كَذَا مَثَّلَ بِهِ فِي الْبُرْهَانِ وَكَأَنَّهُ ظَنَّ أَنَّ التَّشْبِيهَ وَاقِعٌ فِي الْقَسْوَةِ وَهُوَ غَيْرُ ظَاهِرٍ بَلْ هُوَ وَاقِعٌ بَيْنِ الْقُلُوبِ وَالْحِجَارَةِ فَهُوَ مِنَ الْأَوَّلِ. وَمِثَالُ الثَّالِثِ: ﴿مَثَلُ الَّذِينَ كَفَرُوا بِرَبِّهِمْ أَعْمَالُهُمْ كَرَمَادٍ اشْتَدَّتْ بِهِ الرِّيحُ﴾\",[[14,18,0,8,1]]],[53,\"\",3,144,144,908,\"وَمِثَالُ الرَّابِعُ: لَمْ يَقَعْ فِي الْقُرْآنِ بَلْ مَنَعَهُ الْإِمَامُ أَصْلًا لِأَنَّ الْعَقْلَ مُسْتَفَادٌ مِنَ الْحِسِّ فَالْمَحْسُوسُ أَصْلٌ لِلْمَعْقُولِ وَتَشْبِيهُهُ بِهِ يَسْتَلْزِمُ جَعْلَ الْأَصْلِ فَرْعًا وَالْفَرْعَ أَصْلًا وَهُوَ غَيْرُ جَائِزٍ. وَقَدِ اخْتُلِفَ فِي قَوْلِهِ تَعَالَى: ﴿هُنَّ لِبَاسٌ لَكُمْ وَأَنْتُمْ لِبَاسٌ لَهُنَّ﴾\",[[2,187,7,12,1]]],[53,\"\",3,144,144,908,\"الثَّانِي: يَنْقَسِمُ بِاعْتِبَارِ وَجْهِهِ إِلَى مُفْرَدٍ وَمُرَكَّبٍ وَالْمُرَكَّبُ أَنْ يُنْتَزَعَ وَجْهُ الشَّبَهِ مِنْ أُمُورٍ مَجْمُوعٍ بَعْضُهَا إِلَى بَعْضٍ كَقَوْلِهِ: ﴿كَمَثَلِ الْحِمَارِ يَحْمِلُ أَسْفَارًا﴾ فَالتَّشْبِيهُ مُرَكَّبٌ مِنْ أَحْوَالِ الْحِمَارِ وَهُوَ حِرْمَانُ الِانْتِفَاعِ بِأَبْلَغِ نَافِعٍ مَعَ تَحَمُّلِ التَّعَبِ فِي اسْتِصْحَابِهِ\",[[62,5,7,10,1]]],[53,\"\",3,144,145,908,\"وَقَوْلُهُ: ﴿إِنَّمَا مَثَلُ الْحَيَاةِ الدُّنْيَا كَمَاءٍ أَنْزَلْنَاهُ مِنَ السَّمَاءِ﴾ إِلَى قَوْلِهِ: ﴿كَأَنْ لَمْ تَغْنَ بِالأَمْسِ﴾ فَإِنَّ فِيهِ عَشْرَ جُمَلٍ وَقْعَ التَّرْكِيبُ مِنْ مَجْمُوعِهَا بِحَيْثُ لَوْ سَقَطَ مِنْهَا شَيْءٌ اخْتَلَّ التَّشْبِيهُ إِذِ الْمَقْصُودُ تَشْبِيهُ حَالِ الدُّنْيَا فِي سُرْعَةِ تَقَضِّيهَا وَانْقِرَاضِ نَعِيمِهَا وَاغْتِرَارِ النَّاسِ بِهَا بِحَالِ مَاءٍ نَزَلَ مِنَ السَّمَاءِ وَأَنْبَتَ أَنْوَاعَ الْعُشْبِ وَزَيَّنَ بِزُخْرُفِهَا وَجْهَ الْأَرْضِ كَالْعَرُوسِ إِذَا أَخَذَتِ الثِّيَابَ الْفَاخِرَةَ حَتَّى إِذَا طَمِعَ أَهْلُهَا فِيهَا وَظَنُّوا أَنَّهَا مُسَلَّمَةٌ مِنَ الْجَوَائِحِ أَتَاهَا بِأْسُ اللَّهِ فَجْأَةً فَكَأَنَّهَا لَمْ تَكُنْ بِالْأَمْسِ وَقَالَ بَعْضُهُمْ: وَجْهُ تَشْبِيهِ الدُّنْيَا بِالْمَاءِ أَمْرَانِ: أَحَدُهُمَا: أَنَّ الْمَاءَ إِذَا أَخَذْتَ مِنْهُ فَوْقَ حَاجَتِكَ تَضَرَّرْتَ وَإِنْ أَخَذْتَ قَدَرَ الْحَاجَةِ انْتَفَعْتَ بِهِ فَكَذَلِكَ الدُّنْيَا.\",[[10,24,0,7,1],[10,24,34,37,1]]],[53,\"\",3,145,145,909,\"وَالثَّانِي: أَنَّ الْمَاءَ إِذَا طَبَّقْتَ عَلَيْهِ كَفَّكَ لِتَحْفَظَهُ لَمْ يَحْصُلْ فِيهِ شَيْءٌ فَكَذَلِكَ الدُّنْيَا. وَقَوْلُهُ: ﴿مَثَلُ نُورِهِ كَمِشْكَاةٍ فِيهَا مِصْبَاحٌ﴾ الْآيَةَ فَشَبَّهَ نُورَهُ الَّذِي يُلْقِيهِ فِي قَلْبِ الْمُؤْمِنِ بِمِصْبَاحٍ اجْتَمَعَتْ فِيهِ أَسْبَابُ الْإِضَاءَةِ إِمَّا بِوَضْعِهِ فِي مِشْكَاةٍ وَهِيَ الطَّاقَةُ الَّتِي لَا تَنْفُذُ وَكَوْنُهَا لَا تَنْفُذُ لِتَكُونَ أَجْمَعَ لِلْبَصَرِ وَقَدْ جُعِلَ فِيهَا مِصْبَاحٌ فِي دَاخِلِ زُجَاجَةٍ تُشْبِهُ الْكَوْكَبَ الدُّرِّيَّ فِي صَفَائِهَا وَدُهْنُ الْمِصْبَاحِ مِنْ أَصْفَى الْأَدْهَانِ وَأَقْوَاهَا وَقُودًا لِأَنَّهُ مَنْ زَيْتِ شجرة في وسط السراج لَا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍ فَلَا تُصِيبُهَا الشَّمْسُ فِي أَحَدِ طَرَفَيِ النَّهَارِ بَلْ تُصِيبُهَا الشَّمْسُ أَعْدَلَ إصابة وهذا مثل ضربه الله لِلْمُؤْمِنِ ثُمَّ ضَرَبَ لِلْكَافِرِ مَثَلَيْنِ أَحَدُهُمَا كَسَرَابٍ بِقِيعَةٍ وَالْآخَرُ كَظُلُمَاتٍ فِي بَحْرٍ لُجِّيٍّ إِلَى آخِرِهِ وَهُوَ أَيْضًا تَشْبِيهُ تَرْكِيبٍ.\",[[24,35,4,8,1]]],[53,\"\",3,145,145,909,\"أَحَدُهَا: تَشْبِيهُ مَا تَقَعُ عَلَيْهِ الْحَاسَّةُ بِمَا لَا تَقَعُ اعْتِمَادًا عَلَى مَعْرِفَةِ النَّقِيضِ وَالضِّدِّ فَإِنَّ إِدْرَاكَهُمَا أَبْلَغُ مِنْ إِدْرَاكِ الْحَاسَّةِ كقوله: ﴿طَلْعُهَا كَأَنَّهُ رُؤُوسُ الشَّيَاطِينِ﴾ شَبَّهَ بِمَا لَا يُشَكُّ أَنَّهُ قَبِيحٌ لِمَا حَصَلَ فِي نُفُوسِ النَّاسِ مِنْ بَشَاعَةِ صُورَةِ الشَّيَاطِينِ وَإِنْ لَمْ تَرَهَا عَيَانًا.\",[[37,65,0,3,1]]],[53,\"\",3,145,146,909,\"الثَّانِي: عَكْسُهُ وَهُوَ تَشْبِيهُ مَا لَا تَقَعُ عَلَيْهِ الْحَاسَّةُ بِمَا تَقَعُ عَلَيْهِ كَقَوْلِهِ: ﴿وَالَّذِينَ كَفَرُوا أَعْمَالُهُمْ كَسَرَابٍ بِقِيعَةٍ﴾ الآية أَخْرَجَ مَا لَا يُحَسُّ وَهُوَ الْإِيمَانُ إِلَى مَا يُحَسُّ وَهُوَ السَّرَابُ وَالْمَعْنَى الْجَامِعُ بُطْلَانُ التَّوَهُّمِ مَعَ شَدَّةِ الْحَاجَةِ وَعِظَمِ الْفَاقَةِ.\",[[24,39,0,4,1]]],[53,\"\",3,146,146,910,\"الثَّالِثُ: إِخْرَاجُ مَا لَمْ تَجْرِ الْعَادَةُ بِهِ إِلَى مَا جَرَتْ كَقَوْلِهِ تَعَالَى: ﴿وَإِذْ نَتَقْنَا الْجَبَلَ فَوْقَهُمْ كَأَنَّهُ ظُلَّةٌ﴾ وَالْجَامِعُ بَيْنَهُمَا الِارْتِفَاعُ فِي الصُّورَةِ.\",[[7,171,0,5,1]]],[53,\"\",3,146,146,910,\"الرَّابِعُ: إِخْرَاجُ مَا لَا يُعْلَمُ بِالْبَدِيهَةِ إِلَى مَا يُعْلَمُ بِهَا كَقَوْلِهِ: ﴿وَجَنَّةٍ عَرْضُهَا كَعَرْضِ السَّمَاءِ وَالأَرْضِ﴾ وَالْجَامِعُ الْعِظَمُ وَفَائِدَتُهُ التَّشْوِيقُ إِلَى الْجَنَّةِ بِحُسْنِ الصِّفَةِ وَإِفْرَاطِ السَّعَةِ.\",[[57,21,5,9,1]]],[53,\"\",3,146,146,910,\"الْخَامِسُ: إِخْرَاجُ مَا لَا قُوَّةَ لَهُ فِي الصِّفَةِ إِلَى مَا لَهُ قُوَّةٌ فِيهَا كَقَوْلِهِ تَعَالَى: ﴿وَلَهُ الْجَوَارِ الْمُنْشَآتُ فِي الْبَحْرِ كَالأَعْلامِ﴾ وَالْجَامِعُ فِيهِمَا الْعِظَمُ وَالْفَائِدَةُ إِبَانَةُ الْقُدْرَةِ عَلَى تَسْخِيرِ الْأَجْسَامِ الْعِظَامِ فِي أَلْطَفِ مَا يَكُونُ مِنَ الْمَاءِ وَمَا فِي ذَلِكَ مِنَ انْتِفَاعِ الْخَلْقِ بِحَمْلِ الْأَثْقَالِ وَقَطْعِهَا الْأَقْطَارَ الْبَعِيدَةَ فِي الْمَسَافَةِ الْقَرِيبَةِ وَمَا يُلَازِمُ ذَلِكَ مِنْ تَسْخِيرِ الرياح للإنسان فتضمن الكلام نبأ عَظِيمًا مِنَ الْفَخْرِ وَتَعْدَادِ النِّعَمِ وعلى هَذِهِ الْأَوْجُهِ الْخَمْسَةِ تَجْرِي تَشْبِيهَاتُ الْقُرْآنِ\",[[55,24,0,5,1]]],[53,\"\",3,146,146,910,\"مُؤَكَّدٍ: وَهُوَ مَا حُذِفَتْ فِيهِ الْأَدَاةُ نَحْوُ: ﴿وَهِيَ تَمُرُّ مَرَّ السَّحَابِ﴾ أَيْ مِثْلَ مَرِّ السَّحَابِ ﴿وَأَزْوَاجُهُ أُمَّهَاتُهُمْ﴾ ﴿وَجَنَّةٍ عَرْضُهَا السَّمَاوَاتُ وَالأَرْضُ﴾\",[[27,88,4,7,1],[33,6,5,6,1],[3,133,5,8,1]]],[53,\"\",3,147,147,911,\"الْأَصْلُ دُخُولُ أَدَاةِ التَّشْبِيهِ عَلَى الْمُشَبَّهِ بِهِ وَقَدْ تَدْخُلُ عَلَى الْمُشَبَّهِ إِمَّا لِقَصْدِ الْمُبَالَغَةِ فيقلب التشبيه ويجعل الْمُشَبَّهَ هُوَ الْأَصْلَ نَحْوُ: ﴿قَالُوا إِنَّمَا الْبَيْعُ مِثْلُ الرِّبا﴾ كَأَنَّ الْأَصْلَ أَنْ يَقُولُوا إِنَّمَا الرِّبَا مِثْلُ الْبَيْعِ لِأَنَّ الْكَلَامَ فِي الرِّبَا لَا فِي الْبَيْعِ فَعَدَلُوا عَنْ ذَلِكَ وَجَعَلُوا الرِّبَا أَصْلًا مُلْحَقًا بِهِ الْبَيْعُ فِي الجواز لأنه الْخَلِيقُ بِالْحَلِّ وَمِنْهُ قَوْلُهُ تَعَالَى: ﴿أَفَمَنْ يَخْلُقُ كَمَنْ لَا يَخْلُقُ﴾ فَإِنَّ الظَّاهِرَ الْعَكْسُ لِأَنَّ الْخِطَابَ لِعَبَدَةِ الْأَوْثَانِ الَّذِينَ سَمَّوْهَا آلِهَةً تَشْبِيهًا بِاللَّهِ ﷾ فَجَعَلُوا غَيْرَ الْخَالِقِ مِثْلَ الْخَالِقِ فَخُولِفَ فِي خِطَابِهِمْ لِأَنَّهُمْ بَالَغُوا فِي عِبَادَتِهِمْ وَغَلَوْا حَتَّى صَارَتْ عِنْدَهُمْ أَصْلًا فِي الْعِبَادَةِ فَجَاءَ الرَّدُّ عَلَى وَفْقِ ذَلِكَ\",[[2,275,15,19,1],[16,17,0,4,1]]],[53,\"\",3,147,147,911,\"وَإِمَّا لِوُضُوحِ الْحَالِ نَحْوُ: ﴿وَلَيْسَ الذَّكَرُ كَالأُنْثَى﴾ فَإِنَّ الْأَصْلَ \\\"وَلَيْسَ الْأُنْثَى كَالذَّكَرِ\\\" وَإِنَّمَا عُدِلَ عَنِ الْأَصْلِ لِأَنَّ الْمَعْنَى \\\"وَلَيْسَ الذَّكَرُ الَّذِي طَلَبْتُ كَالْأُنْثَى الَّتِي وُهِبْتُ\\\" وَقِيلَ: لِمُرَاعَاةِ الْفَوَاصِلِ لِأَنَّ قَبْلَهُ: ﴿إِنِّي وَضَعْتُهَا أُنْثَى﴾\",[[3,36,11,13,1],[3,36,4,6,1]]],[53,\"\",3,147,147,911,\"وَقَدْ تَدْخُلُ عَلَى غَيْرِهِمَا اعْتِمَادًا عَلَى فَهْمِ الْمُخَاطَبِ نَحْوُ: ﴿كُونُوا أَنْصَارَ اللَّهِ كَمَا قَالَ عِيسَى ابْنُ مَرْيَمَ﴾ الْآيَةَ الْمُرَادُ \\\"كُونُوا أَنْصَارَ اللَّهِ خَالِصِينَ فِي الِانْقِيَادِ كَشَأْنِ مُخَاطِبِي عِيسَى إِذْ قَالُوا.\\\"\",[[61,14,3,10,1]]],[53,\"\",3,148,148,912,\"وَكَذَا فِي السلب ومنه: ﴿يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ﴾ أَيْ فِي النُّزُولِ لَا فِي الْعُلُوِّ ﴿أَمْ نَجْعَلُ الْمُتَّقِينَ كَالْفُجَّارِ﴾ أَيْ فِي سُوءِ الْحَالِ أَيْ لَا نَجْعَلُهُمْ كَذَلِكَ\",[[33,32,0,5,1],[38,28,9,12,1]]],[53,\"\",3,148,148,912,\"نَعَمْ أُورِدَ عَلَى ذَلِكَ: ﴿مَثَلُ نُورِهِ كَمِشْكَاةٍ﴾ فَإِنَّهُ شَبَّهَ فِيهِ الْأَعْلَى بِالْأَدْنَى لَا فِي مَقَامِ السَّلْبِ وَأُجِيبَ بِأَنَّهُ لِلتَّقْرِيبِ إِلَى أَذْهَانِ الْمُخَاطَبِينَ إِذْ لَا أَعْلَى مِنْ نُورِهِ فَيُشَبَّهُ بِهِ.\",[[24,35,4,6,1]]],[53,\"\",3,149,150,913,\"وَقَالَ بَعْضُهُمْ: حَقِيقَةُ الِاسْتِعَارَةِ أَنْ تُسْتَعَارَ الْكَلِمَةُ مِنْ شَيْءٍ مَعْرُوفٍ بِهَا إِلَى شَيْءٍ لَمْ يُعْرَفْ بِهَا وَحِكْمَةُ ذَلِكَ إِظْهَارُ الْخَفِيِّ وَإِيضَاحُ الظَّاهِرِ الَّذِي لَيْسَ بِجَلِيٍّ أَوْ حُصُولُ الْمُبَالَغَةِ أَوِ الْمَجْمُوعِ مِثَالُ إِظْهَارِ الْخَفِيِّ: ﴿وَإِنَّهُ فِي أُمِّ الْكِتَابِ﴾ فَإِنَّ حَقِيقَتَهُ: \\\"وَأَنَّهُ فِي أَصْلِ الْكِتَابِ\\\" فَاسْتُعِيرَ لَفْظُ الْأُمِّ لِلْأَصْلِ لِأَنَّ الْأَوْلَادَ تَنْشَأُ مِنَ الْأُمِّ كما تنشأ الْفُرُوعِ مِنَ الْأُصُولِ وَحِكْمَةُ ذَلِكَ تَمْثِيلُ مَا لَيْسَ بِمَرْئِيٍّ حَتَّى يصيرمرئيا فَيَنْتَقِلُ السَّامِعُ مِنْ حَدِّ السَّمَاعِ إِلَى حَدِّ الْعَيَانِ وَذَلِكَ أَبْلَغُ فِي الْبَيِانِ وَمِثَالُ إِيضَاحِ مَا لَيْسَ بِجَلِيٍّ لِيَصِيرَ جَلِيًّا: ﴿وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ﴾ فَإِنَّ الْمُرَادَ أَمْرُ الْوَلَدِ بِالذُّلِّ لِوَالِدَيْهِ رَحْمَةً فَاسْتُعِيرَ لِلذُّلِّ أَوَّلًا \\\"جَانِبٌ\\\" ثُمَّ لِلْجَانِبِ جَنَاحٌ وَتَقْدِيرُ الِاسْتِعَارَةِ الْقَرِيبَةِ: \\\"وَاخْفِضْ لَهُمَا جَانِبَ الذُّلِّ\\\" أَيِ اخِفِضْ جَانِبَكَ ذُلًّا وَحِكْمَةُ الِاسْتِعَارَةِ فِي هَذَا جَعْلُ مَا لَيْسَ بِمَرْئِيٍّ مَرْئِيًّا لِأَجْلِ حُسْنِ الْبَيَانِ وَلَمَّا كَانَ الْمُرَادُ خَفْضَ جَانِبِ الْوَلَدِ لِلْوَالِدَيْنِ بِحَيْثُ لَا يُبْقِي الْوَلَدُ مِنَ الذُّلِّ لَهُمَا وَالِاسْتِكَانَةِ مُمْكِنًا احْتِيجَ فِي الِاسْتِعَارَةِ إِلَى مَا هُوَ أَبْلَغُ مِنَ الْأُولَى فَاسْتُعِيرَ لَفْظُ الْجَنَاحِ لِمَا فِيهِ مِنَ الْمَعَانِي الَّتِي لَا تَحْصُلُ مِنْ خَفْضِ الْجَانِبِ لِأَنَّ مَنْ يَمِيلُ جانبه إلى جهة السفلة أَدْنَى مَيْلٍ صَدَقَ عَلَيْهِ أَنَّهُ خَفَضَ جَانِبَهُ وَالْمُرَادُ خَفْضٌ يُلْصِقُ الْجَانِبَ بِالْأَرْضِ وَلَا يَحْصُلُ ذَلِكَ إِلَّا بِذِكْرِ الْجَنَاحِ كَالطَّائِرِ\",[[43,4,0,3,1],[17,24,0,3,1]]],[53,\"\",3,150,150,914,\"وَمِثَالُ الْمُبَالَغَةِ: ﴿وَفَجَّرْنَا الأَرْضَ عُيُونًا﴾ وَحَقِيقَتُهُ: \\\" وَفَجَّرْنَا عُيُونَ الْأَرْضِ \\\" وَلَوْ عَبَّرَ بِذَلِكَ لَمْ يَكُنْ فِيهِ مِنَ الْمُبَالَغَةِ مَا فِي الْأَوَّلِ الْمُشْعِرِ بِأَنَّ الْأَرْضَ كُلَّهَا صَارَتْ عُيُونًا.\",[[54,12,0,2,1]]],[53,\"\",3,150,151,914,\"أَحَدُهَا: اسْتِعَارَةُ مَحْسُوسٍ لِمَحْسُوسٍ بِوَجْهٍ مَحْسُوسٍ نَحْوُ: ﴿وَاشْتَعَلَ الرَّأْسُ شَيْبًا﴾ فالمستعارة مِنْهُ هُوَ النَّارُ وَالْمُسْتَعَارُ لَهُ الشَّيْبُ وَالْوَجْهُ هُوَ الِانْبِسَاطُ وَمُشَابَهَةُ ضَوْءِ النَّارِ لِبَيَاضِ الشَّيْبِ وَكُلُّ ذَلِكَ مَحْسُوسٌ وَهُوَ أَبْلَغُ مِمَّا لَوْ قِيلَ: \\\"اشْتَعَلَ شَيْبُ الرَّأْسِ\\\" لِإِفَادَةِ عُمُومِ الشَّيْبِ لِجَمِيعِ الرَّأْسِ وَمِثْلُهُ: ﴿وَتَرَكْنَا بَعْضَهُمْ يَوْمَئِذٍ يَمُوجُ فِي بَعْضٍ﴾ أَصْلُ الْمَوْجِ حَرَكَةُ الْمَاءِ فَاسْتُعْمِلَ فِي حَرَكَتِهِمْ عَلَى سَبِيلِ الِاسْتِعَارَةِ وَالْجَامِعُ سُرْعَةُ الِاضْطِرَابِ وَتَتَابُعُهُ فِي الكثرة ﴿وَالصُّبْحِ إِذَا تَنَفَّسَ﴾ اسْتُعِيرَ خُرُوجُ النَّفَسِ شَيْئًا فَشَيْئًا لِخُرُوجِ النُّورِ مِنَ الْمَشْرِقِ عِنْدَ انْشِقَاقِ الْفَجْرِ قَلِيلًا قَلِيلًا بِجَامِعِ التَّتَابُعِ عَلَى طَرِيقِ التَّدْرِيجِ وَكُلُّ ذَلِكَ مَحْسُوسٌ.\",[[19,4,6,8,1],[18,99,0,5,1],[81,18,0,2,1]]],[53,\"\",3,151,151,915,\"الثَّانِي: اسْتِعَارَةُ مَحْسُوسٍ لِمَحْسُوسٍ بِوَجْهٍ عَقْلِيٍّ قَالَ ابْنُ أَبِي الْإِصْبَعِ وَهِيَ أَلْطَفُ مِنَ الْأُولَى نَحْوُ: ﴿وَآيَةٌ لَهُمُ اللَّيْلُ نَسْلَخُ مِنْهُ النَّهَارَ﴾ فَالْمُسْتَعَارُ مِنْهُ السَّلْخُ الَّذِي هُوَ كَشْطُ الْجِلْدِ عَنِ الشَّاةِ وَالْمُسْتَعَارُ لَهُ كَشْفُ الضَّوْءِ عَنْ مَكَانِ اللَّيْلِ وَهُمَا حِسِّيَّانِ وَالْجَامِعُ مَا يُعْقَلُ مِنْ تَرَتُّبِ أَمْرٍ عَلَى آخَرَ وَحُصُولِهِ عَقِبَ حُصُولِهِ كَتَرَتُّبِ ظُهُورِ اللَّحْمِ عَلَى الْكَشْطِ وَظُهُورِ الظُّلْمَةِ عَلَى كَشْفِ الضَّوْءِ عَنْ مَكَانِ اللَّيْلِ وَالتَّرَتُّبُ أَمْرٌ عَقْلِيٌّ ومثله: ﴿فَجَعَلْنَاهَا حَصِيدًا﴾ أَصْلُ الْحَصِيدِ النَّبَاتُ وَالْجَامِعُ الْهَلَاكُ وَهُوَ أَمْرٌ عَقْلِيٌّ.\",[[36,37,0,5,1],[10,24,32,33,1]]],[53,\"\",3,151,151,915,\"الثَّالِثُ: اسْتِعَارَةُ مَعْقُولٍ لِمَعْقُولٍ بِوَجْهٍ عَقْلِيٍّ قَالَ ابْنُ أَبِي الْإِصْبَعِ وَهِيَ أَلْطَفُ الِاسْتِعَارَاتِ نَحْوُ ﴿مَنْ بَعَثَنَا مِنْ مَرْقَدِنَا﴾ الْمُسْتَعَارُ مِنْهُ الرُّقَادُ أَيِ النَّوْمُ وَالْمُسْتَعَارُ لَهُ الْمَوْتُ وَالْجَامِعُ عَدَمُ ظُهُورِ الْفِعْلِ وَالْكُلُّ عَقْلِيٌّ وَمِثْلُهُ: ﴿وَلَمَّا سَكَتَ عَنْ مُوسَى الْغَضَبُ﴾ الْمُسْتَعَارُ السُّكُوتُ وَالْمُسْتَعَارُ مِنْهُ السَّاكِتُ وَالْمُسْتَعَارُ لَهُ الْغَضَبُ.\",[[36,52,2,5,1],[7,154,0,4,1]]],[53,\"\",3,151,152,915,\"الرَّابِعُ: اسْتِعَارَةُ محسوس لمعقول بِوَجْهٍ عَقْلِيٍّ أَيْضًا نَحْوُ: ﴿مَسَّتْهُمُ الْبَأْسَاءُ وَالضَّرَّاءُ﴾ اسْتُعِيرَ الْمَسُّ وَهُوَ حَقِيقَةٌ فِي الْأَجْسَامِ وَهُوَ مَحْسُوسٌ لِمُقَاسَاةِ الشَّدَّةِ وَالْجَامِعُ اللُّحُوقُ وَهُمَا عَقْلِيَّانِ: ﴿بَلْ نَقْذِفُ بِالْحَقِّ عَلَى الْبَاطِلِ فَيَدْمَغُهُ﴾ فَالْقَذْفُ وَالدَّمْغُ مُسْتَعَارَانِ وَهُمَا مَحْسُوسَانِ وَالْحَقُّ وَالْبَاطِلُ مُسْتَعَارٌ لَهُمَا وَهُمَا مَعْقُولَانِ: ﴿ضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ أَيْنَ مَا ثُقِفُوا إِلاَّ بِحَبْلٍ مِنَ اللَّهِ وَحَبْلٍ مِنَ النَّاسِ﴾ اسْتُعِيرَ الْحَبَلُ الْمَحْسُوسُ لِلْعَهْدِ وَهُوَ مَعْقُولٌ ﴿فَاصْدَعْ بِمَا تُؤْمَرُ﴾ اسْتُعِيرَ الصَّدْعُ وَهُوَ كَسْرُ الزُّجَاجَةِ وَهُوَ مَحْسُوسٌ لِلتَّبْلِيغِ وَهُوَ مَعْقُولٌ وَالْجَامِعُ التَّأْثِيرُ وَهُوَ أَبْلَغُ مَنْ \\\"بَلَغَ\\\" وَإِنْ كَانَ بِمَعْنَاهُ لِأَنَّ تَأْثِيرَ الصَّدْعِ أَبْلَغُ مِنْ تَأْثِيرِ التَّبْلِيغِ فَقَدْ لَا يُؤَثِّرُ التَّبْلِيغُ وَالصَّدْعُ يُؤَثِّرُ جَزْمًا ﴿وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ﴾ قَالَ الرَّاغِبُ لَمَّا كَانَ الذُّلُّ عَلَى ضَرْبَيْنِ: ضَرْبٌ يَضَعُ الْإِنْسَانَ وَضَرْبٌ يَرْفَعُهُ وَقُصِدَ فِي هَذَا المكان إلى مَا يَرْفَعُ اسْتُعِيرَ لَفْظُ الْجَنَاحِ فَكَأَنَّهُ قِيلَ اسْتَعْمِلِ الذُّلَّ الَّذِي يَرْفَعُكَ عِنْدَ اللَّهِ وَكَذَا قَوْلُهُ: ﴿يَخُوضُونَ فِي آيَاتِنَا﴾ ﴿فَنَبَذُوهُ وَرَاءَ ظُهُورِهِمْ﴾ ﴿أَفَمَنْ أَسَّسَ بُنْيَانَهُ عَلَى تَقْوَى﴾ ﴿وَيَبْغُونَهَا عِوَجًا﴾ ﴿لِيُخْرِجَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ مِنَ الظُّلُمَاتِ إِلَى النُّورِ﴾ ﴿فَجَعَلْنَاهُ هَبَاءً مَنْثُورًا﴾ ﴿فِي كُلِّ وَادٍ يَهِيمُونَ﴾ ﴿وَلا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَى عُنُقِكَ﴾ كُلُّهَا مِنَ اسْتِعَارَةِ الْمَحْسُوسِ لِلْمَعْقُولِ وَالْجَامِعُ عَقْلِيٌّ.\",[[2,214,12,14,1],[21,18,0,5,1],[3,112,0,12,1],[15,94,0,2,1],[17,24,0,3,1],[6,68,3,5,1],[3,187,11,13,1],[9,109,0,4,1],[7,45,5,6,3],[11,19,5,6,3],[14,3,10,11,3],[65,11,6,14,1],[25,23,6,8,1],[26,225,3,6,1],[17,29,0,5,1]]],[53,\"\",3,152,153,916,\"الْخَامِسُ: اسْتِعَارَةُ مَعْقُولٍ لمحسوس والجماع عَقْلِيٌّ أَيْضًا نَحْوُ: ﴿إِنَّا لَمَّا طَغَا الْمَاءُ﴾ المستعار منه التكبر وَهُوَ عَقْلِيٌّ وَالْمُسْتَعَارُ لَهُ كَثْرَةُ الْمَاءِ وَهُوَ حِسِّيٌّ وَالْجَامِعُ الِاسْتِعْلَاءُ وهو عقلي أيضا مثله: ﴿تَكَادُ تَمَيَّزُ مِنَ الْغَيْظِ﴾ ﴿وَجَعَلْنَا آيَةَ النَّهَارِ مُبْصِرَةً﴾ وَتَنْقَسِمُ بِاعْتِبَارِ اللَّفْظِ إِلَى:\",[[69,11,0,3,1],[67,8,0,3,1],[17,12,7,10,1]]],[53,\"\",3,153,153,917,\"أَصْلِيَّةٍ: وَهِيَ مَا كَانَ اللَّفْظُ الْمُسْتَعَارُ فِيهَا اسْمُ جِنْسٍ كَآيَةِ: ﴿بِحَبْلِ اللَّهِ﴾ ﴿مِنَ الظُّلُمَاتِ إِلَى النُّورِ﴾ ﴿فِي كُلِّ وَادٍ﴾\",[[3,103,1,2,1],[26,225,3,5,1]]],[53,\"\",3,153,153,917,\"وَتَبَعِيَّةٍ: وَهِيَ مَا كَانَ اللَّفْظُ فِيهَا غَيْرُ اسْمِ جِنْسٍ كَالْفِعْلِ وَالْمُشْتَقَّاتِ كَسَائِرِ الْآيَاتِ السَّابِقَةِ وَكَالْحُرُوفِ نَحْوُ: ﴿فَالْتَقَطَهُ آلُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوًّا﴾ شَبَّهَ تَرَتُّبَ الْعَدَاوَةِ وَالْحُزْنِ عَلَى الِالْتِقَاطِ بِتَرَتُّبِ غَلَبَةِ الْغَائِيَّةِ عَلَيْهِ ثُمَّ اسْتُعِيرَ فِي الْمُشَبَّهِ اللَّامُ الْمَوْضُوعَةُ لِلْمُشَبَّهِ بِهِ.\",[[28,8,0,5,1]]],[53,\"\",3,153,153,917,\"فَالْأُولَى: وَهِيَ أَبْلَغُهَا أَنْ تَقْتَرِنَ بِمَا يُلَائِمُ الْمُسْتَعَارَ مِنْهُ نَحْوُ: ﴿أُولَئِكَ الَّذِينَ اشْتَرَوُا الضَّلالَةَ بِالْهُدَى فَمَا رَبِحَتْ تِجَارَتُهُمْ﴾ استعير الاشتراء للاستبدال والاختيار ثُمَّ قُرِنَ بِمَا يُلَائِمُهُ مِنَ الرِّبْحِ وَالتِّجَارَةِ.\",[[2,16,0,7,1]]],[53,\"\",3,153,153,917,\"وَالثَّانِيَةُ: أَنْ تُقْرَنَ بِمَا يُلَائِمُ الْمُسْتَعَارَ لَهُ نَحْوُ: ﴿فَأَذَاقَهَا اللَّهُ لِبَاسَ الْجُوعِ وَالْخَوْفِ﴾ اسْتُعِيرَ اللِّبَاسُ لِلْجُوعِ ثُمَّ قُرِنَ بِمَا يُلَائِمُ الْمُسْتَعَارَ لَهُ مِنَ الْإِذَاقَةِ وَلَوْ أَرَادَ التَّرْشِيحَ لَقَالَ \\\"فَكَسَاهَا\\\" لَكِنَّ التَّجْرِيدَ هُنَا أَبْلَغُ لِمَا فِي لَفْظِ الْإِذَاقَةِ مِنَ الْمُبَالَغَةِ فِي الْأَلَمِ بَاطِنًا\",[[16,112,16,20,1]]],[53,\"\",3,153,154,917,\"وَتَنْقَسِمُ بِاعْتِبَارٍ آخَرَ: إِلَى تَحْقِيقِيَّةٍ وَتَخْيِيلِيَّةٍ وَمَكْنِيَّةٍ وَتَصْرِيحِيَّةٍ: فَالْأُولَى: مَا تَحَقَّقَ مَعْنَاهَا حِسًّا نَحْوُ: ﴿فَأَذَاقَهَا اللَّهُ﴾ الْآيَةَ أَوْ عَقْلًا نَحْوُ: ﴿وَأَنْزَلْنَا إِلَيْكُمْ نُورًا مُبِينًا﴾ أَيْ بَيَانًا وَاضِحًا وَحُجَّةً لَامِعَةً ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ أَيِ الدِّينَ الْحَقَّ فَإِنَّ كُلًّا منهما يَتَحَقَّقُ عَقْلًا.\",[[16,112,16,17,1],[4,174,7,10,1],[1,6,0,2,1]]],[53,\"\",3,154,155,918,\"وَيُقَابِلُهُ التَّصْرِيحِيَّةُ وَيُسَمَّى إِثْبَاتُ ذَلِكَ الْأَمْرِ الْمُخْتَصِّ بِالْمُشَبَّهِ بِهِ لِلْمُشَبَّهِ اسْتِعَارَةً تَخْيِيلِيَّةً لِأَنَّهُ قَدِ اسْتُعِيرَ لِلْمُشَبَّهِ ذَلِكَ الْأَمْرُ الْمُخْتَصُّ بِالْمُشَبَّهِ بِهِ وَبِهِ يَكُونُ كَمَالُ الْمُشَبَّهِ بِهِ وَقِوَامُهُ فِي وَجْهِ الشَّبَهِ لِتَخَيُّلِ أَنَّ الْمُشَبَّهَ مِنْ جِنْسِ الْمُشَبَّهِ بِهِ وَمِنْ أَمْثِلَةِ ذَلِكَ: ﴿الَّذِينَ يَنْقُضُونَ عَهْدَ اللَّهِ مِنْ بَعْدِ مِيثَاقِهِ﴾ شبه العهد بِالْحَبْلِ وَأَضْمَرَ فِي النَّفْسِ فَلَمْ يُصَرِّحْ بِشَيْءٍ مِنْ أَرْكَانِ التَّشْبِيهِ سِوَى الْعَهْدِ الْمُشَبَّهِ وَدَلَّ عَلَيْهِ بِإِثْبَاتِ النَّقْضِ الَّذِي هُوَ مِنْ خَوَاصِّ الْمُشَبَّهِ بِهِ وَهُوَ الْحَبْلُ وَكَذَا: ﴿وَاشْتَعَلَ الرَّأْسُ شَيْبًا﴾ طَوَى ذِكْرَ الْمُشَبَّهِ بِهِ وَهُوَ النَّارُ وَدَلَّ عَلَيْهِ بِلَازِمِهِ وَهُوَ الاشتعال: ﴿فَأَذَاقَهَا اللَّهُ﴾ الْآيَةَ شَبَّهَ مَا يُدْرَكُ مِنْ أَثَرِ الضَّرَرِ وَالْأَلَمِ بِمَا يُدْرَكُ مِنْ طَعْمِ الْمُرِّ فَأَوْقَعَ عَلَيْهِ الْإِذَاقَةَ ﴿خَتَمَ اللَّهُ عَلَى قُلُوبِهِمْ﴾ شبهها في ألا تَقْبَلُ الْحَقَّ بِالشَّيْءِ الْمَوْثُوقِ الْمَخْتُومِ ثُمَّ أَثْبَتَ لَهَا الْخَتْمَ: ﴿جِدَارًا يُرِيدُ أَنْ يَنْقَضَّ﴾ شَبَّهَ مَيَلَانَهُ لِلسُّقُوطِ بِانْحِرَافِ الْحَيِّ فَأَثْبَتَ لَهُ الْإِرَادَةَ الَّتِي هِيَ مِنْ خَوَاصِّ الْعُقَلَاءِ\",[[2,27,0,6,1],[19,4,6,8,1],[16,112,16,17,1],[2,7,0,3,1],[18,77,13,16,1]]],[53,\"\",3,155,155,919,\"وَمِنَ التَّصْرِيحِيَّةِ آية: ﴿مَسَّتْهُمُ الْبَأْسَاءُ﴾ ﴿مَنْ بَعَثَنَا مِنْ مَرْقَدِنَا﴾\",[[2,214,12,13,1],[36,52,2,5,1]]],[53,\"\",3,155,155,919,\"وِفَاقِيَّةٍ: بِأَنْ يَكُونَ اجْتِمَاعُهُمَا فِي شَيْءٍ مُمْكِنًا نَحْوُ: ﴿أَوَمَنْ كَانَ مَيْتًا فَأَحْيَيْنَاهُ﴾ أَيْ ضَالًّا فَهَدَيْنَاهُ اسْتُعِيرَ الْإِحْيَاءُ مِنْ جَعْلِ الشَّيْءِ حَيًّا لِلْهِدَايَةِ الَّتِي بِمَعْنَى الدَّلَالَةِ عَلَى مَا يُوصِّلُ إِلَى الْمَطْلُوبِ وَالْإِحْيَاءُ وَالْهِدَايَةُ مِمَّا يُمْكِنُ اجْتِمَاعُهُمَا فِي شَيْءٍ.\",[[6,122,0,3,1]]],[53,\"\",3,155,155,919,\"وَمِنَ الْعِنَادِيَّةِ التَّهَكُّمِيَّةُ وَالتَّمْلِيحِيَّةُ وَهُمَا مَا اسْتُعْمِلَ فِي ضِدٍّ أَوْ نَقِيضٍ نَحْوُ: ﴿فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ﴾ أَيْ أَنْذِرْهُمْ اسْتُعِيرَتِ الْبِشَارَةُ وَهِيَ الْإِخْبَارُ بِمَا يَسُرُّ لِلْإِنْذَارِ الَّذِي هو ضده بإدخاله في جِنْسِهَا عَلَى سَبِيلِ التَّهَكُّمِ وَالِاسْتِهْزَاءِ ونحو: ﴿إِنَّكَ لأَنْتَ الْحَلِيمُ الرَّشِيدُ﴾ عنى الْغَوِيَّ السَّفِيهَ تَهَكُّمًا، ﴿ذُقْ إِنَّكَ أَنْتَ الْعَزِيزُ الْكَرِيمُ﴾\",[[3,21,15,17,3],[9,34,25,27,3],[84,24,0,2,3],[11,87,16,19,1],[44,49,0,4,1]]],[53,\"\",3,155,156,919,\"وَتَنْقَسِمُ بِاعْتِبَارٍ آخَرَ: إِلَى تَمْثِيلِيَّةٍ وَهِيَ أَنْ يَكُونَ وَجْهُ الشَّبَهِ فِيهَا مُنْتَزَعًا مِنْ مُتَعَدِّدٍ نَحْوُ: ﴿وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا﴾ شَبَّهَ اسْتِظْهَارَ الْعَبْدِ بِاللَّهِ وَوُثُوقَهُ بِحِمَايَتِهِ وَالنَّجَاةَ مِنَ الْمَكَارِهِ بِاسْتِمْسَاكِ الْوَاقِعِ فِي مَهْوَاةٍ بِحَبْلٍ وَثِيقٍ مُدَلًّى مِنْ مَكَانٍ مُرْتَفِعٍ يَأْمَنُ انْقِطَاعَهُ.\",[[3,103,0,3,1]]],[53,\"\",3,156,156,920,\"قَدْ تَكُونُ الِاسْتِعَارَةُ بِلَفْظَيْنِ نَحْوُ: ﴿قَوَارِيرَ قَوَارِيرَ مِنْ فِضَّةٍ﴾ يَعْنِي تِلْكَ الْأَوَانِي لَيْسَتْ مِنَ الزُّجَاجِ وَلَا مِنَ الْفِضَّةِ بَلْ فِي صَفَاءِ الْقَارُورَةِ وَبَيَاضِ الْفِضَّةِ\",[[76,15,7,7,1],[76,16,0,2,1]]],[53,\"\",3,156,156,920,\"﴿فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ﴾ فَالصَّبُّ كِنَايَةٌ عَنِ الدَّوَامِ وَالسَّوْطُ عَنِ الْإِيلَامِ فَالْمَعْنَى عَذَّبَهُمْ عَذَابًا دَائِمًا مُؤْلِمًا\",[[89,13,0,4,1]]],[53,\"\",3,157,158,921,\"قَالَ الزَّمَخْشَرِيُّ فِي قَوْلِهِ تَعَالَى: ﴿صُمٌّ بُكْمٌ عُمْيٌ﴾ فَإِنْ قُلْتَ: هَلْ يُسَمَّى مَا فِي الْآيَةِ استعارة قلت مختلف فِيهِ وَالْمُحَقِّقُونَ عَلَى تَسْمِيَتِهِ تَشْبِيهًا بَلِيغًا لَا اسْتِعَارَةً لِأَنَّ الْمُسْتَعَارَ لَهُ مَذْكُورٌ وَهُمُ الْمُنَافِقُونَ وَإِنَّمَا تُطْلَقُ الِاسْتِعَارَةُ حَيْثُ يُطْوَى ذِكْرُ الْمُسْتَعَارِ لَهُ وَيُجْعَلُ الْكَلَامُ خُلُوًّا عَنْهُ صَالِحًا لِأَنْ يُرَادَ الْمَنْقُولُ عَنْهُ وَالْمَنْقُولُ لَهُ لَوْلَا دَلَالَةُ الْحَالِ أَوْ فَحَوَى الْكَلَامِ وَمِنْ ثَمَّ تَرَى الْمُفْلِقِينَ السَّحَرَةَ يَتَنَاسَوْنَ التَّشْبِيهَ وَيَضْرِبُونَ عَنْهُ صَفْحًا\",[[2,18,0,2,2],[2,171,12,14,2]]],[54,\"\",3,159,159,923,\"أَحَدُهَا: التَّنْبِيهُ عَلَى عِظَمِ الْقُدْرَةِ نَحْوُ: ﴿هُوَ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ﴾ كِنَايَةٌ عَنْ آدَمَ\",[[7,189,0,5,1]]],[54,\"\",3,159,160,923,\"ثَانِيهَا: تَرْكُ اللَّفْظِ إِلَى مَا هُوَ أَجْمَلُ نَحْوُ: ﴿إِنَّ هَذَا أَخِي لَهُ تِسْعٌ وَتِسْعُونَ نَعْجَةً وَلِيَ نَعْجَةٌ وَاحِدَةٌ﴾ فَكَنَّى بِالنَّعْجَةِ عَنِ الْمَرْأَةِ كَعَادَةِ الْعَرَبِ فِي ذَلِكَ لِأَنَّ تَرْكَ التَّصْرِيحِ بِذِكْرِ النِّسَاءِ أَجْمَلُ مِنْهُ ولهذا لَمْ تُذْكَرْ فِي الْقُرْآنِ امْرَأَةٌ بِاسْمِهَا إِلَّا مَرْيَمَ قَالَ السُّهَيْلِيُّ وَإِنَّمَا ذُكِرَتْ مَرْيَمُ بِاسْمِهَا عَلَى خِلَافِ عَادَةِ الْفُصَحَاءِ لِنُكْتَةٍ وَهُوَ أَنَّ الْمُلُوكَ وَالْأَشْرَافَ لَا يَذْكُرُونَ حَرَائِرَهُمْ فِي مَلَإٍ وَلَا يَبْتَذِلُونَ أَسْمَاءَهُنَّ بَلْ يُكَنُّونَ عَنِ الزَّوْجَةِ بِالْفَرْشِ وَالْعِيَالِ وَنَحْوِ ذَلِكَ فَإِذَا ذَكَرُوا الْإِمَاءَ لَمْ يُكَنُّوا عَنْهُنَّ وَلَمْ يَصُونُوا أَسْمَاءَهُنَّ عَنِ الذِّكْرِ فَلَمَّا قَالَتِ النَّصَارَى فِي مَرْيَمَ مَا قَالُوا صَرَّحَ اللَّهُ بِاسْمِهَا وَلَمْ يَكُنْ تأكيدا للعبودية إلا الَّتِي هِيَ صِفَةٌ لَهَا وَتَأْكِيدًا لِأَنَّ عِيسَى لَا أَبَ لَهُ وَإِلَّا لَنُسِبَ إِلَيْهِ.\",[[38,23,0,9,1]]],[54,\"\",3,160,160,924,\"ثَالِثُهَا: أَنْ يَكُونَ التَّصْرِيحُ مِمَّا يُسْتَقْبَحُ ذِكْرُهُ كَكِنَايَةِ اللَّهِ عَنِ الْجِمَاعِ بِالْمُلَامِسَةِ وَالْمُبَاشِرَةِ وَالْإِفْضَاءِ وَالرَّفَثِ وَالدُّخُولِ وَالسِّرِّ في قوله: ﴿لا تُوَاعِدُوهُنَّ سِرًّا﴾ وَالْغَشَيَانِ فِي قَوْلِهِ ﴿فَلَمَّا تَغَشَّاهَا﴾ أَخْرَجَ ابْنُ أَبِي حَاتِمٍ عَنِ ابْنِ عَبَّاسٍ قَالَ الْمُبَاشَرَةُ الْجِمَاعُ وَلَكِنَّ اللَّهَ يُكَنِّي\",[[2,235,18,20,1],[7,189,11,12,1]]],[54,\"\",3,160,160,924,\"وَأَخْرَجَ عَنْهُ قَالَ إِنَّ اللَّهَ كَرِيمٌ يُكَنِّي مَا شَاءَ وَإِنَّ الرَّفَثَ هُوَ الْجِمَاعُ وَكَنَّى عَنْ طَلَبِهِ بِالْمُرَاوَدَةِ فِي قَوْلِهِ: ﴿وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَنْ نَفْسِهِ﴾ وَعَنْهُ أَوْ عَنِ الْمُعَانَقَةِ بِاللِّبَاسِ فِي قَوْلِهِ: ﴿هُنَّ لِبَاسٌ لَكُمْ وَأَنْتُمْ لِبَاسٌ لَهُنَّ﴾ وَبِالْحَرْثِ فِي قَوْلِهِ: ﴿نِسَاؤُكُمْ حَرْثٌ لَكُمْ﴾\",[[12,23,0,6,1],[2,187,7,12,1],[2,223,0,2,1]]],[54,\"\",3,160,160,924,\"وَكَنَّى عَنِ الْبَوْلِ وَنَحْوِهِ بِالْغَائِطِ فِي قَوْلِهِ: ﴿أَوْ جَاءَ أَحَدٌ مِنْكُمْ مِنَ الْغَائِطِ﴾ وَأَصْلُهُ الْمَكَانُ الْمُطَمْئِنُ مِنَ الْأَرْضِ\",[[4,43,26,30,2],[5,6,28,32,2]]],[54,\"\",3,160,160,924,\"وَكَنَّى عَنْ قَضَاءِ الْحَاجَةِ بِأَكْلِ الطَّعَامِ فِي قَوْلِهِ فِي مَرْيَمَ وابنها: ﴿كَانَا يَأْكُلانِ الطَّعَامَ﴾\",[[5,75,13,15,1]]],[54,\"\",3,160,160,924,\"وَكَنَّى عَنِ الْأَسْتَاهِ بِالْأَدْبَارِ فِي قَوْلِهِ: ﴿يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَارَهُمْ﴾\",[[8,50,7,9,2],[47,27,4,6,2]]],[54,\"\",3,160,161,924,\"وَأَوْرَدَ عَلَى ذَلِكَ التَّصْرِيحَ بِالْفَرْجِ فِي قوله: ﴿الَّتِي أَحْصَنَتْ فَرْجَهَا﴾ وَأُجِيبَ: بِأَنَّ الْمُرَادَ بِهِ فَرْجُ الْقَمِيصِ وَالتَّعْبِيرُ به من أَلْطَفُ الْكِنَايَاتِ وَأَحْسَنُهَا أَيْ لَمْ يَعْلَقْ ثَوْبُهَا بِرِيبَةٍ فَهِيَ طَاهِرَةُ الثَّوْبِ كَمَا يُقَالُ: نَقِيُّ الثَّوْبِ وَعَفِيفُ الذَّيْلِ كِنَايَةً عَنِ الْعِفَّةِ – وَمِنْهُ: ﴿وَثِيَابَكَ فَطَهِّرْ﴾ - وَكَيْفَ يُظَنُّ أَنَّ نَفْخَ جِبْرِيلَ وَقْعَ فِي فَرْجِهَا وَإِنَّمَا نَفَخَ فِي جَيْبِ دِرْعِهَا\",[[21,91,0,2,2],[66,12,3,5,2],[74,4,0,1,1]]],[54,\"\",3,161,161,925,\"وَنَظِيرُهُ أَيْضًا: ﴿وَلا يَأْتِينَ بِبُهْتَانٍ يَفْتَرِينَهُ بَيْنَ أَيْدِيهِنَّ وَأَرُجُلِهِنَّ﴾\",[[60,12,19,25,1]]],[54,\"\",3,161,161,925,\"رَابِعُهَا: قَصْدُ الْبَلَاغَةِ وَالْمُبَالَغَةِ نَحْوُ: ﴿أَوَمَنْ يُنَشَّأُ فِي الْحِلْيَةِ وَهُوَ فِي الْخِصَامِ غَيْرُ مُبِينٍ﴾، كَنَّى عَنِ النِّسَاءِ بِأَنَّهُنَّ يَنْشَأْنَ فِي التَّرَفُّهِ وَالتَّزَيُّنِ الشَّاغِلِ عَنِ النَّظَرِ فِي الْأُمُورِ وَدَقِيقِ الْمَعَانِي وَلَوْ أَتَى بِلَفْظِ \\\"النِّسَاءِ\\\" لَمْ يُشْعِرْ بِذَلِكَ وَالْمُرَادُ نَفْيُ ذَلِكَ عَنِ الْمَلَائِكَةِ وَقَوْلُهُ: ﴿بَلْ يَدَاهُ مَبْسُوطَتَانِ﴾ كِنَايَةٌ عَنْ سَعَةِ جُودِهِ وَكَرَمِهِ جِدًّا\",[[43,18,0,8,1],[5,64,10,12,1]]],[54,\"\",3,161,161,925,\"خَامِسُهَا: قَصْدُ الِاخْتِصَارِ كَالْكِنَايَةِ عَنْ أَلْفَاظٍ مُتَعَدِّدَةٍ بِلَفْظِ \\\"فَعَلَ\\\" نَحْوُ: ﴿لَبِئْسَ مَا كَانُوا يَفْعَلُونَ﴾ ﴿فَإِنْ لَمْ تَفْعَلُوا وَلَنْ تَفْعَلُوا﴾ أَيْ فَإِنْ لَمْ تَأْتُوا بِسُورَةٍ مِنْ مِثْلِهِ\",[[5,79,6,9,1],[2,24,0,4,1]]],[54,\"\",3,161,162,925,\"سَادِسُهَا: التَّنْبِيهُ عَلَى مَصِيرِهِ نَحْوُ: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ﴾ أَيْ جَهَنَّمِيٌّ مَصِيرُهُ إِلَى اللَّهَبِ ﴿حَمَّالَةَ الْحَطَبِ فِي جِيدِهَا حَبْلٌ﴾ أَيْ نَمَّامَةٌ مَصِيرُهَا إِلَى أَنْ تَكُونَ حَطَبًا لِجَهَنَّمَ فِي جِيدِهَا غُلٌّ قَالَ بِدُرُ الدِّينِ بْنُ مَالِكٍ فِي الْمِصْبَاحِ إِنَّمَا يُعْدَلُ عَنِ التصريح إلى الكناية لنكتة كَالْإِيضَاحِ أَوْ بَيَانِ حَالِ الْمَوْصُوفِ أَوْ مِقْدَارِ حَالِهِ أَوِ الْقَصْدِ إِلَى الْمَدْحِ أَوِ الذَّمِّ أَوِ الِاخْتِصَارِ أَوِ السَّتْرِ أَوِ الصِّيَانَةِ أَوِ التَّعْمِيَةِ وَالْإِلْغَازِ أَوِ التَّعْبِيرِ عَنِ الصَّعْبِ بِالسَّهْلِ أو عن الْمَعْنَى الْقَبِيحِ بِاللَّفْظِ الْحَسَنِ\",[[111,1,0,4,1],[111,4,1,2,1],[111,5,0,2,1]]],[54,\"\",3,162,162,926,\"وَاسْتَنْبَطَ الزَّمَخْشَرِيُّ نَوْعًا مِنَ الْكِنَايَةِ غَرِيبًا وَهُوَ أَنْ تَعْمَدَ إِلَى جُمْلَةٍ مَعْنَاهَا عَلَى خِلَافِ الظَّاهِرِ فَتَأْخُذَ الْخُلَاصَةَ مِنْ غَيْرِ اعْتِبَارِ مُفْرَدَاتِهَا بِالَحَقِيقَةِ وَالْمَجَازِ فَتُعَبِّرُ بِهَا عَنِ الْمَقْصُودِ كَمَا تَقُولُ فِي نَحْوِ: ﴿الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى﴾ إِنَّهُ كِنَايَةٌ عَنِ الْمُلْكِ فَإِنَّ الِاسْتِوَاءَ عَلَى السَّرِيرِ لَا يَحْصُلُ إِلَّا مَعَ الْمُلْكِ فَجُعِلَ كِنَايَةً عَنْهُ وَكَذَا قَوْلُهُ: ﴿وَالأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ﴾ كِنَايَةٌ عَنْ عَظْمَتِهِ وَجَلَالَتِهِ مِنْ غَيْرِ ذَهَابٍ بِالْقَبْضِ وَالْيَمِينِ إِلَى جِهَتَيْنِ حَقِيقَةٍ وَمَجَازٍ\",[[20,5,0,3,1],[39,67,5,12,1]]],[54,\"\",3,163,163,927,\"وَكَذَا قَوْلُهُ: ﴿وَاسْتَوَتْ عَلَى الْجُودِيِّ﴾ حَقِيقَةُ ذَلِكَ \\\"جَلَسَتْ\\\" فَعَدَلَ عَنِ اللَّفْظِ الْخَاصِّ بِالْمَعْنَى إِلَى مُرَادِفِهِ لِمَا فِي الِاسْتِوَاءِ مِنَ الْإِشْعَارِ بِجُلُوسٍ مُتَمَكِّنٍ لَا زَيْغَ فِيهِ وَلَا مَيْلَ وَهَذَا لَا يَحْصُلُ مِنْ لَفْظِ \\\"الْجُلُوسِ\\\"\",[[11,44,10,12,1]]],[54,\"\",3,163,163,927,\"وَكَذَا: ﴿فِيهِنَّ قَاصِرَاتُ الطَّرْفِ﴾ الْأَصْلُ \\\"عَفِيفَاتٌ\\\" وَعَدَلَ عَنْهُ لِلدَّلَالَةِ عَلَى أَنَّهُنَّ مَعَ الْعِفَّةِ لَا تَطْمَحُ أَعْيُنُهُنَّ إِلَى غَيْرِ أَزْوَاجِهِنَّ وَلَا يَشْتَهِينَ غَيْرَهُمْ وَلَا يُؤْخَذُ ذَلِكَ مِنْ لَفْظِ الْعِفَّةِ\",[[55,56,0,2,1]]],[54,\"\",3,163,163,927,\"وَمِنْ أَمْثِلَتِهِ أَيْضًا: ﴿لِيَجْزِيَ الَّذِينَ أَسَاءُوا بِمَا عَمِلُوا وَيَجْزِيَ الَّذِينَ أَحْسَنُوا بِالْحُسْنَى﴾ عَدَلَ فِي الْجُمْلَةِ الْأُولَى عَنْ قوله \\\"بالسوءى\\\" مَعَ أَنَّ فِيهِ مُطَابَقَةً لِلْجُمْلَةِ الثَّانِيَةِ إِلَى \\\"بِمَا عَمِلُوا\\\" تَأَدُّبًا أَنْ يُضَافَ السُّوءُ إِلَى اللَّهِ تعالى.\",[[53,31,7,15,1]]],[54,\"\",3,164,164,928,\"وَقَالَ السُّبْكِيُّ: فِي كتاب الْإِغْرِيضُ فِي الْفَرْقِ بَيْنَ الْكِنَايَةِ وَالتَّعْرِيضِ: الْكِنَايَةُ لَفْظٌ اسْتُعْمِلَ فِي مَعْنَاهُ مُرَادًا مِنْهُ لَازِمَ الْمَعْنَى فَهِيَ بِحَسَبِ اسْتِعْمَالِ اللَّفْظِ فِي الْمَعْنَى حَقِيقَةً وَالتَّجَوُّزُ فِي إِرَادَةِ إِفَادَةِ مَا لَمْ يُوضَعْ لَهُ وَقَدْ لَا يراد منها الْمَعْنَى بَلْ يُعَبَّرُ بِالْمَلْزُومِ عَنِ اللَّازِمِ وَهِيَ حِينَئِذٍ مَجَازٌ وَمِنْ أَمْثِلَتِهِ: ﴿قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرًّا﴾ فَإِنَّهُ لَمْ يَقْصِدْ إِفَادَةَ ذَلِكَ لِأَنَّهُ مَعْلُومٌ بَلْ إِفَادَةَ لَازِمِهِ وَهُوَ أَنَّهُمْ يَرِدُونَهَا وَيَجِدُونَ حَرَّهَا إِنْ لَمْ يُجَاهِدُوا وَأَمَّا التَّعْرِيضُ: فَهُوَ لَفْظٌ اسْتُعْمِلَ فِي مَعْنَاهُ لِلتَّلْوِيحِ بِغَيْرِهِ نَحْوُ: ﴿بَلْ فَعَلَهُ كَبِيرُهُمْ هَذَا﴾\",[[9,81,19,23,1],[21,63,1,4,1]]],[54,\"\",3,164,165,928,\"قَالَ الطِّيبِيُّ: وَذَلِكَ يُفْعَلُ إِمَّا لِتَنْوِيهِ جَانِبَ الْمَوْصُوفِ وَمِنْهُ: ﴿وَرَفَعَ بَعْضَهُمْ دَرَجَاتٍ﴾ أَيْ مُحَمَّدًا ﷺ إِعْلَاءً لِقَدْرِهِ أَيْ أَنَّهُ الْعَلَمُ الَّذِي لَا يَشْتَبِهُ\",[[2,253,10,12,1]]],[54,\"\",3,165,165,929,\"وَإِمَّا لِتَلَطُّفٍ بِهِ وَاحْتِرَازٍ عَنِ الْمُخَاشَنَةِ نَحْوُ: ﴿وَمَا لِيَ لَا أَعْبُدُ الَّذِي فَطَرَنِي﴾ أَيْ وَمَالَكُمْ لَا تَعْبُدُونَ بِدَلِيلِ قَوْلِهِ: ﴿وَإِلَيْهِ تُرْجَعُونَ﴾ وَكَذَا قَوْلُهُ: ﴿أَأَتَّخِذُ مِنْ دُونِهِ آلِهَةً﴾ وَوَجْهُ حُسْنِهِ إِسْمَاعُ مَنْ يَقْصِدُ خِطَابَهُ الْحَقَّ عَلَى وَجْهٍ يَمْنَعُ غَضَبَهُ إِذْ لَمْ يُصَرِّحُ بنسبته للباطل وَالْإِعَانَةُ عَلَى قَبُولِهِ إِذْ لَمْ يُرِدْ لَهُ إِلَّا مَا أَرَادَهُ لِنَفْسِهِ\",[[18,15,2,5,4],[21,24,1,4,4],[25,3,0,3,4],[36,23,0,3,4]]],[54,\"\",3,165,165,929,\"وَإِمَّا لِاسْتِدْرَاجِ الْخَصْمِ إِلَى الْإِذْعَانِ وَالتَّسْلِيمِ وَمِنْهُ: ﴿لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ﴾، خُوطِبَ النَّبِيُّ ﷺ وَأُرِيدَ غَيْرُهُ لِاسْتِحَالَةِ الشِّرْكِ عَلَيْهِ شَرْعًا\",[[39,65,7,10,1]]],[54,\"\",3,165,165,929,\"وَإِمَّا لِلذَّمِّ نَحْوُ: ﴿إِنَّمَا يَتَذَكَّرُ أُولُو الأَلْبَابِ﴾ فإنه تعريض بذم الْكُفَّارِ وَإِنَّهُمْ فِي حُكْمِ الْبَهَائِمِ الَّذِينَ لَا يَتَذَكَّرُونَ\",[[13,19,11,14,2],[39,9,20,23,2]]],[54,\"\",3,165,165,929,\"وَإِمَّا لِلْإِهَانَةِ والتوبيخ نحو: ﴿وَإِذَا الْمَوْؤُودَةُ سُئِلَتْ بِأَيِّ ذَنْبٍ قُتِلَتْ﴾ وَقَالَ السُّبْكِيُّ التَّعْرِيضُ قِسْمَانِ:\",[[81,8,0,2,1],[81,9,0,2,1]]],[54,\"\",3,165,165,929,\"قِسْمٌ يُرَادُ بِهِ مَعْنَاهُ الْحَقِيقِيُّ وَيُشَارُ بِهِ إِلَى الْمَعْنَى الْآخَرِ الْمَقْصُودِ كَمَا تَقَدَّمَ وَقِسْمٌ لَا يُرَادُ بَلْ يُضْرَبُ مَثَلًا لِلْمَعْنَى الَّذِي هُوَ مَقْصُودُ التَّعْرِيضِ كَقَوْلِ إِبْرَاهِيمَ: ﴿بَلْ فَعَلَهُ كَبِيرُهُمْ هَذَا.﴾\",[[21,63,1,4,1]]],[55,\"\",3,166,166,930,\"وَمِثَالُهُ مَجَازِيًّا: ﴿وَمَا مُحَمَّدٌ إِلاَّ رَسُولٌ﴾ أَيْ أَنَّهُ مَقْصُورٌ عَلَى الرِّسَالَةِ لَا يَتَعَدَّاهَا إِلَى التَّبَرِّي مِنَ الْمَوْتِ الَّذِي اسْتَعْظَمُوهُ الَّذِي هُوَ مِنْ شَأْنِ الْإِلَهِ\",[[3,144,0,3,1]]],[55,\"\",3,166,166,930,\"وَمِثَالُ قَصْرِ الصِّفَةِ عَلَى الْمَوْصُوفِ حَقِيقِيًّا: ﴿لَا إِلَهَ إِلاَّ اللَّهُ﴾\",[[37,35,5,8,2],[47,19,2,5,2]]],[55,\"\",3,166,167,930,\"وَمِثَالُهُ مَجَازِيًّا: ﴿قُلْ لَا أَجِدُ فِي مَا أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَى طَاعِمٍ يَطْعَمُهُ إِلاَّ أَنْ يَكُونَ مَيْتَةً﴾ الآية كَمَا قَالَ الشَّافِعِيُّ فِيمَا تَقَدَّمَ نقله عنه في أَسْبَابِ النُّزُولِ إِنَّ الْكُفَّارَ لَمَّا كَانُوا يُحِلُّونَ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الخنزير وما أهل لغير اللَّهِ بِهِ وَكَانُوا يُحْرِّمُونَ كَثِيرًا مِنَ الْمُبَاحَاتِ وَكَانَتْ سَجِيَّتُهُمْ تُخَالِفُ وَضْعَ الشَّرْعِ وَنَزَلَتِ الْآيَةُ مسبوقة بِذِكْرِ شُبَهِهِمْ فِي الْبَحِيرَةِ وَالسَّائِبَةِ وَالْوَصِيلَةِ وَالْحَامِي وَكَانَ الْغَرَضُ إِبَانَةَ كَذِبِهِمْ فَكَأَنَّهُ قَالَ لَا حَرَامَ إِلَّا مَا أَحْلَلْتُمُوهُ وَالْغَرَضُ الرَّدُّ عَلَيْهِمْ وَالْمُضَادَّةُ لَا الْحَصْرُ الْحَقِيقِيُّ وَقَدْ تَقَدَّمَ بِأَبْسَطَ مِنْ هَذَا\",[[6,145,0,14,1]]],[55,\"\",3,167,167,931,\"فَالْأَوَّل: يُخَاطَبُ بِهِ مَنْ يَعْتَقِدُ الشَّرِكَةَ نَحْوُ: ﴿إِنَّمَا هُوَ إِلَهٌ وَاحِدٌ﴾ خُوطِبَ بِهِ مَنْ يَعْتَقِدُ اشْتَرَاكَ اللَّهِ وَالْأَصْنَامِ فِي الْأُلُوهِيَّةِ\",[[6,19,29,32,3],[14,52,6,9,3],[16,51,6,9,3]]],[55,\"\",3,167,167,931,\"وَالثَّانِي: يُخَاطَبُ بِهِ مَنْ يَعْتَقِدُ إِثْبَاتَ الْحُكْمِ لِغَيْرِ مَنْ أَثْبَتَهُ الْمُتَكَلِّمُ لَهُ نَحْوُ: ﴿رَبِّيَ الَّذِي يُحْيِي وَيُمِيتُ﴾ خوطب به نمرود الَّذِي اعْتَقَدَ أَنَّهُ هُوَ الْمُحْيِي الْمُمِيتُ دُونَ اللَّهِ، ﴿أَلا إِنَّهُمْ هُمُ السُّفَهَاءُ﴾ خُوطِبَ بِهِ مَنِ اعْتَقَدَ مِنَ الْمُنَافِقِينَ أَنَّ الْمُؤْمِنِينَ سُفَهَاءُ دُونَهُمْ، ﴿وَأَرْسَلْنَاكَ لِلنَّاسِ رَسُولًا﴾ خُوطِبَ بِهِ مَنْ يَعْتَقِدُ مِنَ الْيَهُودِ اخْتِصَاصَ بِعْثَتِهِ بِالْعَرَبِ.\",[[2,258,15,18,1],[2,13,12,15,1],[4,79,12,14,1]]],[55,\"\",3,167,169,931,\"أَحَدُهَا: النَّفْيُ وَالِاسْتِثْنَاءُ سَوَاءً كَانَ النَّفْيُ بِلَا أَوْ مَا أَوْ غَيْرِهِمَا وَالِاسْتِثْنَاءُ بِإِلَا أَوْ غَيْرِ نَحْوُ: ﴿لَا إِلَهَ إِلاَّ اللَّهُ﴾ ﴿وَمَا مِنْ إِلَهٍ إِلاَّ اللَّهُ وَإِنَّ اللَّهَ﴾ ﴿مَا قُلْتُ لَهُمْ إِلاَّ مَا أَمَرْتَنِي بِهِ﴾ ووجه إفادته الحصر أن لَأَفَادَهُ نَحْوُ\\\"إِنَّ زَيْدًا لَقَائِمٌ\\\" وَأُجِيبُ بِأَنَّ مُرَادَهُ لَا يَجْتَمِعُ حَرْفَا تَأْكِيدٍ مُتَوَالِيَانِ إِلَّا لِلْحَصْرِ\",[[37,35,5,8,2],[47,19,2,5,2],[3,62,5,11,1],[5,117,0,6,1]]],[55,\"\",3,169,169,932,\"وَمِنْهَا قَوْلُهُ تَعَالَى: ﴿قَالَ إِنَّمَا الْعِلْمُ عِنْدَ اللَّهِ﴾ ﴿قَالَ إِنَّمَا يَأْتِيكُمْ بِهِ اللَّهُ﴾ ﴿إِنَّمَا عِلْمُهَا عِنْدَ رَبِّي﴾ فَإِنَّهُ إِنَّمَا تَحْصُلُ مُطَابَقَةُ الْجَوَابِ إِذَا كَانَتْ إِنَّمَا لِلْحَصْرِ لِيَكُونَ مَعْنَاهَا لَا آتِيكُمْ بِهِ إِنَّمَا يَأْتِي بِهِ اللَّهُ وَلَا أَعْلَمُهَا \\\"إِنَّمَا يَعْلَمُهَا اللَّهُ\\\" وَكَذَا قَوْلُهُ: ﴿وَلَمَنِ انْتَصَرَ بَعْدَ ظُلْمِهِ فَأُولَئِكَ مَا عَلَيْهِمْ مِنْ سَبِيلٍ إِنَّمَا السَّبِيلُ عَلَى الَّذِينَ يَظْلِمُونَ النَّاسَ﴾ ﴿مَا عَلَى الْمُحْسِنِينَ مِنْ سَبِيلٍ﴾ إِلَى قَوْلِهِ: ﴿إِنَّمَا السَّبِيلُ عَلَى الَّذِينَ يَسْتَأْذِنُونَكَ وَهُمْ أَغْنِيَاءُ﴾ ﴿وَإِذَا لَمْ تَأْتِهِمْ بِآيَةٍ قَالُوا لَوْلا اجْتَبَيْتَهَا قُلْ إِنَّمَا أَتَّبِعُ مَا يُوحَى إِلَيَّ مِنْ رَبِّي﴾ ﴿وَإِنْ تَوَلَّوْا فَإِنَّمَا عَلَيْكَ الْبَلاغُ﴾ ولا يَسْتَقِيمُ الْمَعْنَى فِي هَذِهِ الْآيَاتِ وَنَحْوِهَا إِلَّا بِالْحَصْرِ\",[[46,23,0,4,2],[67,26,0,4,2],[11,33,0,4,1],[7,187,6,9,1],[42,41,0,8,1],[42,42,0,5,1],[9,91,18,22,1],[9,93,0,6,1],[7,203,0,14,1],[3,20,18,22,1]]],[55,\"\",3,169,169,932,\"وَأَحْسَنُ مَا تستعمل إنما في مَوَاقِعِ التَّعْرِيضِ نَحْوُ: ﴿إِنَّمَا يَتَذَكَّرُ أُولُو الأَلْبَابِ﴾\",[[13,19,11,14,2],[39,9,20,23,2]]],[55,\"\",3,169,170,932,\"الثَّالِثُ: أَنَّمَا بِالْفَتْحِ عَدَّهَا مِنْ طُرُقِ الْحَصْرِ الزَّمَخْشَرِيُّ وَالْبَيْضَاوِيُّ فَقَالَا فِي قَوْلِهِ تَعَالَى: ﴿قُلْ إِنَّمَا يُوحَى إِلَيَّ أَنَّمَا إِلَهُكُمْ إِلَهٌ وَاحِدٌ﴾ إِنَّمَا لِقَصْرِ الْحُكْمِ عَلَى شَيْءٍ أَوْ لِقَصْرِ الشَّيْءِ عَلَى حُكْمٍ نَحْوُ\\\"إِنَّمَا زَيْدٌ قَائِمٌ\\\" وإنما يَقُومُ زَيْدٌ وَقَدِ اجْتَمَعَ الْأَمْرَانِ فِي هَذِهِ الْآيَةِ لِأَنَّ \\\"إِنَّمَا يُوحَى إِلَيَّ\\\" مَعَ فَاعِلِهِ بِمَنْزِلَةِ إِنَّمَا يَقُومُ زَيْدٌ وَ\\\"أَنَّمَا إِلَهُكُمْ\\\" بِمَنْزِلَةِ إِنَّمَا زِيدٌ قَائِمٌ وَفَائِدَةُ اجْتِمَاعِهِمَا الدَّلَالَةُ عَلَى أَنَّ الْوَحْيَ إِلَى الرَّسُولِ الله ﷺ مَقْصُورٌ عَلَى اسْتِئْثَارِ اللَّهِ بِالْوَحْدَانِيَّةِ\",[[21,108,0,7,1]]],[55,\"\",3,170,170,933,\"الْخَامِسُ: تَقْدِيمُ الْمَعْمُولِ نَحْوُ: ﴿إِيَّاكَ نَعْبُدُ﴾ ﴿لإِلَى اللَّهِ تُحْشَرُونَ﴾ وَخَالَفَ فِيهِ قَوْمٌ وَسَيَأْتِي بَسْطُ الْكَلَامِ فِيهِ قَرِيبًا\",[[1,5,0,1,1],[3,158,4,6,1]]],[55,\"\",3,170,171,933,\"السَّادِسُ: ضَمِيرُ الْفَصْلِ نَحْوُ: ﴿فَاللَّهُ هُوَ الْوَلِيُّ﴾ أَيْ لَا غَيْرُهُ ﴿وَأُولَئِكَ هُمُ الْمُفْلِحُونَ﴾ ﴿إِنَّ هَذَا لَهُوَ الْقَصَصُ الْحَقُّ﴾ ﴿إِنَّ شَانِئَكَ هُوَ الأَبْتَرُ﴾ وَمِمَّنْ ذَكَرَ أَنَّهُ لِلْحَصْرِ الْبَيَانِيُّونَ فِي بَحْثِ الْمُسْنَدِ إِلَيْهِ وَاسْتَدَلَّ لَهُ السُّهَيْلِيُّ بِأَنَّهُ أُتِيَ بِهِ فِي كُلِّ مَوْضِعٍ ادُّعِيَ فِيهِ نِسْبَةُ ذَلِكَ الْمَعْنَى إِلَى غَيْرِ اللَّهِ وَلَمْ يُؤْتَ بِهِ حَيْثُ لَمْ يُدَّعَ وَذَلِكَ فِي قَوْلِهِ: ﴿وَأَنَّهُ هُوَ أَضْحَكَ وَأَبْكَى﴾ إِلَى آخِرِ الْآيَاتِ فَلَمْ يُؤْتَ بِهِ فِي ﴿وَأَنَّهُ خَلَقَ الزَّوْجَيْنِ﴾، ﴿وَأَنَّ عَلَيْهِ النَّشْأَةَ﴾ ﴿وَأَنَّهُ أَهْلَكَ عَادًا الأُولَى﴾: لِأَنَّ ذَلِكَ لَمْ يُدَّعَ لِغَيْرِ اللَّهِ وَأُتِيَ بِهِ فِي الْبَاقِي لِادِّعَائِهِ لِغَيْرِهِ قَالَ فِي عَرُوسُ الْأَفْرَاحِ: وَقَدِ اسْتَنْبَطْتُ دَلَالَتَهُ عَلَى الْحَصْرِ مِنْ قَوْلِهِ: ﴿فَلَمَّا تَوَفَّيْتَنِي كُنْتَ أَنْتَ الرَّقِيبَ عَلَيْهِمْ﴾ لِأَنَّهُ لَوْ لَمْ يَكُنْ لِلْحَصْرِ لَمَا حَسُنَ لَأَنَّ اللَّهَ لَمْ يَزَلْ رَقِيبًا عَلَيْهِمْ وَإِنَّمَا الَّذِي حَصَلَ بِتَوْفِيَتِهِ أَنَّهُ لَمْ يَبْقَ لَهُمْ رَقِيبٌ غَيْرُ اللَّهِ تَعَالَى وَمِنْ قَوْلِهِ: ﴿لَا يَسْتَوِي أَصْحَابُ النَّارِ وَأَصْحَابُ الْجَنَّةِ أَصْحَابُ الْجَنَّةِ هُمُ الْفَائِزُونَ﴾ فَإِنَّهُ ذُكِرَ لِتَبْيِينِ عَدَمِ الِاسْتِوَاءِ وَذَلِكَ لَا يَحْسُنُ إِلَّا بِأَنْ يَكُونَ الضَّمِيرُ لِلِاخْتِصَاصِ.\",[[42,9,5,7,1],[59,9,28,30,1],[3,62,0,4,1],[108,3,0,3,1],[53,43,0,3,1],[53,45,0,2,1],[53,47,0,2,1],[53,50,0,3,1],[5,117,18,23,1],[59,20,0,9,1]]],[55,\"\",3,171,172,934,\"أَحَدُهَا: أَنْ يَكُونَ الْمُسْنَدُ إِلَيْهِ مَعْرِفَةً وَالْمُسْنَدُ مُثْبَتًا فَيَأْتِي لِلتَّخْصِيصِ نَحْوُ أَنَا قُمْتُ وَأَنَا سَعَيْتُ فِي حَاجَتِكَ فَإِنْ قُصِدَ بِهِ قَصْرُ الْإِفْرَادِ أُكِّدَ بِنَحْوِ \\\"وَحْدِي\\\" أَوْ قَصْرُ الْقَلْبِ أُكِّدَ بِنَحْوِ \\\"لَا غَيْرِي\\\" وَمِنْهُ: ﴿بَلْ أَنْتُمْ بِهَدِيَّتِكُمْ تَفْرَحُونَ﴾ فَإِنَّ مَا قَبْلُهُ مِنْ قَوْلِهِ: ﴿أَتُمِدُّونَنِ بِمَالٍ﴾ وَلَفْظُ \\\"بَلْ\\\" الْمُشْعِرُ بِالْإِضْرَابِ يَقْضِي بِأَنَّ الْمُرَادَ بَلْ\\\" أَنْتُمْ لَا غيركم\\\" فإن الْمَقْصُودَ نَفْيُ فَرَحِهِ هُوَ بِالْهَدِيَّةِ لَا إِثْبَاتُ الْفَرَحِ لَهُمْ بِهَدِيَّتِهِمْ قَالَهُ فِي عَرُوسِ الْأَفْرَاحِ قَالَ: وَكَذَا قَوْلُهُ: ﴿لَا تَعْلَمُهُمْ نَحْنُ نَعْلَمُهُمْ﴾ أي لا نعلمهم إِلَّا نَحْنُ وَقَدْ يَأْتِي لِلتَّقْوِيَةِ وَالتَّأْكِيدِ دُونَ التَّخْصِيصِ قَالَ الشَّيْخُ بَهَاءُ الدِّينِ وَلَا يَتَمَيَّزُ ذَلِكَ إِلَّا بِمَا يَقْتَضِيهِ الْحَالُ وَسِيَاقُ الْكَلَامِ\",[[27,36,12,15,1],[27,36,4,5,1],[9,101,11,14,1]]],[55,\"\",3,172,172,935,\"ثَانِيهَا: أَنْ يَكُونَ الْمُسْنَدُ مَنْفِيًّا نَحْوُ أَنْتَ لَا تَكْذِبُ فَإِنَّهُ أَبْلَغُ فِي نَفْيِ الْكَذِبِ مِنْ \\\"لَا تَكْذِبْ\\\" وَمِنْ لَا تَكْذِبْ أَنْتَ وَقَدْ يُفِيدُ التَّخْصِيصُ وَمِنْهُ ﴿فَهُمْ لَا يَتَسَاءَلُونَ﴾\",[[28,66,4,6,1]]],[55,\"\",3,172,172,935,\"رَابِعُهَا: أَنْ يَلِيَ الْمُسْنَدُ إِلَيْهِ حَرْفَ النَّفْيِ فَيُفِيدُهُ نَحْوُ \\\"مَا أَنَا قُلْتُ هَذَا\\\" أَيْ لَمْ أَقُلْهُ مَعَ أَنَّ غَيْرِي قَالَهُ وَمِنْهُ: ﴿وَمَا أَنْتَ عَلَيْنَا بِعَزِيزٍ﴾ أَيِ الِعَزِيزُ عَلَيْنَا رَهْطُكَ لَا أَنْتَ وَلِذَا قَالَ: ﴿أَرَهْطِي أَعَزُّ عَلَيْكُمْ مِنَ اللَّهِ﴾ هَذَا حَاصِلُ رَأَيِ الشَّيْخِ عَبْدِ الْقَاهِرِ وَوَافَقَهُ السَّكَّاكِيُّ وَزَادَ شُرُوطًا وَتَفَاصِيلَ بَسَطْنَاهَا فِي شَرْحِ أَلْفِيَّةِ الْمَعَانِي.\",[[11,91,14,17,1],[11,92,2,6,1]]],[55,\"\",3,172,173,935,\"التَّاسِعُ: ذِكْرُ الْمُسْنَدِ إِلَيْهِ، ذَكَرَ السَّكَّاكِيُّ أَنَّهُ قَدْ ذكر لِيُفِيدَ التَّخْصِيصَ وَتَعَقَّبَهُ صَاحِبُ الْإِيضَاحِ وَصَرَّحَ الزَّمَخْشَرِيُّ: بِأَنَّهُ أَفَادَ الِاخْتِصَاصَ فِي قوله: ﴿اللَّهُ يَبْسُطُ الرِّزْقَ﴾ في سورة الرَّعْدِ وَفِي قَوْلِهِ: ﴿اللَّهُ نَزَّلَ أَحْسَنَ الْحَدِيثِ﴾ وَفِي قَوْلِهِ: ﴿وَاللَّهُ يَقُولُ الْحَقَّ وَهُوَ يَهْدِي السَّبِيلَ﴾ وَيُحْتَمَلُ أَنَّهُ أَرَادَ أَنَّ تَقْدِيمَهُ أَفَادَهُ فَيَكُونُ مِنْ أَمْثِلَةِ الطَّرِيقِ السَّابِعِ\",[[39,52,3,5,1],[39,23,0,3,1],[33,4,22,27,1]]],[55,\"\",3,173,173,936,\"الْعَاشِرُ: تَعْرِيفُ الْجُزْأَيْنِ ذَكَرَ الْإِمَامُ فَخْرُ الدِّينِ فِي نِهَايَةِ الْإِيجَازِ أَنَّهُ يُفِيدُ الْحَصْرَ حَقِيقَةً أَوْ مُبَالَغَةً نَحْوُ: \\\"الْمُنْطَلِقُ زَيْدٌ\\\" وَمِنْهُ فِي الْقُرْآنِ فِيمَا ذَكَرَ الزَّمْلَكَانِيُّ فِي أَسْرَارِ التَّنْزِيلِ: ﴿الْحَمْدُ لِلَّهِ﴾ قَالَ إِنَّهُ يُفِيدُ الْحَصْرَ كَمَا فِي ﴿إِيَّاكَ نَعْبُدُ﴾،أَيِ ﴿الْحَمْدُ لِلَّهِ﴾ لَا لِغَيْرِهِ\",[[1,2,0,1,1],[1,5,0,1,1],[1,2,0,1,1]]],[55,\"\",3,173,173,936,\"الرَّابِعَ عَشَرَ: قَلْبُ بَعْضِ حُرُوفِ الْكَلِمَةِ فَإِنَّهُ يُفِيدُ الْحَصْرَ عَلَى مَا نَقَلَهُ فِي الْكَشَّافِ فِي قَوْلِهِ: ﴿وَالَّذِينَ اجْتَنَبُوا الطَّاغُوتَ أَنْ يَعْبُدُوهَا﴾ قَالَ الْقَلْبُ لِلِاخْتِصَاصِ بِالنِّسْبَةِ إِلَى لَفْظِ \\\"الطَّاغُوتِ\\\" لِأَنَّ وَزْنَهُ عَلَى قَوْلِ \\\"فَعَلُوتٍ\\\" مِنَ الطُّغْيَانِ كَمَلَكُوتٍ وَرَحَمُوتٍ قُلِبَ بِتَقْدِيمِ اللَّامِ عَلَى الْعَيْنِ فَوَزْنُهُ \\\"فَلَعُوتٌ\\\" فَفِيهِ مُبَالَغَاتُ التَّسْمِيَةِ بِالْمَصْدَرِ وَالْبِنَاءُ بِنَاءُ مُبَالِغَةٍ وَالْقَلْبُ وَهُوَ لِلِاخْتِصَاصِ إِذْ لَا يُطْلَقُ عَلَى غَيْرِ الشَّيْطَانِ.\",[[39,17,0,4,1]]],[55,\"\",3,174,174,937,\"كَادَ أَهْلُ الْبَيَانِ يُطْبِقُونَ عَلَى أَنَّ تَقْدِيمَ الْمَعْمُولِ يُفِيدُ الْحَصْرَ سَوَاءٌ كَانَ مَفْعُولًا أَوْ ظَرْفًا أَوْ مَجْرُورًا وَلِهَذَا قِيلَ فِي: ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾ مَعْنَاهُ \\\"نَخُصُّكَ بِالْعِبَادَةِ وَالِاسْتِعَانَةِ\\\"،وَفِي: ﴿لإِلَى اللَّهِ تُحْشَرُونَ﴾ مَعْنَاهُ \\\"إِلَيْهِ لَا إِلَى غَيْرِهِ\\\"،وَفِي: ﴿لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا﴾ أُخِّرَتِ الصِّلَةُ فِي الشَّهَادَةِ الْأُولَى وَقُدِّمَتْ فِي الثَّانِيَةِ لِأَنَّ الْغَرَضَ فِي الْأَوَّلِ إِثْبَاتُ شَهَادَتِهِمْ وَفِي الثَّانِي إِثْبَاتُ اخْتِصَاصِهِمْ بِشَهَادَةِ النَّبِيِّ ﷺ عَلَيْهِمْ.\",[[1,5,0,3,1],[3,158,4,6,1],[2,143,4,11,1]]],[55,\"\",3,174,174,937,\"وَخَالَفَ فِي ذَلِكَ ابْنُ الْحَاجِبِ فَقَالَ فِي شَرْحِ الْمُفَصَّلِ الِاخْتِصَاصُ الَّذِي يَتَوَهَّمُهُ كَثِيرٌ مِنَ النَّاسِ مِنْ تَقْدِيمِ الْمَعْمُولِ وَهْمٌ وَاسْتَدَلَّ عَلَى ذَلِكَ بِقَوْلِهِ: ﴿فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ﴾ ثُمَّ قَالَ: ﴿بَلِ اللَّهَ فَاعْبُدْ﴾ وَرُدَّ هَذَا الِاسْتِدْلَالَ بِأَنَّ \\\"مُخْلِصًا لَهُ الدِّينَ\\\" أَغْنَى عَنْ إِفَادَةِ الْحَصْرِ فِي الْآيَةِ الْأُولَى وَلَوْ لَمْ يَكُنْ فَمَا الْمَانِعُ مِنْ ذِكْرِ الْمَحْصُورِ فِي مَحَلٍّ بِغَيْرِ صِيغَةِ الْحَصْرِ كَمَا قَالَ تَعَالَى: ﴿وَاعْبُدُوا رَبَّكُمْ﴾ وَقَالَ: ﴿أَمَرَ أَلاَّ تَعْبُدُوا إِلاَّ إِيَّاهُ﴾ بَلْ قَوْلُهُ: ﴿بَلِ اللَّهَ فَاعْبُدْ﴾ مِنْ أَقْوَى أَدِلَّةِ الِاخْتِصَاصِ فَإِنَّ قَبْلَهَا: ﴿لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ﴾ فَلَوْ لَمْ يَكُنْ لِلِاخْتِصَاصِ وَكَانَ مَعْنَاهَا \\\"اعْبُدِ اللَّهَ\\\" لَمَا حَصَلَ الْإِضْرَابُ الَّذِي هُوَ مَعْنَى \\\"بَلْ\\\"\",[[39,11,4,8,1],[39,66,0,2,1],[2,21,2,3,2],[22,77,5,6,2],[12,40,19,23,1],[39,66,0,2,1],[39,65,7,10,1]]],[55,\"\",3,174,175,937,\"وَاعْتَرَضَ أَبُو حَيَّانَ عَلَى مُدَّعِي الِاخْتِصَاصِ بِنَحْوِ: ﴿أَفَغَيْرَ اللَّهِ تَأْمُرُونِّي أعبد﴾ وَأُجِيبُ بِأَنَّهُ لَمَّا أَشْرَكَ بِاللَّهِ غَيْرَهُ كَأَنَّهُ لَمْ يَعْبُدِ اللَّهَ وكان أَمْرُهُمْ بِالشِّرْكِ كَأَنَّهُ أَمْرٌ بِتَخْصِيصِ غَيْرِ اللَّهِ بِالْعِبَادَةِ وَرَدَّ صَاحِبُ الْفَلَكِ الدَّائِرِ الِاخْتِصَاصَ بِقَوْلِهِ: ﴿كُلًّا هَدَيْنَا وَنُوحًا هَدَيْنَا مِنْ قَبْلُ﴾ وَهُوَ مِنْ أَقْوَى مَا رُدَّ بِهِ وَأُجِيبُ بِأَنَّهُ لَا يُدَّعَى فِيهِ اللُّزُومُ بَلِ الْغَلَبَةُ وَقَدْ يَخْرُجُ الشَّيْءُ عَنِ الْغَالِبِ.\",[[39,64,1,4,1],[6,84,4,9,1]]],[55,\"\",3,175,175,938,\"قَالَ الشَّيْخُ بَهَاءُ الدِّينِ وَقَدِ اجْتَمَعَ الِاخْتِصَاصُ وَعَدَمُهُ فِي آيَةٍ وَاحِدَةٍ وَهِيَ ﴿أَغَيْرَ اللَّهِ تَدْعُونَ إِنْ كُنْتُمْ صَادِقِينَ بَلْ إِيَّاهُ تَدْعُونَ﴾ فَإِنَّ التَّقْدِيمَ فِي الْأَوَّلِ قَطْعًا لَيْسَ لِلِاخْتِصَاصِ وَفِي \\\"إِيَّاهُ\\\" قَطْعًا لِلِاخْتِصَاصِ\",[[6,40,9,14,1],[6,41,0,2,1]]],[55,\"\",3,175,176,938,\"وَقَالَ وَالِدُهُ الشَّيْخُ تَقِيُّ الدِّينِ فِي كِتَابِ الِاقْتِنَاصِ فِي الْفَرْقِ بَيْنَ الْحَصْرِ وَالِاخْتِصَاصِ اشْتَهَرَ كَلَامُ النَّاسِ فِي أَنَّ تَقْدِيمَ الْمَعْمُولِ يُفِيدُ الِاخْتِصَاصَ وَمِنَ النَّاسِ مَنْ يُنْكِرُ ذَلِكَ وَيَقُولُ إِنَّمَا يُفِيدُ الِاهْتِمَامَ وَقَدْ قَالَ سِيبَوَيْهِ فِي كِتَابِهِ وَهُمْ يُقَدِّمُونَ مَا هُمْ بِهِ أَعَنَى. وَالْبَيَانِيُّونَ عَلَى إِفَادَتِهِ الِاخْتِصَاصَ وَيَفْهَمُ كَثِيرٌ مِنَ النَّاسِ مِنَ الِاخْتِصَاصِ الْحَصْرَ وَلَيْسَ كَذَلِكَ وَإِنَّمَا الِاخْتِصَاصُ شَيْءٌ وَالْحَصْرُ شَيْءٌ آخَرُ وَالْفُضَلَاءُ لَمْ يَذْكُرُوا فِي ذَلِكَ لَفْظَةَ \\\"الْحَصْرِ\\\" وَإِنَّمَا عَبَّرُوا بِالِاخْتِصَاصِ وَالْفَرْقُ بَيْنَهُمَا أَنَّ الْحَصْرَ نَفْيُ غَيْرِ الْمَذْكُورِ وَإِثْبَاتُ الْمَذْكُورِ وَالِاخْتِصَاصُ قَصْدُ الْخَاصِّ مِنْ جِهَةِ خُصُوصِهِ وَبَيَانُ ذَلِكَ أَنَّ الِاخْتِصَاصَ افْتِعَالٌ مِنَ الْخُصُوصِ وَالْخُصُوصُ مُرَكَّبٌ مِنْ شَيْئَيْنِ: أَحَدُهُمَا عَامٌّ مُشْتَرَكٌ بَيْنَ شَيْئَيْنِ أَوْ أَشْيَاءَ وَالثَّانِي مَعْنًى مُنْضَمٌّ إِلَيْهِ يَفْصِلُهُ عَنْ غَيْرِهِ كَضَرَبَ زَيْدٌ فَإِنَّهُ أَخَصُّ مِنْ مُطْلَقِ الضَّرْبِ فَإِذَا قُلْتَ ضَرَبْتُ زَيْدًا أَخْبَرْتَ بِضَرْبٍ عَامٍّ وَقَعَ مِنْكَ عَلَى شَخْصٍ خَاصٍّ فَصَارَ ذَلِكَ الضَّرْبُ الْمُخْبَرُ بِهِ خَاصًّا لِمَا انْضَمَّ إِلَيْهِ مِنْكَ وَمِنْ زَيْدٍ وَهَذِهِ الْمَعَانِي الثَّلَاثَةُ أَعْنِي مُطْلَقَ الضَّرْبِ، وَكَوْنَهُ وَاقِعًا مِنْكَ وَكَوْنَهُ وَاقِعًا عَلَى زَيْدٍ - قَدْ يَكُونُ قَصْدُ الْمُتَكَلِّمِ لَهَا ثَلَاثَتَهَا عَلَى السَّوَاءِ وَقَدْ يَتَرَجَّحُ قَصْدُهُ لِبَعْضِهَا عَلَى بَعْضٍ وَيُعْرَفُ ذَلِكَ بِمَا ابْتَدَأَ بِهِ كَلَامَهُ فَإِنَّ الِابْتِدَاءَ بِالشَّيْءِ يَدُلُّ عَلَى الِاهْتِمَامِ بِهِ وَأَنَّهُ هُوَ الْأَرْجَحُ فِي غَرَضِ الْمُتَكَلِّمِ فَإِذَا قُلْتَ: زَيْدًا ضَرَبْتُ عُلِمَ أَنَّ خُصُوصَ الضَّرْبِ عَلَى زَيْدٍ هُوَ الْمَقْصُودُ وَلَا شك أَنَّ كُلَّ مُرَكَّبٍ مِنْ خَاصٍّ وَعَامٍّ لَهُ جِهَتَانِ فَقَدْ يُقْصَدُ مِنْ جِهَةِ عُمُومِهِ وَقَدْ يُقْصَدُ مِنْ جِهَةِ خُصُوصِهِ وَالثَّانِي هُوَ الِاخْتِصَاصُ وَأَنَّهُ هُوَ الْأَهَمُّ عِنْدَ الْمُتَكَلِّمِ وَهُوَ الَّذِي قَصَدَ إِفَادَتَهُ السَّامِعَ مِنْ غَيْرِ تَعَرُّضٍ وَلَا قَصْدٍ لِغَيْرِهِ بِإِثْبَاتٍ وَلَا نَفْيٍ فَفِي الْحَصْرِ مَعْنًى زَائِدٌ عَلَيْهِ وَهُوَ نَفْيُ مَا عَدَا الْمَذْكُورَ وإنما جاء هذا في ﴿إِيَّاكَ نَعْبُدُ﴾ لِلْعِلْمِ بِأَنَّ قَائِلِيهِ لَا يَعْبُدُونَ غَيْرَ اللَّهِ تَعَالَى وَلِذَا لَمْ يَطَّرِدْ فِي بَقِيَّةِ الْآيَاتِ فَإِنَّ قَوْلَهُ: ﴿أَفَغَيْرَ دِينِ اللَّهِ يَبْغُونَ﴾ لَوْ جُعِلَ فِي مَعْنَى \\\"مَا يَبْغُونَ إِلَّا غَيْرَ دِينِ اللَّهِ\\\" وَهَمْزَةُ الْإِنْكَارِ دَاخِلَةٌ عَلَيْهِ لَزِمَ أَنْ يَكُونَ الْمُنْكَرُ الْحَصْرَ لَا مُجَرَّدَ بَغْيِهِمْ غَيْرَ دِينِ اللَّهِ وَلَيْسَ الْمُرَادَ وَكَذَلِكَ ﴿آلِهَةً دُونَ اللَّهِ تُرِيدُونَ﴾ الْمُنْكَرُ إِرَادَتُهُمْ آلِهَةً دُونَ اللَّهِ مِنْ غَيْرِ حَصْرٍ.\",[[1,5,0,1,1],[3,83,0,3,1],[37,86,1,4,1]]],[55,\"\",3,176,176,939,\"وَقَدْ قَالَ الزَّمَخْشَرِيُّ فِي ﴿وَبِالآخِرَةِ هُمْ يُوقِنُونَ﴾: فِي تَقْدِيمِ \\\"الْآخِرَةِ\\\" وَبِنَاءِ \\\"يُوقِنُونَ\\\" عَلَى \\\"هُمْ\\\" تَعْرِيضٌ بِأَهْلِ الْكِتَابِ وَمَا كَانُوا عَلَيْهِ مِنْ إِثْبَاتِ أَمْرِ الْآخِرَةِ عَلَى خِلَافِ حَقِيقَتِهِ وَأَنَّ قَوْلَهُمْ لَيْسَ بِصَادِرٍ عَنْ إِيقَانٍ وَأَنَّ الْيَقِينَ مَا عَلَيْهِ مَنْ آمَنَ بِمَا أُنْزِلُ إِلَيْكَ وَمَا أُنْزِلَ مِنْ قَبْلِكَ\",[[2,4,9,11,3],[27,3,6,8,3],[31,4,6,8,3]]],[55,\"\",3,176,177,939,\"وَهَذَا الَّذِي قَالَهُ الزَّمَخْشَرِيُّ فِي غَايَةِ الْحُسْنِ وَقَدِ اعْتَرَضَ عَلَيْهِ بَعْضُهُمْ فَقَالَ تَقْدِيمُ \\\"الْآخِرَةِ\\\" أَفَادَ أَنَّ إِيقَانَهُمْ مَقْصُورٌ عَلَى أَنَّهُ إِيقَانٌ بِالْآخِرَةِ لَا بِغَيْرِهَا وَهَذَا الِاعْتِرَاضُ مِنْ قَائِلِهِ مَبْنِيٌّ عَلَى مَا فَهِمَهُ مِنْ أَنَّ تَقْدِيمَ الْمَعْمُولِ يُفِيدُ الْحَصْرَ وَلَيْسَ كَذَلِكَ ثُمَّ قَالَ الْمُعْتَرِضِ وَتَقْدِيمُ \\\"هُمْ\\\" أَفَادَ أَنَّ هَذَا الْقَصْرَ مُخْتَصٌّ بِهِمْ فَيَكُونُ إِيقَانُ غَيْرِهِمْ بِالْآخِرَةِ إِيمَانًا بِغَيْرِهَا حَيْثُ قَالُوا: ﴿لَنْ تَمَسَّنَا النَّارُ﴾ وَهَذَا مِنْهُ أَيْضًا اسْتِمْرَارٌ عَلَى مَا فِي ذِهْنِهِ مِنَ الْحَصْرِ أَيْ أَنَّ الْمُسْلِمِينَ لَا يُوقِنُونَ إِلَّا بِالْآخِرَةِ وَأَهْلُ الْكِتَابِ يُوقِنُونَ بِهَا وَبِغَيْرِهَا وَهَذَا فَهْمٌ عَجِيبٌ أَلْجَأَهُ إِلَيْهِ فَهَمُهُ الْحَصْرَ وَهُوَ مَمْنُوعٌ وَعَلَى تَقْدِيرِ تَسْلِيمِهِ فَالْحَصْرُ على ثلاثة أقسام:\",[[2,80,1,3,2],[3,24,3,5,2]]],[56,\"\",3,180,180,944,\"فَإِنْ قُلْتَ عَدَمُ ذِكْرِكَ الْمُسَاوَاةَ فِي التَّرْجَمَةِ لِمَاذَا هَلْ هُوَ لِرُجْحَانِ نَفْيِهَا أَوْ عَدَمِ قَبُولِهَا أَوْ لِأَمْرٍ غَيْرِ ذَلِكَ؟ قُلْتُ: لَهُمَا وَلِأَمْرٍ ثَالِثٍ وَهُوَ أَنَّ الْمُسَاوَاةَ لَا تَكَادُ تُوجَدُ خُصُوصًا فِي الْقُرْآنِ وَقَدْ مَثَّلَ لَهَا فِي التَّلْخِيصِ بِقَوْلِهِ تَعَالَى: ﴿وَلا يَحِيقُ الْمَكْرُ السَّيِّئُ إِلاَّ بِأَهْلِهِ﴾ وَفِي الْإِيضَاحِ بِقَوْلِهِ: ﴿وَإِذَا رَأَيْتَ الَّذِينَ يَخُوضُونَ فِي آيَاتِنَا﴾ وَتُعُقِّبَ بِأَنَّ فِي الْآيَةِ الثَّانِيَةِ حَذْفَ مَوْصُوفِ \\\"الَّذِينَ\\\" وَفِي الْأَوْلَى إِطْنَابٌ بِلَفْظِ \\\"السَّيِّئِ\\\" لِأَنَّ الْمَكْرَ لَا يَكُونُ إِلَّا سَيِّئًا وَإِيجَازٌ بِالْحَذْفِ إِنْ كَانَ الِاسْتِثْنَاءُ غَيْرَ مُفَرَّغٍ أَيْ بِأَحَدٍ وَبِالْقَصْرِ فِي الِاسْتِثْنَاءِ وَبِكَوْنِهَا حَاثَّةً عَلَى كَفِّ الْأَذَى عَنْ جَمِيعِ النَّاسِ مُحَذِّرَةً عَنْ جَمِيعِ مَا يُؤَدِّي إِلَيْهِ وَبِأَنَّ تَقْدِيرَهَا يَضُرُّ بِصَاحِبِهِ مَضَرَّةً بَلِيغَةً فَأَخْرَجَ الْكَلَامَ مَخْرَجَ الِاسْتِعَارَةِ التَّبَعِيَّةِ الواقعة على سبيل التمثيلية لِأَنَّ \\\"يَحِيقُ\\\"بِمَعْنَى \\\"يُحِيطُ\\\" فَلَا يُسْتَعْمَلُ إِلَّا فِي الْأَجْسَامِ.\",[[35,43,5,10,1],[6,68,0,5,1]]],[56,\"\",3,181,182,945,\"أَحَدُهَا: إِيجَازُ الْقَصْرِ وَهُوَ أَنْ يُقْصَرَ اللَّفْظُ عَلَى مَعْنَاهُ كَقَوْلِهِ: ﴿إِنَّهُ مِنْ سُلَيْمَانَ﴾ إِلَى قَوْلِهِ: ﴿وَأْتُونِي مُسْلِمِينَ﴾ جَمَعَ فِي أَحْرُفِ الْعُنْوَانِ وَالْكِتَابِ وَالْحَاجَةِ وَقِيلَ فِي وَصْفٍ بَلِيغٍ: كَانَتْ أَلْفَاظُهُ قَوَالِبَ مَعْنَاهُ قُلْتُ وَهَذَا رَأْيُ مَنْ يُدْخِلُ الْمُسَاوَاةَ فِي الْإِيجَازِ.\",[[27,30,0,2,1],[27,31,3,4,1]]],[56,\"\",3,182,182,946,\"الثَّانِي: إِيجَازُ التَّقْدِيرِ وَهُوَ أَنْ يُقَدَّرَ معنى زائد عَلَى الْمَنْطُوقِ وَيُسَمَّى بِالتَّضْيِيقِ أَيْضًا وَبِهِ سَمَّاهُ بَدْرُ الدِّينِ بْنُ مَالِكٍ فِي الْمِصْبَاحِ لِأَنَّهُ نَقَصَ مِنَ الْكَلَامِ مَا صَارَ لَفْظُهُ أَضْيَقَ مِنْ قَدْرِ مَعْنَاهُ نَحْوُ: ﴿فَمَنْ جَاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ فَانْتَهَى فَلَهُ مَا سَلَفَ﴾ أَيْ خَطَايَاهُ غُفِرَتْ فَهِيَ لَهُ لَا عَلَيْهِ ﴿هُدىً لِلْمُتَّقِينَ﴾ أي للضالين الصَّائِرِينَ بَعْدَ الضَّلَالِ إِلَى التَّقْوَى.\",[[2,275,25,33,1],[2,2,5,6,1]]],[56,\"\",3,182,182,946,\"الثَّالِثُ: الْإِيجَازُ الْجَامِعُ وَهُوَ أَنْ يَحْتَوِيَ اللَّفْظُ عَلَى مَعَانٍ مُتَعَدِّدَةٍ نَحْوُ: ﴿إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالأِحْسَانِ﴾ الْآيَةَ فَإِنَّ الْعَدْلَ هُوَ الصِّرَاطُ الْمُسْتَقِيمُ الْمُتَوَسِّطُ بَيْنَ طَرَفَيِ الْإِفْرَاطِ وَالتَّفْرِيطِ الْمُومَى بِهِ إِلَى جَمِيعِ الْوَاجِبَاتِ فِي الِاعْتِقَادِ وَالْأَخْلَاقِ وَالْعُبُودِيَّةِ وَالْإِحْسَانُ هُوَ الْإِخْلَاصُ فِي وَاجِبَاتِ الْعُبُودِيَّةِ لِتَفْسِيرِهِ فِي الْحَدِيثِ بِقَوْلِهِ: \\\"أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ\\\" أَيْ تَعَبُّدَهُ مُخْلِصًا فِي نِيَّتِكَ وَوَاقِفًا فِي الْخُضُوعِ آخِذًا أُهْبَةَ الْحَذَرِ إِلَى مَا لَا يُحْصَى ﴿وَإِيتَاءِ ذِي الْقُرْبَى﴾ هُوَ الزِّيَادَةُ عَلَى الْوَاجِبِ مِنَ النَّوَافِلِ هَذَا فِي الْأَوَامِرِ. وَأَمَّا النواهي\",[[16,90,0,7,1]]],[56,\"\",3,183,183,947,\"وَمِنْ ذَلِكَ قَوْلُهُ تَعَالَى: ﴿خُذِ الْعَفْوَ﴾ الْآيَةَ فَإِنَّهَا جَامِعَةٌ لِمَكَارِمِ الْأَخْلَاقِ لِأَنَّ فِي أَخْذِ الْعَفْوِ التَّسَاهُلَ وَالتَّسَامُحَ فِي الْحُقُوقِ وَاللِّينَ وَالرِّفْقَ فِي الدُّعَاءِ إِلَى الدِّينِ وَفِي الْأَمْرِ بِالْمَعْرُوفِ كَفُّ الْأَذَى وَغَضُّ الْبَصَرِ وَمَا شَاكَلَهُمَا مِنَ الْمُحَرَّمَاتِ وفي الإعراض الصبر وَالْحِلْمِ وَالتُّؤَدَةِ\",[[7,199,0,1,1]]],[56,\"\",3,183,183,947,\"وَمِنْ بَدِيعِ الْإِيجَازِ قَوْلُهُ تَعَالَى: ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ إِلَى آخِرِهَا فَإِنَّهُ نِهَايَةُ التَّنْزِيهِ وَقَدْ تَضَمَّنَتِ الرَّدَّ عَلَى نَحْوِ أَرْبَعِينَ فِرْقَةً كَمَا أَفْرَدَ ذَلِكَ بِالتَّصْنِيفِ بَهَاءُ الدِّينِ بْنُ شَدَّادٍ\",[[112,1,0,3,1]]],[56,\"\",3,183,183,947,\"وَقَوْلُهُ: ﴿أَخْرَجَ مِنْهَا مَاءَهَا وَمَرْعَاهَا﴾ دَلَّ بِهَاتَيْنِ الْكَلِمَتَيْنِ عَلَى جَمِيعِ مَا أَخْرَجَهُ مِنَ الْأَرْضِ قُوتًا وَمَتَاعًا لِلْأَنَامِ مِنَ الْعُشْبِ وَالشَّجَرِ وَالْحَبِّ وَالثَّمَرِ وَالْعَصْفِ وَالْحَطَبِ وَاللِّبَاسِ وَالنَّارِ وَالْمِلْحِ لِأَنَّ النَّارَ مِنَ الْعِيدَانِ وَالْمِلْحَ مِنَ الْمَاءِ\",[[79,31,0,3,1]]],[56,\"\",3,183,183,947,\"وَقَوْلُهُ: ﴿لَا يُصَدَّعُونَ عَنْهَا وَلا يُنْزِفُونَ﴾ جَمَعَ فِيهِ جَمِيعَ عُيُوبِ الْخَمْرِ مِنَ الصُّدَاعِ وَعَدَمِ الْعَقْلِ وَذَهَابِ المال ونفاد الشَّرَابِ\",[[56,19,0,4,1]]],[56,\"\",3,183,184,947,\"وَقَوْلُهُ: ﴿وَقِيلَ يَا أَرْضُ ابْلَعِي مَاءَكِ﴾ الْآيَةَ أَمَرَ فِيهَا وَنَهَى وَأَخْبَرَ وَنَادَى، وَنَعَتَ وَسَمَّى وَأَهْلَكَ وَأَبْقَى، وَأَسْعَدَ وَأَشْقَى وَقَصَّ مِنَ الْأَنْبَاءِ مَا لَوْ شُرِحَ مَا انْدَرَجَ فِي هَذِهِ الْجُمْلَةِ مِنْ بَدِيعِ اللَّفْظِ وَالْبَلَاغَةِ وَالْإِيجَازِ وَالْبَيَانِ لَجَفَّتِ الْأَقْلَامُ وَقَدْ أَفْرَدْتُ بَلَاغَةَ هَذِهِ الْآيَةِ بِالتَّأْلِيفِ، وَفِي الْعَجَائِبِ لِلْكِرْمَانِيِّ: أَجْمَعَ الْمُعَانِدُونَ عَلَى أَنَّ طَوْقَ الْبَشَرِ قَاصِرٌ عَنِ الْإِتْيَانِ بِمِثْلِ هَذِهِ الْآيَةِ بَعْدَ أَنْ فَتَّشُوا جَمِيعَ كَلَامِ الْعَرَبِ وَالْعَجَمِ فَلَمْ يَجِدُوا مِثْلَهَا فِي فَخَامَةِ أَلْفَاظِهَا وَحُسْنِ نَظْمِهَا وَجَوْدَةِ مَعَانِيهَا فِي تَصْوِيرِ الْحَالِ مَعَ الْإِيجَازِ مِنْ غَيْرِ إِخْلَالٍ\",[[11,44,0,3,1]]],[56,\"\",3,184,184,948,\"وَقَوْلُهُ تَعَالَى: ﴿يَا أَيُّهَا النَّمْلُ ادْخُلُوا مَسَاكِنَكُمْ﴾ الْآيَةَ جَمَعَ فِي هَذِهِ اللَّفْظَةِ أَحَدَ عَشَرَ جِنْسًا مِنَ الْكَلَامِ نَادَتْ وَكَنَّتْ وَنَبَّهَتْ وَسَمَّتْ وَأَمَرَتْ وَقَصَّتْ وَحَذَّرَتْ وَخَصَّتْ وَعَمَّتْ وَأَشَارَتْ وَعَذَرَتْ فَالنِّدَاءُ \\\"يَا\\\"وَالْكِنَايَةُ \\\"أَيْ\\\" وَالتَّنْبِيهُ \\\"هَا\\\" وَالتَّسْمِيَةُ \\\"النَّمْلُ\\\" وَالْأَمْرُ \\\"ادْخُلُوا\\\" وَالْقَصَصُ \\\"مَسَاكِنَكُمْ\\\" وَالتَّحْذِيرُ \\\"لَا يَحْطِمَنَّكُمْ\\\" وَالتَّخْصِيصُ \\\"سُلَيْمَانُ\\\" وَالتَّعْمِيمُ \\\"جُنُودُهُ\\\" وَالْإِشَارَةُ \\\"وَهُمْ \\\" وَالْعُذْرُ \\\"لَا يَشْعُرُونَ\\\" فأدت خمس حُقُوقٍ حَقَّ اللَّهِ وَحَقَّ رَسُولِهِ وَحَقَّهَا وَحَقَّ رَعِيَّتِهَا وَحَقَّ جُنُودِ سليمان\",[[27,18,8,11,1]]],[56,\"\",3,184,184,948,\"وقوله: ﴿يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ﴾ الْآيَةَ جُمِعَ فِيهَا أُصُولُ الْكَلَامِ النِّدَاءُ وَالْعُمُومُ وَالْخُصُوصُ وَالْأَمْرُ وَالْإِبَاحَةُ وَالنَّهْيُ وَالْخَبَرُ\",[[7,31,0,6,1]]],[56,\"\",3,184,185,948,\"وَقَالَ بَعْضُهُمْ جَمَعَ اللَّهُ الْحِكْمَةَ فِي شَطْرِ آيَةِ ﴿وَكُلُوا وَاشْرَبُوا وَلا تُسْرِفُوا﴾ وَقَوْلُهُ تَعَالَى: ﴿وَأَوْحَيْنَا إِلَى أُمِّ مُوسَى أَنْ أَرْضِعِيهِ﴾ الْآيَةَ، قَالَ ابْنُ الْعَرَبِيِّ: هِيَ مِنْ أَعْظَمِ آيٍ فِي الْقُرْآنِ فَصَاحَةً إِذْ فِيهَا أَمْرَانِ وَنَهْيَانِ وَخَبَرَانِ وَبِشَارَتَانِ\",[[7,31,7,10,1],[28,7,0,5,1]]],[56,\"\",3,185,185,949,\"وَقَوْلُهُ: ﴿فَاصْدَعْ بِمَا تُؤْمَرُ﴾ قَالَ ابْنُ أَبِي الْإِصْبَعِ: الْمَعْنَى: صَرِّحَ بِجَمِيعِ مَا أُوحِيَ إِلَيْكَ وَبَلِّغْ كُلَّ مَا أُمِرْتَ بِبَيَانِهِ وَإِنْ شَقَّ بَعْضُ ذَلِكَ عَلَى بَعْضِ الْقُلُوبِ فَانْصَدَعَتْ وَالْمُشَابَهَةُ بَيْنَهُمَا فِيمَا يُؤْثِرُهُ التَّصْرِيحُ فِي الْقُلُوبِ فَيَظْهَرُ أَثَرُ ذَلِكَ عَلَى ظَاهِرِ الْوُجُوهِ مِنَ التَّقَبُّضِ وَالِانْبِسَاطِ وَيَلُوحُ عَلَيْهَا مِنْ عَلَامَاتِ الْإِنْكَارِ وَالِاسْتِبْشَارِ كَمَا يَظْهَرُ عَلَى ظَاهِرِ الزُّجَاجَةِ الْمَصْدُوعَةِ فَانْظُرْ إِلَى جَلِيلِ هَذِهِ الِاسْتِعَارَةِ وَعِظَمِ إِيجَازِهَا وَمَا انْطَوَتْ عَلَيْهِ مِنَ الْمَعَانِي الْكَثِيرَةِ وَقَدْ حُكِيَ أَنَّ بَعْضَ الْأَعْرَابِ لَمَّا سَمِعَ هَذِهِ الْآيَةَ سَجَدَ وَقَالَ: سَجَدْتُ لِفَصَاحَةِ هَذَا الْكَلَامِ\",[[15,94,0,2,1]]],[56,\"\",3,185,185,949,\"وَقَوْلُهُ تَعَالَى: ﴿وَفِيهَا مَا تَشْتَهِيهِ الأَنْفُسُ وَتَلَذُّ الأَعْيُنُ﴾ قال بعضهم جمع بهاتين اللفظين مَا لَوِ اجْتَمَعَ الْخَلْقُ كُلُّهُمْ عَلَى وَصْفِ مَا فِيهَا عَلَى التَّفْصِيلِ لَمْ يَخْرُجُوا عَنْهُ\",[[43,71,6,11,1]]],[56,\"\",3,185,186,949,\"وَقَوْلُهُ تَعَالَى: ﴿وَلَكُمْ فِي الْقِصَاصِ حَيَاةٌ﴾ فَإِنَّ مَعْنَاهُ كَثِيرٌ وَلَفْظُهُ قَلِيلٌ لِأَنَّ مَعْنَاهُ أَنَّ الْإِنْسَانَ إِذَا عَلِمَ أَنَّهُ مَتَى قَتَلَ قُتِلَ كان ذلك داعيا إلى ألا يُقْدِمَ عَلَى الْقَتْلِ فَارْتَفَعَ بِالْقَتْلِ الَّذِي هُوَ الْقِصَاصُ كَثِيرٌ مِنْ قَتْلِ النَّاسِ بَعْضُهُمْ لِبَعْضٍ وَكَانَ ارْتِفَاعُ الْقَتْلِ حَيَاةً لَهُمْ وَقَدْ فُضِّلَتْ هَذِهِ الْجُمْلَةُ عَلَى أَوْجَزِ مَا كَانَ عِنْدَ الْعَرَبِ فِي هَذَا الْمَعْنَى وَهُوَ قَوْلُهُمْ \\\"الْقَتْلُ أَنْفَى لِلْقَتْلِ\\\" بِعِشْرِينَ وَجْهًا أَوْ أَكْثَرَ وَقَدْ أَشَارَ ابْنُ الْأَثِيرِ إِلَى إِنْكَارِ هَذَا التَّفْضِيلِ وَقَالَ: لَا تَشْبِيهَ بَيْنَ كَلَامِ الْخَالِقِ وَكَلَامِ الْمَخْلُوقِ وَإِنَّمَا الْعُلَمَاءُ يَقْدَحُونَ أَذْهَانَهُمْ فِيمَا يَظْهَرُ لَهُمْ مِنْ ذِلَكَ. الْأَوَّلُ: أَنَّ مَا يُنَاظِرُهُ مِنْ كَلَامِهِمْ وَهُوَ قَوْلُهُ: \\\"الْقِصَاصِ حَيَاةٌ \\\" أَقَلُّ حُرُوفًا فَإِنَّ حُرُوفَهُ عَشْرَةٌ وَحُرُوفُ \\\"الْقَتْلُ أَنْفَى لِلْقَتْلِ\\\" أَرْبَعَةَ عَشَرَ.\",[[2,179,0,3,1]]],[56,\"\",3,186,186,950,\"الثَّالِثُ: أَنَّ تَنْكِيرَ \\\"حَيَاةٍ\\\" يُفِيدُ تَعْظِيمًا فَيَدُلُّ عَلَى أَنَّ فِي الْقِصَاصِ حَيَاةً مُتَطَاوِلَةً كَقَوْلِهِ تَعَالَى: ﴿وَلَتَجِدَنَّهُمْ أَحْرَصَ النَّاسِ عَلَى حَيَاةٍ﴾ وَلَا كَذَلِكَ الْمَثَلُ فَإِنَّ اللَّامَ فيه لِلْجِنْسِ وَلِذَا فَسَّرُوا الْحَيَاةَ فِيهَا بِالْبَقَاءِ.\",[[2,96,0,4,1]]],[56,\"إيجاز الحذف\",3,190,190,954,\"وَمِنْهَا التَّنْبِيهُ عَلَى أَنَّ الزَّمَانَ يَتَقَاصَرُ عَنِ الْإِتْيَانِ بِالْمَحْذُوفِ وَأَنَّ الِاشْتِغَالَ بِذِكْرِهِ يُفْضِي إِلَى تَفْوِيتِ الْمُهِمِّ وَهَذِهِ هِيَ فَائِدَةُ بَابِ التَّحْذِيرِ وَالْإِغْرَاءِ وَقَدِ اجْتَمَعَا فِي قَوْلِهِ تَعَالَى: ﴿نَاقَةَ اللَّهِ وَسُقْيَاهَا﴾ فناقة اللَّهِ تَحْذِيرٌ بِتَقْدِيرِ \\\"ذَرُوا\\\" وَ\\\"سُقْيَاهَا\\\" إِغْرَاءٌ بِتَقْدِيرِ \\\"الْزَمُوا\\\"\",[[91,13,4,6,1]]],[56,\"إيجاز الحذف\",3,190,191,954,\"وَمِنْهَا التَّفْخِيمُ وَالْإِعْظَامُ لِمَا فِيهِ مِنَ الْإِبْهَامِ قَالَ حَازِمٌ فِي مِنْهَاجِ الْبُلَغَاءِ إِنَّمَا يَحْسُنُ الْحَذْفُ لِقُوَّةِ الدَّلَالَةِ عَلَيْهِ أَوْ يُقْصَدُ بِهِ تَعْدِيدُ أَشْيَاءَ فَيَكُونُ فِي تَعْدَادِهَا طُولٌ وَسَآمَةٌ فَيُحْذَفُ وَيُكْتَفَى بِدَلَالَةِ الْحَالِ وَتُتْرَكُ النَّفْسُ تَجُولُ فِي الْأَشْيَاءِ الْمُكْتَفَى بِالْحَالِ عَنْ ذِكْرِهَا قَالَ: وَلِهَذَا الْقَصْدِ يُؤْثَرُ فِي الْمَوَاضِعِ الَّتِي يُرَادُ بِهَا التَّعَجُّبُ وَالتَّهْوِيلُ عَلَى النُّفُوسِ وَمِنْهُ قَوْلُهُ فِي وَصْفِ أَهْلِ الْجَنَّةِ: ﴿حَتَّى إِذَا جَاءُوهَا وَفُتِحَتْ أَبْوَابُهَا﴾، فَحُذِفَ الْجَوَابُ إِذْ كَانَ وَصْفُ مَا يَجِدُونَهُ وَيَلْقَوْنَهُ عِنْدَ ذَلِكَ لَا يَتَنَاهَى فَجُعِلَ الْحَذْفُ دَلِيلًا على ضيق الْكَلَامِ عَنْ وَصْفِ مَا يُشَاهِدُونَهُ وَتُرِكَتِ النُّفُوسُ تُقَدِّرُ مَا شَاءَتْهُ وَلَا تَبْلُغُ مَعَ ذَلِكَ كُنْهَ مَا هُنَالِكَ. وَكَذَا قَوْلُهُ: ﴿وَلَوْ تَرَى إِذْ وُقِفُوا عَلَى النَّارِ﴾ أَيْ لَرَأَيْتَ أَمْرًا فَظِيعًا لَا تَكَادُ تُحِيطُ بِهِ الْعِبَارَةُ\",[[39,71,6,10,2],[39,73,7,11,2],[6,27,0,5,1]]],[56,\"إيجاز الحذف\",3,191,191,955,\"وَمِنْهَا التَّخْفِيفُ لِكَثْرَةِ دَوَرَانِهِ فِي الْكَلَامِ كَمَا فِي حَذْفِ حَرْفِ النِّدَاءِ نَحْوِ: ﴿يُوسُفُ أَعْرِضْ﴾ ونون \\\"لم يك\\\" وَالْجَمْعُ السَّالِمُ وَمِنْهُ قِرَاءَةُ ﴿وَالْمُقِيمِي الصَّلاةِ﴾ وياء ﴿وَاللَّيْلِ إِذَا يَسْرِ﴾ وَسَأَلَ الْمُؤَرَّجُ السَّدُوسِيُّ الْأَخْفَشَ عَنْ هَذِهِ الْآيَةِ فَقَالَ عَادَةُ الْعَرَبِ أَنَّهَا إِذَا عَدَلَتْ بِالشَّيْءِ عَنْ مَعْنَاهُ نَقَصَتْ حُرُوفُهُ وَاللَّيْلُ لَمَّا كَانَ لَا يَسْرِي وَإِنَّمَا يُسْرَى فِيهِ نَقَصَ مِنْهُ حَرْفٌ كَمَا قَالَ تَعَالَى: ﴿وَمَا كَانَتْ أُمُّكِ بَغِيًّا﴾ الْأَصْلُ \\\"بَغِيَّةً\\\" فَلَمَّا حُوِّلَ عَنْ فَاعِلٍ نَقَصَ مِنْهُ حَرْفٌ\",[[12,29,0,1,1],[14,40,2,3,2],[22,35,10,11,2],[89,4,0,2,1],[19,28,7,10,1]]],[56,\"إيجاز الحذف\",3,191,191,955,\"وَمِنْهَا كَوْنُهُ لَا يَصْلُحُ إِلَّا لَهُ نحو ﴿عَالِمُ الْغَيْبِ وَالشَّهَادَةِ﴾ ﴿فَعَّالٌ لِمَا يُرِيدُ﴾\",[[11,107,12,14,2],[85,16,0,2,2]]],[56,\"إيجاز الحذف\",3,191,191,955,\"وَمِنْهَا شُهْرَتُهُ حَتَّى يَكُونَ ذِكْرُهُ وَعَدَمُهُ سَوَاءً قال الزمخشري وهو نَوْعٌ مِنْ دَلَالَةِ الْحَالِ الَّتِي لِسَانُهَا أَنْطَقُ مِنْ لِسَانِ الْمَقَالِ وَحُمِلَ عَلَيْهِ قِرَاءَةُ حَمْزَةَ ﴿تَسَاءَلُونَ بِهِ وَالأَرْحَامَ﴾ لِأَنَّ هَذَا مَكَانٌ شُهِرَ بِتَكَرُّرِ الْجَارِّ فَقَامَتِ الشُّهْرَةُ مَقَامَ الذِّكْرِ\",[[4,1,20,22,1]]],[56,\"إيجاز الحذف\",3,191,192,955,\"وَمِنْهَا صِيَانَتُهُ عَنْ ذِكْرِهِ تَشْرِيفًا كَقَوْلِهِ تَعَالَى: ﴿قَالَ فِرْعَوْنُ وَمَا رَبُّ الْعَالَمِينَ قَالَ رَبُّ السَّمَاوَاتِ﴾ الْآيَاتِ حُذِفَ فِيهَا الْمُبْتَدَأُ فِي ثَلَاثَةِ مَوَاضِعَ: قَبْلَ ذِكْرِ الرَّبِّ أَيْ \\\"هُوَ رَبٌّ\\\"، \\\"اللَّهُ رَبُّكُمْ\\\"، \\\"اللَّهُ رَبُّ الْمَشْرِقِ\\\" لِأَنَّ مُوسَى اسْتَعْظَمَ حَالَ فِرْعَوْنَ وَإِقْدَامَهُ عَلَى السُّؤَالِ فَأَضْمَرَ اسْمَ اللَّهِ تَعْظِيمًا وَتَفْخِيمًا وَمِثْلُهُ فِي عَرُوسِ الْأَفْرَاحِ بِقَوْلِهِ تَعَالَى: ﴿رَبِّ أَرِنِي أَنْظُرْ إِلَيْكَ﴾ أَيْ ذَاتِكَ\",[[26,23,0,4,1],[26,24,0,2,1],[7,143,7,10,1]]],[56,\"إيجاز الحذف\",3,192,192,956,\"وَمِنْهَا صِيَانَةُ اللِّسَانِ عَنْهُ تَحْقِيرًا لَهُ نَحْوُ: ﴿صُمٌّ بُكْمٌ﴾ أَيْ هُمْ أَوِ الْمُنَافِقُونَ وَمِنْهَا قَصْدُ الْعُمُومِ نَحْوُ: ﴿وَإِيَّاكَ نَسْتَعِينُ﴾ أَيْ عَلَى الْعِبَادَةِ وَعَلَى أُمُورِنَا كُلِّهَا، ﴿وَاللَّهُ يَدْعُو إِلَى دَارِ السَّلامِ﴾ أَيْ كَلَّ وَاحِدٍ وَمِنْهَا رِعَايَةُ الْفَاصِلَةِ نَحْوُ: ﴿مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى﴾ أَيْ \\\"وَمَا قَلَاكَ \\\"\",[[2,18,0,1,5],[2,171,12,13,5],[2,183,5,6,5],[6,39,3,4,5],[8,22,5,6,5],[1,5,2,3,1],[10,25,0,4,1],[93,3,0,4,1]]],[56,\"إيجاز الحذف\",3,192,192,956,\"وَمِنْهَا قَصْدُ الْبَيَانِ بَعْدَ الْإِبْهَامِ كَمَا فِي فعل المشيئة نحو: ﴿وَلَوْ شَاءَ لَهَدَاكُمْ﴾ أي ولو شَاءَ هِدَايَتَكُمْ فَإِنَّهُ إِذَا سَمِعَ السَّامِعُ \\\"وَلَوْ شَاءَ\\\" تَعَلَّقَتْ نَفْسُهُ بم شاء ابنهم عَلَيْهِ لَا يَدْرِي مَا هُوَ فَلَمَّا ذُكِرَ الْجَوَابُ اسْتَبَانَ بَعْدَ ذَلِكَ وَأَكْثَرُ مَا يَقَعُ ذَلِكَ بَعْدَ أَدَاةِ شَرْطٍ لِأَنَّ مَفْعُولَ الْمَشِيئَةِ مَذْكُورٌ فِي جَوَابِهَا\",[[16,9,6,8,1]]],[56,\"إيجاز الحذف\",3,192,193,956,\"وَقَدْ يَكُونُ مَعَ غَيْرِهَا اسْتِدْلَالًا بِغَيْرِ الْجَوَابِ نَحْوُ: ﴿وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلاَّ بِمَا شَاءَ﴾ وَقَدْ ذَكَرَ أَهْلُ الْبَيَانِ أَنَّ مَفْعُولَ الْمَشِيئَةِ وَالْإِرَادَةِ لَا يُذْكَرُ إِلَّا إِذَا كَانَ غَرِيبًا أَوْ عَظِيمًا نَحْوُ: ﴿لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ﴾ ﴿لَوْ أَرَدْنَا أَنْ نَتَّخِذَ لَهْوًا﴾ وَإِنَّمَا اطَّرَدَ أَوْ كَثُرَ حَذْفُ مَفْعُولِ الْمَشِيئَةِ دُونَ سَائِرِ الْأَفْعَالِ لِأَنَّهُ يَلْزَمُ مِنْ وُجُودِ الْمَشِيئَةِ وُجُودُ الْمُشَاءِ فَالْمَشِيئَةُ الْمُسْتَلْزِمَةُ لِمَضْمُونِ الْجَوَابِ لَا يُمْكِنُ أَنْ تَكُونَ إِلَّا مَشِيئَةَ الْجَوَابِ وَلِذَلِكَ كَانَتِ الْإِرَادَةُ مِثْلَهَا في اطراد حذف مَفْعُولِهَا ذَكَرَهُ الزَّمْلَكَانِيُّ وَالتَّنُوخِيُّ فِي الْأَقْصَى الْقَرِيبِ قَالُوا: وَإِذَا حُذِفَ بَعْدَ \\\"لَوْ\\\" فَهُوَ الْمَذْكُورُ فِي جَوَابِهَا أَبَدًا وَأَوْرَدَ فِي عَرُوسِ الْأَفْرَاحِ: ﴿قَالُوا لَوْ شَاءَ رَبُّنَا لأَنْزَلَ مَلائِكَةً﴾ فَإِنَّ الْمَعْنَى \\\"لَوْ شَاءَ رَبُّنَا إِرْسَالَ الرُّسُلِ لَأَنْزَلَ مَلَائِكَةً\\\" لَأَنَّ الْمَعْنَى مُعِينٌ عَلَى ذَلِكَ.\",[[2,255,32,39,1],[81,28,0,4,1],[21,17,0,4,1],[41,14,12,17,1]]],[56,\"إيجاز الحذف\",3,193,194,957,\"قَالَ ابْنُ هِشَامٍ جَرَتْ عَادَةُ النَّحْوِيِّينَ أَنْ يَقُولُوا بِحَذْفِ المفعولاختصارا وَاقْتِصَارًا وَيُرِيدُونَ بِالِاخْتِصَارِ الْحَذْفَ لِدَلِيلٍ وَيُرِيدُونَ بِالِاقْتِصَارِ الْحَذْفَ لِغَيْرِ دَلِيلٍ وَيُمَثِّلُونَهُ بِنَحْوِ: ﴿كُلُوا وَاشْرَبُوا﴾ أَيْ أَوْقِعُوا هَذَيْنِ الْفِعْلَيْنِ وَالتَّحْقِيقُ أَنْ يُقَالَ يَعْنِي كَمَا قَالَ أَهْلُ الْبَيَانِ تَارَةً يَتَعَلَّقُ الْغَرَضُ بِالْإِعْلَامِ بِمُجَرَّدِ وُقُوعِ الْفِعْلِ مِنْ غَيْرِ تَعْيِينِ مَنْ أَوْقَعَهُ وَمَنْ أُوقِعُ عَلَيْهِ فَيُجَاءُ بِمَصْدَرِهِ مُسْنَدًا إِلَى فِعْلِ كَوْنٍ عَامٍّ فَيُقَالُ حَصَلَ حَرِيقٌ أَوْ نَهْبٌ وَتَارَةً يَتَعَلَّقُ بِالْإِعْلَامِ بِمُجَرَّدِ إِيقَاعِ الْفِعْلِ لِلْفَاعِلِ فَيُقْتَصَرُ عَلَيْهِمَا وَلَا يُذَكَرُ الْمَفْعُولُ وَلَا يُنْوَى إِذِ الْمَنْوِيُّ كَالثَّابِتِ وَلَا يُسَمَّى مَحْذُوفًا لِأَنَّ الْفِعْلَ يُنَزَّلُ لِهَذَا الْقَصْدِ مَنْزِلَةَ مَا لَا مَفْعُولَ لَهُ وَمِنْهُ: ﴿رَبِّيَ الَّذِي يُحْيِي وَيُمِيتُ﴾ ﴿قُلْ هَلْ يَسْتَوِي الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لَا يَعْلَمُونَ﴾ ﴿وَكُلُوا وَاشْرَبُوا وَلا تُسْرِفُوا﴾ ﴿وَإِذَا رَأَيْتَ ثَمَّ﴾ إِذِ الْمَعْنَى رَبِّيَ الَّذِي يَفْعَلُ الْإِحْيَاءَ وَالْإِمَاتَةَ وَهَلْ يَسْتَوِي مَنْ يَتَّصِفُ بِالْعِلْمِ وَمَنْ يَنْتَفِي عَنْهُ الْعِلْمُ وَأَوْقِعُوا الْأَكْلَ وَالشُّرْبَ وَذَرُوا الْإِسْرَافَ \\\"وَإِذَا حَصَلَتْ مِنْكَ رُؤْيَةٌ\\\"\",[[7,31,7,10,1],[2,258,15,18,1],[39,9,12,19,1],[7,31,7,8,1],[76,20,0,2,1]]],[56,\"إيجاز الحذف\",3,194,194,958,\"وَمِنْهُ: ﴿وَلَمَّا وَرَدَ مَاءَ مَدْيَنَ﴾ الآية ألا ترى أنه ﵊ رَحِمَهُمَا إِذْ كَانَتَا عَلَى صِفَةِ الذِّيَادِ وَقَوْمُهُمَا عَلَى السَّقْيِ لَا لِكَوْنِ مَذُودِهِمَا غَنَمًا وَسَقْيِهِمْ إِبِلًا وَكَذَلِكَ الْمَقْصُودُ مِنْ \\\"لَا نَسْقِي\\\" السَّقْيُ لَا الْمَسْقِيُّ وَمَنْ لَمْ يَتَأَمَّلْ قَدَّرَ \\\"يَسْقُونَ إِبِلَهُمْ\\\" وَ\\\"تَذُودَانِ غَنَمَهُمَا\\\" وَ\\\"لَا نَسْقِي غَنَمًا\\\" وَتَارَةً يُقْصَدُ إِسْنَادُ الْفِعْلِ إِلَى فَاعِلِهِ وَتَعْلِيقُهُ بِمَفْعُولِهِ فَيُذْكَرَانِ نَحْوُ: ﴿لَا تَأْكُلُوا الرِّبا﴾ ﴿وَلا تَقْرَبُوا الزِّنَى﴾ وَهَذَا النَّوْعُ الَّذِي إِذَا لَمْ يُذْكَرْ مَحْذُوفُهُ قِيلَ مَحْذُوفٌ.\",[[28,23,0,3,1],[3,130,3,5,1],[17,32,0,2,1]]],[56,\"إيجاز الحذف\",3,194,194,958,\"وَقَدْ يكون في اللَّفْظُ مَا يَسْتَدْعِيهِ فَيَحْصُلُ الْجَزْمُ بِوُجُوبِ تَقْدِيرِهِ نَحْوُ: ﴿أَهَذَا الَّذِي بَعَثَ اللَّهُ رَسُولًا﴾ ﴿وَكُلًا وَعَدَ اللَّهُ الْحُسْنَى﴾\",[[25,41,6,10,1],[4,95,22,25,2],[57,10,29,32,2]]],[56,\"إيجاز الحذف\",3,195,195,959,\"أَحَدُهَا: وُجُودُ دَلِيلٍ إِمَّا حَالِيٌّ نَحْوُ: ﴿قَالُوا سَلامًا﴾ أَيْ سَلَّمْنَا سَلَامًا أَوْ مَقَالِيٌّ نَحْوُ: ﴿وَقِيلَ لِلَّذِينَ اتَّقَوْا مَاذَا أَنْزَلَ رَبُّكُمْ قَالُوا خَيْرًا﴾ \\\"أَيْ أَنْزَلَ خَيْرًا\\\"، ﴿قَالَ سَلامٌ قَوْمٌ مُنْكَرُونَ﴾ أَيْ سَلَامٌ عَلَيْكُمْ أَنْتُمْ قَوْمٌ مُنْكَرُونَ\",[[16,30,0,7,1],[51,25,5,8,1]]],[56,\"إيجاز الحذف\",3,195,195,959,\"وَمِنَ الْأَدِلَّةِ الْعَقْلُ حَيْثُ يَسْتَحِيلُ صِحَّةُ الْكَلَامِ عَقْلًا إِلَّا بِتَقْدِيرِ مَحْذُوفٍ ثُمَّ تَارَةً يَدُلُّ عَلَى أَصْلِ الْحَذْفِ مِنْ غَيْرِ دَلَالَةٍ عَلَى تَعْيِينِهِ بَلْ يُسْتَفَادُ التعيين من دليل آخره نحو: ﴿حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ﴾ فَإِنَّ الْعَقْلَ يَدُلُّ عَلَى أَنَّهَا لَيْسَتِ الْمُحَرَّمَةَ لِأَنَّ التَّحْرِيمَ لَا يضاف إلى الأحرام وَإِنَّمَا هُوَ وَالْحِلُّ يُضَافَانِ إِلَى الْأَفْعَالِ فَعُلِمَ بِالْعَقْلَ حَذْفُ شَيْءٍ وأما تعينه وَهُوَ التَّنَاوُلُ فَمُسْتَفَادٌ مِنَ الشَّرْعِ وَهُوَ قَوْلُهُ ﷺ: \\\"إِنَّمَا حَرُمَ أَكْلُهَا\\\" لِأَنَّ الْعَقْلَ لَا يُدْرِكُ مَحَلَّ الْحِلِّ وَلَا الْحُرْمَةِ وَأَمَّا قَوْلُ صَاحِبِ التَّلْخِيصِ: أَنَّهُ مِنْ بَابِ دَلَالَةِ العقل أيضا فتابع فيه السَّكَّاكِيَّ مِنْ غَيْرِ تَأَمُّلِ أَنَّهُ مَبْنِيٌّ عَلَى أُصُولِ الْمُعْتَزِلَةِ\",[[5,3,0,2,1]]],[56,\"إيجاز الحذف\",3,195,196,959,\"وَتَارَةً يَدُلُّ الْعَقْلُ أَيْضًا عَلَى التَّعْيِينِ نحو: ﴿وَجَاءَ رَبُّكَ﴾ أَيْ أَمْرُهُ بِمَعْنَى عَذَابِهِ لِأَنَّ الحق دَلَّ عَلَى اسْتِحَالَةِ مَجِيءِ الْبَارِئِ لِأَنَّهُ مِنْ سِمَاتِ الْحَادِثِ وَعَلَى أن الجائي أمره، ﴿وْفُوا بِالْعُقُودِ﴾ ﴿وَأَوْفُوا بِعَهْدِ اللَّهِ﴾، أَيْ بِمُقْتَضَى الْعُقُودِ وَبِمُقْتَضَى عَهْدِ اللَّهِ لِأَنَّ الْعَقْدَ وَالْعَهْدَ قَوْلَانِ قَدْ دَخَلَا فِي الْوُجُودِ وَانْقَضَيَا فَلَا يُتَصَوَّرُ فِيهِمَا وَفَاءٌ وَلَا نَقْضٌ وَإِنَّمَا الْوَفَاءُ وَالنَّقْضُ بِمُقْتَضَاهُمَا وَمَا تَرَتَّبَ عَلَيْهِمَا مِنْ أَحْكَامِهِمَا\",[[89,22,0,1,1],[5,1,3,4,2],[113,4,3,4,2],[16,91,0,2,1]]],[56,\"إيجاز الحذف\",3,196,196,960,\"وَتَارَةً يَدُلُّ عَلَى التَّعْيِينِ الْعَادَةُ نَحْوُ: ﴿فَذَلِكُنَّ الَّذِي لُمْتُنَّنِي فِيهِ﴾ دَلَّ الْعَقْلُ عَلَى الْحَذْفِ لِأَنَّ يُوسُفَ لَا يَصِحُّ ظَرْفًا لِلَّوْمِ ثُمَّ يُحْتَمَلُ أَنْ يُقَدَّرُ \\\"لُمْتُنَّنِي فِي حُبِّهِ\\\" لِقَوْلِهِ: ﴿قَدْ شَغَفَهَا حُبًّا﴾ وفي مراودتها لقوله: ﴿تُرَاوِدُ فَتَاهَا﴾ وَالْعَادَةُ دَلَّتْ عَلَى الثَّانِي لِأَنَّ الْحُبَّ الْمُفْرِطَ لَا يُلَامُ صَاحِبُهُ عَلَيْهِ عَادَةً لِأَنَّهُ لَيْسَ اخْتِيَارِيًّا بِخِلَافِ الْمُرَاوَدَةِ لِلْقُدْرَةِ عَلَى دَفْعِهَا\",[[12,32,1,4,1],[12,30,10,12,1],[12,30,6,7,1]]],[56,\"إيجاز الحذف\",3,196,196,960,\"وَتَارَةً يدل عليه التَّصْرِيحِ بِهِ فِي مَوْضِعٍ آخَرَ وَهُوَ أَقْوَاهَا نَحْوُ: ﴿هَلْ يَنْظُرُونَ إِلاَّ أَنْ يَأْتِيَهُمُ اللَّهُ﴾ أَيْ أَمْرُهُ بِدَلِيلِ: ﴿أَوْ يَأْتِيَ أَمْرُ رَبِّكَ﴾ ﴿وَجَنَّةٍ عَرْضُهَا السَّمَاوَاتُ﴾ ﴿وَلَمَّا جَاءَهُمْ رَسُولٌ مِنْ عِنْدِ اللَّهِ﴾ أَيْ كَعَرْضِ بِدَلِيلِ التَّصْرِيحِ بِهِ فِي آيَةِ البينة: ﴿رَسُولٌ مِنَ اللَّهِ﴾ أَيْ مِنْ عِنْدِ اللَّهِ بِدَلِيلِ:\",[[2,210,0,5,1],[16,33,7,9,1],[3,133,5,7,1],[2,101,0,5,1],[98,2,0,2,1]]],[56,\"إيجاز الحذف\",3,196,196,960,\"وَمِنَ الْأَدِلَّةِ عَلَى أَصْلِ الْحَذْفِ الْعَادَةُ بِأَنْ يَكُونَ الْعَقْلُ غَيْرَ مَانِعٍ مِنْ إِجْرَاءِ اللَّفْظِ عَلَى ظَاهِرِهِ مِنْ غَيْرِ حَذْفٍ نَحْوُ: ﴿لَوْ نَعْلَمُ قِتَالًا لاتَّبَعْنَاكُمْ﴾ أَيْ مَكَانَ قَتَّالٍ وَالْمُرَادُ مَكَانًا صَالِحًا لِلْقِتَالِ وَإِنَّمَا كَانَ كَذَلِكَ لِأَنَّهُمْ كَانُوا أَخْبَرَ النَّاسِ بِالْقِتَالِ وَيَتَعَيَّرُونَ بِأَنْ يَتَفَوَّهُوا بِأَنَّهُمْ لَا يَعْرِفُونَهُ فَالْعَادَةُ تَمْنَعُ أَنْ يُرِيدُوا: \\\"لَوْ نَعْلَمُ حَقِيقَةَ\\\" الْقِتَالِ فَلِذَلِكَ قَدَّرَهُ مُجَاهِدٌ \\\"مَكَانَ قِتَالٍ\\\" وَيَدُلُّ عَلَيْهِ أَنَّهُمْ أَشَارُوا عَلَى النَّبِيِّ ﷺ إلا يَخْرُجَ مِنَ الْمَدِينَةِ\",[[3,167,13,16,1]]],[56,\"إيجاز الحذف\",3,196,197,960,\"وَمِنْهَا الشُّرُوعُ فِي الْفِعْلِ نَحْوُ\\\"بِسْمِ اللَّهِ\\\" فَيُقَدَّرُ مَا جُعِلَتِ التَّسْمِيَةُ مَبْدَأً لَهُ فَإِنَّ كَانَتْ عِنْدَ الشُّرُوعِ فِي الْقِرَاءَةِ قُدِّرَتْ \\\"أَقْرَأُ\\\" أَوِ الْأَكْلِ قُدِّرَتْ \\\"آكُلُ\\\" وَعَلَى هَذَا أَهْلُ الْبَيَانِ قَاطِبَةً خِلَافًا لِقَوْلِ النُّحَاةِ إِنَّهُ يُقَدَّرُ \\\"ابْتَدَأْتُ\\\" أَوِ \\\"ابْتِدَائِي\\\" كَائِنٌ \\\"بِسْمِ اللَّهِ\\\" وَيَدُلُّ عَلَى صِحَّةِ الْأَوَّلِ التَّصْرِيحُ بِهِ فِي قَوْلِهِ: ﴿وَقَالَ ارْكَبُوا فِيهَا بِسْمِ اللَّهِ مَجْرَاهَا وَمُرْسَاهَا﴾ وَفِي حَدِيثِ \\\"بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي\\\"\",[[11,41,0,6,1]]],[56,\"إيجاز الحذف\",3,197,197,961,\"وَمِنْهَا الصِّنَاعَةُ النَّحْوِيَّةُ كَقَوْلِهِمْ في ﴿لا أُقْسِمُ﴾: التَّقْدِيرُ \\\"لَأَنَا أُقْسِمُ\\\" لِأَنَّ فِعْلَ الْحَالِ لَا يُقَسَمُ عَلَيْهِ وَفِي: ﴿تَاللَّهِ تَفْتَأُ﴾ التَّقْدِيرُ \\\"لَا تَفْتَأُ\\\" لِأَنَّهُ لَوْ كَانَ الْجَوَابُ مُثَبَّتًا دَخَلْتِ اللَّامُ وَالنُّونُ كَقَوْلِهِ: ﴿وَتَاللَّهِ لأَكِيدَنَّ﴾ وَقَدْ تُوجِبُ الصِّنَاعَةُ التَّقْدِيرَ وَإِنْ كَانَ الْمَعْنَى غَيْرَ مُتَوَقِّفٍ عَلَيْهِ كَقَوْلِهِمْ فِي: ﴿لَا إِلَهَ إِلاَّ اللَّهُ﴾: إِنَّ الْخَبَرَ مَحْذُوفٌ أَيْ مَوْجُودٌ وَقَدْ أَنْكَرُهُ الْإِمَامُ فَخْرُ الدِّينِ وَقَالَ: هَذَا الْكَلَامُ لَا يَحْتَاجُ إِلَى تَقْدِيرٍ وَتَقْدِيرُ النُّحَاةِ فَاسِدٌ لِأَنَّ نَفْيَ الْحَقِيقَةِ مُطْلَقَةً أَعَمُّ مِنْ نَفْيِهَا مُقَيَّدَةً فَإِنَّهَا إِذَا انْتَفَتْ مُطْلَقَةً كَانَ ذَلِكَ دَلِيلًا عَلَى سَلْبِ الْمَاهِيَّةِ مَعَ الْقَيْدِ وَإِذَا انْتَفَتْ مُقَيَّدَةً بِقَيْدٍ مَخْصُوصٍ لَمْ يَلْزَمْ نَفْيُهَا مَعَ قَيْدٍ آخَرَ وَرُدَّ بِأَنَّ تَقْدِيرَهُمْ: \\\"مَوْجُودٌ\\\" يَسْتَلْزِمُ نَفْيَ كُلِّ إِلَهٍ غَيْرَ اللَّهِ قَطْعًا فَإِنَّ الْعَدَمَ لَا كَلَامَ فِيهِ فَهُوَ فِي الْحَقِيقَةِ نَفْيٌ لِلْحَقِيقَةِ مُطْلَقَةً لَا مُقَيَّدَةً ثُمَّ لَا بُدَّ مِنْ تَقْدِيرِ خَبَرٍ لِاسْتِحَالَةِ مُبْتَدَأٍ بِلَا خَبَرٍ ظَاهِرٍ أَوْ مُقَدَّرٍ وَإِنَّمَا يُقَدِّرُ النَّحْوِيُّ لِيُعْطِيَ الْقَوَاعِدَ حَقَّهَا وَإِنْ كَانَ الْمَعْنَى مَفْهُوُمًا\",[[75,1,0,1,3],[75,2,0,1,3],[90,1,0,1,3],[12,85,1,2,1],[21,57,0,1,1],[37,35,5,8,2],[47,19,2,5,2]]],[56,\"إيجاز الحذف\",3,198,198,962,\"قَالَ ابْنُ هِشَامٍ إِنَّمَا يُشْتَرَطُ الدَّلِيلُ فِيمَا إِذَا كَانَ الْمَحْذُوفُ الْجُمْلَةَ بِأَسْرِهَا أَوْ أَحَدَ رُكْنَيْهَا أَوْ يُفِيدُ مَعْنًى فِيهَا هِيَ مَبْنِيَّةٌ عَلَيْهِ نَحْوُ: ﴿تَاللَّهِ تَفْتَأُ﴾ أَمَّا الْفَضْلَةُ فَلَا يُشْتَرَطُ لِحَذْفِهَا وُجْدَانُ دَلِيلٍ بل يشترط ألا يَكُونَ فِي حَذْفِهَا ضَرَرٌ مَعْنَوِيٌّ أَوْ صِنَاعِيٌّ قَالَ: وَيُشْتَرَطُ فِي الدَّلِيلِ اللَّفْظِيِّ أَنْ يَكُونَ طِبْقَ الْمَحْذُوفِ وَرُدَّ قَوْلُ الْفَرَّاءِ فِي: ﴿أَيَحْسَبُ الْأِنْسَانُ أَلَّنْ نَجْمَعَ عِظَامَهُ بَلَى قَادِرِينَ﴾: إن التقدير \\\"بلى لَيَحْسَبُنَا قَادِرِينَ\\\" لِأَنَّ الْحُسْبَانَ الْمَذْكُورَ بِمَعْنَى الظَّنِّ وَالْمُقَدَّرَ بِمَعْنَى الْعِلْمِ لِأَنَّ التَّرَدُّدَ فِي الْإِعَادَةِ كُفْرٌ فَلَا يَكُونُ مَأْمُورًا بِهِ قَالَ وَالصَّوَابُ فِيهَا قَوْلُ سِيبَوَيْهِ إِنَّ \\\"قَادِرِينَ\\\" حَالٌ أَيْ بَلْ نَجْمَعُهَا قَادِرِينَ لِأَنَّ فِعْلَ الْجَمْعِ أَقْرَبُ مِنْ فِعْلِ الْحُسْبَانِ وَلِأَنَّ \\\"بَلَى\\\" لِإِيجَابِ الْمَنْفِيِّ وَهُوَ فِيهَا فِعْلُ الجمع.\",[[12,85,1,2,1],[75,3,0,4,1],[75,4,0,1,1]]],[56,\"إيجاز الحذف\",3,198,198,962,\"الشرط الثاني: ألا يَكُونَ الْمَحْذُوفُ كَالْجُزْءِ وَمِنْ ثَمَّ لَمْ يُحْذَفِ الْفَاعِلُ وَلَا نَائِبُهُ وَلَا اسْمُ كَانَ وَأَخَوَاتُهَا قَالَ ابْنُ هِشَامٍ: وَأَمَّا قَوْلُ ابْنِ عَطِيَّةَ فِي ﴿بِئْسَ مَثَلُ الْقَوْمِ﴾ إن التقدير \\\"بِئْسَ الْمَثَلُ مَثَلُ الْقَوْمِ\\\" فَإِنْ أَرَادَ تَفْسِيرَ الْإِعْرَابِ وَأَنَّ الْفَاعِلَ لَفْظُ \\\"الْمَثَلِ\\\" مَحْذُوفًا فَمَرْدُودٌ وَإِنْ أَرَادَ تَفْسِيرَ الْمَعْنَى وَأَنَّ فِي \\\"بِئْسَ \\\" ضَمِيرُ الْمَثَلِ مُسْتَتِرًا فَسَهْلٌ\",[[62,5,11,13,1]]],[56,\"إيجاز الحذف\",3,198,199,962,\"الشرط الثالث: ألا يَكُونَ مُؤَكَّدًا لِأَنَّ الْحَذْفَ مُنَافٍ لِلتَّأْكِيدِ إِذِ الْحَذْفُ مَبْنِيٌّ عَلَى الِاخْتِصَارِ وَالتَّأْكِيدُ مَبْنِيٌّ عَلَى الطُّولِ وَمِنْ ثَمَّ رَدَّ الْفَارِسِيُّ عَلَى الزَّجَاجِ فِي قَوْلِهِ فِي ﴿إِنْ هَذَانِ لَسَاحِرَانِ﴾: إِنَّ التَّقْدِيرَ \\\"إِنْ هَذَانَ لَهُمَا سَاحِرَانِ\\\" فَقَالَ الْحَذْفُ وَالتَّوْكِيدُ بِاللَّامِ مُتَنَافِيَانِ وَأَمَّا حَذْفُ الشَّيْءِ لِدَلِيلٍ وَتَوْكِيدُهُ فَلَا تَنَافِيَ بَيْنَهُمَا لِأَنَّ الْمَحْذُوفَ لِدَلِيلٍ كَالثَّابِتِ.\",[[20,63,1,3,1]]],[56,\"إيجاز الحذف\",3,199,199,963,\"السابع: ألا يُؤَدِّي حَذْفُهُ إِلَى تَهْيِئَةِ الْعَامِلِ الْقَوِيِّ وَمِنْ ثَمَّ لَمْ يُقَسْ عَلَى قِرَاءَةِ: ﴿وَكُلًا وَعَدَ اللَّهُ الْحُسْنَى﴾\",[[4,95,22,25,2],[57,10,29,32,2]]],[56,\"إيجاز الحذف\",3,199,199,963,\"اعْتَبَرَ الْأَخْفَشُ فِي الْحَذْفِ التَّدْرِيجَ حَيْثُ أَمْكَنَ وَلِهَذَا قَالَ فِي قَوْلِهِ تَعَالَى: ﴿وَاتَّقُوا يَوْمًا لَا تَجْزِي نَفْسٌ عَنْ نَفْسٍ شَيْئًا﴾ إِنَّ الْأَصْلَ \\\"لَا تَجْزِي فِيهِ\\\" فَحُذِفَ حَرْفُ الْجَرِّ فَصَارَ \\\"تَجْزِيهِ\\\" ثُمَّ حُذِفَ الضَّمِيرُ فَصَارَ \\\"تَجْزِي\\\" وَهَذِهِ مُلَاطَفَةٌ فِي الصِّنَاعَةِ وَمَذْهَبُ سِيبَوَيْهِ أَنَّهُمَا حُذِفَا مَعًا قَالَ ابْنُ جِنِّي: وَقَوْلُ الْأَخْفَشِ أَوْفَقُ فِي النَّفْسِ وَآنَسُ مِنْ أَنْ يُحْذَفَ الْحَرْفَانِ مَعًا فِي وَقْتٍ وَاحِدٍ.\",[[2,48,0,7,2],[2,123,0,7,2]]],[56,\"إيجاز الحذف\",3,200,200,964,\"الْأَصْلُ أَنْ يُقَدَّرَ الشَّيْءُ فِي مَكَانِهِ الْأَصْلِيِّ لِئَلَّا يُخَالِفَ الْأَصْلَ مِنْ وَجْهَيْنِ الْحَذْفُ وَوَضْعُ الشَّيْءِ فِي غَيْرِ مَحَلِّهِ فَيُقَدِّرُ الْمُفَسِّرُ فِي نَحْوِ \\\"زَيْدًا رَأَيْتُهُ\\\" مُقَدَّمًا عَلَيْهِ وَجَوَّزَ الْبَيَانِيُّونَ تَقْدِيرُهُ مُؤَخَّرًا عَنْهُ لِإِفَادَةِ الِاخْتِصَاصِ كَمَا قَالَهُ النُّحَاةُ وَإِذَا مَنَعَ مِنْهُ مَانِعٌ نَحْوَ: ﴿وَأَمَّا ثَمُودُ فَهَدَيْنَاهُمْ﴾ إِذْ لَا يَلِي \\\"أَمَّا\\\" فِعْلٌ.\",[[41,17,0,2,1]]],[56,\"إيجاز الحذف\",3,200,201,964,\"يَنْبَغِي تَقْلِيلُ الْمُقَدَّرِ مَهْمَا أَمْكَنَ لِتَقِلَّ مُخَالَفَةُ الْأَصْلِ وَمِنْ ثَمَّ ضَعُفَ قَوْلُ الْفَارِسِيِّ فِي ﴿وَاللاَّئِي لَمْ يَحِضْنَ﴾ إِنَّ التَّقْدِيرَ \\\"فَعِدَتُهُنَّ ثَلَاثَةُ أَشْهُرٍ\\\" وَالْأَوْلَى أَنْ يُقَدَّرَ \\\"كَذَلِكَ\\\" قَالَ الشَّيْخُ عِزُّ الدِّينِ وَلَا يُقَدَّرُ مِنَ الْمَحْذُوفَاتِ إِلَّا أَشَدُّهَا مُوَافَقَةً لِلْغَرَضِ وَأَفْصَحُهَا لِأَنَّ الْعَرَبَ لَا يُقَدِّرُونَ إِلَّا مَا لَوْ لَفَظُوا بِهِ لَكَانَ أَحْسَنَ وَأَنْسَبَ لِذَلِكَ الكلام كما يفعلون في ذَلِكَ فِي الْمَلْفُوظِ بِهِ نَحْوِ: ﴿جَعَلَ اللَّهُ الْكَعْبَةَ الْبَيْتَ الْحَرَامَ قِيَامًا لِلنَّاسِ﴾ قَدَّرَ أَبُو عَلِيٍّ \\\"جَعَلَ اللَّهُ نُصُبَ الْكَعْبَةِ\\\" وَقَدَّرَ غَيْرُهُ \\\"حُرْمَةَ الْكَعْبَةِ\\\" وَهُوَ أَوْلَى لِأَنَّ تَقْدِيرَ الْحُرْمَةِ فِي الْهَدْيِ وَالْقَلَائِدِ وَالشَّهْرِ الْحَرَامِ لَا شَكَّ فِي فَصَاحَتِهِ وَتَقْدِيرُ النُّصُبِ فِيهَا بَعِيدٌ مِنَ الْفَصَاحَةِ قَالَ وَمَهْمَا تَرَدَّدَ الْمَحْذُوفُ بَيْنَ الْحَسَنِ وَالْأَحْسَنِ وَجَبَ تَقْدِيرُ الْأَحْسَنِ لِأَنَّ اللَّهَ وَصَفَ كِتَابَهُ بِأَنَّهُ أَحْسَنُ الْحَدِيثِ فَلْيَكُنْ مَحْذُوفُهُ أَحْسَنَ الْمَحْذُوفَاتِ كَمَا أَنَّ مَلْفُوظَهُ أَحْسَنُ الملفوظات قال وَمَتَى: تَرَدَّدَ بَيْنَ أَنْ يَكُونَ مُجْمَلًا أَوْ مُبَيِّنًا فَتَقْدِيرُ الْمُبَيِّنِ أَحْسَنُ نَحْوُ: ﴿وَدَاوُدَ وَسُلَيْمَانَ إِذْ يَحْكُمَانِ فِي الْحَرْثِ﴾ لَكَ أَنْ تُقَدِّرَ \\\"فِي أَمْرِ الْحَرْثِ\\\" وَ\\\"فِي تَضْمِينِ الْحَرْثِ\\\" وَهُوَ أَوْلَى لِتَعَيُّنِهِ وَالْأَمْرُ مُجْمَلٌ لِتَرَدُّدِهِ بَيْنَ أَنْوَاعٍ.\",[[5,97,0,6,1],[21,78,0,5,1]]],[56,\"إيجاز الحذف\",3,201,201,965,\"فَالْأَوَّلُ: كَقِرَاءَةِ ﴿يُسَبِّحُ لَهُ فِيهَا﴾ بِفَتْحِ الْبَاءِ، ﴿كَذَلِكَ يُوحِي إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ اللَّهُ﴾ بِفَتْحِ الْحَاءِ فَإِنَّ التَّقْدِيرَ: \\\"يُسَبِّحُهُ رِجَالٌ\\\" وَ\\\"يُوحِيهِ اللَّهُ\\\" وَلَا يُقَدَّرَانِ مُبْتَدَأَيْنِ حُذِفَ خَبَرُهُمَا لِثُبُوتِ فَاعِلِيَّةِ الِاسْمَيْنِ فِي رِوَايَةِ مَنْ بَنَى الْفِعْلَ لِلْفَاعِلِ\",[[24,36,9,11,1],[42,3,0,7,1]]],[56,\"إيجاز الحذف\",3,201,201,965,\"وَالثَّانِي: نَحْوُ: ﴿وَلَئِنْ سَأَلْتَهُمْ مَنْ خَلَقَهُمْ لَيَقُولُنَّ اللَّهُ﴾ فَتَقْدِيرُ \\\"خَلَقَهُمُ اللَّهُ\\\" أَوْلَى مِنَ \\\"اللَّهُ خَلَقَهُمْ\\\" لِمَجِيءِ ﴿خَلَقَهُنَّ الْعَزِيزُ الْعَلِيمُ.﴾\",[[43,87,0,5,1],[43,9,7,9,1]]],[56,\"إيجاز الحذف\",3,201,202,965,\"إِذَا دَارَ الْأَمْرُ بَيْنَ كَوْنِ الْمَحْذُوفِ أَوَّلًا أَوْ ثَانِيًا فَكَوْنُهُ ثَانِيًا أَوْلَى وَمِنْ ثَمَّ رُجِّحَ أَنَّ الْمَحْذُوفَ فِي نَحْوِ: ﴿أَتُحَاجُّونِّي﴾ نُونُ الْوِقَايَةِ لَا نُونُ الرَّفْعِ وَفِي ﴿نَارًا تَلَظَّى﴾ التَّاءُ الثَّانِيَةُ لَا تَاءُ الْمُضَارَعَةِ وَفِي ﴿وَاللَّهُ وَرَسُولُهُ أَحَقُّ أَنْ يُرْضُوهُ﴾: أَنَّ الْمَحْذُوفَ خَبَرُ الثَّانِي لَا الْأَوَّلِ وَفِي نَحْوِ: ﴿الْحَجُّ أَشْهُرٌ﴾ أَنَّ الْمَحْذُوفَ مُضَافٌ لِلثَّانِي أَيْ حَجُّ أَشْهُرٍ لَا الْأَوَّلِ أَيْ أَشْهُرُ الْحَجِّ وَقَدْ يَجِبُ كَوْنُهُ مِنَ الْأَوَّلِ نَحْوُ: ﴿إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ﴾ في قراءة من رفع \\\"ملائكته\\\" لِاخْتِصَاصِ الْخَبَرِ بِالثَّانِي لِوُرُودِهِ بِصِيغَةِ الْجَمْعِ وَقَدْ يَجِبُ كَوْنُهُ مِنَ الثَّانِي نَحْوُ: ﴿أَنَّ اللَّهَ بَرِيءٌ مِنَ الْمُشْرِكِينَ وَرَسُولُهُ﴾ أَيْ بَرِيءٌ أَيْضًا لِتَقَدُّمِ الْخَبَرِ عَلَى الثَّانِي.\",[[3,65,3,3,4],[3,66,8,8,4],[6,80,3,3,4],[40,47,1,1,4],[92,14,1,2,1],[9,62,4,8,1],[2,197,0,1,1],[33,56,0,5,1],[9,3,9,14,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,202,203,966,\"أَحَدُهَا: مَا يُسَمَّى بِالِاقْتِطَاعِ وَهُوَ حَذْفُ بَعْضِ حُرُوفِ الْكَلِمَةِ وَأَنْكَرَ ابْنُ الْأَثِيرِ وُرُودَ هَذَا النَّوْعِ فِي الْقُرْآنِ وَرُدَّ بِأَنَّ بَعْضَهُمْ جَعَلَ مِنْهُ فَوَاتِحَ السُّوَرِ عَلَى الْقَوْلِ بِأَنَّ كُلَّ حَرْفٍ مِنْهَا مِنِ اسْمٍ مِنْ أَسْمَائِهِ كَمَا تَقَدَّمَ وَادَّعَى بَعْضُهُمْ أَنَّ الْبَاءَ فِي ﴿وَامْسَحُوا بِرُؤُوسِكُمْ﴾ أَوَّلُ كَلِمَةِ بَعْضٍ ثُمَّ حُذِفَ الْبَاقِي وَمِنْهُ قراءة بعضهم: ﴿وَنَادَوْا يَا مَالِكُ﴾ بِالتَّرْخِيمِ وَلَمَّا سَمِعَهَا بَعْضُ السَّلَفِ قَالَ: مَا أَغْنَى أَهْلَ النَّارِ عَنِ التَّرْخِيمِ وَأَجَابَ بَعْضُهُمْ بِأَنَّهُمْ لشدة ما هم عَجَزُوا عَنْ إِتْمَامِ الْكَلِمَةِ وَيَدْخُلُ فِي هَذَا النَّوْعِ حَذْفُ هَمْزَةِ \\\"أَنَا\\\" فِي قَوْلِهِ: ﴿لَكِنَّا هُوَ اللَّهُ رَبِّي﴾ إِذِ الْأَصْلُ \\\"لَكِنَّ أَنَا\\\" حُذِفَتْ هَمْزَةُ \\\"أَنَا\\\" تَخْفِيفًا وَأُدْغِمَتِ النُّونُ فِي النُّونِ وَمِثْلُهُ مَا قُرِئَ \\\"ويمسك السماء أن تقع علرض\\\" بما أنزليك\\\" ﴿فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ فَلا إِثْمَ عَلَيْهِ﴾ ﴿إِنَّهَا لإِحْدَى الْكُبَرِ.﴾\",[[5,6,12,13,1],[43,77,0,1,1],[18,38,0,3,1],[2,203,5,11,1],[74,35,0,2,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,203,203,967,\"النَّوْعُ الثَّانِي: مَا يُسَمَّى بِالِاكْتِفَاءِ وَهُوَ أَنْ يَقْتَضِيَ الْمَقَامُ ذِكْرَ شَيْئَيْنِ بَيْنَهُمَا تَلَازُمٌ وَارْتِبَاطٌ فَيُكْتَفَى بِأَحَدِهِمَا عَنِ الْآخَرِ لِنُكْتَةٍ وَيَخْتَصُّ غَالِبًا بِالِارْتِبَاطِ الْعَطْفِيِّ كَقَوْلِهِ: ﴿سَرَابِيلَ تَقِيكُمُ الْحَرَّ﴾ أَيْ وَالْبَرْدَ وَخُصِّصَ الْحَرُّ بِالذِّكْرِ لِأَنَّ الْخِطَابَ لِلْعَرَبِ وَبِلَادُهُمْ حَارَةٌ وَالْوِقَايَةُ عِنْدَهُمْ مِنَ الْحَرِّ أَهَمُّ لِأَنَّهُ أَشَدُّ عِنْدَهُمْ مِنَ الْبَرْدِ وَقِيلَ لِأَنَّ الْبَرْدَ تَقَدَّمَ ذِكْرُ الِامْتِنَانِ بِوِقَايَتِهِ صَرِيحًا فِي قَوْلِهِ: ﴿وَمِنْ أَصْوَافِهَا وَأَوْبَارِهَا وَأَشْعَارِهَا﴾ وَفِي قَوْلِهِ: ﴿وَجَعَلَ لَكُمْ مِنَ الْجِبَالِ أَكْنَانًا﴾ وَفِي قَوْلِهِ تَعَالَى: ﴿وَالأَنْعَامَ خَلَقَهَا لَكُمْ فِيهَا دِفْءٌ﴾ وَمِنْ أَمْثِلَةِ هَذَا النَّوْعِ ﴿بِيَدِكَ الْخَيْرُ﴾ أَيْ وَالشَّرُّ وَإِنَّمَا خَصَّ الْخَيْرَ بِالذِّكْرِ لِأَنَّهُ مَطْلُوبُ الْعِبَادِ وَمَرْغُوبُهُمْ أَوْ لِأَنَّهُ أَكْثَرُ وُجُودًا فِي الْعَالَمِ أَوْ لِأَنَّ إِضَافَةَ الشَّرِّ إِلَى الله ليس من بابا الْآدَابِ كَمَا قَالَ ﷺ \\\"وَالشَّرُّ لَيْسَ إِلَيْكَ.\\\"\",[[16,81,13,15,1],[16,80,17,20,1],[16,81,6,10,1],[16,5,0,4,1],[3,26,18,19,2],[7,143,28,29,2]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,203,203,967,\"وَمِنْهَا ﴿وَلَهُ مَا سَكَنَ فِي اللَّيْلِ وَالنَّهَارِ﴾ أَيْ وَمَا تَحَرَّكَ وَخَصَّ السُّكُونَ بِالذِّكْرِ لِأَنَّهُ أَغْلَبُ الْحَالَيْنِ عَلَى الْمَخْلُوقِ مِنَ الْحَيَوَانِ وَالْجَمَادِ وَلِأَنَّ كُلَّ مُتَحَرِّكٍ يَصِيرُ إِلَى السُّكُونِ.\",[[6,13,0,5,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,203,204,967,\"وَمِنْهَا: ﴿الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ﴾ أَيْ وَالشَّهَادَةُ لِأَنَّ الْإِيمَانَ بِكُلٍّ مِنْهُمَا وَاجِبٌ وَآثَرَ الْغَيْبَ لِأَنَّهُ أَمْدَحُ وَلِأَنَّهُ يَسْتَلْزِمُ الْإِيمَانَ بِالشَّهَادَةِ مِنْ غَيْرِ عَكْسٍ. ومنها: ﴿وَرَبُّ الْمَشَارِقِ﴾ أَيْ وَالْمَغَارِبِ\",[[2,3,0,2,1],[26,28,1,2,4],[37,5,5,6,4],[70,40,2,3,4],[73,9,0,1,4]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,204,204,968,\"وَمِنْهَا: ﴿هُدىً لِلْمُتَّقِينَ﴾ أَيْ وَلِلْكَافِرِينَ قَالَهُ ابْنُ الْأَنْبَارِيِّ ويؤيده قوله: ﴿هُدىً لِلنَّاسِ﴾\",[[2,2,5,6,1],[2,185,6,7,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,204,204,968,\"وَمِنْهَا: ﴿إِنِ امْرُؤٌ هَلَكَ لَيْسَ لَهُ وَلَدٌ﴾ أَيْ وَلَا وَالِدٌ بِدَلِيلِ أَنَّهُ أَوْجَبَ لِلْأُخْتِ النِّصْفَ وَإِنَّمَا يَكُونُ ذَلِكَ مَعَ فَقْدِ الْأَبِ لِأَنَّهُ يُسْقِطُهَا\",[[4,176,6,11,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,204,204,968,\"النَّوْعُ الثَّالِثُ: مَا يُسَمَّى بِالِاحْتِبَاكِ وَهُوَ مِنْ أَلْطَفِ الْأَنْوَاعِ وَأَبْدَعِهَا وَقَلَّ مَنْ تَنَبَّهَ لَهُ أَوْ نَبَّهَ عَلَيْهِ مِنْ أَهْلِ فن البلاغة ولم أره فِي شَرْحِ بَدِيعِيَّةِ الْأَعْمَى لِرَفِيقِهِ الْأَنْدَلُسِيِّ وَذَكَرَهُ الزَّرْكَشِيُّ فِي الْبُرْهَانِ ولم يسمه هذا لاسم بَلْ سَمَّاهُ الْحَذْفَ الْمُقَابَلِيَّ وَأَفْرَدَهُ بِالتَّصْنِيفِ مِنْ أَهْلِ الْعَصْرِ الْعَلَّامَةُ بُرْهَانُ الدِّينِ الْبِقَاعِيُّ قَالَ الْأَنْدَلُسِيُّ فِي شَرْحِ الْبَدِيعِيَّةِ مِنْ أَنْوَاعِ الْبَدِيعِ الِاحْتِبَاكُ وَهُوَ نَوْعٌ عَزِيزٌ وَهُوَ أَنْ يُحْذَفَ مِنَ الْأَوَّلِ مَا أُثْبِتَ نَظِيرُهُ فِي الثَّانِي وَمِنَ الثَّانِي مَا أُثْبِتَ نَظِيرُهُ فِي الْأَوَّلِ كَقَوْلِهِ تَعَالَى: ﴿وَمَثَلُ الَّذِينَ كَفَرُوا كَمَثَلِ الَّذِي يَنْعِقُ﴾ الْآيَةَ التَّقْدِيرُ وَمَثَلُ الْأَنْبِيَاءِ وَالْكُفَّارِ كَمَثَلِ الَّذِي يَنْعِقُ وَالَّذِي يَنْعَقُ بِهِ فَحَذَفَ مِنَ الْأَوَّلِ الْأَنْبِيَاءَ لِدَلَالَةِ \\\"الَّذِي يَنْعِقُ\\\" عَلَيْهِ وَمِنَ الثَّانِي الَّذِي يَنْعِقُ بِهِ لِدَلَالَةِ \\\"الَّذِينَ كَفَرُوا\\\" عَلَيْهِ\",[[2,171,0,5,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,204,205,968,\"وَقَوْلُهُ: ﴿وَأَدْخِلْ يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ﴾ التَّقْدِيرُ تَدُخُلُ غَيْرَ بَيْضَاءَ وَأَخْرِجْهَا تَخْرُجُ بَيْضَاءَ فَحَذَفَ مِنَ الْأَوَّلِ \\\"غَيْرَ بَيْضَاءَ\\\" وَمِنَ الثَّانِي \\\"وَأَخْرِجْهَا\\\" وَقَالَ الزَّرْكَشِيُّ: هو أَنْ يَجْتَمِعَ فِي الْكَلَامِ مُتَقَابِلَانِ فَيُحْذَفُ مِنْ كُلِّ وَاحِدٍ مِنْهُمَا مُقَابِلُهُ لِدَلَالَةِ الْآخَرِ عَلَيْهِ كَقَوْلِهِ تَعَالَى: ﴿أَمْ يَقُولُونَ افْتَرَاهُ قُلْ إِنِ افْتَرَيْتُهُ فَعَلَيَّ إِجْرَامِي وَأَنَا بَرِيءٌ مِمَّا تُجْرِمُونَ﴾ التَّقْدِيرُ \\\"إِنِ افْتَرَيْتُهُ فَعَلَيَّ إِجْرَامِي وَأَنْتُمْ بُرَآءُ مِنْهُ وَعَلَيْكُمْ إِجْرَامُكُمْ وَأَنَا بَرِيءٌ مِمَّا تُجْرِمُونَ\\\"\",[[27,12,0,5,1],[11,35,0,11,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,205,205,969,\"وَقَوْلُهُ: ﴿وَلا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ﴾ أَيْ حَتَّى يَطْهُرْنَ مِنَ الدَّمِ وَيَتَطَهَّرْنَ بِالْمَاءِ فَإِذَا طَهُرْنَ وَتَطَهَّرْنَ فَأْتُوهُنَّ\",[[2,222,10,16,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,205,205,969,\"وَقَوْلُهُ: ﴿خَلَطُوا عَمَلًا صَالِحًا وَآخَرَ سَيِّئًا﴾ أَيْ عَمَلًا صَالِحًا بِسَيِّئٍ وَآخَرَ سيئا صالح\",[[9,102,3,7,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,205,205,969,\"قُلْتُ: وَمِنْ لَطِيفِهِ قَوْلُهُ: ﴿فِئَةٌ تُقَاتِلُ فِي سَبِيلِ اللَّهِ وَأُخْرَى كَافِرَةٌ﴾ أَيْ فِئَةٌ مُؤْمِنَةٌ تُقَاتِلُ فِي سَبِيلِ اللَّهِ وَأُخْرَى كَافِرَةٌ تَقَاتُلُ فِي سَبِيلِ الطَّاغُوتِ\",[[3,13,7,13,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,206,206,970,\"حذف المضاف هو كَثِيرٌ فِي الْقُرْآنِ جِدًّا حَتَّى قَالَ ابْنُ جِنِّي فِي الْقُرْآنِ مِنْهُ زُهَاءَ أَلْفِ مَوْضِعٍ وَقَدْ سَرَدَهَا الشَّيْخُ عِزُّ الدِّينِ فِي كِتَابِهِ \\\"الْمَجَازُ\\\" عَلَى تَرْتِيبِ السُّوَرِ وَالْآيَاتِ وَمِنْهُ: ﴿الْحَجُّ أَشْهُرٌ﴾ أَيْ حَجُّ أَشْهُرٍ أَوْ أَشْهُرُ الْحَجِّ ﴿وَلَكِنَّ الْبِرَّ مَنْ آمَنَ﴾ أَيْ ذَا الْبَرِّ أَوْ بِرُّ مَنْ ﴿حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ﴾ أي نكاح أمهاتكم ﴿إِذًا لَأَذَقْنَاكَ ضِعْفَ الْحَيَاةِ وَضِعْفَ الْمَمَاتِ﴾ أَيْ ضِعفَ عَذَابِ ﴿وَفِي الرِّقَابِ﴾ أَيْ وَفِي تَحْرِيرِ الرِّقَابِ\",[[2,197,0,1,1],[2,177,8,11,1],[4,23,0,2,1],[17,75,0,5,1],[2,177,29,30,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,206,206,970,\"حَذْفُ الْمُضَافِ إِلَيْهِ يَكْثُرُ فِي يَاءِ الْمُتَكَلِّمِ نَحْوُ ﴿رَبِّ اغْفِرْ لِي﴾ وَفِي الْغَايَاتِ نَحْوُ: ﴿لِلَّهِ الأَمْرُ مِنْ قَبْلُ وَمِنْ بَعْدُ﴾ أَيْ مِنْ قَبْلِ الْغَلَبِ وَمِنْ بَعْدِهِ\",[[7,151,1,3,3],[38,35,1,3,3],[71,28,0,2,3],[30,4,3,8,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,206,206,970,\"وَفِي كُلٍّ وَأَيٍّ وَبَعْضٍ وَجَاءَ فِي غَيْرِهِنَّ كَقِرَاءَةِ ﴿فَلا خَوْفٌ عَلَيْهِمْ﴾ بِضَمٍّ بِلَا تَنْوِينٍ أَيْ فَلَا خَوْفَ شَيْءٍ عَلَيْهِمْ\",[[2,38,11,13,5],[5,69,14,16,5],[6,48,9,11,5],[7,35,12,14,5],[46,13,7,9,5]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,206,207,970,\"حَذْفُ الْمُبْتَدَإِ يَكْثُرُ فِي جَوَابِ الِاسْتِفْهَامِ نَحْوُ: ﴿وَمَا أَدْرَاكَ مَا هِيَهْ نَارٌ﴾ أَيْ هِيَ نَارٌ وَبَعْدَ فَاءِ الجواب ﴿مَنْ عَمِلَ صَالِحًا فَلِنَفْسِهِ﴾ أَيْ فَعَمِلَهُ لِنَفْسِهِ ﴿وَمَنْ أَسَاءَ فَعَلَيْهَا﴾ أَيْ فَإِسَاءَتُهُ عَلَيْهَا وَبَعْدَ الْقَوْلِ نَحْوُ: ﴿وَقَالُوا أَسَاطِيرُ الأَوَّلِينَ﴾ ﴿قَالُوا أَضْغَاثُ أَحْلامٍ﴾ وَبَعْدَ مَا الْخَبَرُ صِفَةٌ لَهُ فِي الْمَعْنَى نَحْوُ: ﴿التَّائِبُونَ الْعَابِدُونَ﴾ ونحو: ﴿صُمٌّ بُكْمٌ عُمْيٌ﴾\",[[101,10,0,3,1],[101,11,0,0,1],[41,46,0,6,2],[45,15,0,6,2],[16,24,6,8,4],[25,5,0,2,4],[68,15,4,6,4],[83,13,4,6,4],[12,44,0,2,2],[21,5,1,3,2],[9,112,0,1,1],[2,18,0,2,2],[2,171,12,14,2]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,207,207,971,\"وَوَقَعَ فِي غَيْرِ ذَلِكَ نَحْوُ: ﴿لَا يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُوا فِي الْبِلادِ مَتَاعٌ قَلِيلٌ﴾ ﴿لَمْ يَلْبَثُوا إِلاَّ سَاعَةً مِنْ نَهَارٍ بَلاغٌ﴾ أي هذا ﴿سُورَةٌ أَنْزَلْنَاهَا﴾ أَيْ هَذِهِ\",[[3,196,0,6,1],[3,197,0,1,1],[46,35,15,21,1],[24,1,0,1,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,207,207,971,\"وَوَجَبَ فِي النَّعْتِ الْمَقْطُوعِ إِلَى الرَّفْعِ حَذْفُ الْخَبَرِ نَحْوُ: ﴿أُكُلُهَا دَائِمٌ وَظِلُّهَا﴾ أَيْ دَائِمٌ\",[[13,35,9,11,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,207,207,971,\"وَيَحْتَمِلُ الْأَمْرَيْنِ: ﴿فَصَبْرٌ جَمِيلٌ﴾ أَيْ أَجْمَلُ أَوْ فَأَمْرِي صَبْرٌ ﴿فَتَحْرِيرُ رَقَبَةٍ﴾ أَيْ عَلَيْهِ أَوْ فَالْوَاجِبُ\",[[12,18,11,12,3],[12,83,6,7,3],[70,5,1,2,3],[4,92,12,13,5],[4,92,30,31,5],[4,92,44,45,5],[5,89,23,24,5],[58,3,8,9,5]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,207,207,971,\"حَذْفُ الموصوف: ﴿نْدَهُمْ قَاصِرَاتُ الطَّرْف﴾ أَيْ حُورٌ قَاصِرَاتٌ ﴿أَنِ اعْمَلْ سَابِغَاتٍ﴾ أَيْ دُرُوعًا سَابِغَاتٍ ﴿أَيُّهَا الْمُؤْمِنُونَ﴾ أَيِ الِقَوْمُ الِمُؤِمِنُونَ\",[[34,11,0,2,1],[24,31,74,75,2],[48,20,13,14,2]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,207,208,971,\"حَذْفُ الصِّفَةِ نَحْوُ ﴿يَأْخُذُ كُلَّ سَفِينَةٍ﴾ أَيْ صَالِحَةٍ بِدَلِيلِ أَنَّهُ قُرِئَ كَذَلِكَ وَأَنَّ تَعْيِيبَهَا لَا يُخْرِجُهَا عَنْ كَوْنِهَا سَفِينَةً ﴿الآنَ جِئْتَ بِالْحَقِّ﴾ أَيِ الِوَاضِحِ وَإِلَّا لَكَفَرُوا بِمَفْهُومِ ذَلِكَ ﴿فَلا نُقِيمُ لَهُمْ يَوْمَ الْقِيَامَةِ وَزْنًا﴾ أَيْ نَافِعًا\",[[18,79,13,15,1],[2,71,17,19,1],[18,105,8,13,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,208,208,972,\"حَذْفُ الْمَعْطُوفِ عَلَيْهِ: ﴿أَنِ اضْرِبْ بِعَصَاكَ الْبَحْرَ﴾ فَانْفَلَقَ أَيْ فَضَرَبَ فَانْفَلَقَ، وَحَيْثُ دَخَلَتْ وَاوُ الْعَطْفِ عَلَى لَامِ التَّعْلِيلِ فَفِي تَخْرِيجِهِ وَجْهَانِ:\",[[26,63,3,6,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,208,208,972,\"أَحَدُهُمَا: أَنْ يَكُونَ تَعْلِيلًا مُعَلَّلُهُ مَحْذُوفٌ كَقَوْلِهِ ﴿وَلِيُبْلِيَ الْمُؤْمِنِينَ مِنْهُ بَلاءً حَسَنًا﴾ فَالْمَعْنَى وَلِلْإِحْسَانِ إِلَى الْمُؤْمِنِينَ فَعَلَ ذَلِكَ.\",[[8,17,12,16,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,208,208,972,\"حَذْفُ الْمَعْطُوفِ مَعَ الْعَاطِفِ ﴿لَا يَسْتَوِي مِنْكُمْ مَنْ أَنْفَقَ مِنْ قَبْلِ الْفَتْحِ وَقَاتَلَ﴾ أَيْ وَمَنْ أَنْفَقَ بَعْدَهُ ﴿بِيَدِكَ الْخَيْرُ﴾ أَيْ وَالشَّرُ\",[[57,10,11,19,1],[3,26,18,19,2],[7,143,28,29,2]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,208,208,972,\"حَذْفُ الْمُبْدَلِ مِنْهُ خَرَّجَ عَلَيْهِ: ﴿وَلا تَقُولُوا لِمَا تَصِفُ أَلْسِنَتُكُمُ الْكَذِبَ﴾ أي لما تصفه والكذب بَدَلٌ مِنَ الْهَاءِ\",[[16,116,0,5,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,208,208,972,\"حَذْفُ الْفَاعِلِ لَا يَجُوزُ إِلَّا فِي فَاعِلِ الْمَصْدَرِ نَحْوُ: ﴿لَا يَسْأَمُ الأِنْسَانُ مِنْ دُعَاءِ الْخَيْرِ﴾ أَيْ دُعَائِهِ الْخَيْرَ وَجَوَّزَهُ الْكِسَائِيُّ مُطْلَقًا لِدَلِيلٍ وَخَرَّجَ عَلَيْهِ: ﴿إِذَا بَلَغَتِ التَّرَاقِيَ﴾ أَيِ الرُّوحُ، ﴿حَتَّى تَوَارَتْ بِالْحِجَابِ﴾ أَيْ الشَّمْسُ\",[[41,49,0,5,1],[75,26,1,3,1],[38,32,8,10,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,208,209,972,\"حَذْفُ الْمَفْعُولِ تَقَدَّمَ أَنَّهُ كَثِيرٌ فِي مَفْعُولِ الْمَشِيئَةِ وَالْإِرَادَةِ وَيَرِدُ فِي غَيْرِهِمَا، نَحْوُ: ﴿إِنَّ الَّذِينَ اتَّخَذُوا الْعِجْلَ﴾ أَيْ إِلَهًا ﴿كَلَّا سَوْفَ تَعْلَمُونَ﴾ أَيْ عَاقِبَةَ أَمْرِكُمْ\",[[7,152,0,3,1],[102,3,0,2,2],[102,4,1,3,2]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,209,209,973,\"حَذْفُ الْحَالِ يَكْثُرُ إِذَا كَانَ قَوْلًا نَحْوُ: ﴿وَالْمَلائِكَةُ يَدْخُلُونَ عَلَيْهِمْ مِنْ كُلِّ بَابٍ سَلامٌ﴾ أَيْ قَائِلِينَ حَذْفُ الْمُنَادَى: ﴿أَلَّا يا اسجدوا﴾ أي يا هؤلاء ﴿يَا لَيْتَ﴾ أَيْ يَا قَوْمِ\",[[13,23,9,14,1],[13,24,0,0,1],[27,25,0,1,3],[68,42,5,6,3],[68,43,7,8,3]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,209,209,973,\"الصِّلَةُ: نَحْوُ: ﴿أَهَذَا الَّذِي بَعَثَ اللَّهُ رَسُولًا﴾ أَيْ بَعَثَهُ.\",[[25,41,6,10,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,209,209,973,\"وَالصِّفَةُ: نَحْوُ: ﴿وَاتَّقُوا يَوْمًا لَا تَجْزِي نَفْسٌ عَنْ نَفْسٍ﴾ أَيْ فِيهِ\",[[2,48,0,6,2],[2,123,0,6,2]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,209,209,973,\"وَالْخَبَرُ: نَحْوُ: ﴿وَكُلًا وَعَدَ اللَّهُ الْحُسْنَى﴾ أَيْ وَعَدَهُ.\",[[4,95,22,25,2],[57,10,29,32,2]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,209,209,973,\"حَذْفُ مَخْصُوصِ نِعْمَ، ﴿إِنَّا وَجَدْنَاهُ صَابِرًا نِعْمَ الْعَبْدُ﴾ أَيْ أَيُّوبُ. ﴿فَقَدَرْنَا فَنِعْمَ الْقَادِرُونَ﴾ أَيْ نَحْنُ ﴿وَلَنِعْمَ دَارُ الْمُتَّقِينَ﴾ أي الجنة\",[[38,44,7,11,1],[77,23,0,2,1],[16,30,17,19,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,209,210,973,\"حذف الموصول، نحو: ﴿آمَنَّا بِالَّذِي أُنْزِلَ إِلَيْنَا وَأُنْزِلَ إِلَيْكُمْ﴾ أَيْ وَالَّذِي أُنْزِلَ إِلَيْكُمْ لِأَنَّ الَّذِي أُنْزِلَ إِلَيْنَا لَيْسَ هُوَ الَّذِي أُنْزِلَ إِلَى مَنْ قَبْلَنَا وَلِهَذَا أُعِيدَتْ \\\"مَا\\\" فِي قَوْلِهِ: ﴿آمَنَّا بِاللَّهِ وَمَا أُنْزِلَ إِلَيْنَا وَمَا أُنْزِلَ إِلَى إِبْرَاهِيمَ﴾\",[[29,46,13,18,1],[2,136,1,9,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,210,210,974,\"يَطَّرِدُ إِذَا كَانَ مُفَسَّرًا نَحْوُ: ﴿وَإِنْ أَحَدٌ مِنَ الْمُشْرِكِينَ اسْتَجَارَكَ﴾ ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ ﴿قُلْ لَوْ أَنْتُمْ تَمْلِكُونَ﴾\",[[9,6,0,4,1],[84,1,0,2,1],[17,100,0,3,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,210,210,974,\"وَيَكْثُرُ فِي جَوَابِ الِاسْتِفْهَامِ نَحْوُ: ﴿وَقِيلَ لِلَّذِينَ اتَّقَوْا مَاذَا أَنْزَلَ رَبُّكُمْ قَالُوا خَيْرًا﴾ أَيْ أَنْزَلَ\",[[16,30,0,7,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,210,211,974,\"وَأَكْثَرُ مِنْهُ حَذْفُ الْقَوْلِ نَحْوُ: ﴿وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ مِنَ الْبَيْتِ وَإِسْمَاعِيلُ رَبَّنَا﴾ أي يقولان: ربنا ويأتي في غَيْرِ ذَلِكَ نَحْوُ: ﴿انْتَهُوا خَيْرًا لَكُمْ﴾ أي وأتوا ﴿وَالَّذِينَ تَبَوَّأُوا الدَّارَ وَالأِيمَانَ﴾ أَيْ وَأَلِفُوا الْإِيمَانَ أَوِ اعْتَقَدُوا ﴿اسْكُنْ أَنْتَ وَزَوْجُكَ الْجَنَّةَ﴾ أَيْ وَلْيَسْكُنْ زَوْجُكَ ﴿وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ﴾ أي أذم ﴿وَالْمُقِيمِينَ الصَّلاةَ﴾ أَيْ أَمْدَحُ ﴿وَلَكِنْ رَسُولَ اللَّهِ﴾ أَيْ كَانَ ﴿وَإِنَّ كُلًا لَمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمَالَهُمْ﴾ أَمْثِلَةُ حَذْفِ الْحَرْفِ:\",[[2,127,0,7,1],[4,171,31,33,1],[59,9,0,3,1],[2,35,2,5,1],[111,4,0,2,1],[4,162,14,15,1],[33,40,7,9,1],[11,111,0,5,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,211,211,975,\"قَالَ ابْنُ جِنِّي فِي الْمُحْتَسَبِ أَخْبَرْنَا أَبُو عَلِيٍّ قَالَ قَالَ أَبُو بَكْرٍ حَذْفُ الْحَرْفِ لَيْسَ بِقِيَاسٍ لِأَنَّ الْحُرُوفَ إنما دخلت الكلام الْكَلَامَ لِضَرْبٍ مِنَ الِاخْتِصَارِ فَلَوْ ذَهَبْتَ تَحْذِفُهَا لَكُنْتَ مُخْتَصِرًا لَهَا هِيَ أَيْضًا وَاخْتِصَارُ الْمُخْتَصَرِ إِجْحَافٌ بِهِ. حَذْفُ هَمْزَةِ الِاسْتِفْهَامِ قَرَأَ ابْنُ محيصن: \\\"سواء عليهم أنذرتهم\\\" وخرج عليه ﴿هَذَا رَبِّي﴾ فِي الْمَوَاضِعِ الثَّلَاثَةِ ﴿وَتِلْكَ نِعْمَةٌ تَمُنُّهَا﴾ أي أو تلك؟\",[[6,76,7,8,3],[6,77,5,6,3],[6,78,5,6,3],[26,22,0,2,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,211,211,975,\"حذف الموصوف الْحَرْفَيِّ قَالَ ابْنُ مَالِكٍ: لَا يَجُوزُ إِلَّا فِي \\\"أَنْ\\\" نَحْوُ: ﴿وَمِنْ آيَاتِهِ يُرِيكُمُ الْبَرْقَ﴾\",[[30,24,0,3,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,211,211,975,\"وَحَذْفُ الْجَارِ يَطِّرُدُ مَعَ أَنْ وأن نَحْوُ: ﴿يَمُنُّونَ عَلَيْكَ أَنْ أَسْلَمُوا قُلْ لَا تَمُنُّوا عَلَيَّ إِسْلامَكُمْ بَلِ اللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَدَاكُمْ﴾ ﴿أَطْمَعُ أَنْ يَغْفِرَ لِي﴾ ﴿أَيَعِدُكُمْ أَنَّكُمْ﴾ أَيْ بِأَنَّكُمْ وَجَاءَ مَعَ غَيْرِهِمَا نَحْوُ: ﴿قَدَّرْنَاهُ مَنَازِلَ﴾ أي قدرنا له ﴿وَيَبْغُونَهَا عِوَجًا﴾ أي لها ﴿يُخَوِّفُ أَوْلِيَاءَهُ﴾ أَيْ يُخَوِّفُكُمْ بِأَوْلِيَائِهِ ﴿وَاخْتَارَ مُوسَى قَوْمَهُ﴾ أَيْ مِنْ قَوْمِهِ ﴿وَلا تَعْزِمُوا عُقْدَةَ النِّكَاحِ﴾ أَيْ عَلَى عُقْدَةِ النِّكَاحِ\",[[49,17,0,14,1],[26,82,1,4,1],[23,35,0,1,1],[36,39,1,2,1],[7,45,5,6,1],[7,155,0,2,1],[2,235,26,29,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,211,212,975,\"حَذْفُ الْعَاطِفِ خَرَّجَ عَلَيْهِ الْفَارِسِيُّ: ﴿وَلا عَلَى الَّذِينَ إِذَا مَا أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَا أَجِدُ مَا أَحْمِلُكُمْ عَلَيْهِ تَوَلَّوْا﴾ أَيْ وَقُلْتَ ﴿وُجُوهٌ يَوْمَئِذٍ نَاعِمَةٌ﴾، أَيْ وَوُجُوهٌ عَطْفًا عَلَى ﴿وُجُوهٌ يَوْمَئِذٍ خَاشِعَةٌ.﴾\",[[9,92,0,13,1],[88,8,0,2,1],[88,2,0,2,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,212,212,976,\"حَذْفُ فَاءِ الْجَوَابِ وَخَرَّجَ عَلَيْهِ الْأَخْفَشُ: ﴿إِنْ تَرَكَ خَيْرًا الْوَصِيَّةُ لِلْوَالِدَيْنِ.﴾\",[[2,180,6,10,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,212,212,976,\"حَذْفُ حَرْفِ النِّدَاءِ كَثِيرٌ: ﴿هَا أَنْتُمْ أُولاءِ ت﴾ ﴿يُوسُفُ أَعْرِضْ﴾ ﴿قَالَ رَبِّ إِنِّي وَهَنَ الْعَظْمُ مِنِّي﴾ ﴿فَاطِرِ السَّمَاوَاتِ وَالأَرْضِ﴾ وَفِي الْعَجَائِبِ لِلْكَرْمَانِيِّ: كَثُرَ حَذْفُ \\\"يَا\\\" فِي الْقُرْآنِ مِنَ الرَّبِّ تَنْزِيهًا وَتَعْظِيمًا لِأَنَّ فِي النِّدَاءِ طَرَفًا مِنَ الْأَمْرِ.\",[[12,29,0,1,1],[19,4,0,5,1],[12,101,9,11,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,212,212,976,\"حَذْفُ \\\"قَدْ\\\" فِي الْمَاضِي إِذَا وَقَعَ حَالًا نَحْوُ: ﴿أوْ جَاءُوكُمْ حَصِرَتْ صُدُورُهُمْ﴾ ﴿قَالُوا أَنُؤْمِنُ لَكَ وَاتَّبَعَكَ الأَرْذَلُونَ.﴾\",[[4,90,9,11,1],[26,111,0,4,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,212,212,976,\"حَذْفُ \\\"لَا\\\" النَّافِيَةِ يَطَّرِدُ فِي جَوَابِ الْقَسَمِ إِذَا كَانَ الْمَنْفِيُّ مضارعا نحو: ﴿تَاللَّهِ تَفْتَأُ﴾ وَوَرَدَ فِي غَيْرِهِ نَحْوُ: ﴿وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ﴾ أَيْ لَا يُطِيقُونَهُ ﴿وَأَلْقَى فِي الأَرْضِ رَوَاسِيَ أَنْ تَمِيدَ بِكُمْ﴾ أَيْ لِئَلَّا تَمِيدَ\",[[12,85,1,2,1],[2,184,13,16,1],[16,15,0,6,2],[31,10,5,11,2]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,212,212,976,\"حَذْفُ لَامِ التَّوْطِئَةِ: ﴿وَإِنْ لَمْ يَنْتَهُوا عَمَّا يَقُولُونَ لَيَمَسَّنَّ﴾ ﴿وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ﴾\",[[5,73,14,19,1],[6,121,16,19,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,212,213,976,\"حَذْفُ لَامِ الْأَمْرِ خَرَّجَ عَلَيْهِ ﴿قُلْ لِعِبَادِيَ الَّذِينَ آمَنُوا يُقِيمُوا﴾ أَيْ لِيُقِيمُوا حَذْفُ لَامِ \\\"لَقَدْ\\\" يَحْسُنُ مَعَ طُولِ الْكَلَامِ نَحْوُ: ﴿قَدْ أَفْلَحَ مَنْ زَكَّاهَا﴾ حَذْفُ نُونِ التَّوْكِيدِ خَرَّجَ عَلَيْهِ قِرَاءَةَ ﴿أَلَمْ نَشْرَحْ لَكَ﴾ بِالنَّصْبِ\",[[14,31,0,4,1],[91,9,0,3,1],[94,1,0,2,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,213,213,977,\"حَذْفُ التَّنْوِينِ خَرَّجَ عَلَيْهِ قِرَاءَةَ: ﴿قُلْ هُوَ اللَّهُ أَحَدٌ اللَّهُ الصَّمَدُ﴾ ﴿وَلا اللَّيْلُ سَابِقُ النَّهَارِ﴾ بِالنَّصْبِ حَذْفُ نُونِ الْجَمْعِ خَرَّجَ عَلَيْهِ قِرَاءَةَ \\\"وَمَا هُمْ بِضَارِّي بِهِ مِنْ أَحَدٍ\\\"\",[[112,1,0,3,1],[112,2,0,1,1],[36,40,7,10,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,213,213,977,\"حَذْفُ حَرَكَةِ الْإِعْرَابِ وَالْبِنَاءِ وخرج عَلَيْهِ قِرَاءَةَ ﴿فَتُوبُوا إِلَى بَارِئِكُمْ﴾ وَ﴿يَأْمُرُكُمْ﴾ ﴿وَبُعُولَتُهُنَّ أَحَقُّ﴾ بِسُكُونِ الثَّلَاثَةِ\",[[2,54,10,12,1],[2,222,19,19,1],[2,228,21,22,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,213,213,977,\"وَكَذَا ﴿أَوْ يَعْفُوَ الَّذِي بِيَدِهِ عُقْدَةُ النِّكَاحِ﴾ ﴿فَأُوَارِيَ سَوْءَةَ أَخِي﴾ ﴿مَا بَقِيَ مِنَ الرِّبا﴾\",[[2,237,17,21,1],[5,31,19,21,1],[2,278,6,9,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,213,214,977,\"حَذْفُ مُضَافَيْنِ ﴿فَإِنَّهَا مِنْ تَقْوَى الْقُلُوبِ﴾ أَيْ فَإِنَّ تَعْظِيمَهَا مِنْ أَفْعَالِ ذَوِي تَقْوَى الْقُلُوبِ ﴿فَقَبَضْتُ قَبْضَةً مِنْ أَثَرِ الرَّسُولِ﴾ أَيْ مِنْ أَثَرِ حَافِرِ فَرَسِ الرَّسُولِ ﴿تَدُورُ أَعْيُنُهُمْ كَالَّذِي يُغْشَى عَلَيْهِ مِنَ الْمَوْتِ﴾ أَيْ كَدَوَرَانِ عَيْنِ الَّذِي، ﴿وَتَجْعَلُونَ رِزْقَكُمْ﴾ أَيْ بَدَلَ شُكْرِ رِزْقِكُمْ حَذْفُ ثَلَاثَةِ مُتَضَايِفَاتٍ:\",[[22,32,5,8,1],[20,96,6,10,1],[33,19,8,14,1],[56,82,0,1,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,214,214,978,\"﴿فَكَانَ قَابَ قَوْسَيْنِ﴾ أَيْ فَكَانَ مِقْدَارُ مَسَافَةِ قُرْبِهِ مِثْلَ قَابِ قَوْسَيْنِ فَحُذِفَ ثَلَاثَةٌ مِنِ اسْمِ كَانَ وَوَاحِدٌ مِنْ خَبَرِهَا\",[[53,9,0,2,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,214,214,978,\"حَذْفُ مَفْعُولَيْ بَابِ ظَنَّ، ﴿أَيْنَ شُرَكَائِيَ الَّذِينَ كُنْتُمْ تَزْعُمُونَ﴾ أَيْ تَزْعُمُونَهُمْ شُرَكَائِي\",[[28,62,3,7,2],[28,74,3,7,2]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,214,214,978,\"حَذْفُ الْجَارِ مَعَ الْمَجْرُورِ ﴿خَلَطُوا عَمَلًا صَالِحًا﴾ أي بسيء ﴿وَآخَرَ سَيِّئًا﴾ أَيْ بِصَالِحٍ\",[[9,102,3,7,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,214,214,978,\"حَذْفُ حَرْفِ الشَّرْطِ وَفِعْلِهِ يَطَّرِدُ بَعْدَ الطَّلَبِ نَحْوُ: ﴿فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ﴾ أَيْ إِنِ اتَّبَعْتُمُونِي، ﴿قُلْ لِعِبَادِيَ الَّذِينَ آمَنُوا يُقِيمُوا الصَّلاةَ﴾ أَيْ إِنْ قُلْتُ لَهُمْ يُقِيمُوا وَجَعَلَ مِنْهُ الزَّمَخْشَرِيُّ ﴿فَلَنْ يُخْلِفَ اللَّهُ عَهْدَهُ﴾ أَيْ إِنِ اتَّخَذْتُمْ عِنْدَ اللَّهِ عَهْدًا فَلَنْ يُخْلِفَ اللَّهُ وَجَعَلَ مِنْهُ أَبُو حَيَّانَ ﴿فَلِمَ تَقْتُلُونَ أَنْبِيَاءَ اللَّهِ مِنْ قَبْلُ﴾ أَيْ إِنْ كُنْتُمْ آمَنْتُمْ بِمَا أُنْزِلُ إِلَيْكُمْ فَلِمَ تَقْتُلُونَ\",[[3,31,5,7,1],[14,31,0,5,1],[2,80,12,15,1],[2,91,21,26,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,214,215,978,\"حَذْفُ جَوَابِ الشَّرْطِ ﴿فَإِنِ اسْتَطَعْتَ أَنْ تَبْتَغِيَ نَفَقًا فِي الأَرْضِ أَوْ سُلَّمًا فِي السَّمَاءِ﴾ أَيْ فَافْعَلْ، ﴿وَإِذَا قِيلَ لَهُمُ اتَّقُوا مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ﴾ أَيْ أَعْرَضُوا بِدَلِيلِ مَا بَعْدَهُ، ﴿أَإِنْ ذُكِّرْتُمْ﴾ أي تطيرتم، ﴿وَلَوْ جِئْنَا بِمِثْلِهِ مَدَدًا﴾ أي لنفذ، ﴿وَلَوْ تَرَى إِذِ الْمُجْرِمُونَ نَاكِسُو رُؤُوسِهِمْ﴾ أَيْ لَرَأَيْتَ أَمْرًا فَظِيعًا، ﴿وَلَوْلا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ وَأَنَّ اللَّهَ رَؤُوفٌ رَحِيمٌ﴾ أَيْ لَعَذَّبَكُمْ ﴿لَوْلا أَنْ رَبَطْنَا عَلَى قَلْبِهَا﴾ أَيْ لَأَبْدَتْ بِهِ ﴿وَلَوْلا رِجَالٌ مُؤْمِنُونَ وَنِسَاءٌ مُؤْمِنَاتٌ لَمْ تَعْلَمُوهُمْ أَنْ تَطَأُوهُمْ﴾ أَيْ لَسَلَّطَكُمْ عَلَى أَهْلِ مَكَّةَ\",[[36,45,0,10,1],[36,19,3,4,1],[18,109,14,17,1],[32,12,0,5,1],[24,20,0,8,1],[28,10,9,13,1],[48,25,12,20,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,215,215,979,\"حَذْفُ جُمْلَةِ الْقَسَمِ ﴿لأُعَذِّبَنَّهُ عَذَابًا شَدِيدًا﴾ أَيْ وَاللَّهِ حَذْفُ جَوَابِهِ ﴿وَالنَّازِعَاتِ غَرْقًا﴾ الْآيَاتِ أَيْ لَتُبْعَثُنَّ، ﴿ص وَالْقُرْآنِ ذِي الذِّكْرِ﴾ أَيْ إِنَّهُ لِمُعْجِزٌ، ﴿ق وَالْقُرْآنِ الْمَجِيدِ﴾ أَيْ مَا الْأَمْرُ كَمَا زَعَمُوا حَذْفُ جُمْلَةٍ مُسَبَّبَةٍ عَنِ الْمَذْكُورِ نَحْوُ: ﴿لِيُحِقَّ الْحَقَّ وَيُبْطِلَ الْبَاطِلَ﴾ أَيْ فَعَلَ مَا فَعَلَ\",[[27,21,0,2,1],[79,1,0,1,1],[38,1,0,3,1],[50,1,0,2,1],[8,8,0,3,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,215,215,979,\"حَذْفُ جُمَلٍ كَثِيرَةٍ نَحْوُ: ﴿فَأَرْسِلُونِ يُوسُفُ أَيُّهَا الصِّدِّيقُ﴾ أَيْ فَأَرْسَلُونِي إِلَى يُوسُفَ لِأَسْتَعْبِرَهُ الرُّؤْيَا فَفَعَلُوا فَأَتَاهُ فَقَالَ لَهُ يَا يُوسُفُ.\",[[12,45,10,10,1],[12,46,0,2,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,215,215,979,\"تَارَةً لَا يُقَامُ شَيْءٌ مُقَامَ الْمَحْذُوفِ كَمَا تَقَدَّمَ وَتَارَةً يُقَامُ مَا يَدُلُّ عَلَيْهِ نَحْوُ: ﴿فَإِنْ تَوَلَّوْا فَقَدْ أَبْلَغْتُكُمْ مَا أُرْسِلْتُ بِهِ إِلَيْكُمْ﴾ فَلَيْسَ الْإِبْلَاغُ هُوَ الْجَوَابُ لِتَقَدُّمِهِ عَلَى تَوَلِّيهِمْ وَإِنَّمَا التَّقْدِيرُ: \\\"فَإِنْ تَوَلَّوْا فَلَا لَوْمَ عَلَيَّ\\\" أَوْ فَلَا عُذْرَ لَكُمْ لِأَنِّي أَبْلَغْتُكُمْ\",[[11,57,0,7,1]]],[56,\"فِي أَنْوَاعِ الْحَذْفِ\",3,215,216,979,\"﴿وَإِنْ يُكَذِّبُوكَ فَقَدْ كُذِّبَتْ رُسُلٌ مِنْ قَبْلِكَ﴾ أَيْ فَلَا تَحْزَنْ وَاصْبِرْ ﴿وَإِنْ يَعُودُوا فَقَدْ مَضَتْ سُنَّتُ الأَوَّلِينَ﴾ أَيْ يُصِيبُهُمْ مِثْلُ مَا أَصَابَهُمْ.\",[[35,4,0,6,1],[8,38,10,15,1]]],[56,\"الإطناب بالبسط\",3,216,216,980,\"فَالْأَوَّلُ: الْإِطْنَابُ بِتَكْثِيرِ الْجُمَلِ كَقَوْلِهِ تَعَالَى: ﴿إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالأَرْضِ﴾ الآية فِي سُورَةِ الْبَقَرَةِ أَطْنَبَ فِيهَا أَبْلَغَ الْإِطْنَابِ لِكَوْنِ الْخِطَابِ مَعَ الثَّقَلَيْنِ وَفِي كُلِّ عَصْرٍ وَحِينٍ لِلْعَالِمِ مِنْهُمْ وَالْجَاهِلِ وَالْمُوَافِقِ مِنْهُمْ وَالْمُنَافِقِ\",[[2,164,0,4,2],[3,190,0,4,2]]],[56,\"الإطناب بالبسط\",3,216,216,980,\"وَقَوْلِهِ ﴿الَّذِينَ يَحْمِلُونَ الْعَرْشَ وَمَنْ حَوْلَهُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُؤْمِنُونَ بِهِ﴾ فَقَوْلُهُ: \\\"وَيُؤْمِنُونَ بِهِ\\\" إِطْنَابٌ لِأَنَّ إِيمَانَ حَمَلَةِ الْعَرْشِ مَعْلُومٌ وَحَسَّنَهُ إِظْهَارُ شَرَفِ الْإِيمَانِ تَرْغِيبًا فِيهِ\",[[40,7,0,9,1]]],[56,\"الإطناب بالبسط\",3,216,216,980,\"﴿وَوَيْلٌ لِلْمُشْرِكِينَ الَّذِينَ لَا يُؤْتُونَ الزَّكَاةَ﴾ وَلَيْسَ مِنَ الْمُشْرِكِينَ مُزَكٍّ، وَالنُّكْتَةُ الْحَثُّ لِلْمُؤْمِنِينَ عَلَى أَدَائِهَا وَالتَّحْذِيرُ مِنَ الْمَنْعِ حَيْثُ جُعِلَ مِنْ أوصاف المشركين\",[[41,6,14,15,1],[41,7,0,3,1]]],[56,\"الإطناب الزيادة\",3,217,217,981,\"وَيَتَفَاوَتُ التَّأْكِيدُ بِحَسَبِ قُوَّةِ الْإِنْكَارِ وَضَعْفِهِ كَقَوْلِهِ تَعَالَى حِكَايَةً عَنْ رُسُلِ عِيسَى إِذْ كَذَّبُوا فِي الْمَرَّةِ الْأُولَى: ﴿إِنَّا إِلَيْكُمْ مُرْسَلُونَ﴾ فأكد بأن وَاسْمِيَّةِ الْجُمْلَةِ\",[[36,14,8,10,2],[36,16,3,5,2]]],[56,\"الإطناب الزيادة\",3,217,217,981,\"وَفِي الْمَرَّةِ الثَّانِيَةِ: ﴿قَالُوا رَبُّنَا يَعْلَمُ إِنَّا إِلَيْكُمْ لَمُرْسَلُونَ﴾ فأكد بالقسم وإن وَاللَّامِ وَاسْمِيَّةِ الْجُمْلَةِ لِمُبَالَغَةِ الْمُخَاطَبِينَ فِي الْإِنْكَارِ حيث قالوا: ﴿قَالُوا مَا أَنْتُمْ إِلاَّ بَشَرٌ مِثْلُنَا وَمَا أَنْزَلَ الرَّحْمَنُ مِنْ شَيْءٍ إِنْ أَنْتُمْ إِلاَّ تَكْذِبُونَ﴾\",[[36,16,0,5,1],[36,15,0,14,1]]],[56,\"الإطناب الزيادة\",3,217,218,981,\"وَقَدْ يُؤَكَّدُ بِهَا وَالْمُخَاطَبُ بِهِ غَيْرُ مُنْكِرٍ لِعَدَمِ جَرْيِهِ عَلَى مُقْتَضَى إِقْرَارِهِ فَيُنَزَّلُ مَنْزِلَةَ الْمُنْكِرِ وَقَدْ يُتْرَكُ التَّأْكِيدُ وَهُوَ مَعَهُ مُنْكِرٌ لِأَنَّ مَعَهُ أَدِلَّةً ظَاهِرَةً لَوْ تَأَمَّلَهَا لَرَجَعَ عَنْ إِنْكَارِهِ وعلى ذلك يُخَرَّجُ قَوْلُهُ: ﴿ثُمَّ إِنَّكُمْ بَعْدَ ذَلِكَ لَمَيِّتُونَ ثُمَّ إِنَّكُمْ يَوْمَ الْقِيَامَةِ تُبْعَثُونَ﴾ أَكَّدَ الْمَوْتَ تَأْكِيدَيْنِ وَإِنْ لَمْ يُنْكِرْ لِتَنْزِيلِ الْمُخَاطِبِينَ لِتَمَادِيهِمْ فِي الْغَفْلَةِ تَنْزِيلَ مَنْ يُنْكِرُ الْمَوْتَ وَأَكَّدَ إِثْبَاتَ الْبَعْثِ تَأْكِيدًا وَاحِدًا وَإِنْ كَانَ أَشَدَّ نَكِيرًا لِأَنَّهُ لَمَّا كَانَتْ أَدِلَّتُهُ ظَاهِرَةً كَانَ جَدِيرًا بِأَنْ لَا يُنْكَرَ فَنُزِّلَ الْمُخَاطَبُونَ مَنْزِلَةَ غَيْرِ الْمُنْكِرِ حَثًّا لَهُمْ عَلَى النَّظَرِ فِي أَدِلَّتِهِ الْوَاضِحَةِ وَنَظِيرُهُ قَوْلُهُ تَعَالَى: ﴿لا رَيْبَ فِيهِ﴾ نَفَى عَنْهُ الرِّيبَةَ بِ \\\"لَا\\\" عَلَى سَبِيلِ الِاسْتِغْرَاقِ مَعَ أَنَّهُ ارْتَابَ فِيهِ الْمُرْتَابُونَ لَكِنْ نُزِّلَ مَنْزِلَةَ الْعَدَمِ تَعْوِيلًا عَلَى مَا يُزِيلُهُ مِنَ الْأَدِلَّةِ الْبَاهِرَةِ كَمَا نُزِّلَ الْإِنْكَارُ مَنْزِلَةَ عَدَمِهِ لِذَلِكَ\",[[23,15,0,4,1],[23,16,0,4,1]]],[56,\"الإطناب الزيادة\",3,218,218,982,\"وَقَالَ التَّاجُ بْنُ الْفِرْكَاحِ: أَكَّدَ الْمَوْتَ رَدًّا عَلَى الدَّهْرِيَّةِ الْقَائِلِينَ بِبَقَاءِ النَّوْعِ الْإِنْسَانِيِّ خَلَفًا عَنْ سَلَفٍ وَاسْتَغْنَى عَنْ تَأْكِيدِ الْبَعْثِ هُنَا لِتَأْكِيدِهِ وَالرَّدِّ عَلَى مُنْكِرِهِ فِي مَوَاضِعَ كَقَوْلِهِ: ﴿قُلْ بَلَى وَرَبِّي لَتُبْعَثُنَّ﴾ وَقَالَ غَيْرُهُ: لَمَّا كَانَ الْعَطْفُ يَقْتَضِي الِاشْتِرَاكَ اسْتَغْنَى عَنْ إِعَادَةِ اللَّامِ لِذِكْرِهَا فِي الْأَوَّلِ\",[[64,7,6,9,1]]],[56,\"الإطناب الزيادة\",3,218,219,982,\"وَقَدْ يؤكد بها- أي اللام- لِلْمُسْتَشْرِفِ الطَّالِبِ الَّذِي قُدِّمَ لَهُ مَا يُلَوِّحُ بِالْخَبَرِ فَاسْتَشْرَفَتْ نَفْسُهُ إِلَيْهِ نَحْوُ: ﴿وَلا تُخَاطِبْنِي فِي الَّذِينَ ظَلَمُوا﴾ أَيْ لَا تَدْعُنِي يَا نُوحُ فِي شَأْنِ قَوْمِكَ فَهَذَا الْكَلَامُ يُلَوِّحُ بِالْخَبَرِ تَلْوِيحًا، وَيُشْعِرُ بِأَنَّهُ قَدْ حَقَّ عَلَيْهِمُ الْعَذَابُ فَصَارَ الْمَقَامُ مَقَامَ أَنْ يَتَرَدَّدَ الْمُخَاطَبُ فِي أَنَّهُمْ: هَلْ صَارُوا مَحْكُومًا عَلَيْهِمْ بِذَلِكَ أَوْ لَا؟ فَقِيلَ: إِنَّهُمْ مُغْرَقُونَ بِالتَّأْكِيدِ\",[[11,37,4,8,2],[23,27,25,29,2]]],[56,\"الإطناب الزيادة\",3,219,219,983,\"وكذا قوله: ﴿يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ﴾ لَمَّا أَمَرَهُمْ بِالتَّقْوَى وَظُهُورُ ثَمَرَتِهَا وَالْعُقَابُ عَلَى تَرْكِهَا مَحَلُّهُ الْآخِرَةُ تَشَوَّقَتْ نُفُوسُهُمْ إِلَى وَصْفِ حَالِ السَّاعَةِ فَقَالَ: ﴿إِنَّ زَلْزَلَةَ السَّاعَةِ شَيْءٌ عَظِيمٌ﴾ بالتأكيد ليقرر عَلَيْهِ الْوُجُوبُ\",[[22,1,0,8,1]]],[56,\"الإطناب الزيادة\",3,219,219,983,\"وَكَذَا قَوْلُهُ: ﴿وَمَا أُبَرِّئُ نَفْسِي﴾ فِيهِ تَحْيِيرٌ لِلْمُخَاطَبِ وَتَرَدُّدٌ فِي أَنَّهُ كَيْفَ لا يبريء نفسه وهي برئية زَكِيَّةٌ ثَبَتَتْ عِصْمَتُهَا وَعَدَمُ مُوَاقَعَتِهَا السُّوءَ فَأَكَّدَهُ بِقَوْلِهِ: ﴿إِنَّ النَّفْسَ لأَمَّارَةٌ بِالسُّوءِ﴾\",[[12,53,0,6,1]]],[56,\"الإطناب الزيادة\",3,219,219,983,\"وَقَدْ يُؤَكَّدُ لِقَصْدِ التَّرْغِيبِ نَحْوُ: ﴿فَتَابَ عَلَيْهِ إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ﴾ أَكَّدَ بِأَرْبَعِ تَأْكِيدَاتٍ تَرْغِيبًا لِلْعِبَادِ فِي التَّوْبَةِ\",[[2,37,5,10,1]]],[56,\"الإطناب الزيادة\",3,220,220,984,\"قَوْلُهُ تَعَالَى: ﴿وَيَقُولُ الْأِنْسَانُ أَإِذَا مَا مِتُّ لَسَوْفَ أُخْرَجُ حَيًّا﴾ قَالَ الْجُرْجَانِيُّ فِي نَظْمِ الْقُرْآنِ لَيْسَتِ اللَّامُ فِيهِ لِلتَّأْكِيدِ فَإِنَّهُ مُنْكِرٌ فَكَيْفَ يُحَقِّقُ مَا ينكره وَإِنَّمَا قَالَهُ حِكَايَةً لِكَلَامِ النَّبِيِّ ﷺ الصَّادِرِ منه بأداة التَّأْكِيدِ فَحَكَاهُ فَنَزَلَتِ الْآيَةُ عَلَى ذَلِكَ\",[[19,66,0,7,1]]],[56,\"دُخُولُ الْأَحْرُفِ الزَّائِدَةِ\",3,221,221,985,\"وَأَمَّا الْأَفْعَالُ فَزِيدَ مِنْهَا كَانَ وَخُرِّجَ عَلَيْهِ: ﴿كَيْفَ نُكَلِّمُ مَنْ كَانَ فِي الْمَهْدِ صَبِيًّا﴾ وَأَصْبَحَ وَخَرَّجَ عَلَيْهِ: ﴿فَأَصْبَحُوا خَاسِرِينَ﴾ وَقَالَ الرُّمَّانِيُّ: الْعَادَةُ أَنَّ مَنْ بِهِ عِلَّةٌ تُزَادُ بِاللَّيْلِ أَنْ يَرْجُوَ الْفَرَجَ عِنْدَ الصَّبَاحِ فَاسْتَعْمَلَ \\\"أَصْبَحَ\\\" لِأَنَّ الْخُسْرَانَ حَصَلَ لَهُمْ فِي الْوَقْتِ الَّذِي يَرْجُونَ فِيهِ الْفَرَجَ فَلَيْسَتْ زَائِدَةً\",[[19,29,3,9,1],[5,53,13,14,1]]],[56,\"دُخُولُ الْأَحْرُفِ الزَّائِدَةِ\",3,221,221,985,\"وَأَمَّا الْأَسْمَاءُ فَنَصَّ أَكْثَرُ النَّحْوِيِّينَ عَلَى أَنَّهَا لَا تُزَادُ وَوَقَعَ فِي كَلَامِ الْمُفَسِّرِينَ الْحُكْمُ عَلَيْهَا بِالزِّيَادَةِ فِي مَوَاضِعَ كَلَفْظِ \\\"مِثْلِ\\\" فِي قَوْلِهِ: ﴿فَإِنْ آمَنُوا بِمِثْلِ مَا آمَنْتُمْ بِهِ﴾ أَيْ بِمَا\",[[2,137,0,5,1]]],[56,\"التَّأْكِيدُ الصِّنَاعِيُّ\",3,221,221,985,\"أَحَدُهَا: التَّوْكِيدُ الْمَعْنَوِيُّ بِكُلٍّ وَأَجْمَعَ وَكِلَا وَكِلْتَا نَحْوُ: ﴿فَسَجَدَ الْمَلائِكَةُ كُلُّهُمْ أَجْمَعُونَ﴾ وَفَائِدَتُهُ رَفْعُ تَوَهُّمِ الْمَجَازِ وَعَدَمِ الشُّمُولِ وَادَّعَى الْفَرَّاءُ أَنَّ \\\"كُلُّهُمْ\\\" أَفَادَتْ ذَلِكَ وَ\\\"أَجْمَعُونَ\\\" أَفَادَتِ اجْتِمَاعَهُمْ عَلَى السُّجُودِ وَأَنَّهُمْ لَمْ يَسْجُدُوا مُتَفَرِّقِينَ.\",[[15,30,0,3,2],[38,73,0,3,2]]],[56,\"التَّأْكِيدُ الصِّنَاعِيُّ\",3,221,222,985,\"ثَانِيهَا: التَّأْكِيدُ اللَّفْظِيُّ وَهُوَ تَكْرَارُ اللَّفْظِ الْأَوَّلِ إِمَّا بمرادفه نحو: ﴿ضَيِّقًا حَرَجًا﴾ بِكَسْرِ الرَّاءِ وَ: ﴿وَغَرَابِيبُ سُودٌ﴾ وجعل منه الصفار في: ﴿فِيمَا إِنْ مَكَّنَّاكُمْ فِيهِ﴾ عَلَى الْقَوْلِ بِأَنَّ كِلَيْهِمَا لِلنَّفْيِ وَجَعَلَ مِنْهُ غَيْرُهُ ﴿قِيلَ ارْجِعُوا وَرَاءَكُمْ فَالْتَمِسُوا نُورًا﴾ فوراء هنا ليس ظرفا لأن لفظ \\\"ارْجِعُوا\\\" يُنْبِئُ عَنْهُ بَلْ هُوَ اسْمُ فِعْلٍ بِمَعْنَى \\\"ارْجِعُوا\\\" فَكَأَنَّهُ قَالَ ارْجِعُوا ارْجِعُوا\",[[6,125,14,15,1],[35,27,20,21,1],[46,26,2,5,1],[57,13,10,14,1]]],[56,\"التَّأْكِيدُ الصِّنَاعِيُّ\",3,222,223,986,\"وَإِمَّا بِلَفْظِهِ وَيَكُونُ فِي الِاسْمِ وَالْفِعْلِ وَالْحَرْفِ وَالْجُمْلَةِ فالاسم والجملة نحو: ﴿قَوَارِيرَ قَوَارِيرَ﴾ ﴿دَكًّا دَكًّا﴾ والفعل ﴿فَمَهِّلِ الْكَافِرِينَ أَمْهِلْهُمْ﴾ وَاسْمُ الْفِعْلِ نَحْوُ: ﴿هَيْهَاتَ هَيْهَاتَ لِمَا تُوعَدُونَ﴾ وَالْحَرْفُ نَحْوُ: ﴿فَفِي الْجَنَّةِ خَالِدِينَ فِيهَا﴾ ﴿أَيَعِدُكُمْ أَنَّكُمْ إِذَا مِتُّمْ وَكُنْتُمْ تُرَابًا وَعِظَامًا أَنَّكُمْ﴾ وَالْجُمْلَةُ نَحْوُ: ﴿فَإِنَّ مَعَ الْعُسْرِ يُسْرًا إِنَّ مَعَ الْعُسْرِ يُسْرًا﴾ وَالْأَحْسَنُ اقْتِرَانُ الثَّانِيَةِ بِثُمَّ نَحْوُ: ﴿وَمَا أَدْرَاكَ مَا يَوْمُ الدِّينِ ثُمَّ مَا أَدْرَاكَ مَا يَوْمُ الدِّينِ﴾ ﴿كَلاَّ سَوْفَ تَعْلَمُونَ ثُمَّ كَلاَّ سَوْفَ تَعْلَمُونَ﴾ وَمِنْ هَذَا النَّوْعِ تَأْكِيدُ الضَّمِيرِ الْمُتَّصِلِ بِالْمُنْفَصِلِ نَحْوُ: ﴿اسْكُنْ أَنْتَ وَزَوْجُكَ الْجَنَّةَ﴾ ﴿فَاذْهَبْ أَنْتَ وَرَبُّكَ﴾ ﴿وَإِمَّا أَنْ نَكُونَ نَحْنُ الْمُلْقِينَ﴾ ومن تَأْكِيدُ الْمُنْفَصِلِ بِمِثْلِهِ ﴿وَهُمْ بِالآخِرَةِ هُمْ كَافِرُونَ.﴾ ثَالِثُهَا: تَأْكِيدُ الْفِعْلِ بِمَصْدَرِهِ وَهُوَ عِوَضٌ مِنْ تَكْرَارِ الْفِعْلِ مَرَّتَيْنِ وَفَائِدَتُهُ رَفْعُ تَوَهُّمِ الْمَجَازِ فِي الفعل بخلاف التوكيد السابق فإن لِرَفْعِ تَوَهُّمِ الْمَجَازِ فِي الْمُسْنَدِ إِلَيْهِ كَذَا فَرَّقَ بِهِ ابْنُ عُصْفُورٍ وَغَيْرُهُ. وَمِنْ ثَمَّ رَدَّ بَعْضُ أَهْلِ السُّنَّةِ عَلَى بَعْضِ الْمُعْتَزِلَةِ فِي دَعْوَاهُ نَفْيَ التَّكْلِيمِ حَقِيقَةً بِقَوْلِهِ: ﴿وَكَلَّمَ اللَّهُ مُوسَى تَكْلِيمًا﴾ لِأَنَّ التَّوْكِيدَ رَفَعَ الْمَجَازَ فِي الْفِعْلِ، وَمِنْ أمثلته ﴿وَسَلِّمُوا تَسْلِيمًا﴾ ﴿يَوْمَ تَمُورُ السَّمَاءُ مَوْرًا وَتَسِيرُ الْجِبَالُ سَيْرًا﴾ ﴿جَزَاؤُكُمْ جَزَاءً مَوْفُورًا﴾\",[[76,15,7,7,1],[76,16,0,0,1],[89,21,4,5,1],[86,17,0,2,1],[23,36,0,3,1],[11,108,3,6,1],[23,35,0,7,1],[94,5,0,3,1],[94,6,0,3,1],[82,17,0,4,1],[82,18,0,5,1],[102,3,0,2,1],[102,4,0,3,1],[7,19,1,4,1],[5,24,9,11,1],[7,115,5,9,1],[11,19,7,10,1],[4,164,10,13,1],[4,65,17,18,1],[52,9,0,3,1],[52,10,0,2,1],[17,63,7,9,1]]],[56,\"التَّأْكِيدُ الصِّنَاعِيُّ\",3,223,223,987,\"وليس منه: ﴿وَتَظُنُّونَ بِاللَّهِ الظُّنُونَا﴾ بَلْ هُوَ جَمْعُ \\\"ظَنٍّ\\\" لِاخْتِلَافِ أَنْوَاعِهِ وَأَمَّا: ﴿إِلاَّ أَنْ يَشَاءَ رَبِّي شَيْئًا﴾ فتحتمل أَنْ يَكُونَ مِنْهُ وَأَنْ يَكُونَ الشَّيْءُ بِمَعْنَى الْأَمْرِ وَالشَّأْنِ\",[[33,10,13,15,1],[6,80,13,17,1]]],[56,\"التَّأْكِيدُ الصِّنَاعِيُّ\",3,223,224,987,\"وَالْأَصْلُ فِي هَذَا النَّوْعِ أَنْ يُنْعَتَ بِالْوَصْفِ الْمُرَادِ نَحْوُ: ﴿اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا﴾ ﴿وَسَرِّحُوهُنَّ سَرَاحًا جَمِيلًا﴾ وَقَدْ يُضَافُ وَصْفُهُ إِلَيْهِ نَحْوُ: ﴿اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ﴾ وَقَدْ يُؤَكَّدُ بِمَصْدَرِ فِعْلٍ آخَرَ أَوِ اسْمِ عَيْنٍ نِيَابَةً عَنِ الْمَصْدَرِ نَحْوُ: ﴿وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا﴾ \\\"مصدر\\\" والتبتيل المصدر \\\"بتل\\\"، ﴿وَاللَّهُ أَنْبَتَكُمْ مِنَ الأَرْضِ نَبَاتًا﴾ أَيْ إِنْبَاتًا إِذِ النَّبَاتُ اسْمُ عين. وَقَدْ يُضَافُ وَصْفُهُ إِلَيْهِ نَحْوُ: ﴿اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ﴾ وَقَدْ يُؤَكَّدُ بِمَصْدَرِ فِعْلٍ آخَرَ أَوِ اسْمِ عَيْنٍ نِيَابَةً عَنِ الْمَصْدَرِ نَحْوُ: ﴿وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا﴾ \\\"مصدر\\\" والتبتيل المصدر \\\"بتل\\\"، ﴿وَاللَّهُ أَنْبَتَكُمْ مِنَ الأَرْضِ نَبَاتًا﴾ أَيْ إِنْبَاتًا إِذِ النَّبَاتُ اسْمُ عَيْنٍ. رَابِعُهَا: الْحَالُ الْمُؤَكِّدَةُ نَحْوُ: ﴿وَيَوْمَ أُبْعَثُ حَيًّا﴾ ﴿وَلا تَعْثَوْا فِي الأَرْضِ مُفْسِدِينَ﴾ ﴿وَأَرْسَلْنَاكَ لِلنَّاسِ رَسُولًا﴾ ﴿ثُمَّ تَوَلَّيْتُمْ إِلاَّ قَلِيلًا مِنْكُمْ وَأَنْتُمْ مُعْرِضُونَ﴾ ﴿وَأُزْلِفَتِ الْجَنَّةُ لِلْمُتَّقِينَ غَيْرَ بَعِيدٍ﴾\",[[33,41,3,6,1],[33,49,19,21,1],[3,102,3,6,1],[73,8,3,5,1],[71,17,0,4,1],[3,102,3,6,1],[73,8,3,5,1],[71,17,0,4,1],[19,15,6,8,2],[19,33,6,8,2],[2,60,23,27,1],[4,79,12,14,1],[2,83,22,28,1],[50,31,0,4,1]]],[56,\"التَّأْكِيدُ الصِّنَاعِيُّ\",3,224,224,988,\"وليس منه: ﴿وَلَّى مُدْبِرًا﴾ لِأَنَّ التَّوْلِيَةَ قَدْ لَا تَكُونُ إِدْبَارًا بِدَلِيلِ قَوْلِهِ: ﴿فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ﴾ ولا: ﴿فَتَبَسَّمَ ضَاحِكًا﴾ لِأَنَّ التَّبَسُّمَ قَدْ لَا يَكُونُ ضَحِكًا وَلَا ﴿وَهُوَ الْحَقُّ مُصَدِّقًا﴾ لِاخْتِلَافِ الْمَعْنَيَيْنِ إِذْ كَوْنُهُ حَقًّا فِي نَفْسِهِ غَيْرُ كَوْنِهِ مُصَدِّقًا لِمَا قَبْلَهُ\",[[27,10,7,8,1],[2,144,9,13,3],[2,149,3,7,3],[2,150,3,7,3],[27,19,0,1,1],[2,91,15,17,2],[35,31,5,7,2]]],[56,\"التَّأْكِيدُ\",3,224,225,988,\"وَمِنْهَا زِيَادَةُ التَّنْبِيهِ عَلَى مَا يَنْفِي التُّهْمَةَ لِيَكْمُلَ تَلَقِّي الْكَلَامِ بِالْقَبُولِ وَمِنْهُ: ﴿وَقَالَ الَّذِي آمَنَ يَا قَوْمِ اتَّبِعُونِ أَهْدِكُمْ سَبِيلَ الرَّشَادِ يَا قَوْمِ إِنَّمَا هَذِهِ الْحَيَاةُ الدُّنْيَا مَتَاعٌ﴾ فَإِنَّهُ كَرَّرَ فِيهِ النِّدَاءَ لِذَلِكَ\",[[40,38,0,7,1],[40,39,0,5,1]]],[56,\"التَّأْكِيدُ\",3,225,225,989,\"وَمِنْهَا إِذَا طَالَ الْكَلَامُ وَخُشِيَ تناسى الأول أعيد ثانيا تَطْرِيَةً لَهُ وَتَجْدِيدًا لِعَهْدِهِ وَمِنْهُ: ﴿ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُوا السُّوءَ بِجَهَالَةٍ ثُمَّ تَابُوا مِنْ بَعْدِ ذَلِكَ وَأَصْلَحُوا إِنَّ رَبَّكَ مِنْ بَعْدِهَا﴾ ﴿ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُوا مِنْ بَعْدِ مَا فُتِنُوا ثُمَّ جَاهَدُوا وَصَبَرُوا إِنَّ رَبَّكَ مِنْ بَعْدِهَا﴾ ﴿وَلَمَّا جَاءَهُمْ كِتَابٌ مِنْ عِنْدِ اللَّهِ﴾ إِلَى قَوْلِهِ: ﴿فَلَمَّا جَاءَهُمْ مَا عَرَفُوا كَفَرُوا بِهِ﴾ ﴿لَا تَحْسَبَنَّ الَّذِينَ يَفْرَحُونَ بِمَا أَتَوْا وَيُحِبُّونَ أَنْ يُحْمَدُوا بِمَا لَمْ يَفْعَلُوا فَلا تَحْسَبَنَّهُمْ بِمَفَازَةٍ مِنَ الْعَذَابِ﴾ ﴿إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ﴾ وَمِنْهَا التَّعْظِيمُ وَالتَّهْوِيلُ نَحْوُ: ﴿الْحَاقَّةُ مَا الْحَاقَّةُ﴾ ﴿الْقَارِعَةُ مَا الْقَارِعَةُ﴾ ﴿وَأَصْحَابُ الْيَمِينِ مَا أَصْحَابُ الْيَمِينِ﴾\",[[16,119,0,16,1],[16,110,0,15,1],[2,89,0,5,1],[2,89,16,21,1],[3,188,0,16,1],[12,4,5,12,1],[69,1,0,0,1],[69,2,0,1,1],[101,1,0,0,1],[101,2,0,1,1],[56,27,0,4,1]]],[56,\"التَّأْكِيدُ\",3,225,226,989,\"فَإِنْ قُلْتَ: هَذَا النَّوْعُ أَحَدُ أَقْسَامِ النَّوْعِ الَّذِي قَبْلَهُ فَإِنَّ مِنْهَا التَّأْكِيدَ بِتَكْرَارِ اللَّفْظِ فَلَا يَحْسُنُ عَدُّهُ نَوْعًا مُسْتَقِلًّا قُلْتُ: هُوَ يُجَامِعُهُ وَيُفَارِقُهُ وَيَزِيدُ عَلَيْهِ وَيَنْقُصُ عَنْهُ فَصَارَ أَصْلًا بِرَأْسِهِ فَإِنَّهُ قَدْ يَكُونُ التَّأْكِيدُ تَكْرَارًا كَمَا تَقَدَّمَ فِي أَمْثِلَتِهِ وَقَدْ لَا يَكُونُ تَكْرَارًا كَمَا تَقَدَّمَ أَيْضًا وَقَدْ يَكُونُ التَّكْرِيرُ غَيْرَ تَأْكِيدٍ صِنَاعَةً وَإِنْ كَانَ مُفِيدًا لِلتَّأْكِيدِ مَعْنًى وَمِنْهُ مَا وَقَعَ فِيهِ الْفَصْلُ بَيْنَ الْمُكَرَّرَيْنِ فَإِنَّ التَّأْكِيدَ لَا يَفْصِلُ بَيْنَهُ وَبَيْنَ مُؤَكَّدِهِ نَحْوُ: ﴿اتَّقُوا اللَّهَ وَلْتَنْظُرْ نَفْسٌ مَا قَدَّمَتْ لِغَدٍ وَاتَّقُوا اللَّهَ﴾ ﴿إِنَّ اللَّهَ اصْطَفَاكِ وَطَهَّرَكِ وَاصْطَفَاكِ عَلَى نِسَاءِ الْعَالَمِينَ﴾ فَالْآيَتَانِ مِنْ بَابِ التَّكْرِيرِ لَا التَّأْكِيدِ اللَّفْظِيِّ الصِّنَاعِيِّ وَمِنْهُ الْآيَاتُ الْمُتَقَدِّمَةُ فِي التَّكْرِيرِ لِلطُّولِ\",[[59,18,3,11,1],[3,42,4,11,1]]],[56,\"التَّأْكِيدُ\",3,226,226,990,\"وَمِنْهُ مَا كَانَ لِتَعَدُّدِ الْمُتَعَلِّقِ بِأَنْ يَكُونَ الْمُكَرَّرُ ثَانِيًا مُتَعَلِّقًا بِغَيْرِ مَا تَعَلَّقَ بِهِ الْأَوَّلُ وَهَذَا الْقِسْمُ يُسَمَّى بِالتَّرْدِيدِ كَقَوْلِهِ: ﴿اللَّهُ نُورُ السَّمَاوَاتِ وَالأَرْضِ مَثَلُ نُورِهِ كَمِشْكَاةٍ فِيهَا مِصْبَاحٌ الْمِصْبَاحُ فِي زُجَاجَةٍ الزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌ دُرِّيٌّ﴾ وَقَعَ فِيهَا التَّرْدِيدُ أَرْبَعَ مَرَّاتٍ\",[[24,35,0,15,1]]],[56,\"التَّأْكِيدُ\",3,226,226,990,\"وَإِنْ كَانَ بَعْضُهَا لَيْسَ بِنِعْمَةٍ فَذِكْرُ النِّقْمَةِ لِلتَّحْذِيرِ نِعْمَةٌ وَقَدْ سُئِلَ أَيُّ نِعْمَةٍ فِي قَوْلِهِ: ﴿كُلُّ مَنْ عَلَيْهَا فَانٍ﴾ فَأُجِيبَ بِأَجْوِبَةٍ أَحْسَنُهَا النَّقْلُ مِنْ دَارِ الْهُمُومِ إِلَى دَارِ السُّرُورِ وَإِرَاحَةُ الْمُؤْمِنِ وَالْبَارِّ مِنَ الْفَاجِرِ\",[[55,26,0,3,1]]],[56,\"التَّأْكِيدُ\",3,227,227,991,\"وَكَذَا قَوْلُهُ فِي سُورَةِ القمر: ﴿وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ.﴾\",[[54,17,0,6,4],[54,22,0,6,4],[54,32,0,6,4],[54,40,0,6,4]]],[56,\"التَّأْكِيدُ\",3,227,228,991,\"وَيَقْرُبُ مِنْ ذَلِكَ مَا ذَكَرَهُ ابْنُ جَرِيرٍ فِي قَوْلِهِ تَعَالَى: ﴿وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ وَلَقَدْ وَصَّيْنَا﴾ إِلَى قَوْلِهِ: ﴿وَكَانَ اللَّهُ غَنِيًّا حَمِيدًا﴾، ﴿وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا﴾ قَالَ فَإِنْ قِيلَ: مَا وَجْهُ تَكْرَارِ قَوْلِهِ: ﴿وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ﴾ فِي آيَتَيْنِ إِحْدَاهُمَا فِي أَثَرِ الْأُخْرَى قُلْنَا لِاخْتِلَافِ مَعْنَى الْخَبَرَيْنِ عَمَّا في السموات والأرض وذلك أن الْخَبَرَ عَنْهُ فِي إِحْدَى الْآيَتَيْنِ ذِكْرُ حَاجَتِهِ إِلَى بَارِئِهِ وَغِنَى بَارِئِهِ عَنْهُ وَفِي الْأُخْرَى حِفْظُ بَارِئِهِ إِيَّاهُ وَعِلْمُهُ بِهِ وَبِتَدْبِيرِهِ قَالَ فَإِنْ قِيلَ أَفَلَا قِيلَ: \\\"وَكَانَ اللَّهُ غَنِيًّا حَمِيدًا وَكَفَى بِاللَّهِ وَكِيلًا\\\" قِيلَ: لَيْسَ فِي الْآيَةِ الْأُولَى مَا يَصْلُحُ أَنْ تُخْتَتَمَ بِوَصْفِهِ مَعَهُ بِالْحِفْظِ وَالتَّدْبِيرِ انْتَهَى.\",[[4,131,0,8,1],[4,131,28,31,1],[4,132,0,9,1]]],[56,\"التَّأْكِيدُ\",3,228,228,992,\"وَقَالَ تَعَالَى: ﴿وَإِنَّ مِنْهُمْ لَفَرِيقًا يَلْوُونَ أَلْسِنَتَهُمْ بِالْكِتَابِ لِتَحْسَبُوهُ مِنَ الْكِتَابِ وَمَا هُوَ مِنَ الْكِتَابِ﴾ قَالَ الرَّاغِبُ: الْكِتَابُ الْأَوَّلُ مَا كَتَبُوهُ بِأَيْدِيهِمُ المذكور فِي قَوْلِهِ تَعَالَى: ﴿فَوَيْلٌ لِلَّذِينَ يَكْتُبُونَ الْكِتَابَ بِأَيْدِيهِمْ﴾ والكتاب الثاني التوراة والثالث الجنس كُتُبِ اللَّهِ كُلِّهَا أَيْ مَا هُوَ مِنْ شَيْءٍ مِنْ كُتُبِ اللَّهِ وَكَلَامِهِ\",[[3,78,0,12,1],[2,79,0,4,1]]],[56,\"التَّأْكِيدُ\",3,228,228,992,\"وَمِنْ أَمْثِلَةِ مَا يُظَنُّ تَكْرَارًا وَلَيْسَ مِنْهُ ﴿قُلْ يَا أَيُّهَا الْكَافِرُونَ لَا أَعْبُدُ مَا تَعْبُدُونَ﴾ إِلَى آخِرِهَا فَإِنَّ \\\"لَا أَعْبُدُ مَا تَعْبُدُونَ\\\" أَيْ فِي الْمُسْتَقْبَلِ \\\"وَلَا أَنْتُمْ عَابِدُونَ\\\" أَيْ فِي الْحَالِ \\\"مَا أَعْبُدُ\\\" فِي الْمُسْتَقْبَلِ \\\"وَلَا أَنَا عَابِدٌ\\\" أَيْ فِي الْحَالِ مَا عَبَدْتُمْ فِي الْمَاضِي \\\"وَلَا أَنْتُمْ عَابِدُونَ\\\" أَيْ فِي الْمُسْتَقْبَلِ \\\"مَا أَعْبُدُ\\\" أَيْ فِي الْحَالِ فَالْحَاصِلُ أَنَّ الْقَصْدَ نَفْيُ عِبَادَتِهِ لِآلِهَتِهِمْ فِي الْأَزْمِنَةِ الثَّلَاثَةِ\",[[109,1,0,2,1],[109,2,0,3,1]]],[56,\"التَّأْكِيدُ\",3,228,229,992,\"وكذاك ﴿فَاذْكُرُوا اللَّهَ عِنْدَ الْمَشْعَرِ الْحَرَامِ وَاذْكُرُوهُ كَمَا هَدَاكُمْ﴾ ثُمَّ قَالَ ﴿فَإِذَا قَضَيْتُمْ مَنَاسِكَكُمْ فَاذْكُرُوا اللَّهَ كَذِكْرِكُمْ آبَاءَكُمْ﴾ ثُمَّ قَالَ ﴿وَاذْكُرُوا اللَّهَ فِي أَيَّامٍ مَعْدُودَاتٍ﴾ فَإِنَّ الْمُرَادَ بِكُلِّ وَاحِدٍ مِنْ هَذِهِ الْأَذْكَارِ غَيْرُ الْمُرَادِ بِالْآخَرِ:\",[[2,198,12,19,1],[2,200,0,6,1],[2,203,0,4,1]]],[56,\"التَّأْكِيدُ\",3,229,229,993,\"فَالْأَوَّلُ: الذِّكْرُ فِي مُزْدَلِفَةٍ عِنْدَ الْوُقُوفِ بِقُزَحَ وَقَوْلُهُ: ﴿وَاذْكُرُوهُ كَمَا هَدَاكُمْ﴾ إِشَارَةٌ إِلَى تَكَرُّرِهِ ثَانِيًا وَثَالِثًا: وَيُحْتَمَلُ أَنْ يُرَادَ بِهِ طَوَافُ الْإِفَاضَةِ بِدَلِيلِ تَعْقِيبِهِ بِقَوْلِهِ: ﴿فَإِذَا قَضَيْتُمْ﴾ وَالذِّكْرُ الثَّالِثُ إِشَارَةٌ إِلَى رَمْيِ جَمْرَةِ الْعَقَبَةِ وَالذِّكْرُ الْأَخِيرُ لِرَمْيِ أَيَّامِ التَّشْرِيقِ\",[[2,198,17,19,1],[2,200,0,1,1]]],[56,\"التَّأْكِيدُ\",3,229,229,993,\"وَمِنْهُ تَكْرِيرُ حَرْفِ الْإِضْرَابِ فِي قَوْلِهِ: ﴿بَلْ قَالُوا أَضْغَاثُ أَحْلامٍ بَلِ افْتَرَاهُ بَلْ هُوَ شَاعِرٌ﴾ وَقَوْلُهُ: ﴿بَلِ ادَّارَكَ عِلْمُهُمْ فِي الآخِرَةِ بَلْ هُمْ فِي شَكٍّ مِنْهَا بَلْ هُمْ مِنْهَا عَمُونَ﴾ وَمِنْهُ قَوْلُهُ: ﴿وَمَتِّعُوهُنَّ عَلَى الْمُوسِعِ قَدَرُهُ وَعَلَى الْمُقْتِرِ قَدَرُهُ مَتَاعًا بِالْمَعْرُوفِ حَقًّا عَلَى الْمُحْسِنِينَ﴾ ثُمَّ قَالَ: ﴿وَلِلْمُطَلَّقَاتِ مَتَاعٌ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ﴾ فَكَرَّرَ الثَّانِي لِيَعُمَّ كُلَّ مُطَلَّقَةٍ فَإِنَّ الْآيَةَ الْأُولَى فِي الْمُطَلَّقَةِ قَبْلَ الْفَرْضِ وَالْمُسِيسِ خَاصَّةً وَقِيلَ لِأَنَّ الْأُولَى لَا تُشْعِرُ بِالْوُجُوبِ وَلِهَذَا لَمَّا نَزَلَتْ قَالَ بَعْضُ الصَّحَابَةِ: إِنْ شِئْتُ أَحْسَنْتُ وَإِنْ شِئْتُ فَلَا فَنَزَلَتِ الثَّانِيَةُ أَخْرَجَهُ ابْنُ جَرِيرٍ.\",[[21,5,0,8,1],[27,66,0,13,1],[2,236,13,24,1],[2,241,0,5,1]]],[56,\"التَّأْكِيدُ\",3,229,229,993,\"وَمِنْ ذَلِكَ تَكْرِيرُ الْأَمْثَالِ كَقَوْلِهِ: ﴿وَمَا يَسْتَوِي الأَعْمَى وَالْبَصِيرُ وَلا الظُّلُمَاتُ وَلا النُّورُ وَلا الظِّلُّ وَلا الْحَرُورُ وَمَا يَسْتَوِي الأَحْيَاءُ وَلا الأَمْوَاتُ﴾\",[[35,19,0,3,1],[35,20,0,3,1],[35,21,0,3,1],[35,22,0,4,1]]],[56,\"التَّأْكِيدُ\",3,230,231,994,\"وَمِنْهَا أَنَّهُ تَعَالَى أَنْزَلَ هَذَا الْقُرْآنَ وَعَجَزَ الْقَوْمُ عَنِ الْإِتْيَانِ بِمِثْلِهِ بِأَيِّ نَظْمٍ جَاءُوا ثُمَّ أَوْضَحَ الْأَمْرَ فِي عَجْزِهِمْ بِأَنْ كَرَّرَ ذِكْرَ الْقِصَّةِ فِي مَوَاضِعَ إِعْلَامًا بِأَنَّهُمْ عَاجِزُونَ عَنِ الإتيان بمثله أي بِأَيِّ نَظْمٍ جَاءُوا وَبِأَيِّ عِبَارَةٍ عَبَّرُوا. وَمِنْهَا أَنَّهُ لَمَّا تَحَدَّاهُمْ قَالَ: ﴿فَأْتُوا بِسُورَةٍ مِّنْ مِثْلِهِ﴾ فَلَوْ ذُكِرَتِ الْقِصَّةُ فِي مَوْضِعٍ وَاحِدٍ وَاكْتُفِيَ بِهَا لَقَالَ الْعَرَبِيُّ ائْتُونَا أَنْتُمْ بِسُورَةٍ مَنْ مِثْلِهِ فأنزلها ﷾ فِي تَعْدَادِ السُّورِ دَفْعًا لِحُجَّتِهِمْ مَنْ كَلِّ وَجْهٍ.\",[[2,23,8,11,1]]],[56,\"التَّأْكِيدُ\",3,232,232,996,\"وَجَوَابٌ خَامِسٌ: وَهُوَ أَقْوَى مَا يُجَابُ بِهِ إِنَّ قَصَصَ الْأَنْبِيَاءِ إِنَّمَا كُرِّرَتْ لِأَنَّ الْمَقْصُودَ بِهَا إِفَادَةُ إِهْلَاكِ مَنْ كَذَّبُوا رُسُلَهُمْ وَالْحَاجَةُ دَاعِيَةٌ إِلَى ذَلِكَ لِتَكْرِيرِ تَكْذِيبِ الكفار لرسول الله فكلما كذبوا أنزلت قِصَّةٌ مُنْذِرَةٌ بِحُلُولِ الْعَذَابِ كَمَا حَلَّ عَلَى الْمُكَذِّبِينَ وَلِهَذَا قَالَ تَعَالَى فِي آيَاتٍ: ﴿فَقَدْ مَضَتْ سُنَّتُ الأَوَّلِينَ﴾ ﴿أَلَمْ يَرَوْا كَمْ أَهْلَكْنَا مِنْ قَبْلِهِمْ مِنْ قَرْنٍ﴾ وَقِصَّةُ يُوسُفَ لَمْ يُقْصَدْ مِنْهَا ذَلِكَ\",[[8,38,12,15,1],[6,6,0,7,1]]],[56,\"الصِّفَةُ\",3,233,233,997,\"أَحَدُهَا: التَّخْصِيصُ فِي النَّكِرَةِ، نَحْوُ: ﴿فَتَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ﴾\",[[4,92,12,14,3],[4,92,30,32,3],[4,92,44,46,3]]],[56,\"الصِّفَةُ\",3,233,233,997,\"الثَّانِي: التَّوْضِيحُ فِي الْمَعْرِفَةِ أَيْ زِيَادَةُ الْبَيَانِ نَحْوُ: ﴿وَرَسُولِهِ النَّبِيِّ الأُمِّيِّ﴾\",[[7,158,21,23,1]]],[56,\"الصِّفَةُ\",3,233,233,997,\"الثَّالِثُ: الْمَدْحُ وَالثَّنَاءُ وَمِنْهُ صِفَاتُ اللَّهِ تَعَالَى، نَحْوُ: ﴿بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ الرَّحْمَنِ الرَّحِيمِ مَالِكِ يَوْمِ الدِّينِ﴾ ﴿هُوَ اللَّهُ الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ﴾\",[[1,1,0,3,1],[1,2,0,3,1],[1,3,0,1,1],[1,4,0,2,1],[59,24,0,4,1]]],[56,\"الصِّفَةُ\",3,233,233,997,\"وَمِنْهُ: ﴿يَحْكُمُ بِهَا النَّبِيُّونَ الَّذِينَ أَسْلَمُوا﴾ فَهَذَا الْوَصْفُ لِلْمَدْحِ وَإِظْهَارِ شَرَفِ الْإِسْلَامِ وَالتَّعْرِيضِ بِالْيَهُودِ وَأَنَّهُمْ بُعَدَاءُ عَنْ مِلَّةِ الْإِسْلَامِ الَّذِي هُوَ دِينُ الْأَنْبِيَاءِ كُلِّهِمْ وَأَنَّهُمْ بِمَعْزِلٍ عَنْهَا قَالَهُ الزَّمَخْشَرِيُّ.\",[[5,44,6,10,1]]],[56,\"الصِّفَةُ\",3,233,233,997,\"الرَّابِعُ: الذَّمُّ نَحْوُ: ﴿فَاسْتَعِذْ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ﴾\",[[16,98,3,7,1]]],[56,\"الصِّفَةُ\",3,233,234,997,\"الْخَامِسُ: التَّأْكِيدُ لِرَفْعِ الْإِيهَامِ، نَحْوُ: ﴿لَا تَتَّخِذُوا إِلَهَيْنِ اثْنَيْنِ﴾ فإن \\\"إلهين\\\" للتثنية فاثنين بَعْدَهُ صِفَةٌ مُؤَكِّدَةٌ لِلنَّهْيِ عَنِ الْإِشْرَاكِ وَلِإِفَادَةِ أَنَّ النَّهْيَ عَنِ \\\"إِلَهَيْنِ\\\" إِنَّمَا هُوَ لِمَحْضِ كَوْنِهِمَا اثْنَيْنِ فَقَطْ لَا لِمَعْنًى آخَرَ مِنْ كَوْنِهِمَا عَاجِزَيْنِ أَوْ غَيْرَ ذَلِكَ وَلِأَنَّ الْوِحْدَةَ تُطْلَقُ وَيُرَادُ بِهَا النَّوْعِيَّةُ كَقَوْلِهِ: ﷺ \\\"إِنَّمَا نَحْنُ وَبَنُو الْمُطَّلِبِ شَيْءٌ وَاحِدٌ\\\" وَتُطْلَقُ وَيُرَادُ بِهَا نَفْيُ الْعِدَّةِ فَالتَّثْنِيَةُ بِاعْتِبَارِهَا فَلَوْ قِيلَ \\\"لَا تَتَّخِذُوا إِلَهَيْنِ\\\" فَقَطْ لَتُوِهِّمَ أَنَّهُ نَهْيٌ عَنِ اتِّخَاذِ جِنْسَيْنِ آلِهَةً وَإِنْ جَازَ أَنْ يُتَّخَذَ مِنْ نَوْعٍ وَاحِدٍ عَدَدٌ آلهة ولهذا أكد بالوحدة قَوْلُهُ: ﴿إِنَّمَا هُوَ إِلَهٌ وَاحِدٌ﴾\",[[16,51,2,9,1]]],[56,\"الصِّفَةُ\",3,234,234,998,\"وَمِثْلُهُ: ﴿فَاسْلُكْ فِيهَا مِنْ كُلٍّ زَوْجَيْنِ اثْنَيْنِ﴾ عَلَى قِرَاءَةِ تَنْوِينِ \\\"كَلٍّ\\\" وَقَوْلُهُ: ﴿فَإِذَا نُفِخَ فِي الصُّورِ نَفْخَةٌ وَاحِدَةٌ﴾ فَهُوَ تَأْكِيدٌ لِرَفْعِ تَوَهُّمِ تَعَدُّدِ النَّفْخَةِ لِأَنَّ هَذِهِ الصِّيغَةَ قَدْ تَدُلُّ عَلَى الْكَثْرَةِ بِدَلِيلِ: ﴿وَإِنْ تَعُدُّوا نِعْمَةَ اللَّهِ لَا تُحْصُوهَا﴾\",[[23,27,12,17,1],[69,13,0,5,1],[16,18,0,5,1]]],[56,\"الصِّفَةُ\",3,234,234,998,\"وَمِنْ ذَلِكَ قَوْلُهُ: ﴿فَإِنْ كَانَتَا اثْنَتَيْنِ﴾ فَإِنَّ لَفْظَ \\\"كَانَتَا\\\" تُفِيدُ التَّثْنِيَةَ فَتَفْسِيرُهُ بِاثْنَتَيْنِ لَمْ يُفِدْ زِيَادَةً عَلَيْهِ\",[[4,176,25,27,1]]],[56,\"الصِّفَةُ\",3,234,234,998,\"وَقَدْ أَجَابَ عَنْ ذَلِكَ الْأَخْفَشُ وَالْفَارِسِيُّ: بِأَنَّهُ أَفَادَ الْعَدَدَ الْمَحْضَ مُجَرَّدًا عَنِ الصِّفَةِ لِأَنَّهُ قَدْ كَانَ يَجُوزُ أَنْ يُقَالَ: \\\"فَإِنْ كَانَتَا صَغِيرَتَيْنِ أَوْ كَبِيرَتَيْنِ أَوْ صَالِحَتَيْنِ أَوْ غَيْرَ ذَلِكَ مِنَ الصِّفَاتِ\\\" فَلَمَّا قَالَ \\\"اثْنَتَيْنِ\\\" أَفْهَمَ أَنَّ فَرْضَ الثِّنْتَيْنِ تَعَلَّقَ بِمُجَرَّدِ كَوْنِهِمَا ثِنْتَيْنِ فَقَطْ وَهِيَ فَائِدَةٌ لَا تَحْصُلُ مِنْ ضَمِيرِ الْمُثَنَّى وَقِيلَ أَرَادَ: \\\"فَإِنْ كَانَتَا اثْنَتَيْنِ فَصَاعِدًا\\\" فَعَبَّرَ بِالْأَدْنَى عَنْهُ وَعَمَّا فَوْقَهُ اكْتِفَاءً وَنَظِيرُهُ: ﴿فَإِنْ لَمْ يَكُونَا رَجُلَيْنِ﴾ والأحسن أَنَّ الضَّمِيرَ عَائِدٌ عَلَى الشَّهِيدَيْنِ الْمُطْلَقَيْنِ\",[[2,282,55,58,1]]],[56,\"الصِّفَةُ\",3,234,235,998,\"وَمِنَ الصِّفَاتِ الْمُؤَكِّدَةِ قَوْلُهُ: ﴿وَلا طَائِرٍ يَطِيرُ بِجَنَاحَيْهِ﴾ فَقَوْلُهُ: \\\"يَطِيرُ\\\" لِتَأْكِيدِ أَنَّ الْمُرَادَ بِالطَّائِرِ حَقِيقَتُهُ فَقَدْ يُطْلَقُ مَجَازًا عَلَى غَيْرِهِ وَقَوْلُهُ: \\\"بِجَنَاحَيْهِ\\\" لِتَأْكِيدِ حَقِيقَةِ الطَّيَرَانِ لِأَنَّهُ يُطْلَقُ مَجَازًا عَلَى شِدَّةِ الْعَدْوِ وَالْإِسْرَاعِ فِي الْمَشْيِ\",[[6,38,5,8,1]]],[56,\"الصِّفَةُ\",3,235,235,999,\"وَنَظِيرُهُ ﴿يَقُولُونَ بِأَلْسِنَتِهِمْ﴾ لِأَنَّ الْقَوْلَ يُطْلَقُ مَجَازًا عَلَى غير اللسان بدليل: ﴿وَيَقُولُونَ فِي أَنْفُسِهِمْ﴾ وَكَذَا ﴿وَلَكِنْ تَعْمَى الْقُلُوبُ الَّتِي فِي الصُّدُورِ﴾ لِأَنَّ الْقَلْبَ قَدْ يُطْلَقُ مَجَازًا عَلَى الْعَيْنِ كَمَا أُطْلِقَتِ الْعَيْنُ مَجَازًا عَلَى الْقَلْبِ فِي قَوْلِهِ: ﴿الَّذِينَ كَانَتْ أَعْيُنُهُمْ فِي غِطَاءٍ عَنْ ذِكْرِي.﴾\",[[48,11,10,11,1],[58,8,25,27,1],[22,46,17,22,1],[18,101,0,6,1]]],[56,\"الصِّفَةُ\",3,235,235,999,\"الصِّفَةُ الْعَامَّةُ لَا تَأْتِي بَعْدَ الْخَاصَّةِ لَا يُقَالُ رَجُلٌ فَصِيحٌ مُتَكَلِّمٌ بَلْ مُتَكَلِّمٌ فَصِيحٌ وأشكل على هذه قَوْلُهُ تَعَالَى فِي إِسْمَاعِيلَ: ﴿وَكَانَ رَسُولًا نَبِيًّا﴾ وأجيب أنه حَالٌ لَا صِفَةٌ أَيْ مُرْسَلًا فِي حَالِ نُبُوَّتِهِ، وَقَدْ تَقَدَّمَ فِي نَوْعِ التَّقْدِيمِ وَالتَّأْخِيرِ أَمْثِلَةٌ مِنْ هَذِهِ.\",[[19,51,7,9,2],[19,54,8,10,2]]],[56,\"الصِّفَةُ\",3,235,235,999,\"إِذَا وَقَعَتِ الصِّفَةُ بَعْدَ مُتَضَايِفَيْنِ أَوَّلُهُمَا عَدَدٌ جاز إجراؤها عَلَى الْمُضَافِ وَعَلَى الْمُضَافِ إِلَيْهِ فَمِنَ الْأَوَّلِ: ﴿سَبْعَ سَمَاوَاتٍ طِبَاقًا﴾\",[[67,3,2,4,2],[71,15,5,7,2]]],[56,\"الصِّفَةُ\",3,235,235,999,\"وَمِنَ الثَّانِي: ﴿سَبْعَ بَقَرَاتٍ سِمَانٍ﴾\",[[12,43,4,6,2],[12,46,5,7,2]]],[56,\"الصِّفَةُ\",3,236,236,1000,\"إِذَا تَكَرَّرَتِ النُّعُوتُ لِوَاحِدٍ فَالْأَحْسَنُ إِنْ تَبَاعَدَ مَعْنَى الصِّفَاتِ الْعَطْفُ نَحْوُ: ﴿هُوَ الأَوَّلُ وَالآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ﴾ وَإِلَّا تَرَكَهُ نَحْوُ: ﴿وَلا تُطِعْ كُلَّ حَلَّافٍ مَهِينٍ هَمَّازٍ مَشَّاءٍ بِنَمِيمٍ مَنَّاعٍ لِلْخَيْرِ مُعْتَدٍ أَثِيمٍ عُتُلٍّ بَعْدَ ذَلِكَ زَنِيمٍ﴾\",[[57,3,0,4,1],[68,10,0,4,1],[68,11,0,2,1],[68,12,0,3,1],[68,13,0,3,1]]],[56,\"الصِّفَةُ\",3,236,236,1000,\"مِثَالُهُ فِي الْمَدْحِ ﴿وَالْمُؤْمِنُونَ يُؤْمِنُونَ بِمَا أُنْزِلَ إِلَيْكَ وَمَا أُنْزِلَ مِنْ قَبْلِكَ وَالْمُقِيمِينَ الصَّلاةَ وَالْمُؤْتُونَ الزَّكَاةَ﴾ ﴿وَلَكِنَّ الْبِرَّ مَنْ آمَنَ بِاللَّهِ﴾ إِلَى قَوْلِهِ: ﴿وَالْمُوفُونَ بِعَهْدِهِمْ إِذَا عَاهَدُوا وَالصَّابِرِينَ﴾ وَقُرِئَ شَاذًّا ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ بِرَفْعِ \\\"رَبٍّ\\\" وَنَصْبِهِ\",[[4,162,5,17,1],[2,177,8,12,1],[2,177,35,39,1]]],[56,\"الصِّفَةُ\",3,236,236,1000,\"وَمِثَالُهُ فِي الذَّمِّ ﴿وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ.﴾\",[[111,4,0,2,1]]],[56,\"الْبَدَلُ\",3,237,237,1001,\"مِثَالُ الْأَوَّلِ: ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ﴾ ﴿وَإِنَّكَ لَتَهْدِي إِلَى صِرَاطٍ مُسْتَقِيمٍ صِرَاطِ اللَّهِ﴾ ﴿لَنَسْفَعًا بِالنَّاصِيَةِ نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ﴾\",[[1,6,0,2,1],[1,7,0,3,1],[42,52,22,26,1],[42,53,0,1,1],[96,15,4,5,1],[96,16,0,2,1]]],[56,\"الْبَدَلُ\",3,237,237,1001,\"وَمِثَالُ الثَّانِي: ﴿وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا﴾ ﴿وَلَوْلا دَفْعُ اللَّهِ النَّاسَ بَعْضَهُمْ بِبَعْضٍ﴾\",[[3,97,9,17,1],[2,251,13,18,2],[22,40,11,16,2]]],[56,\"الْبَدَلُ\",3,237,237,1001,\"وَمِثَالُ الثَّالِثِ: ﴿وَمَا أَنْسَانِيهُ إِلاَّ الشَّيْطَانُ أَنْ أَذْكُرَهُ﴾ ﴿يَسْأَلونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ فِيهِ قُلْ قِتَالٌ فِيهِ كَبِيرٌ﴾ ﴿قُتِلَ أَصْحَابُ الأُخْدُودِ النَّارَ﴾ ﴿لَجَعَلْنَا لِمَنْ يَكْفُرُ بِالرَّحْمَنِ لِبُيُوتِهِمْ﴾\",[[18,63,9,14,1],[2,217,0,9,1],[85,4,0,2,1],[85,5,0,0,1],[43,33,6,10,1]]],[56,\"الْبَدَلُ\",3,237,238,1001,\"وَزَادَ بَعْضُهُمْ بَدَلَ الْكُلِّ مِنَ الْبَعْضِ وَقَدْ وَجَدْتُ لَهُ مِثَالًا فِي الْقُرْآنِ وَهُوَ قَوْلُهُ: ﴿يَدْخُلُونَ الْجَنَّةَ وَلَا يُظْلَمُونَ شَيْئًا جَنَّاتِ عَدْنٍ﴾ ف \\\"جنات عَدْنٍ \\\"بَدَلٌ مِنَ الْجَنَّةِ الَّتِي هِيَ بَعْضٌ وَفَائِدَتُهُ تَقْرِيرُ أَنَّهَا جنات كَثِيرَةٌ لَا جَنَّةٌ وَاحِدَةٌ. قَالَ ابْنُ السَّيِّدِ وليس كل بدل يُقْصَدُ بِهِ رَفَعُ الْإِشْكَالِ الَّذِي يَعْرِضُ فِي الْمُبْدَلِ مِنْهُ بَلْ مِنَ الْبَدَلِ مَا يُرَادُ بِهِ التَّأْكِيدُ وَإِنْ كَانَ مَا قَبْلَهُ غَنِيًّا عَنْهُ كَقَوْلِهِ: ﴿وَإِنَّكَ لَتَهْدِي إِلَى صِرَاطٍ مُسْتَقِيمٍ صِرَاطِ اللَّهِ﴾ أَلَا تَرَى أَنَّهُ لَوْ لَمْ يُذْكَرِ الصِّرَاطُ الثَّانِي لَمْ يَشُكَّ أَحَدٌ فِي أَنَّ الصِّرَاطَ الْمُسْتَقِيمَ هُوَ صِرَاطُ اللَّهِ وَقَدْ نَصَّ سِيبَوَيْهِ عَلَى أَنَّ مِنَ الْبَدَلِ مَا الْغَرَضُ مِنْهُ التَّأْكِيدُ انْتَهَى.\",[[19,60,7,11,1],[19,61,0,1,1],[42,52,22,26,1],[42,53,0,1,1]]],[56,\"الْبَدَلُ\",3,238,238,1002,\"وَجَعَلَ مِنْهُ ابْنُ عَبْدِ السَّلَامِ ﴿وَإِذْ قَالَ إِبْرَاهِيمُ لأَبِيهِ آزَرَ﴾ قَالَ: وَلَا بَيَانَ فِيهِ لِأَنَّ الْأَبَ لَا يَلْتَبِسُ بِغَيْرِهِ وَرُدَّ بِأَنَّهُ يُطْلَقُ عَلَى الْجَدِّ فَأُبْدِلَ لِبَيَانِ إِرَادَةِ الْأَبِ حَقِيقَةً.\",[[6,74,0,4,1]]],[56,\"عَطْفُ الْبَيَانِ\",3,238,239,1002,\"وَقَالَ ابْنُ مَالِكٍ فِي شَرْحِ الْكَافِيَةِ عَطْفُ الْبَيَانِ يَجْرِي مَجْرَى النَّعْتِ فِي تَكْمِيلِ مَتْبُوعِهِ وَيُفَارِقُهُ فِي أَنَّ تَكْمِيلَهُ مَتْبُوعَهُ بِشَرْحٍ وَتَبْيِينٍ لَا بِدِلَالَةٍ عَلَى مَعْنًى فِي الْمَتْبُوعِ أَوْ سَبَبِيَّةٍ وَمَجْرَى التَّأْكِيدِ فِي تَقْوِيَةِ دَلَالَتِهِ وَيُفَارِقُهُ فِي أَنَّهُ لَا يَرْفَعُ تَوَهُّمَ مَجَازٍ وَمَجْرَى الْبَدَلِ فِي صَلَاحِيَتِهِ لِلِاسْتِقْلَالِ وَيُفَارِقُهُ فِي أَنَّهُ غَيْرُ مَنَوِيِّ الِاطِّرَاحِ وَمِنْ أَمْثِلَتِهِ: ﴿فِيهِ آيَاتٌ بَيِّنَاتٌ مَقَامُ إِبْرَاهِيمَ﴾ ﴿مِنْ شَجَرَةٍ مُبَارَكَةٍ زَيْتُونَةٍ﴾\",[[3,97,0,4,1],[24,35,17,20,1]]],[56,\"عَطْفُ الْبَيَانِ\",3,239,239,1003,\"وَقَدْ يَأْتِي لِمُجَرَّدِ الْمَدْحِ بِلَا إِيضَاحِ وَمِنْهُ: ﴿جَعَلَ اللَّهُ الْكَعْبَةَ الْبَيْتَ الْحَرَامَ﴾ فالبيت الْحَرَامَ عَطْفُ بَيَانٍ لِلْمَدْحِ لَا لِلْإِيضَاحِ.\",[[5,97,0,4,1]]],[56,\"عَطْفُ الْبَيَانِ\",3,239,240,1003,\"وَالْقَصْدُ مِنْهُ التَّأْكِيدُ أَيْضًا وَجُعِلَ مِنْهُ: ﴿إِنَّمَا أَشْكُو بَثِّي وَحُزْنِي﴾ ﴿فَمَا وَهَنُوا لِمَا أَصَابَهُمْ فِي سَبِيلِ اللَّهِ وَمَا ضَعُفُوا﴾ ﴿فَلا يَخَافُ ظُلْمًا وَلا هَضْمًا﴾ ﴿لَا تَخَافُ دَرَكًا وَلا تَخْشَى﴾ ﴿لَا تَرَى فِيهَا عِوَجًا وَلا أَمْتًا﴾ قَالَ الْخَلِيلُ: الْعِوَجُ وَالْأَمْتُ بِمَعْنًى وَاحِدٍ ﴿سِرَّهُمْ وَنَجْوَاهُمْ﴾ ﴿شِرْعَةً وَمِنْهَاجًا﴾ ﴿لا تُبْقِي وَلا تَذَرُ﴾ ﴿إِلاَّ دُعَاءً وَنِدَاءً﴾ ﴿أَطَعْنَا سَادَتَنَا وَكُبَرَاءَنَا﴾ ﴿لَا يَمَسُّنَا فِيهَا نَصَبٌ وَلا يَمَسُّنَا فِيهَا لُغُوبٌ﴾ فَإِنَّ \\\"نَصَبٌ\\\" كَلَغَبٍ وَزْنًا وَمَعْنًى، ﴿صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ﴾ عذرا أو نذرا قَالَ ثَعْلَبٌ: هُمَا بِمَعْنًى وَأَنْكَرَ الْمُبَرِّدُ وُجُودَ هَذَا النَّوْعِ فِي الْقُرْآنِ وَأَوَّلَ مَا سَبَقَ عَلَى اخْتِلَافِ الْمَعْنَيَيْنِ وَقَالَ بَعْضُهُمْ الْمَخْلَصُ فِي هَذَا أَنْ تَعْتَقِدَ أَنَّ مَجْمُوعَ الْمُتَرَادِفَيْنِ يُحَصِّلُ مَعْنًى لَا يُوجَدُ عِنْدَ انْفِرَادِهِمَا فَإِنَّ التَّرْكِيبَ يُحْدِثُ مَعْنًى زَائِدًا وَإِذَا كَانَتْ كَثْرَةُ الْحُرُوفِ تُفِيدُ زِيَادَةَ الْمَعْنَى فَكَذَلِكَ كَثْرَةُ الْأَلْفَاظِ\",[[12,86,1,4,1],[3,146,7,15,1],[20,112,6,10,1],[20,77,13,17,1],[20,107,0,5,1],[9,78,5,6,2],[43,80,5,6,2],[5,48,27,28,1],[74,28,0,3,1],[2,171,9,11,1],[33,67,3,5,1],[35,35,6,13,1],[2,157,2,5,1]]],[56,\"عَطْفُ الْبَيَانِ\",3,240,240,1004,\"وَمِنْ أَمْثِلَتِهِ: ﴿حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى﴾ . ﴿مَنْ كَانَ عَدُوًّا لِلَّهِ وَمَلائِكَتِهِ وَرُسُلِهِ وَجِبْرِيلَ وَمِيكَالَ﴾ ﴿وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ﴾ ﴿وَالَّذِينَ يُمَسِّكُونَ بِالْكِتَابِ وَأَقَامُوا الصَّلاةَ﴾ فَإِنَّ إِقَامَتَهَا مِنْ جُمْلَةِ التَّمَسُّكِ بِالْكِتَابِ وَخُصَّتْ بالذكر إظهارا لمرتبتها لِكَوْنِهَا عِمَادَ الدِّينِ وَخُصَّ جِبْرِيلُ ميكائيل بِالذِّكْرِ رَدًّا عَلَى الْيَهُودِ فِي دَعْوَى عَدَاوَتِهِ وَضُمَّ إِلَيْهِ مِيكَائِيلُ لِأَنَّهُ مَلَكُ الرِّزْقِ الَّذِي هُوَ حَيَاةُ الْأَجْسَادِ كَمَا أَنَّ جِبْرِيلَ مَلَكُ الْوَحْيِ الَّذِي هُوَ حَيَاةُ الْقُلُوبِ وَالْأَرْوَاحِ\",[[2,238,0,4,1],[2,98,0,7,1],[3,104,0,10,1],[7,170,0,4,1]]],[56,\"عَطْفُ الْبَيَانِ\",3,241,242,1005,\"ومن أمثلته: ﴿قُلْ إِنَّ صَلاتِي وَنُسُكِي﴾ والنسك العبادة فهو أعم ﴿وَلَقَدْ آتَيْنَاكَ سَبْعًا مِنَ الْمَثَانِي وَالْقُرْآنَ الْعَظِيمَ﴾ ﴿رَبِّ اغْفِرْ لِي وَلِوَالِدَيَّ وَلِمَنْ دَخَلَ بَيْتِيَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ﴾ ﴿فَإِنَّ اللَّهَ هُوَ مَوْلاهُ وَجِبْرِيلُ وَصَالِحُ الْمُؤْمِنِينَ وَالْمَلائِكَةُ بَعْدَ ذَلِكَ ظَهِيرٌ﴾ وجعل مِنْهُ الزَّمَخْشَرِيُّ ﴿وَمَنْ يُدَبِّرُ الأَمْرَ﴾ بَعْدَ قَوْلِهِ: ﴿قُلْ مَنْ يَرْزُقُكُمْ﴾ النَّوْعُ الْحَادِي عَشَرَ: الْإِيضَاحُ بَعْدَ الْإِبْهَامِ\",[[6,162,0,3,1],[15,87,0,6,1],[71,28,0,9,1],[66,4,10,20,1],[10,31,19,21,1],[10,31,0,2,1]]],[56,\"عَطْفُ الْبَيَانِ\",3,242,242,1006,\"وَمِنْ أَمْثِلَتِهِ: ﴿رَبِّ اشْرَحْ لِي صَدْرِي﴾ فَإِنَّ ﴿اشْرَحْ﴾ يُفِيدُ طَلَبَ شَرْحِ شَيْءٍ مَا وَ﴿صَدْرِي﴾ يُفِيدُ تَفْسِيرَهُ وَبَيَانَهُ وَكَذَلِكَ ﴿وَيَسِّرْ لِي أَمْرِي﴾ وَالْمَقَامُ يَقْتَضِي التَّأْكِيدَ لِلْإِرْسَالِ الْمُؤْذِنِ بِتَلَقِّي الشَّدَائِدِ وَكَذَلِكَ ﴿أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ﴾\",[[20,25,1,4,1],[20,25,2,2,1],[20,25,4,4,1],[20,26,0,2,1],[94,1,0,3,1]]],[56,\"عَطْفُ الْبَيَانِ\",3,242,242,1006,\"فَإِنَّ الْمَقَامَ يَقْتَضِي التَّأْكِيدَ لِأَنَّهُ مَقَامُ امْتِنَانٍ وَتَفْخِيمٍ وَكَذَا ﴿وَقَضَيْنَا إِلَيْهِ ذَلِكَ الأَمْرَ أَنَّ دَابِرَ هَؤُلاءِ مَقْطُوعٌ مُصْبِحِينَ﴾\",[[15,66,0,8,1]]],[56,\"عَطْفُ الْبَيَانِ\",3,242,243,1006,\"وَمِنْهُ التَّفْصِيلُ بَعْدَ الْإِجْمَالِ نَحْوُ: ﴿إِنَّ عِدَّةَ الشُّهُورِ عِنْدَ اللَّهِ اثْنَا عَشَرَ شَهْرًا﴾ إِلَى قَوْلِهِ: ﴿مِنْهَا أَرْبَعَةٌ حُرُمٌ﴾ وَعَكْسُهُ كَقَوْلِهِ: ﴿ثَلاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ تِلْكَ عَشَرَةٌ كَامِلَةٌ﴾ أُعِيدَ ذِكْرُ\\\"الْعَشَرَةِ\\\"لِرَفْعِ تَوَهُّمِ أَنَّ الْوَاوَ فِي\\\"وَسَبْعَةٍ\\\"، بِمَعْنَى\\\"أَوْ\\\" فَتَكُونُ الثَّلَاثَةُ دَاخِلَةً فِيهَا كَمَا فِي قَوْلِهِ: ﴿خَلَقَ الأَرْضَ فِي يَوْمَيْنِ﴾ ثُمَّ قَالَ: ﴿وَجَعَلَ فِيهَا رَوَاسِيَ مِنْ فَوْقِهَا وَبَارَكَ فِيهَا وَقَدَّرَ فِيهَا أَقْوَاتَهَا فِي أَرْبَعَةِ أَيَّامٍ﴾ فَإِنَّ مِنْ جُمْلَتِهَا الْيَوْمَيْنِ الْمَذْكُورَيْنِ أَوَّلًا وَلَيْسَتْ أَرْبَعَةً غَيْرَهُمَا. وَهَذَا أَحْسَنُ الْأَجْوِبَةِ فِي الْآيَةِ وَهُوَ الَّذِي أَشَارَ إِلَيْهِ الزَّمَخْشَرِيُّ وَرَجَّحَهُ ابْنُ عَبْدِ السَّلَامِ وَجَزَمَ بِهِ الزَّمْلَكَانِيُّ فِي\\\"أَسْرَارِ التَّنْزِيلِ\\\" قَالَ وَنَظِيرُهُ ﴿وَوَاعَدْنَا مُوسَى ثَلاثِينَ لَيْلَةً وَأَتْمَمْنَاهَا بِعَشْرٍ﴾ فَإِنَّهُ رَافِعٌ لِاحْتِمَالِ أَنْ تَكُونَ تِلْكَ الْعَشَرَةُ مِنْ غَيْرِ مُوَاعَدَةٍ قَالَ ابْنُ عَسْكَرٍ وَفَائِدَةُ الْوَعْدِ بِثَلَاثِينَ أَوَّلًا ثُمَّ بِعَشْرٍ لِيَتَجَدَّدَ لَهُ قرب إنفضاء الْمُوَاعِدَةِ وَيَكُونُ فِيهِ مُتَأَهِّبًا مُجْتَمِعَ الرَّأْيِ حَاضِرَ الذِّهْنِ لِأَنَّهُ لَوْ وَعَدَ بِالْأَرْبَعِينَ أَوَّلًا كَانَتْ مُتَسَاوِيَةً فَلَمَّا فُصِلَتِ اسْتَشْعَرَتِ النَّفْسُ قُرْبَ التَّمَامِ وَتَجَدَّدَ بِذَلِكَ عَزْمٌ لَمْ يَتَقَدَّمْ\",[[9,36,0,7,1],[9,36,15,17,1],[2,196,48,57,1],[41,9,4,7,1],[41,10,0,12,1],[7,142,0,5,1]]],[56,\"عَطْفُ الْبَيَانِ\",3,243,243,1007,\"وَقَالَ الْكَرْمَانِيُّ فِي الْعَجَائِبِ: فِي قَوْلِهِ: ﴿تِلْكَ عَشَرَةٌ كَامِلَةٌ﴾ ثَمَانِيَةُ أَجْوِبَةٍ: جَوَابَانِ مِنَ التَّفْسِيرِ وَجَوَابٌ مِنَ الْفِقْهِ وَجَوَابٌ مِنَ النَّحْوِ وَجَوَابٌ مِنَ اللُّغَةِ وَجَوَابٌ مِنَ الْمَعْنَى وَجَوَابَانِ مِنَ الْحِسَابِ وَقَدْ سُقْتُهَا فِي\\\"أَسْرَارِ التَّنْزِيلِ\\\"\",[[2,196,55,57,1]]],[56,\"التَّفْسِيرُ\",3,243,243,1007,\"قَالَ أَهْلُ الْبَيَانِ وَهُوَ أَنْ يَكُونَ فِي الْكَلَامِ لَبْسٌ وَخَفَاءٌ فَيُؤْتَى بِمَا يُزِيلُهُ وَيُفَسِّرُهُ وَمِنْ أَمْثِلَتِهِ: ﴿إِنَّ الأِنْسَانَ خُلِقَ هَلُوعًا إِذَا مَسَّهُ الشَّرُّ جَزُوعًا وَإِذَا مَسَّهُ الْخَيْرُ مَنُوعًا﴾\",[[70,19,0,3,1],[70,20,0,3,1],[70,21,0,3,1]]],[56,\"التَّفْسِيرُ\",3,243,244,1007,\"فَقَوْلُهُ: \\\"إِذَا مَسَّهُ\\\" إِلَخْ تَفْسِيرٌ لِلْهَلُوعِ كَمَا قَالَ أَبُو الْعَالِيَةِ وَغَيْرُهُ ﴿الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ﴾ قَالَ الْبَيْهَقِيُّ فِي \\\"شَرْحِ الْأَسْمَاءِ الْحُسْنَى\\\" قَوْلُهُ: ﴿لَا تَأْخُذُهُ سِنَةٌ﴾ تَفْسِيرٌ لِلْقَيُّومِ\",[[2,255,6,11,1],[2,255,7,9,1]]],[56,\"التَّفْسِيرُ\",3,244,244,1008,\"﴿يَسُومُونَكُمْ سُوءَ الْعَذَابِ يُذَبِّحُونَ﴾ الآية فَيُذَبِّحُونَ وَمَا بَعْدَهُ تَفْسِيرٌ لِلسَّوْمِ\",[[2,49,5,8,2],[14,6,13,16,2]]],[56,\"التَّفْسِيرُ\",3,244,244,1008,\"﴿إِنَّ مَثَلَ عِيسَى عِنْدَ اللَّهِ كَمَثَلِ آدَمَ خَلَقَهُ مِنْ تُرَابٍ﴾ الْآيَةَ فَ \\\"خَلَقَهُ\\\" وَمَا بَعْدَهُ تَفْسِيرٌ لِلْمَثَلِ ﴿لَا تَتَّخِذُوا عَدُوِّي وَعَدُوَّكُمْ أَوْلِيَاءَ تُلْقُونَ إِلَيْهِمْ بِالْمَوَدَّةِ﴾ فَ \\\"تُلْقُونَ\\\" تَفْسِيرٌ لِاتِّخَاذِهِمْ أَوْلِيَاءَ\",[[3,59,0,9,1],[60,1,3,10,1]]],[56,\"التَّفْسِيرُ\",3,244,244,1008,\"﴿الصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ﴾ الآية قَالَ مُحَمَّدُ بْنُ كَعْبٍ الْقُرَظِيُّ لَمْ يَلِدْ إِلَى آخِرِهِ تَفْسِيرٌ لِلصَّمَدِ وَهُوَ فِي الْقُرْآنِ كَثِيرٌ قَالَ: ابْنُ جِنِّي وَمَتَى كَانْتِ الْجُمْلَةُ تَفْسِيرًا لَمْ يَحْسُنِ الْوَقْفُ عَلَى مَا قَبْلَهَا دُونَهَا لِأَنَّ تفسير الشيء لا حق بِهِ وَمُتَمِّمٌ لَهُ وَجَارٍ مَجْرَى بَعْضِ أَجْزَائِهِ.\",[[112,2,1,1,1],[112,3,0,3,1]]],[56,\"التَّفْسِيرُ\",3,244,245,1008,\"مِنْهَا زِيَادَةُ التَّقْرِيرِ وَالتَّمْكِينِ نَحْوُ: ﴿قُلْ هُوَ اللَّهُ أَحَدٌ اللَّهُ الصَّمَدُ﴾ ﴿وَبِالْحَقِّ أَنْزَلْنَاهُ وَبِالْحَقِّ نَزَلَ﴾ ﴿إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ النَّاسِ لا يَشْكُرُونَ﴾ ﴿لِتَحْسَبُوهُ مِنَ الْكِتَابِ وَمَا هُوَ مِنَ الْكِتَابِ وَيَقُولُونَ هُوَ مِنْ عِنْدِ اللَّهِ وَمَا هُوَ مِنْ عِنْدِ اللَّهِ﴾\",[[112,1,0,3,1],[112,2,0,1,1],[17,105,0,3,1],[2,243,17,27,2],[40,61,9,19,2],[3,78,6,22,1]]],[56,\"التَّفْسِيرُ\",3,245,245,1009,\"وَمِنْهَا: قَصْدُ التَّعْظِيمِ نَحْوُ: ﴿وَاتَّقُوا اللَّهَ وَيُعَلِّمُكُمُ اللَّهُ وَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ﴾ ﴿أُولَئِكَ حِزْبُ اللَّهِ أَلا إِنَّ حِزْبَ اللَّهِ هُمُ الْمُفْلِحُونَ﴾ ﴿وَقُرْآنَ الْفَجْرِ إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا﴾ ﴿وَلِبَاسُ التَّقْوَى ذَلِكَ خَيْرٌ﴾\",[[2,282,120,127,1],[58,22,42,50,1],[17,78,7,13,1],[7,26,9,12,1]]],[56,\"التَّفْسِيرُ\",3,245,245,1009,\"وَمِنْهَا: قَصْدُ الْإِهَانَةِ وَالتَّحْقِيرِ نَحْوُ: ﴿أُولَئِكَ حِزْبُ الشَّيْطَانِ أَلا إِنَّ حِزْبَ الشَّيْطَانِ هُمُ الْخَاسِرُونَ﴾ ﴿إِنَّ الشَّيْطَانَ يَنْزَغُ بَيْنَهُمْ﴾\",[[58,19,6,14,1],[17,53,6,9,1]]],[56,\"التَّفْسِيرُ\",3,245,246,1009,\"وَمِنْهَا: إِزَالَةُ اللَّبْسِ حَيْثُ يُوهِمُ الضَّمِيرُ أَنَّهُ غير الأول: ﴿قُلِ اللَّهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ﴾ لَوْ قَالَ: \\\"تُؤْتِيهِ\\\" لَأَوْهَمَ أَنَّهُ الْأَوَّلُ قَالَهُ ابْنُ الْخَشَّابِ ﴿الظَّانِّينَ بِاللَّهِ ظَنَّ السَّوْءِ عَلَيْهِمْ دَائِرَةُ السَّوْءِ﴾ لِأَنَّهُ لَوْ قَالَ: \\\"عَلَيْهِمْ دَائِرَتُهُ\\\" لَأَوْهَمَ أَنَّ الضَّمِيرَ عَائِدٌ إِلَى اللَّهِ تَعَالَى: ﴿فَبَدَأَ بِأَوْعِيَتِهِمْ قَبْلَ وِعَاءِ أَخِيهِ ثُمَّ اسْتَخْرَجَهَا مِنْ وِعَاءِ أَخِيهِ﴾ لَمْ يَقُلْ \\\"مِنْهُ\\\" لِئَلَّا يُتَوَهَّمُ عَوْدُ الضَّمِيرِ إِلَى الْأَخِ فَيَصِيرُ كَأَنَّهُ مُبَاشِرٌ بِطَلَبِ خُرُوجِهَا وَلَيْسَ كَذَلِكَ لِمَا فِي الْمُبَاشَرَةِ مِنَ الْأَذَى الَّذِي تَأْبَاهُ النُّفُوسُ الْأَبِيَّةُ فَأُعِيدَ لَفْظُ \\\"الظَّاهِرِ\\\" لِنَفْيِ هَذَا وَلَمْ يَقُلْ: \\\"مِنْ وِعَائِهِ\\\" لِئَلَّا يُتَوَهَّمُ عَوْدُ الضَّمِيرِ إِلَى يُوسُفَ لِأَنَّ الْعَائِدَ عَلَيْهِ ضَمِيرُ\\\"اسْتَخْرَجَهَا\\\" وَمِنْهَا قَصْدُ تَرْبِيَةِ الْمَهَابَةِ وَإِدْخَالُ الرَّوْعِ عَلَى ضمير السامع وبذكر الِاسْمِ الْمُقْتَضِي لِذَلِكَ كَمَا تَقُولُ الْخَلِيفَةُ أَمِيرُ الْمُؤْمِنِينَ يَأْمُرُكَ بِكَذَا وَمِنْهُ: ﴿إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الأَمَانَاتِ إِلَى أَهْلِهَا﴾ ﴿إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ﴾\",[[3,26,0,5,1],[48,6,5,11,1],[12,76,0,9,1],[4,58,0,7,1],[16,90,0,3,1]]],[56,\"التَّفْسِيرُ\",3,246,246,1010,\"ومنها قصد تقوية داعية المأمور وَمِنْهُ: ﴿فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى اللَّهِ إِنَّ اللَّهَ يُحِبُّ الْمُتَوَكِّلِينَ﴾\",[[3,159,21,29,1]]],[56,\"التَّفْسِيرُ\",3,246,246,1010,\"وَمِنْهَا تَعْظِيمُ الْأَمْرِ نَحْوُ: ﴿أَوَلَمْ يَرَوْا كَيْفَ يُبْدِئُ اللَّهُ الْخَلْقَ ثُمَّ يُعِيدُهُ إِنَّ ذَلِكَ عَلَى اللَّهِ يَسِيرٌ﴾ ﴿قُلْ سِيرُوا فِي الأَرْضِ فَانْظُرُوا كَيْفَ بَدَأَ الْخَلْقَ﴾ هَلْ أَتَى عَلَى الْإِنْسَانِ حِينٌ مِنَ الدَّهْرِ لَمْ يَكُنْ شَيْئًا مَذْكُورًا إِنَّا خَلَقْنَا الْإِنْسَانَ\",[[29,19,0,12,1],[29,20,0,7,1]]],[56,\"التَّفْسِيرُ\",3,246,246,1010,\"وَمِنْهَا: الِاسْتِلْذَاذُ بِذِكْرِهِ وَمِنْهُ: ﴿وَأَوْرَثَنَا الأَرْضَ نَتَبَوَّأُ مِنَ الْجَنَّةِ﴾ لَمْ يَقُلْ مِنْهَا وَلِهَذَا عَدَلَ عَنْ ذِكْرِ الْأَرْضِ إِلَى الْجَنَّةِ\",[[39,74,6,10,1]]],[56,\"التَّفْسِيرُ\",3,246,246,1010,\"ومنها: قصد التوصل مِنَ الظَّاهِرِ إِلَى الْوَصْفِ وَمِنْهُ: ﴿فَآمِنُوا بِاللَّهِ وَرَسُولِهِ النَّبِيِّ الأُمِّيِّ الَّذِي يُؤْمِنُ بِاللَّهِ﴾ بَعْدَ قَوْلِهِ: ﴿إِنِّي رَسُولُ اللَّهِ﴾ لم يقل فآمنوا بالله وبي لِيَتَمَكَّنَ مِنْ إِجْرَاءِ الصِّفَاتِ الَّتِي ذكرها وليعلم أَنَّ الَّذِي وَجَبَ الْإِيمَانُ بِهِ وَالِاتِّبَاعُ لَهُ هُوَ مَنْ وُصِفَ بِهَذِهِ الصِّفَاتِ وَلَوْ أَتَى بِالضَّمِيرِ لَمْ يُمْكِنْ ذَلِكَ لِأَنَّهُ لَا يُوصَفُ\",[[7,158,19,26,1],[7,158,3,5,1]]],[56,\"التَّفْسِيرُ\",3,246,247,1010,\"وَمِنْهَا: التَّنْبِيهُ عَلَى عِلِّيَةِ الْحُكْمِ نَحْوُ: ﴿فَبَدَّلَ الَّذِينَ ظَلَمُوا قَوْلًا غَيْرَ الَّذِي قِيلَ لَهُمْ﴾ ﴿فَأَنْزَلْنَا عَلَى الَّذِينَ ظَلَمُوا رِجْزًا﴾ ﴿فَإِنَّ اللَّهَ عَدُوٌّ لِلْكَافِرِينَ﴾ لَمْ يَقُلْ: \\\"لَهُمْ إِعْلَامًا بِأَنَّ مَنْ عَادَى هَؤُلَاءِ فَهُوَ كَافِرٌ وَإِنَّ اللَّهَ إِنَّمَا عَادَاهُ لِكُفْرِهِ ﴿فَمَنْ أَظْلَمُ مِمَّنِ افْتَرَى عَلَى اللَّهِ كَذِبًا أَوْ كَذَّبَ بِآياتِهِ إِنَّهُ لَا يُفْلِحُ الْمُجْرِمُونَ﴾ ﴿وَالَّذِينَ يُمَسِّكُونَ بِالْكِتَابِ وَأَقَامُوا الصَّلاةَ إِنَّا لَا نُضِيعُ أَجْرَ الْمُصْلِحِينَ﴾ ﴿إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا﴾\",[[2,59,0,12,1],[2,98,8,11,1],[7,170,0,9,1],[18,30,0,11,1]]],[56,\"التَّفْسِيرُ\",3,247,247,1011,\"وَمِنْهَا: قَصْدُ الْعُمُومِ نَحْوُ: ﴿وَمَا أُبَرِّئُ نَفْسِي إِنَّ النَّفْسَ لأَمَّارَةٌ بِالسُّوءِ﴾ لَمْ يَقُلْ: \\\"إِنَّهَا\\\" لِئَلَّا يُفْهَمُ تَخْصِيصُ ذَلِكَ بِنَفْسِهِ ﴿أُولَئِكَ هُمُ الْكَافِرُونَ حَقًّا﴾ ﴿وَأَعْتَدْنَا لِلْكَافِرِينَ عَذَابًا﴾\",[[12,53,0,6,1],[4,151,0,6,1]]],[56,\"التَّفْسِيرُ\",3,247,247,1011,\"وَمِنْهَا: قَصْدُ الْخُصُوصِ، نَحْوُ: ﴿وَامْرَأَةً مُؤْمِنَةً إِنْ وَهَبَتْ نَفْسَهَا لِلنَّبِيِّ﴾ لَمْ يَقُلْ لَكَ تَصْرِيحًا بِأَنَّهُ خَاصٌّ بِهِ\",[[33,50,27,32,1]]],[56,\"التَّفْسِيرُ\",3,247,247,1011,\"وَمِنْهَا: الْإِشَارَةُ إِلَى عَدَمِ دُخُولِ الْجُمْلَةِ فِي حِكَمِ الْأَوْلَى نَحْوُ: ﴿فَإِنْ يَشَأِ اللَّهُ يَخْتِمْ عَلَى قَلْبِكَ وَيَمْحُ اللَّهُ الْبَاطِلَ﴾ فَإِنَّ\\\"وَيَمْحُ اللَّهُ\\\" اسْتِئْنَافٌ لَا دَاخِلٌ فِي حُكْمِ الشَّرْطِ\",[[42,24,6,14,1]]],[56,\"التَّفْسِيرُ\",3,247,247,1011,\"وَمِنْهَا: مُرَاعَاةُ الْجِنَاسِ وَمِنْهُ: ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ﴾ السُّورَةَ.\",[[114,1,0,3,1]]],[56,\"التَّفْسِيرُ\",3,247,248,1011,\"ذَكَرَهُ الشَّيْخُ عِزُّ الدِّينِ وَمِثْلُهُ ابْنُ الصَّائِغِ بِقَوْلِهِ: ﴿خَلَقَ الأِنْسَانَ مِنْ عَلَقٍ﴾ ثُمَّ قَالَ: ﴿عَلَّمَ الأِنْسَانَ مَا لَمْ يَعْلَمْ كَلَّا إِنَّ الأِنْسَانَ لَيَطْغَى﴾ فَإِنَّ الْمُرَادَ بِالْإِنْسَانِ الْأَوَّلِ الْجِنْسُ وَبِالثَّانِي آدَمُ أَوْ مَنْ يَعْلَمُ الْكِتَابَةَ أَوْ إِدْرِيسَ وَبِالثَّالِثِ أَبُو جَهْلٍ\",[[96,2,0,3,1],[96,5,0,4,1],[96,6,0,3,1]]],[56,\"التَّفْسِيرُ\",3,248,248,1012,\"وَمِنْهَا: أَنْ يَتَحَمَّلَ ضَمِيرًا لَا بُدَّ مِنْهُ ومنه: ﴿حَتَّى إِذَا أَتَيَا أَهْلَ قَرْيَةٍ اسْتَطْعَمَا أَهْلَهَا﴾ لَوْ قَالَ: \\\"اسْتَطْعَمَاهَا\\\" لَمْ يَصِحَّ لِأَنَّهُمَا لَمْ يَسْتَطْعِمَا الْقَرْيَةَ أَوْ \\\"اسْتَطْعَمَاهُمْ\\\" فَكَذَلِكَ لَأَنَّ جُمْلَةَ \\\"اسْتَطْعَمَا\\\" صفة لقرية النكرة لَا لِ \\\"أَهْلَ\\\" فَلَا بُدَّ أَنْ يَكُونَ فِيهَا ضَمِيرٌ يَعُودُ عليها وَلَا يُمْكِنُ إِلَّا مَعَ التَّصْرِيحِ بِالظَّاهِرِ\",[[18,77,1,7,1]]],[56,\"التَّفْسِيرُ\",3,249,249,1013,\"إِعَادَةُ الظَّاهِرِ بِمَعْنَاهُ أَحْسَنُ مِنْ إِعَادَتِهِ بِلَفْظِهِ كَمَا مَرَّ فِي آيَاتِ: ﴿إِنَّا لَا نُضِيعُ أَجْرَ الْمُصْلِحِينَ﴾ ﴿إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا﴾ وَنَحْوِهَا\",[[7,170,5,9,1],[18,30,5,11,1]]],[56,\"التَّفْسِيرُ\",3,249,249,1013,\"وَمِنْهُ: ﴿مَا يَوَدُّ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَلا الْمُشْرِكِينَ أَنْ يُنَزَّلَ عَلَيْكُمْ مِنْ خَيْرٍ مِنْ رَبِّكُمْ وَاللَّهُ يَخْتَصُّ بِرَحْمَتِهِ مَنْ يَشَاءُ﴾ فَإِنَّ إِنْزَالَ الْخَيْرِ مُنَاسِبٌ لِلرُّبُوبِيَّةِ وَأَعَادَهُ بِلَفْظِ \\\"اللَّهِ\\\" لِأَنَّ تَخْصِيصَ النَّاسِ بِالْخَيْرِ دُونَ غَيْرِهِمْ مُنَاسِبٌ لِلْإِلَهِيَّةِ لِأَنَّ دَائِرَةَ الرُّبُوبِيَّةِ أَوْسَعُ\",[[2,105,0,20,1]]],[56,\"التَّفْسِيرُ\",3,249,249,1013,\"وَمِنْهُ: ﴿الْحَمْدُ لِلَّهِ الَّذِي خَلَقَ السَّمَاوَاتِ وَالأَرْضَ﴾ إِلَى قَوِلِهِ: ﴿بِرَبِّهِمْ يَعْدِلُونَ﴾ وَإِعَادَتُهُ فِي جُمْلَةٍ أُخْرَى أَحْسَنُ مِنْهُ فِي الْجُمْلَةِ الْوَاحِدَةِ لِانْفِصَالِهَا وبعد الطُّولِ أَحْسَنُ مِنَ الْإِضْمَارِ لِئَلَّا يَبْقَى الذِّهْنُ مُتَشَاغِلًا بِسَبَبِ مَا يَعُودُ عَلَيْهِ فَيَفُوتُهُ مَا شَرَعَ فِيهِ كَقَوْلِهِ: ﴿وَتِلْكَ حُجَّتُنَا آتَيْنَاهَا إِبْرَاهِيمَ عَلَى قَوْمِهِ﴾ بَعْدَ قَوْلِهِ: ﴿وَإِذْ قَالَ إِبْرَاهِيمُ لِأَبِيهِ آزَرَ﴾\",[[6,1,0,5,1],[6,1,12,13,1],[6,83,0,5,1],[6,74,0,4,1]]],[56,\"التَّفْسِيرُ\",3,249,250,1013,\"وَهُوَ خَتْمُ الْكَلَامِ بِمَا يُفِيدُ نُكْتَةً يَتِمُّ الْمَعْنَى بِدُونِهَا، وَزَعَمَ بَعْضُهُمْ أَنَّهُ خَاصٌّ بِالشِّعْرِ وَرُدَّ بِأَنَّهُ وَقَعَ فِي الْقُرْآنِ من ذلك ﴿يَا قَوْمِ اتَّبِعُوا الْمُرْسَلِينَ اتَّبِعُوا مَنْ لَا يَسْأَلُكُمْ أَجْرًا وَهُمْ مُهْتَدُونَ﴾ فَقَوْلُهُ: \\\"وَهُمْ مُهْتَدُونَ\\\"إِيغَالٌ لِأَنَّهُ يَتِمُّ الْمَعْنَى بِدُونِهِ إِذِ الرَّسُولُ مُهْتَدٍ لَا مَحَالَةَ لَكِنَّ فِيهِ زِيَادَةَ مُبَالَغَةٍ فِي الْحَثِّ عَلَى اتِّبَاعِ الرُّسُلِ وَالتَّرْغِيبِ فِيهِ\",[[36,20,7,9,1],[36,21,0,6,1]]],[56,\"التَّفْسِيرُ\",3,250,250,1014,\"وَجَعَلَ ابْنُ أَبِي الْإِصْبَعِ مِنْهُ: ﴿وَلا تُسْمِعُ الصُّمَّ الدُّعَاءَ إِذَا وَلَّوْا مُدْبِرِينَ﴾ فَإِنَّ قَوْلَهُ: \\\"إِذَا وَلَّوْا مُدْبِرِينَ\\\"زَائِدٌ عَلَى الْمَعْنَى مُبَالَغَةً فِي عَدَمِ انْتِفَاعِهِمْ ﴿وَمَنْ أَحْسَنُ مِنَ اللَّهِ حُكْمًا لِقَوْمٍ يُوقِنُونَ﴾ زَائِدٌ عَلَى الْمَعْنَى لِمَدْحِ الْمُؤْمِنِينَ وَالتَّعْرِيضِ بِالذَّمِّ لِلْيَهُودِ وَأَنَّهُمْ بَعِيدُونَ عَنِ الْإِيقَانِ ﴿إِنَّهُ لَحَقٌّ مِثْلَ مَا أَنَّكُمْ تَنْطِقُونَ﴾ فَقَوْلُهُ \\\"مِثْلَ مَا\\\" إِلَى آخِرِهِ إِيغَالٌ زَائِدٌ عَلَى الْمَعْنَى لِتَحْقِيقِ هَذَا الْوَعْدِ وَأَنَّهُ وَاقِعٌ مَعْلُومٌ ضَرُورَةً لَا يَرْتَابُ فِيهِ أَحَدٌ\",[[27,80,4,10,2],[30,52,4,10,2],[5,50,3,9,1],[51,23,3,8,1]]],[56,\"التَّذْيِيلُ\",3,250,250,1014,\"لِتَأْكِيدِ مَنْطُوقِهِ أَوْ مَفْهُومِهِ لِيَظْهَرَ الْمَعْنَى لِمَنْ لَمْ يَفْهَمْهُ وَيَتَقَرَّرَ عِنْدَ مَنْ فَهِمَهُ نَحْوُ: ﴿ذَلِكَ جَزَيْنَاهُمْ بِمَا كَفَرُوا وَهَلْ نُجَازِي إِلاَّ الْكَفُورَ﴾ ﴿وَقُلْ جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ إِنَّ الْبَاطِلَ كَانَ زَهُوقًا﴾ ﴿وَمَا جَعَلْنَا لِبَشَرٍ مِنْ قَبْلِكَ الْخُلْدَ أَفَإِنْ مِتَّ فَهُمُ الْخَالِدُونَ﴾ ﴿كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ﴾ ﴿وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ﴾\",[[34,17,0,7,1],[17,81,0,8,1],[21,34,0,9,1],[21,35,0,3,1],[35,14,10,17,1]]],[56,\"الطَّرْدُ وَالْعَكْسُ\",3,251,251,1015,\"قَالَ الطِّيبِيُّ: وَهُوَ أَنْ يُؤْتَى بِكَلَامَيْنِ يُقَرِّرُ الْأَوَّلَ بِمَنْطُوقِهِ مَفْهُومَ الثاني وبالعكس كقوله: ﴿لِيَسْتَأْذِنْكُمُ الَّذِينَ مَلَكَتْ أَيْمَانُكُمْ وَالَّذِينَ لَمْ يَبْلُغُوا الْحُلُمَ مِنْكُمْ ثَلاثَ مَرَّاتٍ﴾ إِلَى قَوْلِهِ: ﴿لَيْسَ عَلَيْكُمْ وَلا عَلَيْهِمْ جُنَاحٌ بَعْدَهُنَّ﴾ فَمَنْطُوقُ الْأَمْرِ بِالِاسْتِئْذَانِ فِي تِلْكَ الْأَوْقَاتِ خَاصَّةً مُقَرِّرٌ لِمَفْهُومِ رَفْعِ الْجَنَاحِ فِيمَا عَدَاهَا وَبِالْعَكْسِ وَكَذَا قَوْلُهُ: ﴿لَا يَعْصُونَ اللَّهَ مَا أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ﴾ قُلْتُ وَهَذَا النَّوْعُ يُقَابِلُهُ فِي الْإِيجَازِ نَوْعُ الِاحْتِبَاكِ.\",[[24,58,3,13,1],[24,58,30,35,1],[66,6,14,21,1]]],[56,\"التَّكْمِيلُ\",3,251,252,1015,\"وَيُسَمَّى بِالِاحْتِرَاسِ وَهُوَ أَنْ يُؤْتَى فِي كَلَامٍ يُوهِمُ خِلَافَ الْمَقْصُودِ بِمَا يَدْفَعُ ذَلِكَ الْوَهْمَ نَحْوُ: ﴿أَذِلَّةٍ عَلَى الْمُؤْمِنِينَ أَعِزَّةٍ عَلَى الْكَافِرِينَ﴾ فَإِنَّهُ لَوِ اقْتَصَرَ عَلَى أَذِلَّةٍ لَتُوِهِّمَ أَنَّهُ لِضَعْفِهِمْ فَدَفَعَهُ بِقَوْلِهِ: \\\"أَعِزَّةٍ\\\" وَمِثْلُهُ: ﴿أَشِدَّاءُ عَلَى الْكُفَّارِ رُحَمَاءُ بَيْنَهُمْ﴾ لَوِ اقْتَصَرَ عَلَى\\\"أَشِدَّاءَ\\\" لَتُوِهِّمَ أَنَّهُ لِغِلَظِهِمْ ﴿تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ﴾ ﴿لَا يَحْطِمَنَّكُمْ سُلَيْمَانُ وَجُنُودُهُ وَهُمْ لَا يَشْعُرُونَ﴾ احْتِرَاسٌ لِئَلَّا يُتَوَهَّمَ نِسْبَةُ الظُّلْمِ إِلَى سُلَيْمَانَ، وَمِثْلُهُ: ﴿فَتُصِيبَكُمْ مِنْهُمْ مَعَرَّةٌ بِغَيْرِ عِلْمٍ﴾ وَكَذَا ﴿قَالُوا نَشْهَدُ إِنَّكَ لَرَسُولُ اللَّهِ وَاللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُ وَاللَّهُ يَشْهَدُ إِنَّ الْمُنَافِقِينَ لَكَاذِبُونَ﴾ فَالْجُمْلَةُ الْوُسْطَى احْتِرَاسٌ لِئَلَّا يُتَوَهَّمُ أَنَّ التَّكْذِيبَ مِمَّا فِي نَفْسِ الْأَمْرِ\",[[5,54,14,19,1],[48,29,5,9,1],[27,12,4,8,1],[27,18,12,18,1],[48,25,21,25,1],[63,1,3,16,1]]],[56,\"التَّتْمِيمُ\",3,252,252,1016,\"وَهُوَ أَنْ يُؤْتَى فِي كَلَامٍ لَا يُوهِمُ غَيْرَ الْمُرَادِ بِفَضْلِهِ تُفِيدُ نُكْتَةً كَالْمُبَالَغَةِ فِي قَوْلِهِ: ﴿وَيُطْعِمُونَ الطَّعَامَ عَلَى حُبِّهِ﴾ أَيْ مَعَ حُبِّ الطَّعَامِ أَيِ اشِتِهَائِهِ فَإِنَّ الْإِطْعَامَ حِينَئِذٍ أَبْلَغُ وَأَكْثَرُ أَجْرًا وَمِثْلُهُ: ﴿وَآتَى الْمَالَ عَلَى حُبِّهِ﴾ ﴿وَمَنْ يَعْمَلْ مِنَ الصَّالِحَاتِ وَهُوَ مُؤْمِنٌ فَلا يَخَافُ﴾ فَقَوْلُهُ: \\\"وهُوَ مُؤْمِنٌ\\\" تَتْمِيمٌ فِي غَايَةِ الْحُسْنِ.\",[[76,8,0,3,1],[2,177,18,21,1],[20,112,0,7,1]]],[56,\"الِاسْتِقْصَاءُ\",3,252,253,1016,\"وَهُوَ أَنْ يَتَنَاوَلَ الْمُتَكَلِّمُ معنى فيستقصيه فيأتي بجميع عَوَارِضَهُ وَلَوَازِمَهُ بَعْدَ أَنْ يَسْتَقْصِيَ جَمِيعَ أَوْصَافِهِ الذَّاتِيَّةِ بِحَيْثُ لَا يَتْرُكُ لِمَنْ يَتَنَاوَلُهُ بَعْدَهُ فِيهِ مَقَالًا كَقَوْلِهِ تَعَالَى: ﴿أَيَوَدُّ أَحَدُكُمْ أَنْ تَكُونَ لَهُ جَنَّةٌ﴾ الْآيَةَ فَإِنَّهُ تَعَالَى لَوِ اقْتَصَرَ عَلَى قَوْلِهِ \\\"جَنَّةٌ\\\" لَكَانَ كَافِيًا فَلَمْ يَقِفْ عِنْدَ ذَلِكَ حَتَّى قَالَ فِي تَفْسِيرِهَا: ﴿مِنْ نَخِيلٍ وَأَعْنَابٍ﴾ فَإِنَّ مُصَابَ صَاحِبِهَا بِهَا أَعْظَمُ ثُمَّ زاد ﴿جْرِي مِنْ تَحْتِهَا الأَنْهَارُ﴾ مُتَمِّمًا لِوَصْفِهَا بِذَلِكَ ثُمَّ كَمُلَ وَصْفُهَا بَعْدَ التَّتْمِيمَيْنِ فَقَالَ: ﴿لَهُ فِيهَا مِنْ كُلِّ الثَّمَرَاتِ﴾ فَأَتَى بِكُلِّ مَا يَكُونُ فِي الْجِنَانِ لِيَشْتَدَّ الْأَسَفُ عَلَى إِفْسَادِهَا ثُمَّ قَالَ فِي وَصْفِ صَاحِبِهَا: ﴿وَأَصَابَهُ الْكِبَرُ﴾ ثُمَّ اسْتَقْصَى الْمَعْنَى فِي ذَلِكَ بِمَا يُوجِبُ تَعْظِيمَ الْمُصَابِ بِقَوْلِهِ بَعْدَ وَصْفِهِ بِالْكِبَرِ ﴿وَلَهُ ذُرِّيَّةٌ﴾ وَلَمْ يَقِفْ عِنْدَ ذَلِكَ حَتَّى وَصَفَ الذُّرِّيَّةَ بالضعفاء ثُمَّ ذَكَرَ اسْتِئْصَالَ الْجَنَّةِ الَّتِي لَيْسَ لِهَذَا الْمُصَابِ غَيْرُهَا بِالْهَلَاكِ فِي أَسْرَعِ وَقْتٍ حَيْثُ قَالَ: ﴿فَأَصَابَهَا إِعْصَارٌ﴾ وَلَمْ يَقْتَصِرْ عَلَى ذِكْرِهِ لِلْعِلْمِ بِأَنَّهُ لَا يَحْصُلُ سُرْعَةُ الْهَلَاكِ فَقَالَ: ﴿فِيهِ نَارٌ﴾ ثُمَّ لَمْ يَقِفْ عِنْدَ ذَلِكَ حَتَّى أَخْبَرَ بِاحْتِرَاقِهَا لِاحْتِمَالِ أَنْ تَكُونَ النَّارُ ضَعِيفَةً لَا تَفِي بِاحْتِرَاقِهَا لِمَا فِيهَا مِنَ الْأَنْهَارِ وَرُطُوبَةِ الْأَشْجَارِ فَاحْتَرَسَ عَنْ هَذَا الِاحْتِمَالِ بِقَوْلِهِ: ﴿فَاحْتَرَقَتْ﴾ فَهَذَا أَحْسَنُ اسْتِقْصَاءٍ وَقَعَ فِي كَلَامٍ وَأَتَمَّهُ وَأَكْمَلَهُ\",[[2,266,0,8,1],[2,266,13,21,1],[2,266,23,27,1]]],[56,\"الِاعْتِرَاضُ\",3,253,254,1017,\"وَسَمَّاهُ قُدَامَةُ الْتِفَاتًا وَهُوَ الْإِتْيَانُ بِجُمْلَةٍ أَوْ أَكْثَرَ لَا مَحَلَّ لَهَا مِنَ الْإِعْرَابِ فِي أَثْنَاءِ كَلَامٍ أَوْ كَلَامَيْنِ اتَّصَلَا مَعْنًى لِنُكْتَةِ غَيْرِ دَفْعِ الْإِيهَامِ كَقَوْلِهِ: ﴿وَيَجْعَلُونَ لِلَّهِ الْبَنَاتِ سُبْحَانَهُ وَلَهُمْ مَا يَشْتَهُونَ﴾ فَقَوْلُهُ: ﴿سُبْحَانَهُ﴾ اعْتِرَاضٌ لِتَنْزِيهِ اللَّهِ ﷾ عَنِ الْبَنَاتِ وَالشَّنَاعَةِ عَلَى جَاعِلِيهَا وَقَوْلُهُ: ﴿لَتَدْخُلُنَّ الْمَسْجِدَ الْحَرَامَ إِنْ شَاءَ اللَّهُ آمِنِينَ﴾ فَجُمْلَةُ الِاسْتِثْنَاءِ اعْتِرَاضٌ لِلتَّبَرُّكِ\",[[16,57,0,6,1],[16,57,3,3,1],[48,27,6,12,1]]],[56,\"الِاعْتِرَاضُ\",3,254,254,1018,\"وَمِنْ وُقُوعِهِ بِأَكْثَرَ مِنْ جُمْلَةٍ ﴿فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اللَّهُ إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ نِسَاؤُكُمْ حَرْثٌ لَكُمْ﴾ فَقَوْلُهُ ﴿نِسَاؤُكُمْ﴾ مُتَّصِلٌ بِقَوْلِهِ: ﴿فَأْتُوهُنَّ﴾ لِأَنَّهُ بَيَانٌ لَهُ وَمَا بَيْنَهُمَا اعْتِرَاضٌ لِلْحَثِّ عَلَى الطَّهَارَةِ وَتَجَنُّبِ الأدبار وقوله: ﴿يَا أَرْضُ ابْلَعِي مَاءَكِ﴾ إِلَى قَوْلِهِ: ﴿وَقِيلَ بُعْدًا﴾ فِيهِ اعْتِرَاضٌ بِثَلَاثِ جُمَلٍ وَهِيَ: ﴿وَغِيضَ الْمَاءُ وَقُضِيَ الأَمْرُ وَاسْتَوَتْ عَلَى الْجُودِيِّ﴾ قَالَ فِي الْأَقْصَى الْقَرِيبِ وَنُكْتَتُهُ إِفَادَةُ أَنَّ هَذَا الْأَمْرَ وَاقِعٌ بَيْنِ الْقَوْلَيْنِ لَا مَحَالَةَ وَلَوْ أَتَى بِهِ آخِرًا لَكَانَ الظَّاهِرُ تَأَخُّرَهُ فَبِتَوَسُّطِهِ ظَهَرَ كَوْنُهُ غَيْرَ مُتَأَخِّرٍ ثُمَّ فِيهِ اعتراض في اعْتِرَاضٌ فَإِنَّ\\\"وَقُضِيَ الْأَمْرُ\\\"مُعْتَرِضٌ بَيْنَ\\\"وَغِيضَ\\\"وَ\\\"وَاسْتَوَتْ\\\"لِأَنَّ الِاسْتِوَاءَ يَحْصُلُ عَقِبَ الْغَيْضِ وَقَوْلُهُ: ﴿وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ﴾ إِلَى قَوْلِهِ: ﴿مُتَّكِئِينَ عَلَى فُرُشٍ﴾ فِيهِ اعْتِرَاضٌ بِسَبْعِ جُمَلٍ إِذَا أُعْرِبَ حَالًا مِنْهُ\",[[2,222,16,26,1],[2,223,0,2,1],[2,223,0,0,1],[2,222,16,16,1],[11,44,1,3,1],[11,44,13,14,1],[11,44,6,12,1],[55,46,0,4,1],[55,54,0,2,1]]],[56,\"الِاعْتِرَاضُ\",3,254,254,1018,\"وَمِنْ وُقُوعِ اعْتِرَاضٍ فِي اعْتِرَاضٍ: ﴿فَلا أُقْسِمُ بِمَوَاقِعِ النُّجُومِ وَإِنَّهُ لَقَسَمٌ لَوْ تَعْلَمُونَ عَظِيمٌ إِنَّهُ لَقُرْآنٌ كَرِيمٌ﴾ اعترض بَيْنَ الْقَسَمِ وَجَوَابِهِ بِقَوْلِهِ: ﴿وَإِنَّهُ لَقَسَمٌ﴾ الْآيَةَ وَبَيْنَ الْقَسَمِ وَصِفَتِهِ بِقَوْلِهِ: ﴿لَوْ تَعْلَمُونَ﴾ تَعْظِيمًا لِلْمُقْسَمِ بِهِ وَتَحْقِيقًا لِإِجْلَالِهِ وَإِعْلَامًا لَهُمْ بِأَنَّ لَهُ عَظَمَةً لَا يَعْلَمُونَهَا قَالَ الطِّيبِيُّ فِي التِّبْيَانِ وَوَجْهُ حُسْنِ الِاعْتِرَاضِ حُسْنُ الْإِفَادَةِ مَعَ أَنَّ مَجِيئَهُ مَجِيءُ مَا لَا يترقب فكون كَالْحَسَنَةِ تَأْتِيكَ مِنْ حَيْثُ لَا تَحْتَسِبُ.\",[[56,75,0,3,1],[56,76,0,4,1],[56,77,0,2,1],[56,76,0,3,1]]],[56,\"التَّعْلِيلُ\",3,255,255,1019,\"وَمِمَّا يَقْتَضِي التَّعْلِيلَ لَفْظُ\\\"الْحِكْمَةِ\\\"كَقَوْلِهِ: ﴿حِكْمَةٌ بَالِغَةٌ﴾ وَذِكْرُ الْغَايَةِ مِنَ الْخَلْقِ نَحْوُ قَوْلِهِ: ﴿جَعَلَ لَكُمُ الأَرْضَ فِرَاشًا وَالسَّمَاءَ بِنَاءً﴾ ﴿أَلَمْ نَجْعَلِ الْأَرْضَ مِهَادًا وَالْجِبَالَ أوتادا﴾ .\",[[54,5,0,1,1],[2,22,1,6,1],[78,6,0,3,1],[78,7,0,1,1]]],[57,\"\",3,258,258,1022,\"الْقَصْدُ بِالْخَبَرِ إِفَادَةُ الْمُخَاطَبِ وَقَدْ يَرِدُ بِمَعْنَى الْأَمْرِ نَحْوُ: ﴿وَالْوَالِدَاتُ يُرْضِعْنَ﴾ ﴿وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ ب﴾\",[[2,233,0,1,1]]],[57,\"\",3,258,258,1022,\"وَبِمَعْنَى النَّهْيِ نَحْوُ: ﴿لَا يَمَسُّهُ إِلاَّ الْمُطَهَّرُونَ﴾\",[[56,79,0,3,1]]],[57,\"\",3,258,258,1022,\"وَبِمَعْنَى الدُّعَاءِ نَحْوُ: ﴿وَإِيَّاكَ نَسْتَعِينُ﴾ أَيْ أَعِنَّا وَمِنْهُ: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ﴾ فَإِنَّهُ دُعَاءٌ عَلَيْهِ وَكَذَا ﴿غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا بِمَا قَالُوا﴾\",[[1,5,2,3,1],[111,1,0,4,1],[5,64,5,9,1]]],[57,\"\",3,258,258,1022,\"وَجَعَلَ مِنْهُ قَوْمٌ ﴿حَصِرَتْ صُدُورُهُمْ﴾ قَالُوا هُوَ دُعَاءٌ عَلَيْهِمْ بِضِيقِ صُدُورِهِمْ عَنْ قِتَالِ أَحَدٍ\",[[4,90,10,11,1]]],[57,\"\",3,258,259,1022,\"وَنَازَعَ ابْنُ الْعَرَبِيِّ فِي قَوْلِهِمْ: إِنَّ الْخَبَرَ يَرِدُ بِمَعْنَى الْأَمْرِ أَوِ النَّهْيِ قَالَ فِي قَوْلِهِ تَعَالَى: \\\"فلا\\\"رفث لَيْسَ نَفْيًا لِوُجُودِ الرَّفَثِ بَلْ نَفْيٌ لِمَشْرُوعِيَّتِهِ فَإِنَّ الرَّفَثَ يُوجَدُ مِنْ بَعْضِ النَّاسِ وَأَخْبَارُ اللَّهِ تَعَالَى لَا يَجُوزُ أَنْ تَقَعَ بِخِلَافِ مُخْبَرِهِ وَإِنَّمَا يَرْجِعُ النَّفْيُ إِلَى وُجُودِهِ مَشْرُوعًا لَا إِلَى وُجُودِهِ مَحْسُوسًا كَقَوْلِهِ: ﴿وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ﴾ وَمَعْنَاهُ مَشْرُوعًا لَا مَحْسُوسًا فَإِنَّا نَجِدُ مُطَلَّقَاتٍ لَا يَتَرَبَّصْنَ فَعَادَ النَّفْيُ إِلَى الْحُكْمِ الشَّرْعِيِّ لَا إِلَى الْوُجُودِ الْحِسِّيِّ وَكَذَا ﴿لَا يَمَسُّهُ إِلاَّ الْمُطَهَّرُونَ﴾ أَيْ لَا يَمَسُّهُ أَحَدٌ مِنْهُمْ شَرْعًا فَإِنْ وُجِدَ الْمَسُّ فَعَلَى خِلَافِ حُكْمِ الشَّرْعِ قَالَ وَهَذِهِ الدَّفِينَةُ الَّتِي فَاتَتِ الْعُلَمَاءَ فَقَالُوا: إِنَّ الْخَبَرَ يَكُونُ بِمَعْنَى النَّهْيِ وَمَا وُجِدَ ذَلِكَ قَطُّ وَلَا يَصِحُّ أَنْ يُوجِدَ فَإِنَّهُمَا مُخْتَلِفَانِ حَقِيقَةً وَيَتَبَايَنَانِ وَضْعًا انْتَهَى.\",[[2,228,0,1,1],[56,79,0,3,1]]],[57,\"\",3,259,259,1023,\"ثُمَّ قَدْ وَضَعُوا لِلتَّعَجُّبِ صِيَغًا مَنْ لَفْظِهِ وَهِيَ\\\"مَا أَفْعَلَ\\\"وَ\\\"أَفْعِلْ بِهِ\\\"وَصِيَغًا مِنْ غَيْرِ لَفْظِهِ نَحْوَ\\\"كَبُرَ\\\"كَقَوْلِهِ: ﴿كَبُرَتْ كَلِمَةً تَخْرُجُ مِنْ أَفْوَاهِهِمْ﴾ ﴿كَبُرَ مَقْتًا عِنْدَ اللَّهِ﴾ ﴿كيف تكفرون بالله﴾\",[[18,5,7,11,1],[40,35,8,11,2],[61,3,0,3,2],[2,28,0,2,1]]],[57,\"\",3,260,260,1024,\"قَالَ الْمُحَقِّقُونَ إِذَا وَرَدَ التَّعَجُّبُ مِنَ اللَّهِ صُرِفَ إِلَى الْمُخَاطَبِ كَقَوْلِهِ: ﴿فَمَا أَصْبَرَهُمْ عَلَى النَّارِ﴾ أَيْ هَؤُلَاءِ يَجِبُ أَنْ يُتَعَجَّبَ مِنْهُمْ وَإِنَّمَا لَا يُوصَفُ تَعَالَى بِالتَّعَجُّبِ لِأَنَّهُ اسْتِعْظَامٌ يَصْحَبُهُ الْجَهْلُ وَهُوَ تَعَالَى مُنَزَّهٌ عَنْ ذَلِكَ وَلِهَذَا تعبر جماعة بالتعجيب بَدَلَهُ: أَيْ أَنَّهُ تَعْجِيبٌ مِنَ اللَّهِ لِلْمُخَاطِبِينَ وَنَظِيرُ هَذَا مَجِيءُ الدُّعَاءِ وَالتَّرَجِّي مِنْهُ تَعَالَى إِنَّمَا هُوَ بِالنَّظَرِ إِلَى مَا تَفْهَمُهُ الْعَرَبُ أي هؤلاء مما يَجِبُ أَنْ يُقَالَ لَهُمْ: عِنْدَكُمْ هَذَا وَلِذَلِكَ قَالَ سِيبَوَيْهِ فِي قوله تعالى: ﴿لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى﴾ الْمَعْنَى: اذْهَبَا عَلَى رَجَائِكُمَا وَطَمَعِكُمَا وَفِي قَوْلِهِ: ﴿وَيْلٌ لِلْمُطَفِّفِينَ﴾ ﴿وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ﴾ لا: نقول هَذَا دُعَاءٌ لِأَنَّ الْكَلَامَ بِذَلِكَ قَبِيحٌ وَلَكِنَّ الْعَرَبَ إِنَّمَا تَكَلَّمُوا بِكَلَامِهِمْ وَجَاءَ الْقُرْآنُ عَلَى لُغَتِهِمْ وَعَلَى مَا يَعْنُونَ فَكَأَنَّهُ قِيلَ لَهُمْ: ﴿وَيْلٌ لِلْمُطَفِّفِينَ﴾ أَيْ هَؤُلَاءِ مما وجب هذا الْقَوْلُ لَهُمْ لِأَنَّ هَذَا الْكَلَامَ إِنَّمَا يُقَالُ لِصَاحِبِ الشُّرُورِ وَالْهَلَكَةِ فَقِيلَ هَؤُلَاءِ مِمَّنْ دَخَلَ فِي الْهَلَكَةِ.\",[[2,175,7,10,1],[83,1,0,1,1],[83,10,0,2,1],[83,1,0,1,1]]],[57,\"\",3,260,260,1024,\"مِنْ أَقْسَامِ الْخَبَرِ الْوَعْدُ وَالْوَعِيدُ نَحْوُ ﴿سَنُرِيهِمْ آيَاتِنَا فِي الآفَاقِ﴾ ﴿وَسَيَعْلَمُ الَّذِينَ ظَلَمُوا أَيَّ مُنْقَلَبٍ﴾ وَفِي كَلَامِ ابْنِ قُتَيْبَةَ مَا يُوهِمُ أَنَّهُ إِنْشَاءٌ\",[[41,53,0,3,1]]],[57,\"\",3,261,261,1025,\"مِثَالُ النَّفْيِ: ﴿مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ﴾\",[[33,40,0,6,1]]],[57,\"\",3,261,261,1025,\"وَمِثَالُ الْجَحْدِ نَفْيُ فِرْعَوْنَ وَقَوْمِهِ آيَاتِ مُوسَى قَالَ تَعَالَى: ﴿فَلَمَّا جَاءَتْهُمْ آيَاتُنَا مُبْصِرَةً قَالُوا هَذَا سِحْرٌ مُبِينٌ وَجَحَدُوا بِهَا وَاسْتَيْقَنَتْهَا أَنْفُسُهُمْ﴾\",[[27,13,0,7,1],[27,14,0,3,1]]],[57,\"\",3,262,262,1026,\"الْأَوَّلُ: زَعَمَ بَعْضُهُمْ أَنَّ شَرْطَ صِحَّةِ النَّفْيِ عَنِ الشيء صحة اتصاف الْمَنْفِيِّ عَنْهُ بِذَلِكَ الشَّيْءِ وَهُوَ مَرْدُودٌ بِقَوْلِهِ تَعَالَى: ﴿وَمَا رَبُّكَ بِغَافِلٍ عَمَّا يَعْمَلُونَ﴾ ﴿وَمَا كَانَ رَبُّكَ نَسِيًّا﴾ ﴿لَا تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ﴾ وَنَظَائِرُهُ وَالصَّوَابُ أَنَّ انْتِفَاءَ الشَّيْءِ عَنِ الشَّيْءِ قَدْ يَكُونُ لِكَوْنِهِ لَا يُمْكِنُ مِنْهُ عَقْلًا وَقَدْ يَكُونُ لِكَوْنِهِ لَا يَقَعُ مِنْهُ مَعَ إِمْكَانِهِ.\",[[6,132,4,8,1],[19,64,14,17,1],[2,255,7,11,1]]],[57,\"\",3,262,263,1026,\"الثَّانِي: نَفْيُ الذَّاتِ الْمَوْصُوفَةِ قَدْ يَكُونُ نَفْيًا لِلصِّفَةِ دُونَ الذَّاتِ وَقَدْ يَكُونُ نَفْيًا لِلذَّاتِ أَيْضًا مِنَ الْأَوَّلِ: ﴿وَمَا جَعَلْنَاهُمْ جَسَدًا لَا يَأْكُلُونَ الطَّعَامَ﴾ أَيْ بَلْ هُمْ جَسَدٌ يَأْكُلُونَهُ وَمِنَ الثَّانِي ﴿لَا يَسْأَلونَ النَّاسَ إِلْحَافًا﴾ أَيْ لَا سُؤَالَ لَهُمْ أَصْلًا فَلَا يَحْصُلُ مِنْهُمْ إِلْحَافٌ، ﴿مَا لِلظَّالِمِينَ مِنْ حَمِيمٍ وَلا شَفِيعٍ يُطَاعُ﴾ أَيْ لَا شَفِيعَ لَهُمْ أَصْلًا ﴿فَمَا تَنْفَعُهُمْ شَفَاعَةُ الشَّافِعِينَ﴾ أَيْ لَا شَافِعِينَ لَهُمْ فَتَنْفَعُهُمْ شَفَاعَتُهُمْ بِدَلِيلِ ﴿فَمَا لَنَا مِنْ شَافِعِينَ﴾ وَيُسَمَّى هَذَا النَّوْعُ عِنْدَ أَهْلِ الْبَدِيعِ نَفْيَ الشَّيْءِ بِإِيجَابِهِ وَعِبَارَةُ ابْنِ رَشِيقٍ فِي تَفْسِيرِهِ أَنْ يَكُونَ الْكَلَامُ ظَاهِرُهُ إِيجَابُ الشَّيْءِ وَبَاطِنُهُ نَفْيُهُ بِأَنْ يَنْفِيَ مَا هُوَ مِنْ سَبَبِهِ كَوَصْفِهِ وَهُوَ الْمَنْفِيُّ فِي الْبَاطِنِ وَعِبَارَةُ غَيْرِهِ أَنْ يُنْفَى الشَّيْءُ مُقَيَّدًا وَالْمُرَادُ نَفْيُهُ مُطْلَقًا مُبَالَغَةً فِي النَّفْيِ وَتَأْكِيدًا لَهُ وَمِنْهُ: ﴿وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لَا بُرْهَانَ لَهُ بِهِ﴾ فَإِنَّ \\\"الْإِلَهَ مَعَ اللَّهِ\\\"لَا يَكُونُ إِلَّا عَنْ غَيْرِ بُرْهَانٍ ﴿وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ حَقٍّ﴾ فَإِنَّ قَتْلَهُمْ لَا يَكُونُ إِلَّا بِغَيْرِ حَقٍّ ﴿رَفَعَ السَّمَاوَاتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا﴾ فَإِنَّهَا لَا عَمَدَ لَهَا أَصْلًا\",[[21,8,0,5,1],[2,273,18,21,1],[40,18,8,14,1],[74,48,0,3,1],[26,100,0,3,1],[23,117,0,9,1],[2,61,50,53,1],[13,2,2,6,1]]],[57,\"\",3,263,263,1027,\"الثَّالِثُ: قَدْ يُنْفَى الشَّيْءُ رَأْسًا لِعَدَمِ كَمَالِ وَصْفِهِ أَوِ انْتِفَاءِ ثَمَرَتِهِ كَقَوْلِهِ فِي صِفَةِ أَهْلِ النَّارِ: ﴿ثُمَّ لَا يَمُوتُ فِيهَا وَلا يَحْيَى﴾ فَنَفَى عَنْهُ الْمَوْتَ لِأَنَّهُ لَيْسَ بِمَوْتٍ صَرِيحٍ وَنَفَى عَنْهُ الْحَيَاةَ لِأَنَّهَا لَيْسَتْ بِحَيَاةٍ طَيِّبَةٍ وَلَا نَافِعَةٍ ﴿وَتَرَاهُمْ يَنْظُرُونَ إِلَيْكَ وَهُمْ لَا يُبْصِرُونَ﴾ فَإِنَّ الْمُعْتَزِلَةَ احْتَجُّوا بِهَا عَلَى نَفْيِ الرُّؤْيَةِ فَإِنَّ النَّظَرَ فِي قَوْلِهِ تَعَالَى: ﴿إِلَى رَبِّهَا نَاظِرَةٌ﴾ لَا يَسْتَلْزِمُ الْإِبْصَارَ وَرُدَّ بِأَنَّ الْمَعْنَى أَنَّهَا تَنْظُرُ إِلَيْهِ بِإِقْبَالِهَا عَلَيْهِ وَلَيْسَتْ تُبْصِرُ شَيْئًا ﴿وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ مَا لَهُ فِي الآخِرَةِ مِنْ خَلاقٍ وَلَبِئْسَ مَا شَرَوْا بِهِ أَنْفُسَهُمْ لَوْ كَانُوا يَعْلَمُونَ﴾ فَإِنَّهُ وَصَفَهُمْ أَوَّلًا بِالْعِلْمِ عَلَى سَبِيلِ التَّوْكِيدِ الْقَسَمِي ثُمَّ نَفَاهُ آخِرًا عَنْهُمْ لِعَدَمِ جَرْيِهِمْ عَلَى مُوجَبِ الْعِلْمِ قَالَهُ السَّكَّاكِيُّ.\",[[87,13,0,5,1],[7,198,6,11,1],[75,23,0,2,1],[2,102,56,73,1]]],[57,\"\",3,263,264,1027,\"الرَّابِعُ: قَالُوا: الْمَجَازُ يَصِحُّ نَفْيُهُ بِخِلَافِ الْحَقِيقَةِ وَأُشْكِلَ عَلَى ذَلِكَ ﴿وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَكِنَّ اللَّهَ رَمَى﴾ فإن المنفي فيه هو الْحَقِيقَةُ وَأُجِيبُ بِأَنَّ الْمُرَادَ بِالرَّمْيِ هُنَا الْمُتَرَتِّبُ عَلَيْهِ وَهُوَ وُصُولُهُ إِلَى الْكَفَّارِ فَالْوَارِدُ عَلَيْهِ النَّفْيُ هُنَا مَجَازٌ لَا حَقِيقَةٌ وَالتَّقْدِيرُ وَمَا رَمَيْتَ خَلْقًا إِذْ رَمَيْتَ كَسْبًا أَوْ مَا رَمَيْتَ انْتِهَاءً إِذْ رَمَيْتَ ابْتِدَاءً\",[[8,17,5,11,1]]],[57,\"\",3,264,264,1028,\"مِنَ الْأَوَّلِ: ﴿فَلا يَسْتَطِيعُونَ تَوْصِيَةً﴾ ﴿فَلا يَسْتَطِيعُونَ رَدَّهَا﴾ ﴿فَمَا اسْطَاعُوا أَنْ يَظْهَرُوهُ وَمَا اسْتَطَاعُوا لَهُ نَقْبًا﴾\",[[36,50,0,2,1],[21,40,4,6,1],[18,97,0,7,1]]],[57,\"\",3,264,264,1028,\"وَمِنَ الثَّانِي: ﴿هَلْ يَسْتَطِيعُ رَبُّكَ﴾ عَلَى الْقِرَاءَتَيْنِ أَيْ هَلْ يَفْعَلُ أَوْ هَلْ تُجِيبُنَا إِلَى أَنْ تَسْأَلَ فَقَدْ عَلِمُوا أَنَّهُ قَادِرٌ عَلَى الْإِنْزَالِ وَأَنَّ عِيسَى قَادِرٌ عَلَى السُّؤَالِ\",[[5,112,6,8,1]]],[57,\"\",3,264,264,1028,\"وَمِنَ الثَّالِثِ ﴿إِنَّكَ لَنْ تَسْتَطِيعَ مَعِيَ صَبْرًا﴾\",[[18,67,1,5,3],[18,72,3,7,3],[18,75,4,8,3]]],[57,\"\",3,264,265,1028,\"نَفْيُ الْعَامِّ يَدُلُّ عَلَى نَفْيِ الْخَاصِّ وَثُبُوتُهُ لَا يَدُلُّ عَلَى ثُبُوتِهِ وَثُبُوتُ الْخَاصِّ يَدُلُّ عَلَى ثُبُوتِ الْعَامِّ وَنَفْيُهُ لَا يَدُلُّ عَلَى نَفْيِهِ وَلَا شَكَّ أَنَّ زِيَادَةَ الْمَفْهُومِ مِنَ اللَّفْظِ تُوجِبُ الِالْتِذَاذَ بِهِ فَلِذَلِكَ كَانَ نَفْيُ الْعَامِّ أَحْسَنَ مِنْ نَفْيِ الْخَاصِّ وَإِثْبَاتُ الْخَاصِّ أَحْسَنَ مِنْ إِثْبَاتِ الْعَامِّ فَالْأَوَّلُ كَقَوْلِهِ: ﴿فَلَمَّا أَضَاءَتْ مَا حَوْلَهُ ذَهَبَ اللَّهُ بِنُورِهِمْ﴾ لَمْ يَقُلْ: بِضَوْئِهِمْ بَعْدَ قَوْلِهِ: ﴿أَضَاءَتْ﴾ لِأَنَّ النُّورَ أَعَمُّ مِنَ الضَّوْءِ إِذْ يُقَالُ عَلَى الْقَلِيلِ وَالْكَثِيرِ وَإِنَّمَا يُقَالُ الضَّوْءُ عَلَى النُّورِ الْكَثِيرِ وَلِذَلِكَ قَالَ: ﴿هُوَ الَّذِي جَعَلَ الشَّمْسَ ضِيَاءً وَالْقَمَرَ نُورًا﴾ فَفِي الضَّوْءِ دَلَالَةٌ عَلَى النُّورِ فَهُوَ أَخَصُّ مِنْهُ فَعَدَمُهُ يُوجِبُ عَدَمَ الضَّوْءِ بِخِلَافِ الْعَكْسِ وَالْقَصْدُ إِزَالَةُ النُّورِ عَنْهُمْ أَصْلًا وَلِذَا قَالَ عَقِبَهُ: ﴿وَتَرَكَهُمْ فِي ظُلُمَاتٍ﴾\",[[2,17,5,14,1],[10,5,0,6,1]]],[57,\"\",3,265,265,1029,\"وَمِنْهُ: ﴿لَيْسَ بِي ضَلالةٌ﴾ وَلَمْ يَقُلْ\\\"ضَلَالٌ\\\"كَمَا قَالُوا: ﴿إِنَّا لَنَرَاكَ فِي ضَلالٍ﴾ لِأَنَّهَا أَعَمُّ مِنْهُ فَكَانَ أَبْلَغَ فِي نَفْيِ الضَّلَالِ وَعُبِّرَ عَنْ هَذَا بِأَنَّ نَفْيَ الْوَاحِدِ يَلْزَمُ مِنْهُ نَفْيُ الْجِنْسِ الْبَتَّةَ وَبِأَنَّ نَفْيَ الْأَدْنَى يَلْزَمُ مِنْهُ نَفْيُ الْأَعْلَى\",[[7,61,2,4,1],[7,60,4,7,1]]],[57,\"\",3,265,265,1029,\"وَالثَّانِي كَقَوْلِهِ: ﴿وَجَنَّةٍ عَرْضُهَا السَّمَاوَاتُ وَالأَرْضُ﴾ وَلَمْ يَقُلْ: \\\"طُولُهَا\\\"لِأَنَّ الْعَرْضَ أَخَصُّ إِذْ كَلُّ مَا لَهُ عَرْضٌ فَلَهُ طُولٌ وَلَا يَنْعَكِسُ وَنَظِيرُ هَذِهِ الْقَاعِدَةِ أَنَّ نَفْيَ الْمُبَالَغَةِ فِي الْفِعْلِ لَا يَسْتَلْزِمُ نَفْيَ أَصْلِ الْفِعْلِ وَقَدْ أُشْكِلَ عَلَى هَذَا آيَتَانِ قَوْلُهُ تَعَالَى: ﴿وَمَا رَبُّكَ بِظَلَّامٍ لِلْعَبِيدِ﴾ وَقَوْلُهُ: ﴿وَمَا كَانَ رَبُّكَ نَسِيًّا﴾\",[[3,133,5,8,1],[41,46,7,10,1],[19,64,14,17,1]]],[57,\"\",3,266,267,1030,\"قَالَ صَاحِبُ الْيَاقُوتَةِ قَالَ ثَعْلَبٌ وَالْمُبَرِّدُ الْعَرَبُ إِذَا جَاءَتْ بَيْنَ الْكَلَامَيْنِ بِجَحْدَيْنِ كَانَ الْكَلَامُ إِخْبَارًا نَحْوُ: ﴿وَمَا جَعَلْنَاهُمْ جَسَدًا لا يَأْكُلُونَ الطَّعَامَ﴾ وَالْمَعْنَى إِنَّمَا جَعَلْنَاهُمْ جَسَدًا يَأْكُلُونَ الطَّعَامَ وَإِذَا كَانَ الْجَحْدُ فِي أَوَّلِ الْكَلَامٍ كَانَ جَحْدًا حَقِيقِيًّا نَحْوُ: \\\"مَا زَيْدٌ بِخَارِجٍ\\\"وَإِذَا كَانَ فِي أَوَّلِ الْكَلَامِ جَحْدَانِ كَانَ أَحَدُهُمَا زَائِدًا وَعَلَيْهِ ﴿فِيمَا إِنْ مَكَّنَّاكُمْ فِيهِ﴾ فِي أَحَدِ الْأَقْوَالِ.\",[[21,8,0,5,1],[46,26,2,5,1]]],[57,\"\",3,268,268,1032,\"الْأَوَّلُ: الْإِنْكَارُ وَالْمَعْنَى فِيهِ عَلَى النَّفْيِ وَمَا بَعْدَهُ مَنْفِيٌّ وَلِذَلِكَ تَصْحَبُهُ\\\"إِلَّا\\\"كَقَوْلِهِ: ﴿فَهَلْ يُهْلَكُ إِلاَّ الْقَوْمُ الْفَاسِقُونَ﴾ ﴿وَهَلْ نُجَازِي إِلاَّ الْكَفُورَ﴾ وعطف عليه الْمَنْفِيِّ فِي قَوْلِهِ: ﴿فَمَنْ يَهْدِي مَنْ أَضَلَّ اللَّهُ وَمَا لَهُمْ مِنْ نَاصِرِينَ﴾ أَيْ لَا يَهْدِي وَمِنْهُ: ﴿أَنُؤْمِنُ لَكَ وَاتَّبَعَكَ الأَرْذَلُونَ﴾ ﴿أَنُؤْمِنُ لِبَشَرَيْنِ مِثْلِنَا﴾ أَيْ لَا نُؤْمِنُ ﴿أَمْ لَهُ الْبَنَاتُ وَلَكُمُ الْبَنُونَ﴾ ﴿أَلَكُمُ الذَّكَرُ وَلَهُ الأُنْثَى﴾ أَيْ لَا يَكُونُ هَذَا ﴿أَشَهِدُوا خَلْقَهُمْ﴾ أَيْ مَا شَهِدُوا ذَلِكَ\",[[46,35,22,26,1],[34,17,4,7,1],[30,29,7,15,1],[26,111,1,4,1],[23,47,1,3,1],[52,39,0,4,1],[53,21,0,3,1],[43,19,7,8,1]]],[57,\"\",3,268,269,1032,\"وَكَثِيرًا مَا يَصْحَبُهُ التَّكْذِيبُ وَهُوَ فِي الْمَاضِي بِمَعْنَى\\\"لَمْ يَكُنْ\\\"وَفِي المستقبل بمعنى\\\"لايكون\\\"نحو: ﴿أَفَأَصْفَاكُمْ رَبُّكُمْ بِالْبَنِينَ﴾ الآية أَيْ لَمْ يَفْعَلْ ذَلِكَ ﴿أَنُلْزِمُكُمُوهَا وَأَنْتُمْ لَهَا كَارِهُونَ﴾ أَيْ لَا يَكُونُ هَذَا الْإِلْزَامِ الثَّانِي: التَّوْبِيخُ وَجَعَلَهُ بَعْضُهُمْ مِنْ قَبِيلِ الْإِنْكَارِ إِلَّا أَنَّ الْأَوَّلَ إِنْكَارُ إِبْطَالٍ وَهَذَا إِنْكَارُ تَوْبِيخٍ وَالْمَعْنَى عَلَى أَنَّ مَا بَعْدَهُ وَاقِعٌ جَدِيرٌ بِأَنْ يُنْفَى فَالنَّفْيُ هُنَا غَيْرُ قَصْدِيٍّ وَالْإِثْبَاتُ قَصْدِيٌّ عَكْسُ مَا تَقَدَّمَ وَيُعَبَّرُ عَنْ ذَلِكَ بالتقريع أيضا نحو: ﴿أَلاَّ تَتَّبِعَنِ أَفَعَصَيْتَ أَمْرِي﴾ ﴿قَالَ أَتَعْبُدُونَ مَا تَنْحِتُونَ﴾ ﴿أَتَدْعُونَ بَعْلًا وَتَذَرُونَ أَحْسَنَ الْخَالِقِينَ﴾\",[[17,40,0,2,1],[11,28,15,18,1],[20,93,0,3,1],[37,95,0,3,1],[37,125,0,4,1]]],[57,\"\",3,269,269,1033,\"وَأَكْثَرُ مَا يَقَعُ التَّوْبِيخُ فِي أَمْرٍ ثَابِتٍ وَوُبِّخَ عَلَى فِعْلِهِ كَمَا ذُكِرَ وَيَقَعُ عَلَى تَرْكِ فِعْلٍ كَانَ يَنْبَغِي أَنْ يَقَعَ كَقَوْلِهِ: ﴿أَوَلَمْ نُعَمِّرْكُمْ﴾ ﴿مَا يَتَذَكَّرُ فِيهِ مَنْ تَذَكَّرَ﴾ ﴿أَلَمْ تَكُنْ أَرْضُ اللَّهِ وَاسِعَةً فَتُهَاجِرُوا فِيهَا﴾\",[[35,37,11,17,1],[4,97,15,21,1]]],[57,\"\",3,269,269,1033,\"وَنَقَلَ أَبُو حَيَّانَ عَنْ سِيبَوَيْهِ أَنَّ اسْتِفْهَامَ التقرير لا يكون بهل إِنَّمَا يُسْتَعْمَلُ فِيهِ الْهَمْزَةُ ثُمَّ نُقِلَ عَنْ بَعْضِهِمْ أَنَّ هَلْ تَأْتِي تَقْرِيرًا كَمَا فِي قَوْلِهِ تَعَالَى: ﴿هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ﴾\",[[89,5,0,5,1]]],[57,\"\",3,269,270,1033,\"وَالْكَلَامُ مَعَ التَّقْرِيرِ مُوجِبٌ وَلِذَلِكَ يُعْطَفُ عَلَيْهِ صَرِيحُ الْمُوجِبِ وَيُعْطَفُ عَلَى صَرِيحِ الْمُوجِبِ فَالْأَوَّلُ كَقَوْلِهِ تَعَالَى: ﴿أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ وَوَضَعْنَا عَنْكَ وِزْرَكَ﴾ ﴿أَلَمْ يَجِدْكَ يَتِيمًا فَآوَى وَوَجَدَكَ﴾ ﴿أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ وَأَرْسَلَ﴾ وَالثَّانِي نَحْوُ: ﴿أَكَذَّبْتُمْ بِآياتِي وَلَمْ تُحِيطُوا بِهَا عِلْمًا﴾ عَلَى مَا قَرَّرَهُ الْجُرْجَانِيُّ مِنْ جَعْلِهَا مِثْلَ ﴿وَجَحَدُوا بِهَا وَاسْتَيْقَنَتْهَا أَنْفُسُهُمْ ظُلْمًا وَعُلُوًّا﴾\",[[94,1,0,3,1],[94,2,0,2,1],[93,6,0,3,1],[93,7,0,0,1],[105,2,0,4,1],[105,3,0,0,1],[27,84,4,9,1],[27,14,0,5,1]]],[57,\"\",3,270,270,1034,\"وَحَقِيقَةُ اسْتِفْهَامِ التَّقْرِيرِ أَنَّهُ اسْتِفْهَامُ إِنْكَارٍ وَالْإِنْكَارُ نَفْيٌ وَقَدْ دَخَلَ عَلَى النَّفْيِ وَنَفْيُ النَّفْيِ إِثْبَاتٌ وَمِنْ أَمْثِلَتِهِ: ﴿أَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُ﴾ ﴿أَلَسْتُ بِرَبِّكُمْ﴾ وَجَعَلَ مِنْهُ الزَّمَخْشَرِيُّ ﴿أَلَمْ تَعْلَمْ أَنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾\",[[39,36,0,3,1],[7,172,12,13,1],[2,106,11,18,1]]],[57,\"\",3,270,270,1034,\"الرَّابِعُ: التَّعَجُّبُ أَوِ التَّعْجِيبُ نَحْوُ: ﴿كَيْفَ تَكْفُرُونَ بِاللَّهِ﴾ ﴿مَا لِيَ لَا أَرَى الْهُدْهُدَ﴾ وَقَدِ اجْتَمَعَ هَذَا الْقِسْمُ وَسَابِقَاهُ فِي قَوْلِهِ: ﴿أَتَأْمُرُونَ النَّاسَ بِالْبِرِّ﴾\",[[2,28,0,2,1],[2,44,0,2,1]]],[57,\"\",3,270,270,1034,\"قَالَ الزَّمَخْشَرِيُّ: الْهَمْزَةُ لِلتَّقْرِيرِ مَعَ التَّوْبِيخِ وَالتَّعَجُّبِ مِنْ حَالِهِمْ وَيُحْتَمَلُ التَّعَجُّبُ وَالِاسْتِفْهَامُ الْحَقِيقِيُّ ﴿مَا وَلاَّهُمْ عَنْ قِبْلَتِهِمُ﴾\",[[2,142,4,7,1]]],[57,\"\",3,270,270,1034,\"الْخَامِسُ: الْعِتَابُ كَقَوْلِهِ: ﴿أَلَمْ يَأْنِ لِلَّذِينَ آمَنُوا أَنْ تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ اللَّهِ﴾ قَالَ ابْنُ مَسْعُودٍ: مَا كَانَ بَيْنَ إِسْلَامِهِمْ وَبَيْنَ أَنْ عُوتِبُوا بِهَذِهِ الْآيَةِ إِلَّا أَرْبَعُ سِنِينَ أَخْرَجَهُ الْحَاكِمُ وَمِنَ أَلْطَفِهِ مَا عَاتَبَ اللَّهُ بِهِ خَيْرَ خَلْقِهِ بِقَوْلِهِ: ﴿عَفَا اللَّهُ عَنْكَ لِمَ أَذِنْتَ لَهُمْ﴾ وَلَمْ يَتَأَدَّبِ الزَّمَخْشَرِيُّ بِأَدَبِ اللَّهِ فِي هَذِهِ الْآيَةِ عَلَى عَادَتِهِ فِي سُوءِ الْأَدَبِ\",[[57,16,0,8,1],[9,43,0,5,1]]],[57,\"\",3,270,271,1034,\"السَّادِسُ: التَّذْكِيرُ وَفِيهِ نَوْعُ اخْتِصَارٍ كَقَوْلِهِ: ﴿أَلَمْ أَعْهَدْ إِلَيْكُمْ يَا بَنِي آدَمَ أَنْ لا تَعْبُدُوا الشَّيْطَانَ﴾ ﴿أَلَمْ أَقُلْ لَكُمْ إِنِّي أَعْلَمُ غَيْبَ السَّمَاوَاتِ وَالأَرْضِ﴾ ﴿قَالَ هَلْ عَلِمْتُمْ مَا فَعَلْتُمْ بِيُوسُفَ وَأَخِيهِ﴾\",[[36,60,0,8,1],[2,33,8,15,1],[12,89,0,6,1]]],[57,\"\",3,271,271,1035,\"السَّابِعُ: الِافْتِخَارُ نَحْوُ: ﴿أَلَيْسَ لِي مُلْكُ مِصْرَ﴾\",[[43,51,6,9,1]]],[57,\"\",3,271,271,1035,\"الثَّامِنُ: التَّفْخِيمُ نَحْوُ: ﴿مَالِ هَذَا الْكِتَابِ لَا يُغَادِرُ صَغِيرَةً وَلا كَبِيرَةً﴾\",[[18,49,9,16,1]]],[57,\"\",3,271,271,1035,\"التَّاسِعُ: التَّهْوِيلُ وَالتَّخْوِيفُ نَحْوُ: ﴿الْحَاقَّةُ مَا الْحَاقَّة﴾ ﴿الْقَارِعَةُ مَا الْقَارِعَةُ﴾\",[[69,1,0,0,1],[69,2,0,1,1],[101,1,0,0,1],[101,2,0,1,1]]],[57,\"\",3,271,271,1035,\"الْعَاشِرُ: عَكْسُهُ وَهُوَ التَّسْهِيلُ وَالتَّخْفِيفُ نَحْوُ: ﴿وَمَاذَا عَلَيْهِمْ لَوْ آمَنُوا﴾\",[[4,39,0,3,1]]],[57,\"\",3,271,271,1035,\"الْحَادِي عَشَرَ: التَّهْدِيدُ وَالْوَعِيدُ نَحْوُ: ﴿أَلَمْ نُهْلِكِ الأَوَّلِينَ﴾\",[[77,16,0,2,1]]],[57,\"\",3,271,271,1035,\"الثَّانِي عَشَرَ: التَّكْثِيرُ نَحْوُ: ﴿وَكَمْ مِنْ قَرْيَةٍ أَهْلَكْنَاهَا﴾\",[[7,4,0,3,1]]],[57,\"\",3,271,271,1035,\"الثَّالِثَ عَشَرَ: التَّسْوِيَةُ وَهُوَ الِاسْتِفْهَامُ الدَّاخِلُ عَلَى جُمْلَةٍ يَصِحُّ حُلُولُ الْمَصْدَرِ مَحَلَّهَا نَحْوُ: ﴿سَوَاءٌ عَلَيْهِمْ أَأَنْذَرْتَهُمْ أَمْ لَمْ تُنْذِرْهُمْ﴾\",[[2,6,3,8,2],[36,10,0,5,2]]],[57,\"\",3,271,271,1035,\"الرَّابِعَ عَشَرَ: الْأَمْرُ نَحْوُ: ﴿أَأَسْلَمْتُمْ﴾ أَيْ أَسْلَمُوا ﴿فَهَلْ أَنْتُمْ مُنْتَهُونَ﴾ أي انتهوا ﴿أَتَصْبِرُونَ﴾ أَيْ اصْبِرُوا\",[[2,233,52,52,2],[3,20,13,13,2],[5,91,17,19,1],[25,20,16,16,1]]],[57,\"\",3,271,272,1035,\"الْخَامِسَ عَشَرَ: التَّنْبِيهُ وَهُوَ مِنْ أَقْسَامِ الْأَمْرِ نَحْوُ: ﴿أَلَمْ تَرَ إِلَى رَبِّكَ كَيْفَ مَدَّ الظِّلَّ﴾ أَيِ انِظُرْ ﴿أَلَمْ تَرَ أَنَّ اللَّهَ أَنْزَلَ مِنَ السَّمَاءِ مَاءً فَتُصْبِحُ الأَرْضُ مُخْضَرَّةً﴾ ذكره صاحب الكشاف عن سيبوبه وَلِذَلِكَ رَفَعَ الْفِعْلَ فِي جَوَابِهِ وَجَعَلَ مِنْهُ قَوْلُهُ: ﴿فَأَيْنَ تَذْهَبُونَ﴾ لِلتَّنْبِيهِ عَلَى الضَّلَالِ وَكَذَا ﴿وَمَنْ يَرْغَبُ عَنْ مِلَّةِ إِبْرَاهِيمَ إِلاَّ مَنْ سَفِهَ نَفْسَهُ﴾\",[[25,45,0,6,1],[22,63,0,10,1],[81,26,0,1,1],[2,130,0,8,1]]],[57,\"\",3,272,272,1036,\"السَّادِسَ عَشَرَ: التَّرْغِيبُ نَحْوُ: ﴿مَنْ ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا﴾ هَلْ أَدُلُّكُمْ عَلَى تِجَارَةٍ تُنْجِيكُمْ\",[[2,245,0,6,2],[57,11,0,6,2]]],[57,\"\",3,272,272,1036,\"السابع عشر: النهي نحو: ﴿تَخْشَوْنَهُمْ فَاللَّهُ أَحَقُّ أَنْ تَخْشَوْهُ﴾ بِدَلِيلِ ﴿فَلا تَخْشَوُا النَّاسَ وَاخْشَوْنِ﴾ ﴿مَا غَرَّكَ بِرَبِّكَ الْكَرِيمِ﴾ أَيْ لَا تَغْتَرَّ\",[[9,13,12,16,1],[5,44,23,26,1],[82,6,2,5,1]]],[57,\"\",3,272,272,1036,\"الثَّامِنَ عَشَرَ: الدُّعَاءُ وَهُوَ كَالنَّهْيِ إِلَّا أَنَّهُ مِنَ الْأَدْنَى إِلَى الْأَعْلَى نَحْوُ: ﴿أَتُهْلِكُنَا بِمَا فَعَلَ السُّفَهَاءُ﴾ أَيْ لَا تُهْلِكْنَا\",[[7,155,17,20,1]]],[57,\"\",3,272,272,1036,\"التَّاسِعَ عَشَرَ: الِاسْتِرْشَادُ نَحْوُ: ﴿تَجْعَلُ فِيهَا مَنْ يُفْسِدُ فِيهَا﴾\",[[2,30,10,14,1]]],[57,\"\",3,272,272,1036,\"الْعِشْرُونَ: التَّمَنِّي نَحْوُ: ﴿فَهَلْ لَنَا مِنْ شُفَعَاءَ﴾\",[[7,53,17,20,1]]],[57,\"\",3,272,272,1036,\"الْحَادِي وَالْعِشْرُونَ: الِاسْتِبْطَاءُ نَحْوُ: ﴿مَتَى نَصْرُ اللَّهِ﴾\",[[2,214,22,24,1]]],[57,\"\",3,272,273,1036,\"الثاني والعشرون: العرض نحو ﴿أَلا تُحِبُّونَ أَنْ يَغْفِرَ اللَّهُ لَكُمْ﴾ الثَّالِثُ وَالْعِشْرُونَ: التَّحْضِيضُ نَحْوُ: ﴿أَلا تُقَاتِلُونَ قَوْمًا نَكَثُوا أَيْمَانَهُمْ﴾\",[[24,22,17,22,1],[9,13,0,4,1]]],[57,\"\",3,273,273,1037,\"الرابع والعشرون: التجاهل نحو: ﴿أَأُنْزِلَ عَلَيْهِ الذِّكْرُ مِنْ بَيْنِنَا﴾\",[[38,8,0,4,1]]],[57,\"\",3,273,273,1037,\"الْخَامِسُ وَالْعِشْرُونَ: التَّعْظِيمُ نَحْوُ: ﴿مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ﴾\",[[2,255,19,25,1]]],[57,\"\",3,273,273,1037,\"السَّادِسُ وَالْعِشْرُونَ: التَّحْقِيرُ نَحْوُ: ﴿أَهَذَا الَّذِي يَذْكُرُ آلِهَتَكُمْ﴾ ﴿أَهَذَا الَّذِي بَعَثَ اللَّهُ رَسُولًا﴾ وَيَحْتَمِلُهُ وَمَا قَبْلَهُ قِرَاءَةُ ﴿مِنْ فِرْعَوْنَ﴾\",[[21,36,8,11,1],[25,41,6,10,1],[10,83,9,10,3],[44,31,0,1,3],[66,11,17,18,3]]],[57,\"\",3,273,273,1037,\"السَّابِعُ وَالْعِشْرُونَ: الِاكْتِفَاءُ نَحْوُ: ﴿أَلَيْسَ فِي جَهَنَّمَ مَثْوىً لِلْمُتَكَبِّرِينَ﴾\",[[39,60,9,13,1]]],[57,\"\",3,273,273,1037,\"الثَّامِنُ وَالْعِشْرُونَ: الِاسْتِبْعَادُ نَحْوُ: ﴿وَأَنَّى لَهُ الذِّكْرَى﴾\",[[89,23,6,8,1]]],[57,\"\",3,273,273,1037,\"التَّاسِعُ وَالْعِشْرُونَ: الْإِينَاسُ نَحْوُ: ﴿وَمَا تِلْكَ بِيَمِينِكَ يَا مُوسَى﴾\",[[20,17,0,3,1]]],[57,\"\",3,273,273,1037,\"الثَّلَاثُونَ: التَّهَكُّمُ وَالِاسْتِهْزَاءُ نَحْوُ: ﴿أَصَلاتُكَ تَأْمُرُكَ﴾ ﴿أَلا تَأْكُلُونَ مَا لَكُمْ لَا تَنْطِقُونَ﴾\",[[11,87,2,3,1],[37,91,4,5,1],[37,92,0,3,1]]],[57,\"\",3,273,274,1037,\"الْحَادِي وَالثَّلَاثُونَ: التَّأْكِيدُ لِمَا سَبَقَ مِنْ مَعْنَى أَدَاةِ الِاسْتِفْهَامِ قَبْلَهُ كَقَوْلِهِ: ﴿أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ الْعَذَابِ أَفَأَنْتَ تُنْقِذُ مَنْ فِي النَّارِ﴾ قَالَ الْمُوَفَّقُ عَبْدُ اللَّطِيفِ الْبَغْدَادِيُّ: أَيْ مَنْ حَقَّ عَلَيْهِ كَلِمَةُ الْعَذَابِ فَإِنَّكَ لَا تُنْقِذُهُ فَمَنْ لِلشَّرْطِ وَالْفَاءُ جَوَابُ الشَّرْطِ وَالْهَمْزَةُ فِي ﴿أَفَأَنْتَ﴾ دَخَلَتْ مُعَادَةً مُؤَكِّدَةً لِطُولِ الْكَلَامِ وَهَذَا نَوْعٌ مِنْ أَنْوَاعِهَا\",[[39,19,0,9,1],[39,19,5,5,1]]],[57,\"\",3,274,274,1038,\"الثَّانِي وَالثَّلَاثُونَ: الْإِخْبَارُ نَحْوُ: ﴿أَفِي قُلُوبِهِمْ مَرَضٌ أَمِ ارْتَابُوا﴾ ﴿هَلْ أَتَى عَلَى الأِنْسَانِ﴾\",[[24,50,0,4,1],[76,1,0,3,1]]],[57,\"\",3,275,275,1039,\"الثَّانِي الْقَاعِدَةُ أَنَّ الْمُنْكَرَ يَجِبُ أَنْ يَلِيَ الْهَمْزَةَ وَأُشْكِلَ عَلَيْهَا قَوْلُهُ تَعَالَى: ﴿أَفَأَصْفَاكُمْ رَبُّكُمْ بِالْبَنِينَ﴾ فإن الذين يَلِيهَا هُنَا الْإِصْفَاءُ بِالْبَنِينَ وَلَيْسَ هُوَ الْمُنْكَرُ إِنَّمَا الْمُنْكَرُ قَوْلُهُمْ: إِنَّهُ اتَّخَذَ مِنَ الْمَلَائِكَةِ إِنَاثًا\",[[17,40,0,2,1]]],[57,\"\",3,275,276,1039,\"وَأُشْكِلَ مِنْهُ قَوْلَهُ: ﴿أَتَأْمُرُونَ النَّاسَ بِالْبِرِّ وَتَنْسَوْنَ أَنْفُسَكُمْ﴾ وَوَجْهُ الْإِشْكَالِ أَنَّهُ لَا جَائِزَ أَنْ يَكُونَ الْمُنْكَرُ أَمْرَ النَّاسِ بِالْبَرِّ فَقَطْ كَمَا تَقْتَضِيهِ الْقَاعِدَةُ الْمَذْكُورَةُ لِأَنَّ أَمْرَ الْبَرِّ لَيْسَ مِمَّا يُنْكَرُ وَلَا نِسْيَانَ النَّفْسِ فَقَطْ لِأَنَّهُ يَصِيرُ ذِكْرُ أَمْرِ النَّاسِ بِالْبَرِّ لَا مَدْخَلَ لَهُ وَلَا مَجْمُوعَ الْأَمْرَيْنِ لِأَنَّهُ يَلْزَمُ أَنْ تَكُونَ الْعِبَادَةُ جُزْءَ الْمُنْكَرِ وَلَا نِسْيَانَ النَّفْسِ بِشَرْطِ الْأَمْرِ لِأَنَّ النِّسْيَانَ مُنْكَرٌ مُطْلَقًا وَلَا يَكُونُ نِسْيَانُ النَّفْسِ حَالَ الْأَمْرِ أَشَدَّ مِنْهُ حَالَ عَدَمِ الْأَمْرِ لِأَنَّ الْمَعْصِيَةَ لَا تَزْدَادُ بَشَاعَتُهَا بِانْضِمَامِهَا إِلَى الطَّاعَةِ لِأَنَّ جُمْهُورَ الْعُلَمَاءِ عَلَى أَنَّ الْأَمْرَ بِالْبِرِّ وَاجِبٌ وَإِنْ كَانَ الْإِنْسَانُ نَاسِيًا لِنَفْسِهِ وَأَمْرُهُ لِغَيْرِهِ بِالْبِرِّ كَيْفَ يُضَاعَفُ بِمَعْصِيَةِ نِسْيَانٍ وَلَا يَأْتِي الْخَيْرُ بِالشَّرِّ!\",[[2,44,0,4,1]]],[57,\"الْأَمْرُ\",3,276,276,1040,\"وَهُوَ طَلَبُ فِعْلٍ غَيْرُ كَفٍّ وَصِيغَتُهُ\\\"افْعَلْ\\\"وَ\\\"لْيَفْعَلْ\\\"وَهِيَ حَقِيقَةٌ فِي الْإِيجَابِ نَحْوُ: ﴿وَأَقِيمُوا الصَّلاةَ﴾ ﴿فَلْيُصَلُّوا مَعَكَ﴾\",[[4,103,11,12,1],[4,102,22,23,1]]],[57,\"الْأَمْرُ\",3,276,276,1040,\"مِنْهَا النَّدْبُ نَحْوُ: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾\",[[7,204,0,5,1]]],[57,\"الْأَمْرُ\",3,276,276,1040,\"والإباحة نحو: ﴿فَكَاتِبُوهُمْ﴾ نَصَّ الشَّافِعِيُّ عَلَى أَنَّ الْأَمْرَ فِيهِ لِلْإِبَاحَةِ وَمِنْهُ: ﴿وَإِذَا حَلَلْتُمْ فَاصْطَادُوا﴾\",[[17,71,11,11,2],[24,33,16,16,2],[5,2,23,25,1]]],[57,\"الْأَمْرُ\",3,276,277,1040,\"والدعاء من الغافل لِلْعَالِي نَحْوُ: ﴿رَبِّ اغْفِرْ لِي﴾ وَالتَّهْدِيدُ نَحْوُ: ﴿اعْمَلُوا مَا شِئْتُمْ﴾ إِذْ لَيْسَ الْمُرَادُ الْأَمْرَ بِكُلِّ عَمَلٍ شَاءُوا\",[[7,151,1,3,3],[38,35,1,3,3],[71,28,0,2,3],[41,40,19,21,1]]],[57,\"الْأَمْرُ\",3,277,277,1041,\"وَالْإِهَانَةُ نَحْوُ: ﴿ذُقْ إِنَّكَ أَنْتَ الْعَزِيزُ الْكَرِيمُ﴾\",[[44,49,0,4,1]]],[57,\"الْأَمْرُ\",3,277,277,1041,\"وَالتَّسْخِيرُ أَيِ التَّذْلِيلُ نَحْوُ: ﴿كُونُوا قِرَدَةً﴾ عَبَّرَ بِهِ عَنْ نَقْلِهِمْ مِنْ حَالَةٍ إِلَى حَالَةٍ إِذْلَالًا لَهُمْ فَهُوَ أَخَصُّ مِنَ الْإِهَانَةِ\",[[2,65,9,10,2],[7,166,8,9,2]]],[57,\"الْأَمْرُ\",3,277,277,1041,\"وَالتَّعْجِيزُ نَحْوُ: ﴿فَأْتُوا بِسُورَةٍ مِّنْ مِثْلِهِ﴾ إِذْ لَيْسَ الْمُرَادُ طَلَبَ ذَلِكَ مِنْهُمْ بَلْ إِظْهَارُ عَجْزِهِمْ\",[[2,23,8,11,1]]],[57,\"الْأَمْرُ\",3,277,277,1041,\"وَالِامْتِنَانُ نَحْوُ: ﴿كُلُوا مِنْ ثَمَرِهِ إِذَا أَثْمَرَ﴾\",[[6,141,16,20,1]]],[57,\"الْأَمْرُ\",3,277,277,1041,\"وَالْعَجَبُ نَحْوُ: ﴿انْظُرْ كَيْفَ ضَرَبُوا لَكَ الأَمْثَالَ﴾\",[[17,48,0,4,2],[25,9,0,4,2]]],[57,\"الْأَمْرُ\",3,277,277,1041,\"وَالْإِرْشَادُ نَحْوُ: ﴿وَأَشْهِدُوا إِذَا تَبَايَعْتُمْ﴾\",[[2,282,107,109,1]]],[57,\"الْأَمْرُ\",3,277,277,1041,\"وَالِاحْتِقَارُ نَحْوُ: ﴿أَلْقُوا مَا أَنْتُمْ مُلْقُونَ﴾\",[[10,80,6,9,2],[26,43,3,6,2]]],[57,\"الْأَمْرُ\",3,277,277,1041,\"والإنذار نحو: ﴿قُلْ تَمَتَّعُوا﴾\",[[11,65,1,2,3],[14,30,6,7,3],[39,8,26,27,3]]],[57,\"الْأَمْرُ\",3,277,277,1041,\"والإكرام نحو: ﴿ادْخُلُوهَا بِسَلامٍ﴾\",[[15,46,0,1,2],[50,34,0,1,2]]],[57,\"الْأَمْرُ\",3,277,278,1041,\"وَالْإِنْعَامُ أَيْ تَذْكِيرُ النِّعْمَةِ نَحْوُ: ﴿كُلُوا مِمَّا رَزَقَكُمُ اللَّهُ﴾ وَالتَّكْذِيبُ نَحْوُ: ﴿قُلْ فَأْتُوا بِالتَّوْرَاةِ فَاتْلُوهَا﴾ ﴿قُلْ هَلُمَّ شُهَدَاءَكُمُ الَّذِينَ يَشْهَدُونَ أَنَّ اللَّهَ حَرَّمَ هَذَا﴾ وَالْمَشُورَةُ نَحْوُ: ﴿فَانْظُرْ مَاذَا تَرَى﴾\",[[6,142,4,7,1],[3,93,17,20,1],[6,150,0,8,1],[37,102,12,14,1]]],[57,\"الْأَمْرُ\",3,278,278,1042,\"وَالِاعْتِبَارُ نَحْوُ: ﴿انْظُرُوا إِلَى ثَمَرِهِ إِذَا أَثْمَرَ﴾\",[[6,99,32,36,1]]],[57,\"الْأَمْرُ\",3,278,278,1042,\"وَالتَّعَجُّبُ نَحْوُ: ﴿أَسْمِعْ بِهِمْ وَأَبْصِرْ﴾ ذَكَرَهُ السَّكَّاكِيُّ فِي اسْتِعْمَالِ الْإِنْشَاءِ بِمَعْنَى الْخَبَرِ.\",[[19,38,0,2,1]]],[57,\"النَّهْيُ\",3,278,278,1042,\"منها الكراهة ونحو: ﴿وَلا تَمْشِ فِي الأَرْضِ مَرَحًا﴾\",[[17,37,0,4,2],[31,18,4,8,2]]],[57,\"النَّهْيُ\",3,278,278,1042,\"وَالدُّعَاءُ نَحْوُ: ﴿رَبَّنَا لَا تُزِغْ قُلُوبَنَا﴾\",[[3,8,0,3,1]]],[57,\"النَّهْيُ\",3,278,278,1042,\"وَالْإِرْشَادُ نَحْوُ: ﴿لَا تَسْأَلوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ﴾\",[[5,101,3,10,1]]],[57,\"النَّهْيُ\",3,278,278,1042,\"والتسوية نحو: ﴿وْ لا تَصْبِرُوا﴾\",[[52,16,3,4,1]]],[57,\"النَّهْيُ\",3,278,279,1042,\"وَالِاحْتِقَارُ وَالتَّقْلِيلُ نَحْوُ: ﴿لَا تَمُدَّنَّ عَيْنَيْكَ﴾ الْآيَةَ أَيْ فَهُوَ قَلِيلٌ حَقِيرٌ وَبَيَانُ الْعَاقِبَةِ نَحْوُ: ﴿وَلا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا بَلْ أَحْيَاءٌ﴾ أَيْ عَاقِبَةُ الْجِهَادِ الْحَيَاةُ\\\"لَا الْمَوْتُ\\\"\",[[15,88,0,2,2],[20,131,0,2,2],[3,169,0,9,1]]],[57,\"النَّهْيُ\",3,279,279,1043,\"وَالْيَأْسُ نَحْوُ: ﴿لَا تَعْتَذِرُوا﴾ وَالْإِهَانَةُ نَحْوُ اخْسَئُوا فِيهَا وَلَا تكلمون.\",[[9,66,0,1,3],[9,94,6,7,3],[66,7,3,4,3]]],[57,\"التَّمَنِّي\",3,279,279,1043,\"وَقَدْ بَالَغَ قَوْمٌ فَجَعَلُوا التَّمَنِّيَ مِنْ قِسْمِ الْخَبَرِ وَأَنَّ مَعْنَاهُ النَّفْيُ وَالزَّمَخْشَرِيُّ مِمَّنْ جَزَمَ بِخِلَافِهِ ثُمَّ اسْتَشْكَلَ دُخُولُ التَّكْذِيبِ فِي جَوَابِهِ في قوله: ﴿لَيْتَنَا نُرَدُّ وَلا نُكَذِّبَ﴾ إِلَى قَوْلِهِ: ﴿وَإِنَّهُمْ لَكَاذِبُونَ﴾ وَأَجَابَ بِتَضَمُّنِهِ مَعْنَى الْعِدَةِ فَتَعَلَّقَ بِهِ التَّكْذِيبُ\",[[6,27,7,10,1],[6,28,14,15,1]]],[57,\"التَّمَنِّي\",3,280,280,1044,\"وَحَرْفُ التَّمَنِّي الْمَوْضُوعُ لَهُ\\\"لَيْتَ\\\"نحو: ﴿يَا لَيْتَنَا نُرَدُّ﴾ ﴿يَا لَيْتَ قَوْمِي يَعْلَمُونَ﴾ ﴿لَيْتَنِي كُنْتُ مَعَهُمْ فَأَفُوز﴾\",[[6,27,7,8,1],[6,97,13,15,1],[4,73,12,15,1]]],[57,\"التَّمَنِّي\",3,280,280,1044,\"وقد يتمنى بهل حَيْثُ يُعْلَمُ فَقْدُهُ نَحْوُ: ﴿فَهَلْ لَنَا مِنْ شُفَعَاءَ فَيَشْفَعُوا لَنَا﴾ وبلوا نحو: ﴿فَلَوْ أَنَّ لَنَا كَرَّةً فَنَكُونَ﴾ ولذا نصب الفصل فِي جَوَابِهَا\",[[7,53,17,22,1],[26,102,0,4,1]]],[57,\"التَّمَنِّي\",3,280,280,1044,\"وَقَدْ يُتَمَنَّى بِ\\\"لَعَلَّ\\\"فِي الْبَعِيدِ فَتُعْطَى حُكْمَ\\\"لَيْتَ\\\"فِي نَصْبِ الْجَوَابِ نَحْوُ: ﴿لَعَلِّي أَبْلُغُ الأَسْبَابَ أَسْبَابَ السَّمَاوَاتِ فَأَطَّلِعَ﴾ .\",[[40,36,6,8,1],[40,37,0,2,1]]],[57,\"التَّرَجِّي\",3,280,281,1044,\"وَسَمِعْتُ شَيْخَنَا الْعَلَّامَةَ الْكَافَيْجِيَّ يَقُولُ الْفَرْقُ بَيْنَ التَّمَنِّي وَبَيْنَ الْعَرْضِ هُوَ الْفَرْقُ بَيْنَهُ وَبَيْنَ التَّرَجِّي وَحَرْفُ التَّرَجِّي لَعَلَّ وَعَسَى وَقَدْ تَرِدُ مَجَازًا لِتَوَقُّعٍ مَحْذُورٍ وَيُسَمَّى الْإِشْفَاقُ نَحْوُ: ﴿لَعَلَّ السَّاعَةَ قَرِيبٌ﴾\",[[42,17,8,10,1]]],[57,\"النِّدَاءُ\",3,281,281,1045,\"وَهُوَ طَلَبُ إِقْبَالِ الْمَدْعُوِّ عَلَى الدَّاعِي بِحَرْفٍ نَائِبٍ مَنَابَ\\\"أَدْعُو\\\"وَيَصْحَبُ فِي الْأَكْثَرِ الْأَمْرَ وَالنَّهْيَ وَالْغَالِبُ تَقَدُّمُهُ نَحْوُ: ﴿يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ﴾ ﴿يَا عِبَادِ فَاتَّقُونِ﴾ ﴿يَا أَيُّهَا الْمُزَّمِّلُ قُمِ اللَّيْلَ﴾ ﴿وَيَا قَوْمِ اسْتَغْفِرُوا رَبَّكُمْ﴾ ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُقَدِّمُوا﴾ وقد يتأخر نحو: ﴿تُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ﴾\",[[2,21,0,3,1],[39,16,14,15,1],[73,1,0,1,1],[73,2,0,1,1],[11,52,0,2,1],[49,1,0,4,1],[24,31,70,75,1]]],[57,\"النِّدَاءُ\",3,281,282,1045,\"وَقَدْ يَصْحَبُ الْجُمْلَةَ الْخَبَرِيَّةَ فَتَعْقُبُهَا جُمْلَةُ الْأَمْرِ نحو: ﴿يَا أَيُّهَا النَّاسُ ضُرِبَ مَثَلٌ فَاسْتَمِعُوا لَهُ﴾ ﴿وَيَا قَوْمِ هَذِهِ نَاقَةُ اللَّهِ لَكُمْ آيَةً َذَرُوهَا﴾ وقد لا تعقبها نحو: ﴿يَا عِبَادِ لا خَوْفٌ عَلَيْكُمُ الْيَوْمَ﴾ ﴿يَا أَيُّهَا النَّاسُ أَنْتُمُ الْفُقَرَاءُ إِلَى اللَّهِ﴾ ﴿يَا أَبَتِ هَذَا تَأْوِيلُ رُؤْيايَ﴾ وقد تصحبه الاستفهامية ﴿يا أبت يَا أَبَتِ لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلا يُبْصِرُ﴾ ﴿يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ﴾ ﴿وَيَا قَوْمِ مَا لِي أَدْعُوكُمْ﴾ وَقَدْ تَرِدُ صُورَةُ النِّدَاءِ لِغَيْرِهِ مَجَازًا كَالْإِغْرَاءِ وَالتَّحْذِيرِ وَقَدِ اجْتَمَعَا فِي قَوْلِهِ تَعَالَى: ﴿نَاقَةَ اللَّهِ وَسُقْيَاهَا﴾ والاختصاص كقوله: ﴿رَحْمَتُ اللَّهِ وَبَرَكَاتُهُ عَلَيْكُمْ أَهْلَ الْبَيْتِ﴾ والتنبيه كقوله: ﴿أَلاَّ يَسْجُدُوا﴾ والتعجب كقوله: ﴿يَا حَسْرَةً عَلَى الْعِبَادِ﴾\",[[22,73,0,5,1],[11,64,0,6,1],[43,68,0,4,1],[35,15,0,5,1],[12,100,8,11,1],[66,1,0,3,1],[40,41,0,3,1],[91,13,4,6,1],[11,73,5,10,1],[27,25,0,1,3],[68,42,5,6,3],[68,43,7,8,3],[36,30,0,2,1]]],[57,\"النِّدَاءُ\",3,282,282,1046,\"والتحسر كقوله: ﴿لَيْتَنِي كُنْتُ تُرَابًا﴾\",[[78,40,12,14,1]]],[57,\"النِّدَاءُ\",3,282,282,1046,\"مِنْهَا إِظْهَارُ الْحِرْصِ فِي وُقُوعِهِ عَلَى إِقْبَالِ الْمَدْعُوِّ نَحْوُ: ﴿يَا مُوسَى أَقْبِلْ﴾\",[[28,31,12,13,1]]],[57,\"النِّدَاءُ\",3,282,282,1046,\"وَمِنْهَا كَوْنُ الْخِطَابِ الْمَتْلُوِّ مُعْتَنًى بِهِ نَحْوُ: ﴿يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ﴾\",[[2,21,0,3,1]]],[57,\"النِّدَاءُ\",3,282,282,1046,\"وَمِنْهَا قَصْدُ تَعْظِيمِ شَأْنِ الْمَدْعُوِّ نَحْوُ: ﴿يَا رَبِّ﴾ وَقَدْ قَالَ تعالى: ﴿فَإِنِّي قَرِيبٌ﴾\",[[2,186,4,5,1]]],[57,\"النِّدَاءُ\",3,282,282,1046,\"وَمِنْهَا قَصْدُ انْحِطَاطِهِ كَقَوْلِ فِرْعَوْنُ: ﴿إِنِّي لأَظُنُّكَ يَا مُوسَى مَسْحُورًا﴾\",[[17,101,14,17,1]]],[58,\"الْإِيهَامُ\",3,285,286,1049,\"قَالَ الزَّمَخْشَرِيُّ: لَا تَرَى بَابًا فِي الْبَيَانِ أَدَقَّ وَلَا أَلْطَفَ مِنَ التَّوْرِيَةِ وَلَا أَنْفَعَ وَلَا أَعْوَنَ عَلَى تَعَاطِي تَأْوِيلِ الْمُتَشَابِهَاتِ فِي كَلَامِ اللَّهِ وَرَسُولِهِ قَالَ وَمِنْ أَمْثِلَتِهَا: ﴿الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى﴾ فَإِنَّ الِاسْتِوَاءَ عَلَى مَعْنَيَيْنِ الِاسْتِقْرَارُ فِي الْمَكَانِ وَهُوَ الْمَعْنَى الْقَرِيبُ الْمُوَرَّى بِهِ الَّذِي هُوَ غَيْرُ مَقْصُودٍ لِتَنْزِيهِهِ تَعَالَى عَنْهُ وَالثَّانِي: الِاسْتِيلَاءُ وَالْمُلْكُ وَهُوَ الْمَعْنَى الْبَعِيدُ الْمَقْصُودُ الَّذِي وَرَّى عَنْهُ بِالْقَرِيبِ الْمَذْكُورِ انْتَهَى. وَهَذِهِ التَّوْرِيَةُ تُسَمَّى مُجَرَّدَةً لِأَنَّهَا لَمْ يُذْكَرْ فِيهَا شَيْءٌ مِنْ لَوَازِمِ الْمُوَرَّى بِهِ وَلَا الْمُوَرَّى عَنْهُ\",[[20,5,0,3,1]]],[58,\"الْإِيهَامُ\",3,286,286,1050,\"وَمِنْهَا مَا تُسَمَّى مُرَشَّحَةً وَهِيَ الَّتِي ذُكِرَ فِيهَا شَيْءٌ مِنْ لَوَازِمَ هَذَا أَوْ هَذَا كَقَوْلِهِ تَعَالَى: ﴿وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ﴾ فَإِنَّهُ يَحْتَمِلُ الْجَارِحَةَ وَهُوَ الْمُوَرَّى بِهِ وَقَدْ ذُكِرَ مِنْ لَوَازِمِهِ عَلَى جِهَةِ التَّرْشِيحِ الْبُنْيَانُ وَيَحْتَمِلُ الْقُوَّةَ وَالْقُدْرَةَ وَهُوَ الْبَعِيدُ الْمَقْصُودُ\",[[51,47,0,2,1]]],[58,\"الْإِيهَامُ\",3,286,286,1050,\"قَالَ ابْنُ أَبِي الْإِصْبَعِ فِي كِتَابِهِ \\\"الْإِعْجَازُ\\\"وَمِنْهَا: ﴿قَالُوا تَاللَّهِ إِنَّكَ لَفِي ضَلالِكَ الْقَدِيمِ﴾ فَالضَّلَالُ يَحْتَمِلُ الْحُبَّ وَضِدَّ الْهُدَى فَاسْتَعْمَلَ أَوْلَادُ يَعْقُوبَ ضِدَّ الْهُدَى تَوْرِيَةً عَنِ الْحُبِّ\",[[12,95,0,5,1]]],[58,\"الْإِيهَامُ\",3,286,286,1050,\"﴿فَالْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ﴾ عَلَى تَفْسِيرِهِ بِالدِّرْعِ فَإِنَّ الْبَدَنَ يُطْلَقُ عَلَيْهِ وَعَلَى الْجَسَدِ وَالْمُرَادُ البعيد وهو الجسد\",[[10,92,0,2,1]]],[58,\"الْإِيهَامُ\",3,286,287,1050,\"فقال: ومن ذلك قوله بعد ذِكْرِ أَهْلِ الْكِتَابِ مِنَ الْيَهُودِ وَالنَّصَارَى حَيْثُ قَالَ: ﴿وَلَئِنْ أَتَيْتَ الَّذِينَ أُوتُوا الْكِتَابَ بِكُلِّ آيَةٍ مَا تَبِعُوا قِبْلَتَكَ وَمَا أَنْتَ بِتَابِعٍ قِبْلَتَهُمْ﴾ وَلَمَّا كَانَ الْخِطَابُ لِمُوسَى مِنَ الْجَانِبِ الْغَرْبِيِّ وَتَوَجَّهَتْ إِلَيْهِ الْيَهُودُ وَتَوَجَّهَتِ النَّصَارَى إِلَى الْمَشْرِقِ كَانَتْ قِبْلَةُ الْإِسْلَامِ وَسَطًا بَيْنَ الْقِبْلَتَيْنِ قَالَ تَعَالَى: ﴿وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا﴾ أَيْ خِيَارًا وَظَاهِرُ اللَّفْظِ يُوهِمُ التَّوَسُّطَ مَعَ مَا يُعَضِّدُهُ مِنْ تَوَسُّطِ قِبْلَةِ الْمُسْلِمِينَ صَدَقَ عَلَى لفظة \\\"وسط\\\" ها هنا أَنْ يُسَمِّي تَعَالَى بِهِ لِاحْتِمَالِهَا الْمَعْنَيَيْنِ وَلَمَّا كان المراد أبعدها وَهُوَ الْخِيَارُ صَلُحَتْ أَنْ تَكُونَ مِنْ أَمْثِلَةِ التَّوْرِيَةِ قُلْتُ: وَهِيَ مُرَشَّحَةٌ بِلَازِمِ الْمُوَرَّى عَنْهُ وَهُوَ قَوْلُهُ: ﴿لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ﴾ فَإِنَّهُ مِنْ لَوَازِمِ كَوْنِهِمْ خِيَارًا أَيْ عُدُولًا وَالْإِتْيَانُ قَبْلَهَا مِنْ قِسْمِ الْمُجَرَّدَةِ\",[[2,145,0,13,1],[2,143,0,7,1]]],[58,\"الْإِيهَامُ\",3,287,287,1051,\"وَمِنْ ذَلِكَ قَوْلُهُ: ﴿وَالنَّجْمُ وَالشَّجَرُ يَسْجُدَانِ﴾ فَإِنَّ النَّجْمَ يُطْلَقُ عَلَى الْكَوْكَبِ وَيُرَشِّحُهُ لَهُ ذِكْرُ الشَّمْسِ وَالْقَمَرِ وَعَلَى مَا لَا سَاقَ لَهُ مِنَ النَّبَاتِ وَهُوَ الْمَعْنَى الْبَعِيدُ لَهُ وَهُوَ الْمَقْصُودُ فِي الْآيَةِ\",[[55,6,0,2,1]]],[58,\"الْإِيهَامُ\",3,287,287,1051,\"وَنَقَلْتُ مِنْ خَطِّ شَيْخِ الْإِسْلَامِ ابن حجر أن التَّوْرِيَةِ فِي الْقُرْآنِ قَوْلَهُ تَعَالَى: ﴿وَمَا أَرْسَلْنَاكَ إِلاَّ كَافَّةً لِلنَّاسِ﴾ فَإِنَّ\\\"كَافَّةً\\\"بِمَعْنَى\\\"مَانِعٍ\\\"أَيْ تَكُفُّهُمْ عَنِ الْكُفْرِ وَالْمَعْصِيَةِ وَالْهَاءُ للمبالغة وهذا مَعْنًى بَعِيدٌ وَالْمَعْنَى الْقَرِيبُ الْمُتَبَادِرُ أَنَّ الْمُرَادَ جَامِعَةً بِمَعْنَى \\\"جَمِيعًا\\\" لَكِنْ مَنَعَ مِنْ حَمْلِهِ عَلَى ذَلِكَ أَنَّ التَّأْكِيدَ يَتَرَاخَى عَنِ الْمُؤَكَّدِ فَكَمَا لَا تَقُولُ رَأَيْتُ جَمِيعًا النَّاسَ لَا تَقُولُ رَأَيْتُ كَافَّةً الناسَ\",[[34,28,0,4,1]]],[58,\"الِاسْتِخْدَامُ\",3,287,288,1051,\"وَالْأُخْرَى أَنْ يُؤْتَى بِلَفْظٍ مُشْتَرَكٍ ثُمَّ بِلَفْظَيْنِ يُفْهَمُ مِنْ أَحَدِهِمَا أَحَدُ الْمَعْنَيَيْنِ وَمِنَ الْآخَرُ وَهَذِهِ طَرِيقَةُ بَدْرِ الدِّينِ بن جماعة فِي الْمِصْبَاحِ وَمَشَى عَلَيْهَا ابْنُ أَبِي الْإِصْبَعِ وَمَثَّلَ لَهُ بِقَوْلِهِ تَعَالَى: ﴿لِكُلِّ أَجَلٍ كِتَابٌ﴾ الْآيَةَ فَلَفْظُ\\\"كِتَابٍ\\\"يَحْتَمِلُ الْأَمَدَ الْمَحْتُومَ وَالْكِتَابَ الْمَكْتُوبَ فَلَفْظُ\\\"أَجْلٍ\\\"يَخْدِمُ الْمَعْنَى الْأَوَّلَ وَ\\\"يَمْحُو\\\"يَخْدِمُ الثَّانِي\",[[13,38,18,20,1]]],[58,\"الِاسْتِخْدَامُ\",3,288,288,1052,\"وَمَثَّلَ غَيْرُهُ بِقَوْلِهِ تَعَالَى: ﴿لَا تَقْرَبُوا الصَّلاةَ وَأَنْتُمْ سُكَارَى﴾ الآية فَالصَّلَاةُ تَحْتَمِلُ أَنْ يُرَادَ بِهَا فِعْلُهَا وَمَوْضِعُهَا وَقَوْلُهُ: ﴿حَتَّى تَعْلَمُوا مَا تَقُولُونَ﴾ يَخْدِمُ الْأَوَّلَ ﴿إِلاَّ عَابِرِي سَبِيلٍ﴾ يَخْدِمُ الثَّانِي\",[[4,43,3,11,1],[4,43,14,16,1]]],[58,\"الِاسْتِخْدَامُ\",3,288,288,1052,\"قُلْتُ: وَقَدِ اسْتَخْرَجْتُ بِفِكْرِي آيَاتٍ عَلَى طَرِيقَتِهِ مِنْهَا قَوْلُهُ تَعَالَى: ﴿أَتَى أَمْرُ اللَّهِ﴾ فَأَمْرُ اللَّهِ يُرَادُ بِهِ قِيَامُ السَّاعَةِ وَالْعَذَابُ وَبِعْثَةُ النَّبِيِّ ﷺ وَقَدْ أُرِيدَ بِلَفْظِهِ الْأَخِيرِ كَمَا أَخْرَجَ ابْنُ مَرْدَوَيْهِ مِنْ طَرِيقِ الضَّحَاكِ عَنِ ابْنِ عَبَّاسٍ فِي قَوْلِهِ تَعَالَى: ﴿أَتَى أَمْرُ اللَّهِ﴾ قَالَ مُحَمَّدٌ وَأُعِيدَ الضَّمِيرُ عَلَيْهِ فِي\\\" تَسْتَعْجِلُوهُ \\\"مُرَادًا بِهِ قِيَامُ السَّاعَةِ وَالْعَذَابُ\",[[16,1,0,2,1],[16,1,0,2,1]]],[58,\"الِاسْتِخْدَامُ\",3,288,288,1052,\"وَمِنْهَا وَهِيَ أَظْهَرُهَا قَوْلُهُ تَعَالَى: ﴿وَلَقَدْ خَلَقْنَا الْأِنْسَانَ مِنْ سُلالَةٍ مِنْ طِينٍ﴾ فَإِنَّ الْمُرَادَ بِهِ آدَمُ ثُمَّ أَعَادَ عَلَيْهِ الضَّمِيرَ مُرَادًا بِهِ ولده فقال: ﴿ثُمَّ جَعَلْنَاهُ نُطْفَةً فِي قَرَارٍ مَكِينٍ﴾\",[[23,12,0,6,1],[23,13,0,5,1]]],[58,\"الِاسْتِخْدَامُ\",3,288,288,1052,\"وَمِنْهَا قَوْلُهُ تَعَالَى: ﴿لَا تَسْأَلوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ﴾ ثُمَّ قَالَ: ﴿قَدْ سَأَلَهَا قَوْمٌ مِنْ قَبْلِكُمْ﴾ أَيْ أَشْيَاءُ أُخَرُ لِأَنَّ الْأَوَّلِينَ لَمْ يَسْأَلُوا عَنِ الْأَشْيَاءِ الَّتِي سَأَلَ عَنْهَا الصَّحَابَةُ فَنُهُوا عَنْ سؤالها.\",[[5,101,3,10,1],[5,102,0,4,1]]],[58,\"الِالْتِفَاتُ\",3,289,290,1053,\"وَأُجِيبُ بِأَنَّهُ لَوْ كَانَ الْمُرَادُ ذَلِكَ لَمَا صَحَّ الِاسْتِفْهَامُ الْإِنْكَارِيُّ لَأَنَّ رُجُوعَ الْعَبْدِ إِلَى مَوْلَاهُ لَيْسَ بِمُسْتَلْزِمٍ أَنْ يُعِيدَهُ غَيْرُ ذَلِكَ الرَّاجِعِ فَالْمَعْنَى: كَيْفَ لَا أَعْبُدُ مَنْ إِلَيْهِ رُجُوعِي وَإِنَّمَا عَدَلَ عَنْ\\\"وَإِلَيْهِ أَرْجِعُ\\\"إِلَى \\\"وَإِلَيْهِ تُرْجَعُونَ\\\" لِأَنَّهُ دَاخِلٌ فِيهِمْ وَمَعَ ذَلِكَ أَفَادَ فَائِدَةً حَسَنَةً وَهِيَ تَنْبِيهُهُمْ عَلَى أَنَّهُ مِثْلَهُمْ فِي وُجُوبِ عِبَادَةِ من إليه الرجوع ومن أَمْثِلَتِهِ أَيْضًا قَوْلُهُ تَعَالَى: ﴿وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ الْعَالَمِينَ﴾ ﴿وَأَنْ أَقِيمُوا الصَّلاةَ﴾\",[[6,71,35,38,1],[6,72,0,2,1]]],[58,\"الِالْتِفَاتُ\",3,290,290,1054,\"وَمِثَالُهُ مِنَ التَّكَلُّمِ إِلَى الْغَيْبَةِ وَوَجْهُهُ أَنْ يَفْهَمَ السَّامِعُ أَنَّ هَذَا نَمَطُ الْمُتَكَلِّمِ وَقَصْدُهُ مِنَ السَّامِعِ حَضَرَ أَوْ غَابَ وَأَنَّهُ لَيْسَ فِي كَلَامِهِ مِمَّنْ يَتَلَوَّنُ وَيَتَوَجَّهُ وَيُبْدِي فِي الْغَيْبَةِ خِلَافَ مَا يُبْدِيهِ فِي الْحُضُورِ- قَوْلُهُ تَعَالَى: ﴿إِنَّا فَتَحْنَا لَكَ فَتْحًا مُبِينًا لِيَغْفِرَ لَكَ اللَّهُ﴾ وَالْأَصْلُ\\\"لِنَغْفِرَ لَكَ\\\" ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ فَصَلِّ لِرَبِّكَ﴾ وَالْأَصْلُ\\\"لَنَا\\\" ﴿أَمْرًا مِنْ عِنْدِنَا إِنَّا كُنَّا مُرْسِلِينَ رَحْمَةً مِنْ رَبِّكَ﴾ وَالْأَصْلُ\\\"مِنَّا\\\" ﴿إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ﴾ إِلَى قَوْلِهِ: ﴿فَآمِنُوا بِاللَّهِ وَرَسُولِهِ﴾ وَالْأَصْلُ\\\"وَبِي\\\"وَعَدَلَ عَنْهُ لِنُكْتَتَيْنِ إِحْدَاهُمَا دَفْعُ التُّهْمَةِ عَنْ نَفْسِهِ بِالْعَصَبِيَّةِ لَهَا وَالْأُخْرَى تَنْبِيهُهُمْ عَلَى اسْتِحْقَاقِهِ الِاتِّبَاعَ بِمَا اتَّصَفَ بِهِ مِنَ الصِّفَاتِ الْمَذْكُورَةِ وَالْخَصَائِصِ الْمَتْلُوَّةِ وَمِثَالُهُ\",[[48,1,0,4,1],[48,2,0,2,1],[108,1,0,2,1],[108,2,0,1,1],[44,5,0,5,1],[44,6,0,2,1],[7,158,3,6,3],[61,5,9,12,3],[61,6,7,10,3],[48,13,2,4,1]]],[58,\"الِالْتِفَاتُ\",3,290,290,1054,\"مِنَ الْخِطَابِ إِلَى التَّكَلُّمِ لَمْ يَقَعْ فِي الْقُرْآنِ وَمَثَّلَ لَهُ بَعْضُهُمْ بِقَوْلِهِ: ﴿فَاقْضِ مَا أَنْتَ قَاضٍ﴾ ثُمَّ قَالَ ﴿إِنَّا آمَنَّا بِرَبِّنَا﴾ وَهَذَا الْمِثَالُ لَا يَصِحُّ لِأَنَّ شَرْطَ الِالْتِفَاتِ أَنْ يَكُونَ الْمُرَادُ بِهِ وَاحِدًا\",[[20,72,10,13,1],[20,73,0,2,1]]],[58,\"الِالْتِفَاتُ\",3,290,291,1054,\"وَمِثَالُهُ مِنَ الْخِطَابِ إِلَى الْغَيْبَةِ ﴿حَتَّى إِذَا كُنْتُمْ فِي الْفُلْكِ وَجَرَيْنَ بِهِمْ﴾ وَالْأَصْلُ\\\"بِكُمْ\\\"وَنُكْتَةُ الْعُدُولِ عَنْ خِطَابِهِمْ إِلَى حِكَايَةِ حَالِهِمْ لِغَيْرِهِمْ التَّعَجُّبُ مِنْ كُفْرِهِمْ وَفِعْلِهِمْ إِذْ لَوِ اسْتَمَرَّ عَلَى خِطَابِهِمْ لَفَاتَتْ تِلْكَ الْفَائِدَةُ\",[[10,22,6,12,1]]],[58,\"الِالْتِفَاتُ\",3,291,291,1055,\"وَقِيلَ: لِأَنَّ الْخِطَابَ أَوَّلًا كَانَ مَعَ النَّاسِ مُؤْمِنِهِمْ وَكَافِرِهِمْ بِدَلِيلِ ﴿هُوَ الَّذِي يُسَيِّرُكُمْ فِي الْبَرِّ وَالْبَحْرِ﴾ فَلَوْ كَانَ\\\"وَجَرَيْنَ بِكُمْ\\\"لَلَزِمَ الذَّمُّ لِلْجَمِيعِ فَالْتَفَتَ عَنِ الْأَوَّلِ لِلْإِشَارَةِ إِلَى اخْتِصَاصِهِ بِهَؤُلَاءِ الَّذِينَ شَأْنُهُمْ مَا ذَكَرَهُ عَنْهُمْ فِي آخِرِ الْآيَةِ عُدُولًا مِنَ الْخِطَابِ الْعَامِّ إِلَى الْخَاصِّ\",[[10,22,0,5,1]]],[58,\"الِالْتِفَاتُ\",3,291,291,1055,\"قُلْتُ: وَرَأَيْتُ عن بعض السلف في توجهه عَكْسَ ذَلِكَ وَهُوَ أَنَّ الْخِطَابَ أَوَّلُهُ خَاصٌّ وآخره عام فأخرجه ابْنُ أَبِي حَاتِمٍ عَنْ عَبْدِ الرَّحْمَنِ بْنِ زَيْدِ بْنِ أَسْلَمَ أَنَّهُ قَالَ فِي قَوْلِهِ: ﴿حَتَّى إِذَا كُنْتُمْ فِي الْفُلْكِ وَجَرَيْنَ بِهِمْ﴾ قَالَ: ذَكَرَ الْحَدِيثَ عَنْهُمْ ثُمَّ حَدَّثَ عَنْ غَيْرِهِمْ وَلَمْ يَقُلْ وَجَرَيْنَ بِكُمْ لِأَنَّهُ قَصَدَ أَنْ يَجْمَعَهُمْ وَغَيْرَهُمْ وَجَرَيْنَ بِهَؤُلَاءِ وَغَيْرِهِمْ مِنَ الْخُلُقِ هَذِهِ عِبَارَتُهُ فَلِلَّهِ دَرُّ السَّلَفِ مَا كَانَ أَوْقَفَهُمْ عَلَى الْمَعَانِي اللَّطِيفَةِ الَّتِي يَدْأَبُ الْمُتَأَخِّرُونَ فِيهَا زَمَانًا طَوِيلًا وَيَفْنُونَ فِيهَا أَعْمَارَهُمْ ثُمَّ غَايَتُهُمْ أَنْ يحرموا حَوْلَ الْحِمَى وَمِمَّا ذُكِرَ فِي تَوْجِيهِهِ أَيْضًا أَنَّهُمْ وَقْتَ الرُّكُوبِ حضروا لأنهم خَافُوا الْهَلَاكَ وَغَلَبَةَ الرِّيَاحِ فَخَاطَبَهُمْ خِطَابَ الْحَاضِرِينَ ثُمَّ لَمَّا جَرَتِ الرِّيَاحُ بِمَا تَشْتَهِي السُّفُنُ وَأَمِنُوا الْهَلَاكَ لَمْ يَبْقَ حُضُورُهُمْ كَمَا كَانَ عَلَى عَادَةِ الْإِنْسَانِ أَنَّهُ إذا أمن غالب قَلْبُهُ عَنْ رَبِّهِ فَلَمَّا غَابُوا ذَكَّرَهُمُ اللَّهُ بِصِيغَةِ الْغَيْبَةِ وَهَذِهِ إِشَارَةٌ صُوفِيَّةٌ\",[[10,22,6,12,1]]],[58,\"الِالْتِفَاتُ\",3,291,292,1055,\"وَمِنْ أَمْثِلَتِهِ أَيْضًا: ﴿وَمَا آتَيْتُمْ مِنْ زَكَاةٍ تُرِيدُونَ وَجْهَ اللَّهِ فَأُولَئِكَ هُمُ الْمُضْعِفُونَ﴾ ﴿وَكَرَّهَ إِلَيْكُمُ الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ أُولَئِكَ هُمُ الرَّاشِدُونَ﴾ ﴿ادْخُلُوا الْجَنَّةَ أَنْتُمْ وَأَزْوَاجُكُمْ تُحْبَرُونَ يُطَافُ عَلَيْهِمْ﴾ وَالْأَصْلُ\\\"عَلَيْكُمْ\\\"ثُمَّ قَالَ: ﴿وَأَنْتُمْ فِيهَا خَالِدُونَ﴾ فَكَرَّرَ الِالْتِفَاتَ وَمِثَالُهُ مِنَ الْغَيْبَةِ إِلَى التَّكَلُّمِ ﴿وَاللَّهُ الَّذِي أَرْسَلَ الرِّيَاحَ فَتُثِيرُ سَحَابًا فَسُقْنَاهُ﴾ ﴿وَأَوْحَى فِي كُلِّ سَمَاءٍ أَمْرَهَا وَزَيَّنَّا﴾ ﴿سُبْحَانَ الَّذِي أَسْرَى بِعَبْدِهِ﴾ إِلَى قَوْلِهِ: ﴿بَارَكْنَا حَوْلَهُ لِنُرِيَهُ مِنْ آيَاتِنَا﴾ ثُمَّ الْتَفَتَ ثَانِيًا إِلَى الْغَيْبَةِ فَقَالَ: ﴿إِنَّهُ هُوَ السَّمِيعُ الْبَصِيرُ﴾ وَعَلَى قِرَاءَةِ الْحَسَنِ\\\"لِيُرِيَهُ\\\"بِالْغِيبَةِ يَكُونُ الْتِفَاتًا ثَانِيًا مَنْ\\\"بَارَكْنَا\\\"وَفِي\\\"آيَاتِنَا\\\"الْتِفَاتٌ ثَالِثٌ وَفِي\\\"إِنَّهُ\\\"الْتِفَاتٌ رَابِعٌ قَالَ الزَّمَخْشَرِيُّ: وَفَائِدَتُهُ فِي هَذِهِ الْآيَاتِ وَأَمْثَالِهَا التَّنْبِيهُ عَلَى التَّخْصِيصِ بِالْقُدْرَةِ وَأَنَّهُ لَا يَدْخُلُ تَحْتَ قُدْرَةِ أَحَدٍ\",[[30,39,12,21,1],[49,7,20,27,1],[43,70,0,4,1],[43,71,0,1,1],[43,71,12,14,1],[35,9,0,6,1],[41,12,5,10,1],[17,1,0,3,1],[17,1,12,20,1]]],[58,\"الِالْتِفَاتُ\",3,292,292,1056,\"وَمِثَالُهُ مِنَ الْغَيْبَةِ إِلَى الْخِطَابِ ﴿وَقَالُوا اتَّخَذَ الرَّحْمَنُ وَلَدًا لَقَدْ جِئْتُمْ شَيْئًا إِدًّا﴾ ﴿أَلَمْ يَرَوْا كَمْ أَهْلَكْنَا مِنْ قَبْلِهِمْ مِنْ قَرْنٍ مَكَّنَّاهُمْ فِي الأَرْضِ مَا لَمْ نُمَكِّنْ لَكُمْ﴾ ﴿وَسَقَاهُمْ رَبُّهُمْ شَرَابًا طَهُورًا إِنَّ هَذَا كَانَ لَكُمْ جَزَاءً﴾ ﴿إِنْ أَرَادَ النَّبِيُّ أَنْ يَسْتَنْكِحَهَا خَالِصَةً لَكَ﴾\",[[19,88,0,3,1],[19,89,0,3,1],[6,6,0,14,1],[76,21,9,12,1],[76,22,0,4,1],[33,50,33,39,1]]],[58,\"الِالْتِفَاتُ\",3,292,293,1056,\"وَمِنْ مَحَاسِنِهِ مَا وَقَعَ فِي سُورَةِ الْفَاتِحَةِ فَإِنَّ الْعَبْدَ إِذَا ذكر الله تعالى وحده ثم ذكر صفاته التي كُلَّ صِفَةٍ مِنْهَا تَبْعَثُ عَلَى شِدَّةِ الْإِقْبَالِ وَآخِرُهَا ﴿مَالِكِ يَوْمِ الدِّينِ﴾ الْمُفِيدُ أَنَّهُ مَالِكُ الْأَمْرِ كُلِّهِ فِي يَوْمِ الْجَزَاءِ يَجِدُ مِنْ نَفْسِهِ حَامِلًا لَا يَقْدِرُ عَلَى دَفْعِهِ عَلَى خِطَابِ مَنْ هَذِهِ صِفَاتُهُ بِتَخْصِيصِهِ بِغَايَةِ الْخُضُوعِ وَالِاسْتِعَانَةِ فِي الْمُهِمَّاتِ وَقِيلَ إِنَّمَا اخْتِيرَ لَفْظُ الْغِيبَةِ لِلْحَمْدِ وَلِلْعِبَادَةِ الْخِطَابُ لِلْإِشَارَةِ إِلَى أَنَّ الْحَمْدَ دُونَ الْعِبَادَةِ فِي الرُّتْبَةِ لِأَنَّكَ تَحْمَدُ نظيرك وَلَا تَعْبُدُهُ فَاسْتَعْمَلَ لَفْظَ \\\"الْحَمْدِ\\\" مَعَ الْغَيْبَةِ وَلَفْظَ الْعِبَادَةِ مَعَ الْخِطَابِ لِيَنْسِبَ إِلَى الْعَظِيمِ حَالَ الْمُخَاطَبَةِ وَالْمُوَاجِهَةِ مَا هُوَ أَعْلَى رُتْبَةً وَذَلِكَ عَلَى طَرِيقَةِ التَّأَدُّبِ وَعَلَى نَحْوٍ مَنْ ذَلِكَ جَاءَ آخِرُ السُّورَةِ فَقَالَ: ﴿الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ﴾ مُصَرِّحًا بِذِكْرِ الْمُنْعِمِ وَإِسْنَادِ الْإِنْعَامِ إِلَيْهِ لَفْظًا وَلَمْ يُقَلْ: \\\"صِرَاطَ الْمُنْعَمِ عَلَيْهِمْ\\\" فَلَمَّا صَارَ إلى ذكر الغضب روى عَنْهُ لَفْظَهُ فَلَمْ يَنْسِبْهُ إِلَيْهِ لَفْظًا وَجَاءَ بِاللَّفْظِ مُنْحَرِفًا عَنْ ذِكْرِ الْغَاضِبِ فَلَمْ يَقُلْ: \\\"غَيْرِ الَّذِينَ غَضِبْتَ عَلَيْهِمْ\\\"تَفَادِيًا عَنْ نِسْبَةِ الْغَضَبِ إِلَيْهِ فِي اللَّفْظِ حَالَ الْمُوَاجَهَةِ وَقِيلَ: لِأَنَّهُ لَمَّا ذَكَرَ الْحَقِيقَ بِالْحَمْدِ وَأَجْرَى عَلَيْهِ الصِّفَاتِ الْعَظِيمَةَ مِنْ كَوْنِهِ رَبًّا لِلْعَالِمِينَ وَرَحْمَانًا وَرَحِيمًا وَمَالِكًا لِيَوْمِ الدِّينِ تَعَلَّقَ الْعِلْمُ بِمَعْلُومٍ عَظِيمِ الشَّأْنِ حَقِيقٍ بِأَنْ يَكُونَ مَعْبُودًا دُونَ غَيْرِهِ مُسْتَعَانًا بِهِ فَخُوطِبَ بِذَلِكَ لِتَمَيُّزِهِ بِالصِّفَاتِ الْمَذْكُورَةِ تَعْظِيمًا لِشَأْنِهِ حَتَّى كَأَنَّهُ قِيلَ: \\\"إِيَّاكَ يَا مَنْ هَذِهِ صِفَاتُهُ نَخُصُّ بِالْعِبَادَةِ وَالِاسْتِعَانَةِ لَا غَيْرَكَ\\\"\",[[1,4,0,2,1],[1,7,1,3,1]]],[58,\"الِالْتِفَاتُ\",3,293,293,1057,\"قِيلَ: ومن لطائفه التنبيه على أَنَّ مُبْتَدَأَ الْخَلْقِ الْغَيْبَةُ مِنْهُمْ عَنْهُ ﷾ وَقُصُورُهُمْ عَنْ مُحَاضَرَتِهِ وَمُخَاطَبَتِهِ وَقَيَامُ حِجَابِ الْعَظَمَةِ عَلَيْهِمْ فَإِذَا عَرَفُوهُ بِمَا هُوَ له وَتَوَسَّلُوا لِلْقُرْبِ بِالثَّنَاءِ عَلَيْهِ وَأَقَرُّوا بِالْمَحَامِدِ لَهُ وتعبدوا له بما يليق بهم تأهلوا لمخاطباته وَمُنَاجَاتِهِ فَقَالُوا: ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾\",[[1,5,0,3,1]]],[58,\"الِالْتِفَاتُ\",3,293,294,1057,\"الْتِفَاتٌ الثَّانِي: شَرْطُهُ أَيْضًا أَنْ يَكُونَ فِي جُمْلَتَيْنِ صَرَّحَ بِهِ صَاحِبُ الْكَشَّافِ وَغَيْرُهُ وَإِلَّا يَلْزَمُ عَلَيْهِ أَنْ يَكُونَ نَوْعًا غَرِيبًا. الثَّالِثُ: ذَكَرَ التَّنُوخِيُّ فِي\\\"الْأَقْصَى الْقَرِيبُ\\\"وَابْنُ الْأَثِيرِ وَغَيْرُهُمَا نَوْعًا غَرِيبًا مِنَ الِالْتِفَاتِ وَهُوَ بِنَاءُ الْفِعْلِ لِلْمَفْعُولِ بَعْدَ خِطَابِ فَاعِلِهِ أَوْ تَكَلُّمِهِ كَقَوْلِهِ: ﴿غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ﴾ بَعْدَ ﴿أَنْعَمْتَ﴾ فَإِنَّ الْمَعْنَى: \\\"غَيْرِ الَّذِينَ غَضِبْتَ عَلَيْهِمْ\\\" وَتَوَقَّفَ فِيهِ صَاحِبُ عَرُوسُ الْأَفْرَاحِ\",[[1,7,4,6,1],[1,7,2,2,1]]],[58,\"الِالْتِفَاتُ\",3,294,294,1058,\"الرَّابِعُ: قَالَ ابْنُ أَبِي الْإِصْبَعِ جَاءَ فِي الْقُرْآنِ مِنَ الِالْتِفَاتِ قِسْمٌ غَرِيبٌ جِدًّا لَمْ أَظْفَرْ فِي الشِّعْرِ بِمِثَالِهِ وَهُوَ أَنْ يُقَدِّمَ الْمُتَكَلِّمُ فِي كَلَامِهِ مذكورين مرتيين ثُمَّ يُخْبِرُ عَنِ الْأَوَّلِ مِنْهُمَا وَيَنْصَرِفُ عَنِ الْإِخْبَارِ عَنْهُ إِلَى الْإِخْبَارِ عَنِ الثَّانِي: ثُمَّ يَعُودُ إِلَى الْإِخْبَارِ عَنِ الْأَوَّلِ كَقَوْلِهِ: ﴿إِنَّ الْأِنْسَانَ لِرَبِّهِ لَكَنُودٌ وَإِنَّهُ عَلَى ذَلِكَ لَشَهِيدٌ﴾ انْصَرَفَ عَنِ الْإِخْبَارِ عَنِ الْإِنْسَانِ إِلَى الْإِخْبَارِ عَنْ رَبِّهِ تَعَالَى ثُمَّ قَالَ مُنْصَرِفًا عَنِ الْإِخْبَارِ عَنْ رَبِّهِ تَعَالَى إِلَى الْإِخْبَارِ عَنِ الْإِنْسَانِ: ﴿وَإِنَّهُ لِحُبِّ الْخَيْرِ لَشَدِيدٌ﴾ قَالَ وَهَذَا يَحْسُنُ أَنْ يُسَمَّى الْتِفَاتَ الضَّمَائِرِ\",[[100,6,0,3,1],[100,7,0,3,1],[100,8,0,3,1]]],[58,\"الِالْتِفَاتُ\",3,294,294,1058,\"مِثَالُهُ مِنَ الْوَاحِدِ إِلَى الِاثْنَيْنِ: ﴿قَالُوا أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ آبَاءَنَا وَتَكُونَ لَكُمَا الْكِبْرِيَاءُ فِي الأَرْضِ﴾ وإلى الجمع ﴿يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ﴾\",[[10,78,0,11,1],[65,1,0,4,1]]],[58,\"الِالْتِفَاتُ\",3,294,295,1058,\"وَمِنَ الِاثْنَيْنِ إِلَى الْوَاحِدِ ﴿فَمَنْ رَبُّكُمَا يَا مُوسَى﴾ ﴿فَلا يُخْرِجَنَّكُمَا مِنَ الْجَنَّةِ فَتَشْقَى﴾ وَإِلَى الْجَمْعِ ﴿وَأَوْحَيْنَا إِلَى مُوسَى وَأَخِيهِ أَنْ تَبَوَّءا لِقَوْمِكُمَا بِمِصْرَ بُيُوتًا وَاجْعَلُوا بُيُوتَكُمْ قِبْلَةً﴾\",[[20,49,1,3,1],[20,117,7,11,1],[10,87,0,11,1]]],[58,\"الِالْتِفَاتُ\",3,295,295,1059,\"وَمِنَ الْجَمْعِ إِلَى الْوَاحِدِ ﴿وَأَقِيمُوا الصَّلاةَ وَبَشِّرِ الْمُؤْمِنِينَ﴾\",[[10,87,12,15,1]]],[58,\"الِالْتِفَاتُ\",3,295,295,1059,\"وإلى الاثنين ﴿يَا مَعْشَرَ الْجِنِّ وَالأِنْسِ إِنِ اسْتَطَعْتُمْ﴾ إِلَى قَوْلِهِ: ﴿فَبِأَيِّ آلاءِ رَبِّكُمَا تُكَذِّبَانِ﴾\",[[55,33,0,4,1]]],[58,\"الِالْتِفَاتُ\",3,295,295,1059,\"السَّادِسُ: وَيَقْرُبُ مِنْهُ أَيْضًا- الِانْتِقَالُ مِنَ الْمَاضِي أَوِ الْمُضَارِعِ أَوِ الْأَمْرِ إِلَى آخَرَ مِثَالُهُ مِنَ الماضي إلى المضارع ﴿رْسَلَ الرِّيَاحَ فَتُثِيرُ﴾ ﴿خَرَّ مِنَ السَّمَاءِ فَتَخْطَفُهُ الطَّيْرُ﴾ ﴿إِنَّ الَّذِينَ كَفَرُوا وَيَصُدُّونَ عَنْ سَبِيلِ اللَّهِ﴾\",[[30,48,2,4,2],[35,9,2,4,2],[22,31,9,13,1],[22,25,0,6,1]]],[58,\"الِالْتِفَاتُ\",3,295,295,1059,\"وَإِلَى الْأَمْرِ ﴿قُلْ أَمَرَ رَبِّي بِالْقِسْطِ وَأَقِيمُوا وُجُوهَكُمْ﴾ ﴿وَأُحِلَّتْ لَكُمُ الأَنْعَامُ إِلاَّ مَا يُتْلَى عَلَيْكُمْ فَاجْتَنِبُوا﴾\",[[7,29,0,5,1],[22,30,10,17,1]]],[58,\"الِالْتِفَاتُ\",3,295,295,1059,\"وَمِنَ الْمُضَارِعِ إِلَى الْمَاضِي ﴿وَيَوْمَ يُنْفَخُ فِي الصُّورِ فَفَزِعَ﴾ ﴿وَيَوْمَ نُسَيِّرُ الْجِبَالَ وَتَرَى الأَرْضَ بَارِزَةً وَحَشَرْنَاهُمْ﴾\",[[27,87,0,4,1],[18,47,0,6,1]]],[58,\"الِالْتِفَاتُ\",3,295,295,1059,\"وَإِلَى الْأَمْرِ ﴿قَالَ إِنِّي أُشْهِدُ اللَّهَ وَاشْهَدُوا أَنِّي بَرِيءٌ﴾\",[[11,54,7,13,1]]],[58,\"الِالْتِفَاتُ\",3,295,295,1059,\"وَمِنَ الْأَمْرِ إِلَى الْمَاضِي ﴿وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلّىً وَعَهِدْنَا﴾\",[[2,125,6,11,1]]],[58,\"الِالْتِفَاتُ\",3,295,295,1059,\"وَإِلَى الْمُضَارِعِ ﴿وَأَنْ أَقِيمُوا الصَّلاةَ وَاتَّقُوهُ وَهُوَ الَّذِي إِلَيْهِ تُحْشَرُونَ﴾\",[[6,72,0,7,1]]],[58,\"الِاطِّرَادُ\",3,296,296,1060,\"هُوَ أَنْ يَذْكُرَ الْمُتَكَلِّمُ أَسْمَاءَ آبَاءِ الْمَمْدُوحِ مُرَتَّبَةً عَلَى حُكْمِ تَرْتِيبِهَا فِي الْوِلَادَةِ قَالَ ابْنُ أَبِي الْإِصْبَعِ: وَمِنْهُ فِي الْقُرْآنِ قَوْلُهُ تَعَالَى حِكَايَةً عَنْ يُوسُفَ: ﴿وَاتَّبَعْتُ مِلَّةَ آبَائي إِبْرَاهِيمَ وَإِسْحَاقَ وَيَعْقُوبَ﴾\",[[12,38,0,5,1]]],[58,\"الِاطِّرَادُ\",3,296,296,1060,\"قَالَ: وَإِنَّمَا لَمْ يَأْتِ بِهِ عَلَى التَّرْتِيبِ الْمَأْلُوفِ فَإِنَّ الْعَادَةَ الِابْتِدَاءُ بِالْأَبِ ثُمَّ الْجَدِّ ثُمَّ الْجَدِّ الْأَعْلَى لِأَنَّهُ لَمْ يُرِدْ هُنَا مُجَرَّدُ ذِكْرِ الْآبَاءِ وَإِنَّمَا ذَكَرَهُمْ لِيَذْكُرَ مِلَّتَهُمُ الَّتِي اتَّبَعَهَا فَبَدَأَ بِصَاحِبِ الْمِلَّةِ ثُمَّ بِمَنْ أَخَذَهَا عَنْهُ أَوَّلًا فَأَوَّلًا عَلَى التَّرْتِيبِ وَمِثْلُهُ قَوْلُ أَوْلَادِ يَعْقُوبَ: ﴿نَعْبُدُ إِلَهَكَ وَإِلَهَ آبَائِكَ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ﴾\",[[2,133,15,21,1]]],[58,\"الانسجام\",3,296,296,1060,\"فَمِنْهُ مِنْ بَحْرِ الطَّوِيلِ: ﴿فَمَنْ شَاءَ فَلْيُؤْمِنْ وَمَنْ شَاءَ فَلْيَكْفُرْ﴾\",[[18,29,4,9,1]]],[58,\"الانسجام\",3,296,296,1060,\"وَمِنَ الْمَدِيدِ: ﴿وَاصْنَعِ الْفُلْكَ بِأَعْيُنِنَا﴾\",[[11,37,0,2,2],[23,27,3,5,2]]],[58,\"الانسجام\",3,296,297,1060,\"وَمِنَ الْبَسِيطِ: ﴿فَأَصْبَحُوا لَا يُرَى إِلاَّ مَسَاكِنُهُمْ﴾ وَمِنَ الْوَافِرِ: ﴿وَيُخْزِهِمْ وَيَنْصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍ مُؤْمِنِينَ﴾\",[[46,25,5,9,1],[9,14,4,10,1]]],[58,\"الانسجام\",3,297,297,1061,\"وَمِنَ الْكَامِلِ: ﴿وَاللَّهُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ﴾\",[[2,213,42,48,2],[24,46,4,10,2]]],[58,\"الانسجام\",3,297,297,1061,\"وَمِنَ الْهَزَجِ: ﴿فَأَلْقُوهُ عَلَى وَجْهِ أَبِي يَأْتِ بَصِيرًا﴾\",[[12,93,3,8,1]]],[58,\"الانسجام\",3,297,297,1061,\"وَمِنَ الرَّجَزِ: ﴿وَدَانِيَةً عَلَيْهِمْ ظِلالُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلًا﴾\",[[76,14,0,5,1]]],[58,\"الانسجام\",3,297,297,1061,\"وَمِنَ الرَّمَلِ: ﴿وَجِفَانٍ كَالْجَوَابِ وَقُدُورٍ رَاسِيَاتٍ﴾\",[[34,13,7,10,1]]],[58,\"الانسجام\",3,297,297,1061,\"وَمِنَ السَّرِيعِ: ﴿أَوْ كَالَّذِي مَرَّ عَلَى قَرْيَةٍ﴾\",[[2,259,1,4,1]]],[58,\"الانسجام\",3,297,297,1061,\"وَمِنَ الْمُنْسَرِحِ: ﴿إِنَّا خَلَقْنَا الْأِنْسَانَ مِنْ نُطْفَةٍ﴾\",[[76,2,0,4,1]]],[58,\"الانسجام\",3,297,297,1061,\"وَمِنَ الْخَفِيفِ: ﴿لَا يَكَادُونَ يَفْقَهُونَ حَدِيثًا﴾\",[[4,78,32,35,1]]],[58,\"الانسجام\",3,297,297,1061,\"وَمِنَ الْمُضَارِعِ: ﴿يَوْمَ التَّنَادِ يَوْمَ تُوَلُّونَ مُدْبِرِينَ﴾\",[[40,32,4,5,1],[40,33,0,2,1]]],[58,\"الانسجام\",3,297,297,1061,\"وَمِنَ الْمُجْتَثِّ: ﴿نَبِّئْ عِبَادِي أَنِّي أَنَا الْغَفُورُ الرَّحِيمُ﴾\",[[15,49,0,5,1]]],[58,\"الانسجام\",3,297,297,1061,\"وَمِنَ الْمُتَقَارِبِ: ﴿وَأُمْلِي لَهُمْ إِنَّ كَيْدِي مَتِينٌ﴾\",[[7,183,0,4,2],[68,45,0,4,2]]],[58,\"الإدماج\",3,298,298,1062,\"قال ابن الْإِصْبَعِ هُوَ أَنْ يُدْمِجَ الْمُتَكَلِّمُ غَرَضًا فِي غَرَضٍ أَوْ بَدِيعًا فِي بَدِيعٍ بِحَيْثُ لَا يَظْهَرُ فِي الْكَلَامِ إِلَّا أَحَدُ الْغَرَضَيْنِ أَوْ أَحَدُ الْبَدِيعَيْنِ كَقَوْلِهِ تَعَالَى: ﴿لَهُ الْحَمْدُ فِي الأُولَى وَالآخِرَةِ﴾ أُدْمِجَتِ الْمُبَالَغَةُ فِي الْمُطَابَقَةِ لِأَنَّ انفراده بِالْحَمْدِ فِي الْآخِرَةِ وَهِيَ الْوَقْتُ الَّذِي لَا يُحْمَدُ فِيهِ سِوَاهُ- مبالغة في الوصف بِالِانْفِرَادِ بِالْحَمْدِ وَهُوَ وَإِنْ خَرَجَ مَخْرَجَ الْمُبَالَغَةِ فِي الظَّاهِرِ فَالْأَمْرُ فِيهِ حَقِيقَةٌ فِي الْبَاطِنِ فَإِنَّهُ رَبُّ الْحَمْدِ وَالْمُنْفَرِدُ بِهِ فِي الدَّارَيْنِ انْتَهَى\",[[28,70,6,10,1]]],[58,\"الافتان\",3,298,298,1062,\"هُوَ الْإِتْيَانُ فِي كَلَامٍ بِفَنَّيْنِ مُخْتَلِفَيْنِ كَالْجَمْعِ بَيْنَ الْفَخْرِ وَالتَّعْزِيَةِ في قَوْلِهِ تَعَالَى: ﴿كُلُّ مَنْ عَلَيْهَا فَانٍ وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلالِ وَالأِكْرَامِ﴾ فَإِنَّهُ تَعَالَى عَزَّى جَمِيعَ الْمَخْلُوقَاتِ مِنَ الْإِنْسِ وَالْجِنِّ وَالْمَلَائِكَةِ وَسَائِرِ أَصْنَافِ مَا هُوَ قَابِلٌ لِلْحَيَاةِ وَتَمَدَّحَ بِالْبَقَاءِ بَعْدَ فَنَاءٍ الْمَوْجُودَاتِ فِي عَشْرِ لَفْظَاتٍ مَعَ وَصْفِهِ ذَاتَهُ بَعْدَ- انْفِرَادِهِ بِالْبَقَاءِ- بِالْجَلَالِ وَالْإِكْرَامِ ﷾!\",[[55,26,0,3,1],[55,27,0,5,1]]],[58,\"الافتان\",3,298,298,1062,\"وَمِنْهُ ﴿ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا﴾ الْآيَةَ جَمَعَ فِيهَا بَيْنَ هَنَاءٍ وَعَزَاءٍ.\",[[19,72,0,3,1]]],[58,\"الِاقْتِدَارُ\",3,299,300,1063,\"فَالْأَوَّلُ: كَقَوْلِهِ تَعَالَى: ﴿تَاللَّهِ تَفْتَأُ تَذْكُرُ يُوسُفَ حَتَّى تَكُونَ حَرَضًا﴾ أَتَى بِأَغْرَبِ أَلْفَاظِ الْقَسَمِ وَهِيَ التَّاءُ فَإِنَّهَا أَقَلُّ اسْتِعْمَالًا وَأَبْعَدُ مِنْ أَفْهَامِ الْعَامَّةِ بِالنِّسْبَةِ إِلَى الباء والواو وَبِأَغْرَبِ صِيَغِ الْأَفْعَالِ الَّتِي تَرْفَعُ الْأَسْمَاءَ وَتَنْصِبُ الْأَخْبَارَ فَإِنَّ\\\"تَزَالُ\\\"أَقْرَبُ إِلَى الْأَفْهَامِ وَأَكْثَرُ اسْتِعْمَالًا مِنْهَا وَبِأَغْرَبِ أَلْفَاظِ الْهَلَاكِ وَهُوَ الْحَرَضُ فَاقْتَضَى حُسْنُ الْوَضْعِ فِي النظم أن تجاوز كُلُّ لَفْظَةٍ بِلَفْظَةٍ مِنْ جِنْسِهَا فِي الْغَرَابَةِ تَوَخِّيًا لِحُسْنِ الجوار ورغبة فِي ائْتِلَافِ الْمَعَانِي بِالْأَلْفَاظِ وَلِتَتَعَادَلَ الْأَلْفَاظُ فِي الْوَضْعِ وَتَتَنَاسَبُ فِي النَّظْمِ وَلَمَّا أَرَادَ غَيْرَ ذَلِكَ قَالَ: ﴿وَأَقْسَمُوا بِاللَّهِ جَهْدَ أَيْمَانِهِمْ﴾ فَأَتَى بِجَمِيعِ الْأَلْفَاظِ مُتَدَاوَلَةً لَا غَرَابَةَ فِيهَا\",[[12,85,1,7,1],[5,53,5,8,5],[6,109,0,3,5],[16,38,0,3,5],[24,53,0,3,5],[35,42,0,3,5]]],[58,\"الِاقْتِدَارُ\",3,300,300,1064,\"وَمِنَ الثَّانِي: قَوْلُهُ تَعَالَى: ﴿وَلا تَرْكَنُوا إِلَى الَّذِينَ ظَلَمُوا فَتَمَسَّكُمُ النَّارُ﴾ لَمَّا كَانَ الرُّكُونُ إِلَى الظَّالِمِ وَهُوَ الْمَيْلُ إِلَيْهِ وَالِاعْتِمَادُ عَلَيْهِ دُونَ مُشَارَكَتِهِ فِي الظُّلْمِ وَجَبَ أَنْ يَكُونَ الْعِقَابُ عَلَيْهِ دُونَ الْعِقَابِ عَلَى الظُّلْمِ فَأَتَى بِلَفْظِ\\\"الْمَسِّ\\\"الَّذِي هُوَ دُونَ الْإِحْرَاقِ وَالِاصْطِلَاءِ\",[[11,113,0,6,1]]],[58,\"الِاقْتِدَارُ\",3,300,300,1064,\"وَقَوْلُهُ: ﴿لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ﴾ أَتَى بِلَفْظِ\\\"الِاكْتِسَابِ\\\"الْمُشْعِرِ بِالْكُلْفَةِ وَالْمُبَالَغَةِ فِي جَانِبِ السَّيِّئَةِ لِثِقَلِهَا\",[[2,286,6,11,1]]],[58,\"الِاقْتِدَارُ\",3,300,300,1064,\"وَكَذَا قَوْلُهُ: ﴿فَكُبْكِبُوا فِيهَا﴾ فهو أَبْلَغُ مِنْ كُبُّوا لِلْإِشَارَةِ إِلَى أنهم يكبون كَبًّا عَنِيفًا فَظِيعًا\",[[26,94,0,1,1]]],[58,\"الِاقْتِدَارُ\",3,300,300,1064,\"﴿وَهُمْ يَصْطَرِخُونَ﴾ فإنه أبلغ من\\\"يَصْرُخُونَ\\\"لِلْإِشَارَةِ إِلَى أَنَّهُمْ يَصْرُخُونَ صُرَاخًا مُنْكَرًا خَارِجًا عَنِ الْحَدِّ الْمُعْتَادِ\",[[35,37,0,1,1]]],[58,\"الِاقْتِدَارُ\",3,300,301,1064,\"﴿أَخْذَ عَزِيزٍ مُقْتَدِرٍ﴾ فَإِنَّهُ أَبْلَغُ مِنْ\\\"قَادِرٍ\\\"لِلْإِشَارَةِ إِلَى زِيَادَةِ التَّمَكُّنِ فِي الْقُدْرَةِ وَأَنَّهُ لَا رَادَّ لَهُ وَلَا معقب ومثل ذلك ﴿وَاصْطَبِرْ﴾ فَإِنَّهُ أَبْلَغُ مِنْ\\\"اصْبِرْ\\\"وَ\\\"الرَّحْمَنِ\\\" فَإِنَّهُ أَبْلَغُ مِنَ\\\"الرَّحِيمِ\\\": فَإِنَّهُ يُشْعِرُ بِاللُّطْفِ وَالرِّفْقِ كَمَا أَنَّ الرحمن مشعر بِالْفَخَامَةِ وَالْعَظَمَةِ\",[[54,42,4,6,1],[54,27,6,6,1]]],[58,\"الِاقْتِدَارُ\",3,301,301,1065,\"وَمِنْهُ الْفَرْقُ بَيْنَ سقى وأسقى فَإِنَّ\\\"سَقَى\\\"لِمَا لَا كُلْفَةَ مَعَهُ فِي السُّقْيَا وَلِهَذَا أَوْرَدَهُ تَعَالَى فِي شَرَابِ الْجَنَّةِ فَقَالَ: ﴿وَسَقَاهُمْ رَبُّهُمْ شَرَابًا طَهُورًا﴾ وَ\\\"أَسْقَى\\\" لِمَا فِيهِ كُلْفَةٌ وَلِهَذَا أَوْرَدَهُ فِي شَرَابِ الدُّنْيَا فَقَالَ: ﴿وَأَسْقَيْنَاكُمْ مَاءً فُرَاتًا﴾ ﴿لأَسْقَيْنَاهُمْ مَاءً غَدَقًا﴾ لِأَنَّ السُّقْيَا فِي الدُّنْيَا لَا تَخْلُو مِنَ الْكُلْفَةِ أَبَدًا\",[[76,21,9,12,1],[77,27,4,6,1],[72,16,4,6,1]]],[58,\"الِاسْتِدْرَاكُ وَالِاسْتِثْنَاءُ\",3,301,301,1065,\"مِثَالُ الِاسْتِدْرَاكِ: ﴿قَالَتِ الأَعْرَابُ آمَنَّا قُلْ لَمْ تُؤْمِنُوا وَلَكِنْ قُولُوا أَسْلَمْنَا﴾ فَإِنَّهُ لَوِ اقْتَصَرَ عَلَى قَوْلِهِ لَمْ تُؤْمِنُوا لَكَانَ مُنَفِّرًا لَهُمْ لِأَنَّهُمْ ظَنُّوا الْإِقْرَارَ بِالشَّهَادَتَيْنِ مِنْ غَيْرِ اعْتِقَادٍ إِيمَانًا فَأَوْجَبَتِ الْبَلَاغَةُ ذِكْرَ الِاسْتِدْرَاكِ لِيُعْلَمَ أَنَّ الْإِيمَانَ موافقة القلب اللسان وإن انفرد اللِّسَانِ بِذَلِكَ يُسَمَّى إِسْلَامًا وَلَا يُسَمَّى إِيمَانًا وَزَادَ ذَلِكَ إِيضَاحًا بِقَوْلِهِ: ﴿وَلَمَّا يَدْخُلِ الْأِيمَانُ فِي قُلُوبِكُمْ﴾ فَلَمَّا تَضَمَّنَ الِاسْتِدْرَاكُ إِيضَاحَ مَا عَلَيْهِ ظَاهِرُ الْكَلَامِ مِنَ الْإِشْكَالِ عُدَّ مِنَ الْمَحَاسِنِ\",[[49,14,0,13,1]]],[58,\"الِاسْتِدْرَاكُ وَالِاسْتِثْنَاءُ\",3,301,302,1065,\"وَمِثَالُ الِاسْتِثْنَاءِ: ﴿فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلاَّ خَمْسِينَ عَامًا﴾ فَإِنَّ الْإِخْبَارَ عَنْ هَذِهِ الْمُدَّةِ بِهَذِهِ الصِّيغَةِ يُمَهِّدُ عُذْرَ نُوحٍ فِي دُعَائِهِ عَلَى قَوْمِهِ بِدَعْوَةٍ أَهْلَكَتْهُمْ عَنْ آخِرِهِمْ إِذْ لَوْ قِيلَ: \\\"فَلَبِثَ فِيهِمْ تِسْعَمِائَةٍ وَخَمْسِينَ عَامًا\\\"لَمْ يَكُنْ فِيهِ مِنَ التَّهْوِيلِ مَا فِي الْأَوَّلِ لِأَنَّ لَفْظَ\\\"الألف\\\"في الْأَوَّلِ أَوَّلُ مَا يَطْرُقُ السَّمْعُ فيشتغل بِهَا عَنْ سَمَاعِ بَقِيَّةِ الْكَلَامِ وَإِذَا جَاءَ الِاسْتِثْنَاءُ لَمْ يَبْقَ له بعدما تَقَدَّمَهُ وَقْعٌ يُزِيلُ مَا حَصَلَ عِنْدَهُ مِنْ ذِكْرِ الْأَلْفِ\",[[29,14,5,11,1]]],[58,\"الِاقْتِصَاصُ\",3,302,302,1066,\"ذَكَرَهُ ابْنُ فَارِسٍ وَهُوَ أَنْ يَكُونَ كل كَلَامٌ فِي سُورَةٍ مُقْتَصًّا مِنْ كَلَامٍ فِي سُورَةٍ أُخْرَى أَوْ فِي تِلْكَ السُّورَةِ كَقَوْلِهِ تَعَالَى: ﴿وَآتَيْنَاهُ أَجْرَهُ فِي الدُّنْيَا وَإِنَّهُ فِي الآخِرَةِ لَمِنَ الصَّالِحِينَ﴾ والآخرة دَارُ ثَوَابٍ لَا عَمَلَ فِيهَا فَهَذَا مُقْتَصٌّ من قوله: ﴿وَمَنْ يَأْتِهِ مُؤْمِنًا قَدْ عَمِلَ الصَّالِحَاتِ فَأُولَئِكَ لَهُمُ الدَّرَجَاتُ الْعُلَى﴾\",[[29,27,9,17,1],[20,75,0,9,1]]],[58,\"الِاقْتِصَاصُ\",3,302,302,1066,\"وَمِنْهُ: ﴿وَلَوْلا نِعْمَةُ رَبِّي لَكُنْتُ مِنَ الْمُحْضَرِينَ﴾ مأخوذ مِنْ قَوْلِهِ: ﴿أُولَئِكَ فِي الْعَذَابِ مُحْضَرُونَ﴾\",[[37,57,0,5,1],[30,16,7,10,2],[34,38,5,8,2]]],[58,\"الِاقْتِصَاصُ\",3,302,302,1066,\"وقوله: ﴿وَيَوْمَ يَقُومُ الأَشْهَادُ﴾ مُقْتَصٌّ مِنْ أَرْبَعِ آيَاتٍ لِأَنَّ الْأَشْهَادَ أَرْبَعَةٌ: الْمَلَائِكَةُ فِي قَوْلِهِ: ﴿وَجَاءَتْ كُلُّ نَفْسٍ مَعَهَا سَائِقٌ وَشَهِيدٌ﴾\",[[40,51,8,10,1],[50,21,0,5,1]]],[58,\"الِاقْتِصَاصُ\",3,302,302,1066,\"وَالْأَنْبِيَاءُ فِي قَوْلِهِ: ﴿فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلاءِ شَهِيدًا﴾ وَأُمَّةُ مُحَمَّدٍ فِي قَوْلِهِ: ﴿لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ﴾\",[[4,41,0,11,1],[2,143,4,7,2],[22,78,28,31,2]]],[58,\"الِاقْتِصَاصُ\",3,302,303,1066,\"وَالْأَعْضَاءُ فِي قَوْلِهِ: ﴿يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ﴾ الآية وقوله: ﴿يَوْمَ التَّنَادِ﴾ قُرِئَ مُخَفَّفًا وَمُشَدَّدًا فَالْأَوَّلُ مَأْخُوذٌ مِنْ قَوْلِهِ: ﴿وَنَادَى أَصْحَابُ الْجَنَّةِ أَصْحَابَ النَّارِ﴾ وَالثَّانِي مِنْ قَوْلِهِ: ﴿يَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ﴾\",[[24,24,0,3,1],[40,32,4,5,1],[7,44,0,4,1],[80,34,0,4,1]]],[58,\"الْإِبْدَالُ\",3,303,303,1067,\"هُوَ إِقَامَةُ بَعْضِ الْحُرُوفِ مَقَامَ بَعْضٍ وَجَعَلَ مِنْهُ ابْنُ فَارِسٍ ﴿فَانْفَلَقَ﴾ أَيِ انْفَرَقَ وَلِهَذَا قال: ﴿فَكَانَ كُلُّ فِرْقٍ﴾ فَالرَّاءُ وَاللَّامُ مُتَعَاقِبَتَانِ وَعَنِ الْخَلِيلِ فِي قَوْلِهِ تَعَالَى: ﴿فَجَاسُوا خِلالَ الدِّيَارِ﴾ أَنَّهُ أُرِيدَ\\\"فَحَاسُوا\\\" فَجَاءَتِ الْجِيمُ مَقَامَ الْحَاءِ وَقَدْ قُرِئَ بِالْحَاءِ أَيْضًا وَجَعَلَ مِنْهُ الْفَارِسِيُّ: ﴿إِنِّي أَحْبَبْتُ حُبَّ الْخَيْرِ﴾ أَيِ الْخَيْلَ وَجَعَلَ مِنْهُ أَبُو عبيدة ﴿لَّا مُكَاءً وَتَصْدِيَةً﴾ أَيْ تَصْدِدَةً\",[[26,63,7,10,1],[17,5,11,13,1],[38,32,1,4,1],[8,35,5,7,1]]],[58,\"تَأْكِيدُ الْمَدْحِ بِمَا يُشْبِهُ الذَّمَّ\",3,303,304,1067,\"قَالَ ابْنُ أَبِي الْإِصْبَعِ: هُوَ فِي غَايَةِ الْعِزَّةِ فِي الْقُرْآنِ قَالَ: وَلَمْ أَجِدْ مِنْهُ إِلَّا آيَةً وَاحِدَةً وَهِيَ قوله: ﴿قُلْ يَا أَهْلَ الْكِتَابِ هَلْ تَنْقِمُونَ مِنَّا إِلاَّ أَنْ آمَنَّا بِاللَّهِ﴾ فَإِنَّ الِاسْتِثْنَاءَ بَعْدَ الِاسْتِفْهَامِ الْخَارِجِ مَخْرَجَ التَّوْبِيخِ عَلَى مَا عَابُوا بِهِ الْمُؤْمِنِينَ مِنَ الْإِيمَانِ يُوهِمُ أَنَّ مَا يَأْتِي بَعْدَهُ مِمَّا يُوجِبُ أَنْ يُنْقَمَ عَلَى فَاعِلِهِ مِمَّا يُذَمُّ بِهِ فَلَمَّا أَتَى بَعْدَ الاستثناء ما يُوجِبُ مَدْحَ فَاعِلِهِ كَانَ الْكَلَامُ مُتَضَمِّنًا تَأْكِيدَ الْمَدْحِ بِمَا يُشْبِهُ الذَّمَّ\",[[5,59,0,9,1]]],[58,\"تَأْكِيدُ الْمَدْحِ بِمَا يُشْبِهُ الذَّمَّ\",3,304,304,1068,\"قُلْتُ: وَنَظِيرُهَا قَوْلُهُ: ﴿وَمَا نَقَمُوا إِلّا أَنْ أَغْنَاهُمُ اللَّهُ وَرَسُولُهُ مِنْ فَضْلِهِ﴾ وَقَوْلُهُ: ﴿الَّذِينَ أُخْرِجُوا مِنْ دِيَارِهِمْ بِغَيْرِ حَقٍّ إِلاَّ أَنْ يَقُولُوا رَبُّنَا اللَّهُ﴾ فَإِنَّ ظَاهِرَ الِاسْتِثْنَاءِ أَنَّ مَا بَعْدَهُ حَقٌّ يَقْتَضِي الْإِخْرَاجَ فَلَمَّا كَانَ صِفَةَ مَدْحٍ يَقْتَضِي الْإِكْرَامَ لَا الْإِخْرَاجَ كَانَ تَأْكِيدًا لِلْمَدْحِ بِمَا يُشْبِهُ الذَّمَّ\",[[9,74,15,23,1],[22,40,0,10,1]]],[58,\"تَأْكِيدُ الْمَدْحِ بِمَا يُشْبِهُ الذَّمَّ\",3,304,304,1068,\"وَجَعَلَ مِنْهُ التَّنُوخِيُّ فِي الْأَقْصَى الْقَرِيبِ: ﴿لَا يَسْمَعُونَ فِيهَا لَغْوًا وَلا تَأْثِيمًا إِلاَّ قِيلًا سَلامًا سَلامًا﴾ اسْتَثْنَى\\\"سَلَامًا سَلَامًا\\\"الَّذِي هُوَ ضِدُّ اللَّغْوِ وَالتَّأْثِيمِ فَكَانَ ذَلِكَ مُؤَكِّدًا لِانْتِفَاءِ اللَّغْوِ وَالتَّأْثِيمِ انْتَهَى\",[[56,25,0,5,1],[56,26,0,3,1]]],[58,\"التَّفْوِيتُ\",3,304,304,1068,\"فَمِنَ الطَّوِيلَةِ ﴿الَّذِي خَلَقَنِي فَهُوَ يَهْدِينِ وَالَّذِي هُوَ يُطْعِمُنِي وَيَسْقِينِ وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ وَالَّذِي يُمِيتُنِي ثُمَّ يُحْيِينِ﴾\",[[26,78,0,3,1],[26,79,0,3,1],[26,80,0,3,1],[26,81,0,3,1]]],[58,\"التَّفْوِيتُ\",3,304,305,1068,\"وَمِنَ الْمُتَوَسِّطَةِ ﴿تُولِجُ اللَّيْلَ فِي النَّهَارِ وَتُولِجُ النَّهَارَ فِي اللَّيْلِ وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ﴾ قَالَ ابْنُ أَبِي الْإِصْبَعِ وَلَمْ يَأْتِ الْمُرَكَّبُ مِنَ الْقَصِيرَةِ فِي القرآن\",[[3,27,0,15,1]]],[58,\"التَّقْسِيمُ\",3,305,305,1069,\"هُوَ اسْتِيفَاءُ أَقْسَامِ الشَّيْءِ الْمَوْجُودَةِ لَا الْمُمْكِنَةِ عَقْلًا نَحْوُ: ﴿هُوَ الَّذِي يُرِيكُمُ الْبَرْقَ خَوْفًا وَطَمَعًا﴾ إِذْ لَيْسَ فِي رُؤْيَةِ الْبَرْقِ إِلَّا الْخَوْفُ مِنَ الصَّوَاعِقِ وَالطَّمَعُ فِي الْأَمْطَارِ وَلَا ثَالِثَ لِهَذَيْنَ الْقِسْمَيْنِ\",[[13,12,0,5,1]]],[58,\"التَّقْسِيمُ\",3,305,305,1069,\"وَقَوْلُهُ: ﴿فَمِنْهُمْ ظَالِمٌ لِنَفْسِهِ وَمِنْهُمْ مُقْتَصِدٌ وَمِنْهُمْ سَابِقٌ بِالْخَيْرَاتِ﴾ فَإِنَّ الْعَالَمَ لَا يَخْلُو مِنْ هَذِهِ الْأَقْسَامِ الثلَاثَةِ إِمَّا عَاصٍ ظَالِمٌ لِنَفْسِهِ وَإِمَّا سَابِقٌ مُبَادِرٌ للخيرات وَإِمَّا مُتَوَسِّطٌ بَيْنَهُمَا مُقْتَصِدٌ فِيهَا\",[[35,32,7,14,1]]],[58,\"التَّقْسِيمُ\",3,305,305,1069,\"وَكَذَا قَوْلُهُ تَعَالَى: ﴿لَهُ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا وَمَا بَيْنَ ذَلِكَ﴾ اسْتَوْفَى أَقْسَامَ الزَّمَانِ وَلَا رَابِعَ لهما\",[[19,64,5,13,1]]],[58,\"التَّقْسِيمُ\",3,305,305,1069,\"وَقَوْلُهُ: ﴿وَاللَّهُ خَلَقَ كُلَّ دَابَّةٍ مِنْ مَاءٍ فَمِنْهُمْ مَنْ يَمْشِي عَلَى بَطْنِهِ وَمِنْهُمْ مَنْ يَمْشِي عَلَى رِجْلَيْنِ وَمِنْهُمْ مَنْ يَمْشِي عَلَى أَرْبَعٍ﴾ ستوفى أَقْسَامَ الْخَلْقِ فِي الْمَشْيِ\",[[24,45,0,20,1]]],[58,\"التَّقْسِيمُ\",3,305,306,1069,\"وَقَوْلُهُ: ﴿الَّذِينَ يَذْكُرُونَ اللَّهَ قِيَامًا وَقُعُودًا وَعَلَى جُنُوبِهِمْ﴾ استوفى جميع هيآت الذَّاكِرِ وَقَوْلُهُ: ﴿يَهَبُ لِمَنْ يَشَاءُ إِنَاثًا وَيَهَبُ لِمَنْ يَشَاءُ الذُّكُورَ أَوْ يُزَوِّجُهُمْ ذُكْرَانًا وَإِنَاثًا وَيَجْعَلُ مَنْ يشاء عقيما﴾ اسْتَوْفَى جَمِيعَ أَحْوَالِ الْمُتَزَوِّجِينَ وَلَا خَامِسَ لَهَا\",[[3,191,0,6,1]]],[58,\"التَّدْبِيجُ\",3,306,306,1070,\"هُوَ أَنْ يَذْكُرَ الْمُتَكَلِّمَ أَلْوَانًا يَقْصِدُ التَّوْرِيَةَ بِهَا وَالْكِنَايَةَ قَالَ ابْنُ أَبِي الْإِصْبَعِ: كَقَوْلِهِ تَعَالَى: ﴿وَمِنَ الْجِبَالِ جُدَدٌ بِيضٌ وَحُمْرٌ مُخْتَلِفٌ أَلْوَانُهَا وَغَرَابِيبُ سُودٌ﴾ قَالَ الْمُرَادُ بِذَلِكَ وَاللَّهُ أَعْلَمُ الْكِنَايَةُ عَنِ الْمُشْتَبَهِ وَالْوَاضِحِ مِنَ الطُّرُقِ لِأَنَّ الْجَادَّةَ الْبَيْضَاءَ هِيَ الطَّرِيقُ الَّتِي كَثُرَ السُّلُوكُ عَلَيْهَا جِدًّا وَهِيَ أَوْضَحُ الطُّرُقِ وَأَبْيَنُهَا وَدُونَهَا الْحَمْرَاءُ وَدُونَ الْحَمْرَاءِ السَّوْدَاءُ كَأَنَّهَا فِي الْخَفَاءِ وَالِالْتِبَاسِ ضِدَّ الْبَيْضَاءِ فِي الظُّهُورِ وَالْوُضُوحِ وَلَمَّا كَانَتْ هَذِهِ الْأَلْوَانُ الثَّلَاثَةُ فِي الظُّهُورِ لِلْعَيْنِ طَرَفَيْنِ وَوَاسِطَةً فَالطَّرَفُ الْأَعْلَى فِي الظُّهُورِ الْبَيَاضُ وَالطَّرْفُ الْأَدْنَى فِي الْخَفَاءِ السَّوَادُ وَالْأَحْمَرُ بَيْنَهُمَا عَلَى وَضْعِ الْأَلْوَانِ فِي التَّرْكِيبِ وَكَانَتْ أَلْوَانُ الْجِبَالِ لَا تَخْرُجُ عَنْ هَذِهِ الْأَلْوَانِ الثَّلَاثَةِ وَالْهِدَايَةُ بِكُلِّ عَلَمٍ نُصِبَ لِلْهِدَايَةِ مُنْقَسِمَةٌ هَذِهِ الْقِسْمَةَ أَتَتِ الْآيَةُ الْكَرِيمَةُ مُنْقَسِمَةً كَذَلِكَ فَحَصَلَ فِيهَا التَّدْبِيجُ وصحة التقسيم.\",[[35,27,13,21,1]]],[58,\"التَّنْكِيتُ\",3,306,307,1070,\"هُوَ أَنْ يَقْصِدَ الْمُتَكَلِّمُ إِلَى شَيْءٍ بِالذِّكْرِ دُونَ غَيْرِهِ مِمَّا يَسُدُّ مَسَدَّهُ لِأَجْلِ نُكْتَةٍ فِي الْمَذْكُورِ تُرَجِّحُ مَجِيئَهُ عَلَى سِوَاهُ كَقَوْلِهِ تَعَالَى: ﴿وَأَنَّهُ هُوَ رَبُّ الشِّعْرَى﴾ خَصَّ الشِّعْرَى بِالذِّكْرِ دُونَ غَيْرِهَا مِنَ النُّجُومِ وَهُوَ تَعَالَى رَبُّ كُلِّ شَيْءٍ لِأَنَّ الْعَرَبَ كَانَ ظَهَرَ فِيهِمْ رَجُلٌ يُعْرَفُ بِابْنِ أَبِي كَبْشَةَ عَبَدَ الشِّعْرَى وَدَعَا خَلْقًا إِلَى عِبَادَتِهَا فَأَنْزَلَ اللَّهُ تَعَالَى: ﴿وَأَنَّهُ هُوَ رَبُّ الشِّعْرَى﴾ الَّتِي ادُّعِيَتْ فِيهَا الرُّبُوبِيَّةُ\",[[53,49,0,3,1],[53,49,0,3,1]]],[58,\"التَّجْرِيدُ\",3,307,308,1071,\"وَمِنْ أَمْثِلَتِهِ فِي الْقُرْآنِ: ﴿لَهُمْ فِيهَا دَارُ الْخُلْدِ﴾ لَيْسَ الْمَعْنَى أَنَّ الْجَنَّةَ فِيهَا دَارُ خُلْدٍ وَغَيْرُ دَارِ خُلْدٍ بَلْ هِيَ نَفْسُهَا دَارُ الْخُلْدِ فَكَأَنَّهُ جَرَّدَ مِنَ الدَّارِ دَارًا ذَكَرَهُ في\\\"لمحتسب\\\"جعل مِنْهُ: ﴿يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ﴾ عَلَى أَنَّ الْمُرَادَ بِالْمَيِّتِ النُّطْفَةُ قَالَ الزَّمَخْشَرِيُّ: وَقَرَأَ عُبَيْدُ بْنُ عُمَيْرٍ ﴿فَكَانَتْ وَرْدَةً كَالدِّهَانِ﴾ بِالرَّفْعِ بِمَعْنَى حَصَلَتْ مِنْهَا وَرْدَةٌ قَالَ وَهُوَ مِنَ التَّجْرِيدِ وَقُرِئَ أيضا ﴿يَرِثُنِي وَيَرِثُ مِنْ آلِ يَعْقُوبَ﴾ قَالَ ابْنُ جِنِّي هَذَا هُوَ التَّجْرِيدُ وَذَلِكَ أَنَّهُ\\\"يُرِيدُ وَهَبْ لِي مِنْ لدنك وليا يرثني منه وَارِثٌ مِنْ آلِ يَعْقُوبَ\\\"وَهُوَ الْوَارِثُ نَفْسُهُ فَكَأَنَّهُ جَرَّدَ مِنْهُ وارثا\",[[41,28,5,8,1],[10,31,11,18,2],[30,19,0,7,2],[55,37,3,5,1],[19,6,0,4,1]]],[58,\"التَّعْدِيدُ\",3,308,308,1072,\"هُوَ إِيقَاعُ الْأَلْفَاظِ الْمُفْرَدَةِ عَلَى سِيَاقٍ وَاحِدٍ وَأَكْثَرُ مَا يُوجَدُ فِي الصِّفَاتِ كَقَوْلِهِ: ﴿هُوَ اللَّهُ الَّذِي لَا إِلَهَ إِلاَّ هُوَ الْمَلِكُ الْقُدُّوسُ السَّلامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيزُ الْجَبَّارُ الْمُتَكَبِّرُ﴾\",[[59,23,0,14,1]]],[58,\"التَّعْدِيدُ\",3,308,308,1072,\"وَقَوْلُهُ: ﴿التَّائِبُونَ الْعَابِدُونَ الْحَامِدُونَ﴾ الْآيَةَ\",[[9,112,0,2,1]]],[58,\"التَّعْدِيدُ\",3,308,308,1072,\"وقوله: ﴿مُسْلِمَاتٍ مُؤْمِنَاتٍ﴾ الآية.\",[[66,5,9,10,1]]],[58,\"التَّرْتِيبُ\",3,308,309,1072,\"هُوَ أَنْ يُورِدَ أَوْصَافَ الْمَوْصُوفِ عَلَى تَرْتِيبِهَا فِي الْخِلْقَةِ الطَّبِيعِيَّةِ وَلَا يُدْخِلَ فِيهَا وَصْفًا زَائِدًا وَمَثَّلَهُ عَبْدُ الْبَاقِي الْيَمَنِيُّ بِقَوْلِهِ: ﴿هُوَ الَّذِي خَلَقَكُمْ مِنْ تُرَابٍ ثُمَّ مِنْ نُطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ يُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوا أَشُدَّكُمْ ثُمَّ لِتَكُونُوا شُيُوخًا﴾ وبقوله: ﴿فَكَذَّبُوهُ فَعَقَرُوهَا﴾ الْآيَةَ التَّرَقِّي وَالتَّدَلِّي\",[[40,67,0,19,1],[91,14,0,1,1]]],[58,\"التَّرْتِيبُ\",3,309,309,1073,\"الرَّابِعُ: إِدْرَاجُ كَلَامِ الْغَيْرِ فِي أَثْنَاءِ الْكَلَامِ لِقَصْدِ تَأْكِيدِ الْمَعْنَى، أَوْ تَرْتِيبِ النَّظْمِ وَهَذَا هُوَ النَّوْعُ الْبَدِيعِيُّ قَالَ ابْنُ أَبِي الْإِصْبَعِ: وَلَمْ أَظْفَرْ فِي الْقُرْآنِ بِشَيْءٍ مِنْهُ إِلَّا فِي مَوْضِعَيْنِ تَضَمَّنَا فَصْلَيْنِ مِنَ التَّوْرَاةِ وَالْإِنْجِيلِ قَوْلِهِ: ﴿وَكَتَبْنَا عَلَيْهِمْ فِيهَا أَنَّ النَّفْسَ بِالنَّفْسِ﴾ الْآيَةَ وَقَوْلِهِ: ﴿مُحَمَّدٌ رَسُولُ اللَّهِ﴾ الْآيَةَ\",[[5,45,0,5,1],[48,29,0,2,1]]],[58,\"التَّرْتِيبُ\",3,309,310,1073,\"وَمَثَّلَهُ ابْنُ النَّقِيبِ وَغَيْرُهُ بِإِيدَاعِ حِكَايَاتِ الْمَخْلُوقِينَ فِي الْقُرْآنِ كَقَوْلِهِ تَعَالَى حِكَايَةً عَنِ الْمَلَائِكَةِ: ﴿أَتَجْعَلُ فِيهَا مَنْ يُفْسِدُ فِيهَا﴾، وَعَنِ الْمُنَافِقِينَ: ﴿أَنُؤْمِنُ كَمَا آمَنَ السُّفَهَاءُ﴾، ﴿وَقَالَتِ الْيَهُودُ﴾، ﴿وَقَالَتِ النَّصَارَى﴾ قَالَ وَكَذَلِكَ مَا أَوْدَعَ فِيهِ مِنَ اللُّغَاتِ الْأَعْجَمِيَّةِ\",[[2,30,10,14,1],[2,13,8,11,1],[2,113,0,1,1],[2,113,6,7,1]]],[58,\"الْجِنَاسُ\",3,310,310,1074,\"هُوَ تَشَابُهُ اللَّفْظَيْنِ فِي اللَّفْظِ قَالَ فِي كَنْزِ الْبَرَاعَةِ: وَفَائِدَتُهُ الْمَيْلُ إِلَى الْإِصْغَاءِ إِلَيْهِ فَإِنَّ مُنَاسَبَةَ الْأَلْفَاظِ تُحْدِثُ مَيْلًا وَإِصْغَاءً إِلَيْهَا وَلِأَنَّ اللَّفْظَ الْمُشْتَرَكَ إِذَا حُمِلَ عَلَى مَعْنًى ثُمَّ جَاءَ وَالْمُرَادُ بِهِ آخَرُ كَانَ لِلنَّفْسِ تَشَوُّقٌ إِلَيْهِ وَأَنْوَاعُ الْجِنَاسِ كَثِيرَةٌ مِنْهَا التام: بأن يتفقا في أنواع الحروف وأعدادها وهيآتها كَقَوْلِهِ تَعَالَى: ﴿وَيَوْمَ تَقُومُ السَّاعَةُ يُقْسِمُ الْمُجْرِمُونَ مَا لَبِثُوا غَيْرَ سَاعَةٍ﴾ وقيل: وَلَمْ يَقَعْ مِنْهُ فِي الْقُرْآنِ سِوَاهُ وَاسْتَنْبَطَ شَيْخُ الْإِسْلَامِ ابْنُ حَجَرٍ مَوْضِعًا آخَرَ وَهُوَ ﴿يَكَادُ سَنَا بَرْقِهِ يَذْهَبُ بِالأَبْصَارِ﴾ ﴿يُقَلِّبُ اللَّهُ اللَّيْلَ وَالنَّهَارَ إِنَّ فِي ذَلِكَ لَعِبْرَةً لأُولِي الأَبْصَارِ﴾\",[[30,55,0,8,1],[24,43,33,37,1],[24,44,0,9,1]]],[58,\"الْجِنَاسُ\",3,310,311,1074,\"وَالتَّجْنِيسُ: أَنْ يَتَّفِقَ الْلَّفْظُ وَيَخْتَلِفَ الْمَعْنَى وَلَا يَكُونُ أَحَدُهُمَا حَقِيقَةً وَالْآخِرُ مَجَازًا، بل يكونان حَقِيقَتَيْنِ، وَزَمَانُ الْقِيَامَةِ وَإِنْ طَالَ لَكِنَّهُ عِنْدَ اللَّهِ فِي حُكْمِ السَّاعَةِ الْوَاحِدَةِ فَإِطْلَاقُ السَّاعَةِ عَلَى القيام مَجَازٌ وَعَلَى الْآخِرَةِ حَقِيقَةٌ وَبِذَلِكَ يَخْرُجُ الْكَلَامُ عَنِ التَّجْنِيسِ كَمَا لَوْ قُلْتُ: \\\" رَكِبْتُ حِمَارًا وَلَقِيتُ حِمَارًا\\\"تَعْنِي بَلِيدًا. وَمِنْهَا الْمُصَحَّفُ: وَيُسَمَّى جِنَاسَ الْخَطِّ بِأَنْ تَخْتَلِفَ الْحُرُوفُ فِي النَّقْطِ كَقَوْلِهِ: ﴿وَالَّذِي هُوَ يُطْعِمُنِي وَيَسْقِينِ وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ﴾\",[[26,79,0,3,1],[26,80,0,3,1]]],[58,\"الْجِنَاسُ\",3,311,311,1075,\"وَمِنْهَا الْمُحَرَّفُ: بِأَنْ يَقَعَ الِاخْتِلَافُ فِي الْحَرَكَاتِ كَقَوْلِهِ: ﴿وَلَقَدْ أَرْسَلْنَا فِيهِمْ مُنْذِرِينَ فَانْظُرْ كَيْفَ كَانَ عَاقِبَةُ الْمُنْذَرِينَ﴾\",[[37,72,0,3,1],[37,73,0,4,1]]],[58,\"الْجِنَاسُ\",3,311,311,1075,\"وَقَدِ اجْتَمَعَ التَّصْحِيفُ وَالتَّحْرِيفُ فِي قَوْلِهِ: ﴿وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا﴾\",[[18,104,6,10,1]]],[58,\"الْجِنَاسُ\",3,311,311,1075,\"وَمِنْهَا النَّاقِصُ بِأَنْ يَخْتَلِفَ فِي عَدَدِ الْحُرُوفِ سَوَاءٌ كَانَ الْحَرْفُ الْمَزِيدُ أَوَّلًا أَوْ وَسَطًا أَوْ آخِرًا كَقَوْلِهِ: ﴿وَالْتَفَّتِ السَّاقُ بِالسَّاقِ إِلَى رَبِّكَ يَوْمَئِذٍ الْمَسَاقُ﴾ ثُمَّ كُلِي مِنْ كُلِّ الثَّمَرَاتِ\",[[75,29,0,2,1],[75,30,0,3,1]]],[58,\"الْجِنَاسُ\",3,311,311,1075,\"وَمِنْهَا الْمُذَيَّلُ: بِأَنْ يَزِيدَ أَحَدُهُمَا أَكْثَرَ مِنْ حَرْفٍ فِي الْآخِرِ أَوِ الْأَوَّلِ وَسَمَّى بَعْضُهُمُ الثَّانِي بِالْمُتَوَّجِ كَقَوْلِهِ: ﴿وَانْظُرْ إِلَى إِلَهِكَ﴾ ﴿وَلَكِنَّا كُنَّا مُرْسِلِينَ﴾ ﴿مَنْ آمَنَ بِهِ﴾، ﴿إِنَّ رَبَّهُمْ بِهِمْ﴾ ﴿مذبذبين بين ذلك﴾\",[[20,97,15,17,1],[28,45,15,17,1],[4,55,1,3,1],[100,11,0,2,1],[4,143,0,2,1]]],[58,\"الْجِنَاسُ\",3,311,312,1075,\"وَمِنْهَا الْمُضَارِعُ: وَهُوَ أَنْ يَخْتَلِفَا بِحَرْفٍ مُقَارِبٍ فِي الْمَخْرَجِ سَوَاءٌ كان في الأول أَوِ الْوَسَطِ أَوِ الْآخِرِ كَقَوْلِهِ تَعَالَى: ﴿وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْأَوْنَ عَنْهُ﴾ وَمِنْهَا اللَّاحِقُ، بِأَنْ يَخْتَلِفَا بِحَرْفٍ غَيْرِ مُقَارَبٍ فِيهِ كَذَلِكَ، كَقَوْلِهِ: ﴿وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ﴾ ﴿وَإِنَّهُ عَلَى ذَلِكَ لَشَهِيدٌ وَإِنَّهُ لِحُبِّ الْخَيْرِ لَشَدِيدٌ﴾ ﴿ذَلِكُمْ بِمَا كُنْتُمْ تَفْرَحُونَ فِي الأَرْضِ بِغَيْرِ الْحَقِّ وَبِمَا كُنْتُمْ تَمْرَحُونَ﴾ ﴿وَإِذَا جَاءَهُمْ أَمْرٌ مِنَ الأَمْنِ﴾\",[[6,26,0,4,1],[104,1,0,3,1],[100,7,0,3,1],[100,8,0,3,1],[40,75,0,10,1],[4,83,0,4,1]]],[58,\"الْجِنَاسُ\",3,312,312,1076,\"ومنها المرفوّ: وَهُوَ مَا تَرَكَّبَ مِنْ كَلِمَةٍ وَبَعْضِ أُخْرَى كَقَوْلِهِ: ﴿جُرُفٍ هَارٍ فَانْهَارَ﴾\",[[9,109,15,17,1]]],[58,\"الْجِنَاسُ\",3,312,312,1076,\"وَمِنْهَا اللَّفْظِيُّ: بِأَنْ يَخْتَلِفَا بِحَرْفٍ مُنَاسِبٍ لِلْآخَرِ مُنَاسِبَةً لَفْظِيَّةً كَالضَّادِ وَالظَّاءِ كَقَوْلِهِ: ﴿وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ إِلَى رَبِّهَا نَاظِرَةٌ﴾\",[[75,22,0,2,1],[75,23,0,2,1]]],[58,\"الْجِنَاسُ\",3,312,312,1076,\"وَمِنْهَا تَجْنِيسُ الْقَلْبِ: بِأَنْ يَخْتَلِفَا فِي تَرْتِيبِ الْحُرُوفِ نَحْوُ: ﴿فَرَّقْتَ بَيْنَ بَنِي إِسْرائيلَ﴾\",[[20,94,11,14,1]]],[58,\"الْجِنَاسُ\",3,312,312,1076,\"وَمِنْهَا تَجْنِيسُ الِاشْتِقَاقِ: بِأَنْ يَجْتَمِعَا فِي أَصْلِ الِاشْتِقَاقِ وَيُسَمَّى الْمُقْتَضَبَ نَحْوُ: ﴿فَرَوْحٌ وَرَيْحَانٌ﴾ ﴿فَأَقِمْ وَجْهَكَ لِلدِّينِ الْقَيِّمِ﴾ ﴿وَجَّهْتُ وَجْهِيَ﴾\",[[56,89,0,1,1],[30,43,0,3,1],[6,79,1,2,1]]],[58,\"الْجِنَاسُ\",3,312,313,1076,\"وَمِنْهَا تَجْنِيسُ الْإِطْلَاقِ: بِأَنْ يَجْتَمِعَا فِي الْمُشَابَهَةِ فَقَطْ كَقَوْلِهِ: ﴿وَجَنَى الْجَنَّتَيْنِ دَانٍ﴾ ﴿قَالَ إِنِّي لِعَمَلِكُمْ مِنَ الْقَالِينَ﴾ ﴿لِيُرِيَهُ كَيْفَ يُوَارِي﴾ ﴿وَإِنْ يُرِدْكَ بِخَيْرٍ فَلا رَادَّ﴾ ﴿اثَّاقَلْتُمْ إِلَى الأَرْضِ أَرَضِيتُمْ﴾ ﴿وَإِذَا أَنْعَمْنَا عَلَى الأِنْسَانِ أَعْرَضَ﴾ إِلَى قَوْلِهِ: ﴿فذودعاء عريض﴾\",[[55,54,6,8,1],[26,168,0,4,1],[5,31,6,8,1],[10,107,9,13,1],[9,38,12,15,1],[17,83,0,4,2],[41,51,0,4,2]]],[58,\"الْجِنَاسُ\",3,313,313,1077,\"لِكَوْنِ الْجِنَاسِ مِنَ الْمَحَاسِنِ اللَّفْظِيَّةِ لَا الْمَعْنَوِيَّةِ تُرِكَ عِنْدَ قُوَّةِ الْمَعْنَى كَقَوْلِهِ تَعَالَى: ﴿وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ﴾، قِيلَ: مَا الْحِكْمَةُ فِي كَوْنِهِ لَمْ يَقُلْ: \\\"وَمَا أَنْتِ بِمُصَدِّقٍ\\\" فَإِنَّهُ يُؤَدِّي مَعْنَاهُ مَعَ رِعَايَةِ التجنيس وأجيب بأن في\\\" مؤمن لنا\\\" من المعنى ما لَيْسَ فِي\\\"مُصَدِّقٍ\\\"لِأَنَّ مَعْنَى قَوْلِكَ: \\\" فُلَانٌ مُصَدِّقٌ لِي\\\" قَالَ لِي: صَدَقْتَ وَأَمَّا \\\"مُؤْمِنٌ\\\" فَمَعْنَاهُ مع التَّصْدِيقِ إِعْطَاءُ الْأَمْنِ وَمَقْصُودُهُمُ التَّصْدِيقُ وَزِيَادَةٌ وَهُوَ طَلَبُ الْأَمْنِ فَلِذَلِكَ عَبَّرَ بِهِ\",[[12,17,11,17,1]]],[58,\"الْجِنَاسُ\",3,313,313,1077,\"وَقَدْ زَلَّ بَعْضُ الْأُدَبَاءِ، فَقَالَ فِي قَوْلِهِ: ﴿أَتَدْعُونَ بَعْلًا وَتَذَرُونَ أَحْسَنَ الْخَالِقِينَ﴾ لَوْ قَالَ: \\\"وَتَدَعُونَ\\\"لَكَانَ فِيهِ مراعاة للتجنيس\",[[37,125,0,4,1]]],[58,\"الْجَمْعُ\",3,314,314,1078,\"هُوَ أَنْ يُجْمَعَ بَيْنَ شَيْئَيْنِ أَوْ أَشْيَاءَ مُتَعَدِّدَةٍ فِي حُكْمٍ كَقَوْلِهِ تَعَالَى: ﴿الْمَالُ وَالْبَنُونَ زِينَةُ الْحَيَاةِ الدُّنْيَا﴾ جَمَعَ الْمَالَ وَالْبَنُونَ فِي الزِّينَةِ\",[[18,46,0,4,1]]],[58,\"الْجَمْعُ\",3,314,314,1078,\"وكذلك قَوْلُهُ: ﴿الشَّمْسُ وَالْقَمَرُ بِحُسْبَانٍ وَالنَّجْمُ وَالشَّجَرُ يَسْجُدَانِ.﴾\",[[55,5,0,2,1],[55,6,0,2,1]]],[58,\"الْجَمْعُ وَالتَّفْرِيقُ\",3,314,315,1078,\"هُوَ أَنْ تُدْخِلَ شَيْئَيْنِ فِي مَعْنًى، وَتُفَرِّقَ بَيْنَ جِهَتَيِ الْإِدْخَالِ وَجَعَلَ مِنْهُ الطِّيبِيُّ قَوْلَهُ: ﴿اللَّهُ يَتَوَفَّى الأَنْفُسَ حِينَ مَوْتِهَا﴾ الْآيَةَ جَمَعَ النَّفْسَيْنِ في حكم المتوفي ثُمَّ فَرَّقَ بَيْنَ جِهَتَيِ التَّوَفِّي بِالْحُكْمِ بِالْإِمْسَاكِ وَالْإِرْسَالِ أَيِ اللَّهُ يَتَوَفَّى الْأَنْفُسَ الَّتِي تُقْبَضُ وَالَّتِي لَمْ تُقْبَضُ فَيُمْسِكُ الْأُولَى وَيُرْسِلُ الْأُخْرَى.\",[[39,42,0,4,1]]],[58,\"الجمع والتقسيم\",3,315,315,1079,\"وهو مع مُتَعَدِّدٍ تَحْتَ حُكْمٍ ثُمَّ تَقْسِيمُهُ، كَقَوْلِهِ تَعَالَى: ﴿ثُمَّ أَوْرَثْنَا الْكِتَابَ الَّذِينَ اصْطَفَيْنَا مِنْ عِبَادِنَا فَمِنْهُمْ ظَالِمٌ لِنَفْسِهِ وَمِنْهُمْ مُقْتَصِدٌ وَمِنْهُمْ سَابِقٌ بِالْخَيْرَاتِ﴾\",[[35,32,0,14,1]]],[58,\"الْجَمْعُ مَعَ التَّفْرِيقِ وَالتَّقْسِيمِ\",3,315,315,1079,\"كَقَوْلِهِ تَعَالَى: ﴿يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلاَّ بِإِذْنِهِ﴾ الْآيَاتِ فَالْجَمْعُ فِي قَوْلِهِ: \\\"لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِ\\\" لِأَنَّهَا مُتَعَدِّدَةٌ مَعْنًى إِذِ النَّكِرَةُ فِي سِيَاقِ النَّفْيِ تَعُمُّ وَالتَّفْرِيقُ فِي قَوْلِهِ: ﴿فَمِنْهُمْ شَقِيٌّ وَسَعِيدٌ﴾ وَالتَّقْسِيمُ فِي قَوْلِهِ: ﴿فَأَمَّا الَّذِينَ شَقُوا﴾ ﴿وَأَمَّا الَّذِينَ سُعِدُوا﴾\",[[11,105,0,9,1],[11,106,0,2,1],[11,108,0,2,1]]],[58,\"جَمْعُ الْمُؤْتَلِفِ وَالْمُخْتَلِفِ\",3,315,316,1079,\"هُوَ أَنْ يُرِيدَ التَّسْوِيَةَ بَيْنَ مَمْدُوحِينَ فَيَأْتِيَ بمعان مؤتلفة في مدحهما وَيَرُومُ بَعْدَ ذَلِكَ تَرْجِيحَ أَحَدِهِمَا عَلَى الْآخَرِ، بِزِيَادَةِ فَضْلٍ لَا يُنْقِصُ الْآخَرَ، فَيَأْتِي لِأَجْلِ ذَلِكَ بِمَعَانٍ تُخَالِفُ مَعْنَى التَّسْوِيَةِ، كَقَوْلِهِ تَعَالَى: ﴿وَدَاوُدَ وَسُلَيْمَانَ إِذْ يَحْكُمَانِ﴾ الْآيَةَ سَوَّى فِي الْحُكْمِ وَالْعِلْمِ وَزَادَ فَضْلُ سُلَيْمَانَ بِالْفَهْمِ\",[[21,78,0,3,1]]],[58,\"حُسْنُ النَّسَقِ\",3,316,316,1080,\"هُوَ أَنْ يَأْتِيَ الْمُتَكَلِّمَ بِكَلِمَاتٍ مُتَتَالِيَاتٍ مَعْطُوفَاتٍ مُتَلَاحِمَاتٍ، تَلَاحُمًا سَلِيمًا مُسْتَحْسَنًا بِحَيْثُ إِذَا أُفْرِدَتْ كُلُّ جُمْلَةٍ مِنْهُ قَامَتْ بِنَفْسِهَا وَاسْتَقَلَّ مَعْنَاهَا بِلَفْظِهَا وَمِنْهُ قَوْلُهُ تَعَالَى: ﴿وَقِيلَ يَا أَرْضُ ابْلَعِي مَاءَكِ﴾ الْآيَةَ، فَإِنَّ جُمَلَهُ مَعْطُوفٌ بَعْضُهَا على بعضها بِوَاوِ النَّسَقِ عَلَى التَّرْتِيبِ الَّذِي تَقْتَضِيهِ الْبَلَاغَةُ مِنَ الِابْتِدَاءِ بِالِاسْمِ الَّذِي هُوَ انْحِسَارُ الْمَاءِ عَنِ الْأَرْضِ الْمُتَوَقِّفُ عَلَيْهِ غَايَةُ مَطْلُوبِ أَهْلِ السَّفِينَةِ مِنَ الْإِطْلَاقِ مَنْ سِجْنِهَا ثُمَّ انْقِطَاعُ مَادَّةِ السَّمَاءِ الْمُتَوَقِّفِ عَلَيْهِ تَمَامُ ذَلِكَ مِنْ دَفْعِ أَذَاهُ بَعْدَ الْخُرُوجِ وَمِنْهُ اخْتِلَافُ مَا كَانَ بِالْأَرْضِ ثُمَّ الْإِخْبَارُ بِذَهَابِ الْمَاءِ بَعْدَ انْقِطَاعِ الْمَادَّتَيْنِ الَّذِي هُوَ مُتَأَخِّرٌ عَنْهُ قَطْعًا ثُمَّ بِقَضَاءِ الْأَمْرِ الَّذِي هُوَ هَلَاكُ مَنْ قُدِّرَ هَلَاكُهُ وَنَجَاةُ مَنْ سَبَقَ نَجَاتُهُ وَأُخِّرَ عَمَّا قَبْلَهُ لِأَنَّ عِلْمَ ذَلِكَ لِأَهْلِ السَّفِينَةِ بَعْدَ خُرُوجِهِمْ مِنْهَا وَخُرُوجُهُمْ مَوْقُوفٌ عَلَى مَا تَقَدَّمَ ثُمَّ أَخْبَرَ بِاسْتِوَاءِ السَّفِينَةِ وَاسْتِقْرَارِهَا الْمُفِيدِ ذَهَابَ الْخَوْفِ وَحُصُولَ الْأَمْنِ مِنَ الِاضْطِرَابِ ثُمَّ خَتَمَ بِالدُّعَاءِ عَلَى الظَّالِمِينَ لِإِفَادَةِ أَنَّ الْغَرَقَ وَإِنَّ عَمَّ الْأَرْضَ فَلَمْ يَشْمَلْ إِلَّا مَنِ اسْتَحَقَّ الْعَذَابَ لِظُلْمِهِ.\",[[11,44,0,3,1]]],[58,\"عِتَابُ الْمَرْءِ نَفْسَهُ\",3,317,317,1081,\"مِنْهُ: ﴿وَيَوْمَ يَعَضُّ الظَّالِمُ عَلَى يَدَيْهِ يَقُولُ يَا لَيْتَنِي﴾ الْآيَاتِ\",[[25,27,0,6,1]]],[58,\"عِتَابُ الْمَرْءِ نَفْسَهُ\",3,317,317,1081,\"وَقَوْلُهُ: ﴿أَنْ تَقُولَ نَفْسٌ يَا حَسْرَتَى عَلَى مَا فَرَّطْتُ فِي جَنْبِ اللَّهِ﴾ الْآيَاتِ.\",[[39,56,0,9,1]]],[58,\"الْعَكْسُ\",3,317,317,1081,\"هُوَ أَنْ يُؤْتَى بِكَلَامٍ يُقَدَّمُ فِيهِ جُزْءٌ وَيُؤَخُّرُ آخَرُ ثُمَّ يُقَدَّمُ الْمُؤَخَّرَ وَيُؤَخَّرُ الْمُقَدَّمُ كَقَوْلِهِ تَعَالَى: ﴿مَا عَلَيْكَ مِنْ حِسَابِهِمْ مِنْ شَيْءٍ وَمَا مِنْ حِسَابِكَ عَلَيْهِمْ مِنْ شَيْءٍ﴾ ﴿يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ﴾ ﴿وَمَنْ يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ﴾ ﴿هُنَّ لِبَاسٌ لَكُمْ وَأَنْتُمْ لِبَاسٌ لَهُنَّ﴾ ﴿لَا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ﴾\",[[6,52,9,20,1],[22,61,3,10,4],[31,29,4,11,4],[35,13,0,7,4],[57,6,0,7,4],[10,31,10,18,1],[2,187,7,12,1],[60,10,18,25,1]]],[58,\"الْعَكْسُ\",3,318,318,1082,\"وَمِنْهُ نَوْعٌ يُسَمَّى الْقَلْبُ وَالْمَقْلُوبُ الْمُسْتَوِي وَمَا لَا يَسْتَحِيلُ بِالِانْعِكَاسِ وَهُوَ أَنْ تُقْرَأَ الْكَلِمَةُ مِنْ آخِرِهَا إِلَى أَوَّلِهَا كَمَا تُقْرَأُ مِنْ أَوَّلِهَا إِلَى آخِرِهَا كَقَوْلِهِ تَعَالَى: ﴿كُلٌّ فِي فَلَكٍ﴾، ﴿وَرَبَّكَ فَكَبِّرْ﴾ وَلَا ثَالِثَ لَهُمَا فِي الْقُرْآنِ.\",[[21,33,7,9,2],[36,40,11,13,2],[74,3,0,1,1]]],[58,\"الْعُنْوَانُ\",3,318,319,1082,\"فَمِنَ الْأَوَّلِ قَوْلُهُ تَعَالَى: ﴿وَاتْلُ عَلَيْهِمْ نَبَأَ الَّذِي آتَيْنَاهُ آيَاتِنَا فَانْسَلَخَ مِنْهَا﴾ الْآيَةَ، فَإِنَّهُ عُنْوَانُ قِصَّةِ بَلْعَامَ وَمِنَ الثَّانِي قَوْلُهُ تَعَالَى: ﴿انْطَلِقُوا إِلَى ظِلٍّ ذِي ثَلَاثِ شُعَبٍ﴾ الْآيَةَ، فِيهَا عُنْوَانُ عِلْمِ الْهَنْدَسَةِ فَإِنَّ الشَّكْلَ الْمُثَلَّثَ أَوَّلُ الْأَشْكَالِ، وَإِذَا نُصِبَ فِي الشَّمْسِ عَلَى أَيِّ ضِلْعٍ مِنْ أَضْلَاعِهِ، لَا يَكُونُ لَهُ ظِلٌّ لِتَحْدِيدِ رؤوس زَوَايَاهُ فَأَمَرَ اللَّهُ تَعَالَى أَهْلَ جَهَنَّمَ بِالِانْطِلَاقِ إِلَى ظِلِّ هَذَا الشَّكْلِ تَهَكُّمًا بِهِمْ وَقَوْلُهُ: ﴿وَكَذَلِكَ نُرِي إِبْرَاهِيمَ مَلَكُوتَ السَّمَاوَاتِ وَالأَرْضِ﴾ الْآيَاتُ، فِيهَا عُنْوَانُ عِلْمِ الْكَلَامِ وَعِلْمِ الْجَدَلِ وَعِلْمِ الْهَيْئَةِ.\",[[7,175,0,7,1],[77,30,0,5,1],[6,75,0,5,1]]],[58,\"الْفَرَائِدُ\",3,319,319,1083,\"وَمِنْهُ لَفْظُ: \\\" حَصْحَصَ \\\" فِي قَوْلِهِ: ﴿الآنَ حَصْحَصَ الْحَقُّ﴾ \\\"والرفث \\\" فِي قَوْلِهِ: ﴿أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ إِلَى نِسَائِكُمْ﴾ وَلَفْظَةُ \\\" فُزِّعَ \\\" فِي قَوْلِهِ: ﴿حَتَّى إِذَا فُزِّعَ عَنْ قُلُوبِهِمْ﴾ ﴿خَائِنَةَ الأَعْيُنِ﴾ فِي قَوْلِهِ: ﴿يَعْلَمُ خَائِنَةَ الأَعْيُنِ﴾\",[[12,51,19,21,1],[2,187,0,6,1],[34,23,8,12,1],[40,19,1,2,1],[40,19,0,2,1]]],[58,\"الْفَرَائِدُ\",3,319,319,1083,\"وَأَلْفَاظُ قَوْلِهِ: ﴿فَلَمَّا اسْتَيْأَسُوا مِنْهُ خَلَصُوا نَجِيًّا﴾ وَقَوْلِهِ: ﴿فَإِذَا نَزَلَ بِسَاحَتِهِمْ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ﴾\",[[12,80,0,4,1],[37,177,0,5,1]]],[58,\"الْقَسَمُ\",3,320,320,1084,\"هُوَ أَنْ يُرِيدَ الْمُتَكَلِّمُ الْحَلِفَ عَلَى شَيْءٍ فَيَحْلِفُ بِمَا يَكُونُ فِيهِ فَخْرٌ لَهُ أَوْ تَعْظِيمٌ لِشَأْنِهِ أَوْ تَنْوِيهٌ لِقَدْرِهِ أَوْ ذَمٌّ لِغَيْرِهِ أَوْ جَارِيًا مجرى الغزل والترقق أَوْ خَارِجًا مَخْرَجَ الْمَوْعِظَةِ وَالزُّهْدِ كَقَوْلِهِ: ﴿فَوَرَبِّ السَّمَاءِ وَالأَرْضِ إِنَّهُ لَحَقٌّ مِثْلَ مَا أَنَّكُمْ تَنْطِقُونَ﴾ أقسم ﷾ بقسم يوجب الْفَخْرُ لِتَضَمُّنِهِ التَّمَدُّحَ بِأَعْظَمِ قُدْرَةٍ وَأَجَلِّ عَظَمَةٍ\",[[51,23,0,8,1]]],[58,\"الْقَسَمُ\",3,320,320,1084,\"﴿لَعَمْرُكَ إِنَّهُمْ لَفِي سَكْرَتِهِمْ يَعْمَهُونَ﴾ أَقْسَمَ ﷾ بِحَيَاةِ نَبِيهِ ﷺ تَعْظِيمًا لِشَأْنِهِ وَتَنْوِيهًا بَقَدْرِهِ وَسَيَأْتِي فِي نَوْعِ الْأَقْسَامِ أَشْيَاءُ تَتَعَلَّقُ بذَلِكَ.\",[[15,72,0,4,1]]],[58,\"اللَّفُّ وَالنَّشْرُ\",3,320,321,1084,\"هُوَ أَنْ يُذْكَرَ شَيْئَانِ أَوْ أَشْيَاءُ، إِمَّا تَفْصِيلًا بِالنَّصِّ عَلَى كُلِّ وَاحِدٍ أَوْ إِجْمَالًا بِأَنْ يُؤْتَى بِلَفْظٍ يَشْتَمِلُ عَلَى مُتَعَدِّدٍ ثُمَّ يُذْكَرَ أَشْيَاءُ عَلَى عَدَدِ ذَلِكَ كُلُّ وَاحِدٍ يَرْجِعُ إِلَى وَاحِدٍ مِنَ الْمُتَقَدِّمِ وَيُفَوِّضُ إِلَى عَقْلِ السَّامِعِ رَدَّ كُلِّ وَاحِدٍ إِلَى مَا يَلِيقُ بِهِ فَالْإِجْمَالِيُّ كَقَوْلِهِ تَعَالَى: ﴿وَقَالُوا لَنْ يَدْخُلَ الْجَنَّةَ إِلاَّ مَنْ كَانَ هُودًا أَوْ نَصَارَى﴾ أَيْ وَقَالَتِ الْيَهُودُ: لَنْ يَدْخُلَ الْجَنَّةَ إِلَّا الْيَهُودُ وَقَالَتِ النَّصَارَى لَنْ يَدْخُلَ الْجَنَّةَ إِلَّا النَّصَارَى وَإِنَّمَا سَوَّغَ الْإِجْمَالَ فِي اللَّفِّ ثُبُوتُ الْعِنَادِ بَيْنَ الْيَهُودِ وَالنَّصَارَى فَلَا يُمْكِنُ أَنْ يَقُولَ أَحَدُ الْفَرِيقَيْنِ بِدُخُولِ الْفَرِيقِ الْآخَرِ الْجَنَّةَ فَوُثِقَ بِالْعَقْلِ فِي أَنَّهُ يَرُدُّ كُلَّ قَوْلٍ إِلَى فَرِيقِهِ لِأَمْنِ اللَّبْسِ وَقَائِلُ ذَلِكَ يَهُودُ الْمَدِينَةِ وَنَصَارَى نَجْرَانَ قُلْتُ: وَقَدْ يَكُونُ الْإِجْمَالُ فِي النَّشْرِ لَا فِي اللَّفِّ بِأَنْ يُؤْتَى بِمُتَعَدِّدٍ ثُمَّ بِلَفْظٍ يَشْتَمِلُ عَلَى مُتَعَدِّدٍ يَصْلُحُ لَهُمَا كَقَوْلِهِ تَعَالَى: ﴿حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الأَبْيَضُ مِنَ الْخَيْطِ الأَسْوَدِ مِنَ الْفَجْرِ﴾ عَلَى قَوْلِ أَبِي عُبَيْدَةَ أَنَّ الْخَيْطَ الْأَسْوَدَ أُرِيدَ بِهِ الْفَجْرُ الْكَاذِبُ لَا اللَّيْلُ وَقَدْ بَيَّنْتُهُ فِي أَسْرَارِ التَّنْزِيلِ\",[[2,187,32,41,1]]],[58,\"اللَّفُّ وَالنَّشْرُ\",3,321,321,1085,\"أَحَدُهُمَا: أَنْ يَكُونَ عَلَى تَرْتِيبِ اللَّفِّ كَقَوْلِهِ تَعَالَى: ﴿وَمِنْ رَحْمَتِهِ جَعَلَ لَكُمُ اللَّيْلَ وَالنَّهَارَ لِتَسْكُنُوا فِيهِ وَلِتَبْتَغُوا مِنْ فَضْلِهِ﴾ فَالسُّكُونُ رَاجِعٌ إِلَى اللَّيْلِ وَالِابْتِغَاءُ رَاجِعٌ إِلَى النَّهَارِ\",[[28,73,0,10,1]]],[58,\"اللَّفُّ وَالنَّشْرُ\",3,321,321,1085,\"وَقَوْلِهِ تَعَالَى: ﴿وَلا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَى عُنُقِكَ وَلا تَبْسُطْهَا كُلَّ الْبَسْطِ فَتَقْعُدَ مَلُومًا مَحْسُورًا﴾ فاللوم راجع إلى البخل ومحسورا رَاجِعٌ إِلَى الْإِسْرَافِ لِأَنَّ مَعْنَاهُ: مُنْقَطِعًا لَا شَيْءَ عِنْدَكَ\",[[17,29,0,12,1]]],[58,\"اللَّفُّ وَالنَّشْرُ\",3,321,321,1085,\"وَقَوْلِهِ: ﴿أَلَمْ يَجِدْكَ يَتِيمًا﴾ الْآيَاتِ فَإِنَّ قَوْلَهُ: ﴿فَأَمَّا الْيَتِيمَ فَلا تَقْهَرْ﴾ رَاجِعٌ إِلَى قَوْلِهِ: ﴿أَلَمْ يَجِدْكَ يَتِيمًا فَآوَى﴾ ﴿وَأَمَّا السَّائِلَ فَلا تَنْهَرْ﴾ رَاجِعٌ إِلَى قَوْلِهِ: ﴿وَوَجَدَكَ ضَالًا﴾ فَإِنَّ الْمُرَادَ السَّائِلُ عَنِ الْعِلْمِ كَمَا فَسَّرَهُ مُجَاهِدٌ وَغَيْرُهُ ﴿وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ﴾ رَاجِعٌ إِلَى قَوْلِهِ: ﴿وَوَجَدَكَ عَائِلًا فَأَغْنَى﴾ رَأَيْتُ هَذَا الْمِثَالَ فِي شَرْحِ الْوَسِيطِ لِلنَّوَوِيِّ المسمى بالتنقيح.\",[[93,6,0,3,1],[93,9,0,3,1],[93,6,0,2,1],[93,10,0,3,1],[93,7,0,1,1],[93,11,0,3,1],[93,8,0,2,1]]],[58,\"اللَّفُّ وَالنَّشْرُ\",3,321,321,1085,\"وَالثَّانِي: أَنْ يَكُونَ عَلَى عَكْسِ تَرْتِيبِهِ كَقَوْلِهِ: ﴿يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌ فَأَمَّا الَّذِينَ اسْوَدَّتْ وُجُوهُهُمْ﴾\",[[3,106,0,8,1]]],[58,\"اللَّفُّ وَالنَّشْرُ\",3,321,322,1085,\"وجَعَلَ مِنْهُ جَمَاعَةٌ قَوْلَهُ تَعَالَى: ﴿حَتَّى يَقُولَ الرَّسُولُ وَالَّذِينَ آمَنُوا مَعَهُ مَتَى نَصْرُ اللَّهِ أَلا إِنَّ نَصْرَ اللَّهِ قَرِيبٌ﴾، قَالُوا: \\\" مَتَى نَصْرُ اللَّهِ \\\" قَوْلُ الَّذِينَ آمَنُوا \\\" أَلَا إِنَّ نَصْرَ اللَّهِ قَرِيبٌ \\\" قَوْلُ الرَّسُولِ\",[[2,214,16,29,1]]],[58,\"الْمُشَاكَلَةُ\",3,322,322,1086,\"فَالْأَوَّلُ كَقَوْلِهِ تَعَالَى: ﴿تَعْلَمُ مَا فِي نَفْسِي وَلا أَعْلَمُ مَا فِي نَفْسِكَ﴾ ﴿وَمَكَرُوا وَمَكَرَ اللَّهُ﴾ فَإِنَّ إِطْلَاقَ النَّفْسِ وَالْمَكْرِ فِي جانب البارئ تعالى إنما هو لِمُشَاكَلَةِ مَا مَعَهُ وَكَذَا قَوْلُهُ: ﴿وَجَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا﴾ لِأَنَّ الْجَزَاءَ حَقٌّ لَا يُوصَفُ بِأَنَّهُ سَيِّئَةٌ، ﴿فَمَنِ اعْتَدَى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ﴾ ﴿وَقِيلَ الْيَوْمَ نَنْسَاكُمْ كَمَا نَسِيتُمْ﴾ ﴿فَيَسْخَرُونَ مِنْهُمْ سَخِرَ اللَّهُ مِنْهُمْ﴾ ﴿نَّمَا نَحْنُ مُسْتَهْزِئُونَ اللَّهُ يَسْتَهْزِئُ بِهِمْ﴾\",[[5,116,31,39,1],[3,54,0,2,1],[42,40,0,3,1],[2,194,6,10,1],[45,34,0,4,1],[9,79,12,16,1],[2,14,13,15,1],[2,15,0,2,1]]],[58,\"الْمُشَاكَلَةُ\",3,322,323,1086,\"ومثال التقديري قوله تعالى: ﴿صِبْغَةَ اللَّهِ﴾، أَيْ تَطْهِيرُ اللَّهِ لِأَنَّ الْإِيمَانَ يُطَهِّرُ النُّفُوسَ، وَالْأَصْلُ فِيهِ أَنَّ النَّصَارَى كَانُوا يَغْمِسُونَ أَوْلَادَهُمْ فِي مَاءٍ أَصْفَرَ يُسَمُّونَهُ الْمَعْمُودِيَّةَ وَيَقُولُونَ: إِنَّهُ تَطْهِيرٌ لَهُمْ، فَعَبَّرَ عَنِ الإيمان ب \\\" صبغة اللَّهِ \\\" لِلْمُشَاكَلَةِ بِهَذِهِ الْقَرِينَةِ.\",[[2,138,0,1,1]]],[58,\"الْمُزَاوَجَةُ\",3,323,323,1087,\"وَمِنْهُ فِي الْقُرْآنِ: ﴿آتَيْنَاهُ آيَاتِنَا فَانْسَلَخَ مِنْهَا فَأَتْبَعَهُ الشَّيْطَانُ فَكَانَ مِنَ الْغَاوِينَ﴾ .\",[[7,175,4,12,1]]],[58,\"الْمُبَالَغَةُ\",3,323,323,1087,\"مُبَالَغَةٌ بِالْوَصْفِ: بِأَنْ يَخْرُجَ إِلَى حَدِّ الِاسْتِحَالَةِ، وَمِنْهُ: ﴿يَكَادُ زَيْتُهَا يُضِيءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌ﴾ ﴿وَلا يَدْخُلُونَ الْجَنَّةَ حَتَّى يَلِجَ الْجَمَلُ فِي سَمِّ الْخِيَاطِ﴾ وَمُبَالَغَةٌ بِالصِّيغَةِ:\",[[24,35,25,31,1],[7,40,11,19,1]]],[58,\"الْمُطَابَقَةُ\",3,325,325,1089,\"وَمِنْ أَمْثِلَةِ ذَلِكَ: ﴿فَلْيَضْحَكُوا قَلِيلًا وَلْيَبْكُوا كَثِيرًا﴾ ﴿وَأَنَّهُ هُوَ أَضْحَكَ وَأَبْكَى وَأَنَّهُ هُوَ أَمَاتَ وَأَحْيَا﴾ ﴿لِكَيْلا تَأْسَوْا عَلَى مَا فَاتَكُمْ وَلا تَفْرَحُوا بِمَا آتَاكُمْ﴾ ﴿وَتَحْسَبُهُمْ أَيْقَاظًا وَهُمْ رُقُودٌ﴾\",[[9,82,0,3,1],[53,43,0,3,1],[53,44,0,3,1],[57,23,0,8,1],[18,18,0,3,1]]],[58,\"الْمُطَابَقَةُ\",3,325,325,1089,\"وَمِنْ أَمْثِلَةِ الْمَجَازِيِّ: ﴿أَوَمَنْ كَانَ مَيْتًا فَأَحْيَيْنَاهُ﴾، أَيْ ضَالًّا فَهَدَيْنَاهُ\",[[6,122,0,3,1]]],[58,\"الْمُطَابَقَةُ\",3,325,326,1089,\"وَمِنْ أَمْثِلَةِ طِبَاقِ السَّلْبِ: ﴿تَعْلَمُ مَا فِي نَفْسِي وَلا أَعْلَمُ مَا فِي نَفْسِكَ﴾ ﴿فَلا تَخْشَوُا النَّاسَ وَاخْشَوْنِ﴾ وَمِنْ أَمْثِلَةِ الْمَعْنَوِيِّ: ﴿إِنْ أَنْتُمْ إِلاَّ تَكْذِبُونَ قَالُوا رَبُّنَا يَعْلَمُ إِنَّا إِلَيْكُمْ لَمُرْسَلُونَ﴾ مَعْنَاهُ \\\"رَبُّنَا يَعْلَمُ إِنَّا لَصَادِقُونَ\\\"\",[[5,116,31,39,1],[5,44,23,26,1],[36,15,11,14,1],[36,16,0,5,1]]],[58,\"الْمُطَابَقَةُ\",3,326,326,1090,\"﴿جَعَلَ لَكُمُ الأَرْضَ فِرَاشًا وَالسَّمَاءَ بِنَاءً﴾ قَالَ: أَبُو عَلِيٍّ الْفَارِسِيُّ: لَمَّا كَانَ الْبِنَاءُ رَفْعًا لِلْمَبْنِي قُوبِلَ بِالْفِرَاشِ الَّذِي هُوَ عَلَى خِلَافِ الْبِنَاءِ\",[[2,22,1,6,1]]],[58,\"الْمُطَابَقَةُ\",3,326,326,1090,\"وَمِنْهُ نَوْعٌ يُسَمَّى الطِّبَاقَ الْخَفِيَّ كَقَوْلِهِ: ﴿مِمَّا خَطِيئَاتِهِمْ أُغْرِقُوا فَأُدْخِلُوا نَارًا﴾ لِأَنَّ الْغَرَقَ مِنْ صِفَاتِ الْمَاءِ فَكَأَنَّهُ جَمَعَ بَيْنَ الْمَاءِ وَالنَّارِ قَالَ ابْنُ مُنْقِذٍ وَهِيَ أَخْفَى مُطَابَقَةٍ فِي الْقُرْآنِ\",[[71,25,0,4,1]]],[58,\"الْمُطَابَقَةُ\",3,326,326,1090,\"وَقَالَ ابْنُ الْمُعْتَزِّ: مِنْ أَمْلَحِ الطِّبَاقِ وَأَخْفَاهُ قَوْلُهُ تَعَالَى: ﴿وَلَكُمْ فِي الْقِصَاصِ حَيَاةٌ﴾ لِأَنَّ مَعْنَى الْقِصَاصِ الْقَتْلُ فَصَارَ الْقَتْلُ سَبَبُ الحياة\",[[2,179,0,3,1]]],[58,\"الْمُطَابَقَةُ\",3,326,327,1090,\"وَمِنْهُ نَوْعٌ يُسَمَّى تَرْصِيعُ الْكَلَامِ وَهُوَ اقْتِرَانُ الشَّيْءِ بِمَا يَجْتَمِعُ مَعَهُ فِي قَدْرٍ مُشْتَرَكٍ كَقَوْلِهِ: ﴿إِنَّ لَكَ أَلاَّ تَجُوعَ فِيهَا وَلا تَعْرَى وَأَنَّكَ لَا تَظْمَأُ فِيهَا وَلا تَضْحَى﴾ أَتَى بِالْجُوعِ مَعَ الْعُرْيِ وَبَابُهُ أَنْ يَكُونَ مَعَ الظَّمَأِ وَبِالضُّحَى مَعَ الظَّمَأِ وَبَابُهُ أَنْ يَكُونَ مَعَ الْعُرْيِ لَكِنَّ الْجُوعَ وَالْعُرْيَ اشْتَرَكَا فِي الْخُلُوِّ فَالْجُوعُ خُلُوُّ الْبَاطِنِ مِنَ الطَّعَامِ وَالْعُرْيُ خُلُوُّ الظَّاهِرِ مِنَ اللِّبَاسِ وَالظَّمَأُ وَالضُّحَى اشْتَرَكَا فِي الِاحْتِرَاقِ فَالظَّمَأُ احْتِرَاقُ الْبَاطِنِ مِنَ الْعَطَشِ وَالضُّحَى احْتِرَاقُ الظَّاهِرِ مِنْ حَرِّ الشَّمْسِ وَمِنْهُ نَوْعٌ يُسَمَّى الْمُقَابَلَةُ وَهِيَ أَنْ يُذْكَرَ لَفْظَانِ فَأَكْثَرُ ثُمَّ أضدادها عَلَى التَّرْتِيبِ.\",[[20,118,0,6,1],[20,119,0,5,1]]],[58,\"الْمُطَابَقَةُ\",3,327,327,1091,\"وَالثَّانِي: أَنَّ الطِّبَاقَ لَا يكون إلا بالأضداد والمقابلة بالأضداد وبغيرها قَالَ السَّكَّاكِيُّ: وَمِنْ خَوَاصِّ الْمُقَابَلَةِ أَنَّهُ إِذَا شُرِطَ فِي الْأَوَّلِ أَمْرٌ شُرِطَ فِي الثَّانِي ضِدُّهُ كَقَوْلِهِ تَعَالَى: ﴿فَأَمَّا مَنْ أَعْطَى وَاتَّقَى﴾ الآيتين قَابَلَ بَيْنَ الْإِعْطَاءِ وَالْبُخْلِ وَالِاتِّقَاءِ وَالِاسْتِغْنَاءِ وَالتَّصْدِيقِ وَالتَّكْذِيبِ وَالْيُسْرَى وَالْعُسْرَى وَلَمَّا جُعِلَ التَّيْسِيرُ فِي الْأَوَّلِ مُشْتَرِكًا بَيْنَ الْإِعْطَاءِ وَالِاتِّقَاءِ وَالتَّصْدِيقِ جُعِلَ ضِدُّهُ وَهُوَ التَّعْسِيرُ مُشْتَرِكًا بَيْنَ أَضْدَادِهَا\",[[92,5,0,3,1]]],[58,\"الْمُطَابَقَةُ\",3,327,327,1091,\"وَقَالَ بَعْضُهُمْ: الْمُقَابَلَةُ إِمَّا لِوَاحِدٍ بِوَاحِدٍ وَذَلِكَ قَلِيلٌ جدا كقوله: ﴿تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ﴾\",[[2,255,8,11,1]]],[58,\"الْمُطَابَقَةُ\",3,327,327,1091,\"أَوِ اثْنَيْنِ بِاثْنَيْنِ كَقَوْلِهِ: ﴿فَلْيَضْحَكُوا قَلِيلًا وَلْيَبْكُوا كَثِيرًا﴾ أَوَ ثَلَاثَةٍ بِثَلَاثَةٍ كَقَوْلِهِ: ﴿يَأْمُرُهُمْ بِالْمَعْرُوفِ وَيَنْهَاهُمْ عَنِ الْمُنْكَرِ وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ﴾ ﴿وَاشْكُرُوا لِي وَلا تَكْفُرُونِ﴾ وأربعة بأربعة كَقَوْلِهِ تَعَالَى: ﴿فَأَمَّا مَنْ أَعْطَى﴾ الآيتين\",[[9,82,0,3,1],[7,157,12,22,1],[2,152,2,5,1],[92,5,0,2,1]]],[58,\"الْمُطَابَقَةُ\",3,327,328,1091,\"وَخَمْسَةٍ بِخَمْسَةٍ كَقَوْلِهِ: ﴿إِنَّ اللَّهَ لَا يَسْتَحْيِي أَنْ يَضْرِبَ مَثَلًا مَا﴾ الْآيَاتِ قَابَلَ بَيْنَ \\\"بَعُوضَةً فَمَا فوقه\\\" وبين \\\"فأما الذين آمنو\\\"، و\\\"وَأَمَّا الَّذِينَ كَفَرُوا\\\" وَبَيْنَ يُضِلُّ \\\"وَيَهْدِي\\\" وبين \\\"ينقضون\\\" \\\"وميثاقه\\\" \\\" وَبَيْنَ يَقْطَعُونَ \\\" وَ\\\"أَنْ يُوصَلَ\\\"\",[[2,26,0,7,1]]],[58,\"الْمُطَابَقَةُ\",3,328,328,1092,\"أَوْ سِتَّةٍ بِسِتَّةٍ كَقَوْلِهِ: ﴿زُيِّنَ لِلنَّاسِ حُبُّ الشَّهَوَاتِ﴾ الْآيَةَ، ثُمَّ قال: ﴿قُلْ أَؤُنَبِّئُكُمْ﴾ الآية، قَابَلَ \\\"الْجَنَّاتِ\\\" وَالْأَنْهَارَ وَالْخُلْدَ وَالْأَزْوَاجَ وَالتَّطْهِيرَ وَالرِّضْوَانَ بِإِزَاءِ النِّسَاءِ وَالْبَنِينَ وَالذَّهَبِ وَالْفِضَّةِ وَالْخَيْلِ الْمُسَوَّمَةِ وَالْأَنْعَامِ وَالْحَرْثَ\",[[3,14,0,3,1],[3,15,0,1,1]]],[58,\"الْمُطَابَقَةُ\",3,328,328,1092,\"مِثَالُ الْأَوَّلِ: مُقَابَلَةُ السِّنَةِ بِالنَّوْمِ فِي الْآيَةِ الْأَوْلَى فَإِنَّهُمَا جَمِيعًا مِنْ بَابِ الرُّقَادِ الْمُقَابَلِ بِالْيَقَظَةِ فِي آيَةِ: ﴿وَتَحْسَبُهُمْ أَيْقَاظًا وَهُمْ رُقُودٌ﴾ وَهَذَا مِثَالُ الثَّانِي: فَإِنَّهُمَا نَقِيضَانِ\",[[18,18,0,3,1]]],[58,\"الْمُطَابَقَةُ\",3,328,328,1092,\"وَمِثَالُ الثَّالِثِ: مُقَابَلَةُ الشَّرِّ بِالرَّشَدِ فِي قَوْلِهِ: ﴿وَأَنَّا لَا نَدْرِي أَشَرٌّ أُرِيدَ بِمَنْ فِي الأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا﴾ فَإِنَّهُمَا خِلَافَانِ لَا نَقِيضَانِ فَإِنَّ نَقِيضَ الشَّرِّ الْخَيْرُ وَالرُّشْدِ الْغَيُّ\",[[72,10,0,12,1]]],[58,\"الْمُوَارَبَةُ\",3,328,329,1092,\"بِرَاءٍ مُهْمِلَةٍ وَبَاءٍ مُوَحَّدَةٍ أَنْ يَقُولَ الْمُتَكَلِّمُ قَوْلًا يَتَضَمَّنُ مَا يُنْكَرُ عَلَيْهِ فَإِذَا حَصَلَ الْإِنْكَارُ اسْتَحْضَرَ بِحَذَقِهِ وَجْهًا مِنَ الْوُجُوهِ يَتَخَلَّصُ بِهِ إِمَّا بِتَحْرِيفِ كَلِمَةٍ أَوْ تَصْحِيفِهَا أَوْ زِيَادَةٍ أَوْ نَقْصٍ قَالَ ابْنُ أَبِي الْإِصْبَعِ وَمِنْهُ قَوْلُهُ تَعَالَى حِكَايَةً عَنْ أَكْبَرِ أَوْلَادِ يَعْقُوبَ: ﴿ارْجِعُوا إِلَى أَبِيكُمْ فَقُولُوا يَا أَبَانَا إِنَّ ابْنَكَ سَرَقَ﴾ فَإِنَّهُ قُرِئَ: \\\" إِنَّ ابْنَكَ سَرَقَ وَلَمْ يَسْرِقْ\\\"، فَأَتَى بِالْكَلَامِ عَلَى الصِّحَّةِ بِإِبْدَالِ ضَمَّةٍ مِنْ فَتْحَةٍ وتشديد الراء وكسرتها.\",[[12,81,0,7,1]]],[58,\"الْمُرَاجَعَةُ\",3,329,329,1093,\"قَالَ: ابْنُ أَبِي الْإِصْبَعِ: هِيَ أَنْ يَحْكِيَ الْمُتَكَلِّمُ مُرَاجَعَةً فِي الْقَوْلِ جَرَتْ بَيْنَهُ وَبَيْنَ مُحَاوِرٍ لَهُ بِأَوْجَزِ عِبَارَةٍ وَأَعْدَلِ سَبْكٍ وَأَعْذَبِ أَلْفَاظٍ وَمِنْهُ قَوْلُهُ تَعَالَى: ﴿قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامًا قَالَ وَمِنْ ذُرِّيَّتِي قَالَ لا يَنَالُ عَهْدِي الظَّالِمِينَ﴾ جَمَعَتْ هَذِهِ الْقِطْعَةُ- وَهِيَ بَعْضُ آيَةٍ ثَلَاثَ مُرَاجَعَاتِ فِيهَا مَعَانِي الْكَلَامِ مِنَ الْخَبَرِ وَالِاسْتِخْبَارِ وَالْأَمْرِ وَالنَّهْيِ وَالْوَعْدِ وَالْوَعِيدِ بِالْمَنْطُوقِ وَالْمَفْهُومِ\",[[2,124,6,18,1]]],[58,\"النزاهة\",3,329,330,1093,\"وَمِنْهُ قَوْلُهُ تَعَالَى: ﴿وَإِذَا دُعُوا إِلَى اللَّهِ وَرَسُولِهِ لِيَحْكُمَ بَيْنَهُمْ إِذَا فَرِيقٌ مِنْهُمْ مُعْرِضُونَ﴾ ثُمَّ قَالَ: ﴿أَفِي قُلُوبِهِمْ مَرَضٌ أَمِ ارْتَابُوا أَمْ يَخَافُونَ أَنْ يَحِيفَ اللَّهُ عَلَيْهِمْ وَرَسُولُهُ بَلْ أُولَئِكَ هُمُ الظَّالِمُونَ﴾ فَإِنَّ أَلْفَاظَ ذَمِّ هَؤُلَاءِ الْمُخْبَرِ عَنْهُمْ بِهَذَا الْخَبَرِ أَتَتْ مُنَزَّهَةً عَمَّا يَقْبُحُ فِي الْهِجَاءِ مِنَ الْفُحْشِ وَسَائِرِ هِجَاءِ الْقُرْآنِ كذلك.\",[[24,48,0,10,1],[24,50,0,15,1]]],[58,\"الْإِبْدَاعُ\",3,330,331,1094,\"بِالْبَاءِ الْمُوَحَّدَةِ أَنْ يَشْتَمِلَ الْكَلَامُ عَلَى عِدَّةِ ضُرُوبٍ مِنَ الْبَدِيعِ قَالَ ابْنُ أَبِي الْإِصْبَعِ وَلَمْ أَرَ فِي الْكَلَامِ مِثْلَ قَوْلِهِ تعالى: ﴿وَقِيلَ يَا أَرْضُ ابْلَعِي مَاءَكِ﴾ فَإِنَّ فِيهَا عِشْرِينَ ضَرْبًا مِنَ الْبَدِيعِ وَهِيَ سَبْعَ عَشْرَةَ لَفْظَةً وَذَلِكَ: الْمُنَاسِبَةُ التَّامَّةُ فِي \\\"ابْلَعِي\\\" وَ\\\"أَقْلِعِي\\\"، وَالِاسْتِعَارَةُ فِيهِمَا وَالطِّبَاقُ بَيْنَ الْأَرْضِ وَالسَّمَاءِ وَالْمَجَازُ فِي قوله تعالى: ﴿يَا سَمَاءُ﴾ فَإِنَّ الْحَقِيقَةَ يَا مَطَرَ السَّمَاءِ وَالْإِشَارَةُ فِي \\\"وَغِيضَ الْمَاءُ\\\" فَإِنَّهُ عَبَّرَ بِهِ عَنْ مَعَانٍ كَثِيرَةٍ لِأَنَّ الْمَاءَ لَا يَغِيضُ حَتَّى يُقْلِعَ مَطَرُ السَّمَاءِ وَتَبْلَعَ الْأَرْضُ مَا يَخْرُجُ مِنْهَا مِنْ عُيُونِ الْمَاءِ فَيَنْقُصُ الْحَاصِلُ عَلَى وَجْهِ الْأَرْضِ مِنَ الْمَاءِ وَالْإِرْدَافُ فِي \\\"وَاسْتَوَتْ\\\" وَالتَّمْثِيلُ فِي: \\\"وَقُضِيَ الْأَمْرُ \\\" وَالتَّعْلِيلُ فَإِنَّ \\\"غِيضَ الْمَاءُ\\\" عِلَّةُ الِاسْتِوَاءِ وَصِحَّةُ التَّقْسِيمِ فَإِنَّهُ اسْتَوْعَبَ فِيهِ أَقْسَامَ الْمَاءِ حَالَةَ نَقْصِهِ إِذْ لَيْسَ إِلَّا احْتِبَاسُ مَاءِ السَّمَاءِ وَالْمَاءِ النَّابِعِ مِنَ الْأَرْضِ وَغِيضَ الْمَاءُ الَّذِي عَلَى ظَهْرِهَا وَالِاحْتِرَاسُ فِي الدُّعَاءِ لِئَلَّا يُتَوَهَّمَ أَنَّ الْغَرَقَ لِعُمُومِهِ شمل مَنْ لَا يَسْتَحِقُّ الْهَلَاكَ فَإِنَّ عَدْلَهُ تَعَالَى يَمْنَعُ أَنْ يَدْعُوَ عَلَى غَيْرِ مُسْتَحِقٍّ وَحُسْنُ النَّسَقِ وَائْتِلَافُ اللَّفْظِ مَعَ الْمَعْنَى وَالْإِيجَازُ فَإِنَّهُ تَعَالَى قَصَّ الْقِصَّةَ مُسْتَوْعَبَةً بِأَخْصَرِ عِبَارَةٍ وَالتَّسْهِيمُ لأن أَوَّلَ الْآيَةِ يَدُلُّ عَلَى آخِرِهَا وَالتَّهْذِيبُ لِأَنَّ مُفْرَدَاتِهَا مَوْصُوفَةٌ بِصِفَاتِ الْحُسْنِ كُلُّ لَفْظَةٍ سَهْلَةُ مَخَارِجِ الْحُرُوفِ عَلَيْهَا رَوْنَقُ الْفَصَاحَةِ مَعَ الْخُلُوِّ مِنَ الْبَشَاعَةِ وَعَقَادَةِ التَّرْكِيبِ وَحُسْنُ الْبَيَانِ مِنْ جِهَةِ أَنَّ السَّامِعَ لَا يَتَوَقَّفُ فِي فَهْمِ مَعْنَى الْكَلَامِ وَلَا يُشْكِلُ عَلَيْهِ شَيْءٌ مِنْهُ وَالتَّمْكِينُ لِأَنَّ الْفَاصِلَةَ مُسْتَقِرَّةٌ فِي مَحَلِّهَا مُطَمْئِنَةٌ فِي مَكَانِهَا غَيْرُ قَلِقَةٍ ولا مستدعاة والانسجام \\\"وهو تحدر الكلام بسهوله وعذوبة وسبك مع جزالة لفظ كما ينسجم الماء القليل من الهواء \\\"\",[[11,44,0,3,1]]]]}");
